import React, { useState, useEffect } from 'react';
import { db } from '../services/db';
import { CommercialRecord, DuplicateRequest, User, CommercialType, CITIES } from '../types';
import { Check, X, Search, BarChart3, Archive } from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer, ReferenceLine } from 'recharts';

interface CheckerProps {
  user: User;
}

export const CheckerWorkspace: React.FC<CheckerProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<'AUDIT' | 'APPROVALS'>('AUDIT');
  const [requests, setRequests] = useState<DuplicateRequest[]>([]);

  // Audit State
  const [auditQuery, setAuditQuery] = useState({ fsn: '', city: 'BLR', targetMargin: 0 });
  const [auditResult, setAuditResult] = useState<any>(null);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    loadRequests();
    // Real-time setup would happen here with onSnapshot
    const interval = setInterval(loadRequests, 5000); // Polling for demo
    return () => clearInterval(interval);
  }, []);

  const loadRequests = async () => {
    const reqs = await db.getDuplicateRequests();
    setRequests(reqs.filter(r => r.status === 'PENDING'));
  };

  const handleAudit = async () => {
    if (!auditQuery.fsn) return;
    setLoading(true);
    const records = await db.getRecords();

    // Filter relevant records
    const relevant = records.filter(r => 
      r.fsn === auditQuery.fsn && 
      (r.city === auditQuery.city || r.city === 'PAN-INDIA')
    );

    // Calc Sums
    const nlc = relevant.find(r => r.type === CommercialType.NLC_VALUE)?.value || 0;
    const onInv = relevant.find(r => r.type === CommercialType.ON_INVOICE)?.value || 0;
    // Simple logic: System Margin = 100 - (NLC as % of MRP? - assuming NLC is value for simplified demo logic, treating all as comparable units or converting)
    // For this demo, let's compare: Target Input vs (NLC + OnInvoice)

    const systemTotal = nlc + onInv; 
    const variance = auditQuery.targetMargin - systemTotal;

    setAuditResult({
      data: [
        { name: 'System Sum', value: systemTotal, fill: '#2874f0' },
        { name: 'Checker Input', value: auditQuery.targetMargin, fill: '#ff9f00' }
      ],
      variance,
      status: Math.abs(variance) < 0.1 ? 'MATCH' : 'MISMATCH',
      details: relevant
    });
    setLoading(false);
  };

  const handleRequestAction = async (reqId: string, action: 'APPROVED' | 'REJECTED') => {
    await db.resolveDuplicateRequest(reqId, action, user.id);
    loadRequests();
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      <div className="flex justify-between items-center border-b border-gray-800 pb-4">
        <h2 className="text-2xl font-bold text-white flex items-center gap-2">
           <ShieldCheckIcon className="text-green-400" /> Checker Workspace
        </h2>
        <div className="flex gap-4">
          <button onClick={() => setActiveTab('AUDIT')} className={`text-sm font-bold ${activeTab === 'AUDIT' ? 'text-fkBlue' : 'text-gray-400'}`}>AUDIT TOOL</button>
          <button onClick={() => setActiveTab('APPROVALS')} className={`text-sm font-bold flex items-center gap-2 ${activeTab === 'APPROVALS' ? 'text-fkBlue' : 'text-gray-400'}`}>
            APPROVALS 
            {requests.length > 0 && <span className="bg-red-500 text-white text-[10px] px-1.5 py-0.5 rounded-full">{requests.length}</span>}
          </button>
        </div>
      </div>

      {activeTab === 'AUDIT' ? (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          <div className="lg:col-span-1 space-y-4">
            <div className="glass-panel p-6 rounded-xl">
              <h3 className="text-lg font-semibold mb-4 text-gray-200">Commercial Audit</h3>
              <div className="space-y-3">
                <input 
                  className="w-full bg-slate-800 border border-slate-600 rounded p-2 text-white" 
                  placeholder="FSN to Audit"
                  value={auditQuery.fsn}
                  onChange={e => setAuditQuery({...auditQuery, fsn: e.target.value})}
                />
                <select 
                  className="w-full bg-slate-800 border border-slate-600 rounded p-2 text-white"
                  value={auditQuery.city}
                  onChange={e => setAuditQuery({...auditQuery, city: e.target.value})}
                >
                  {CITIES.map(c => <option key={c} value={c}>{c}</option>)}
                </select>
                <input 
                  type="number"
                  className="w-full bg-slate-800 border border-slate-600 rounded p-2 text-white" 
                  placeholder="Expected Total Value"
                  value={auditQuery.targetMargin || ''}
                  onChange={e => setAuditQuery({...auditQuery, targetMargin: parseFloat(e.target.value)})}
                />
                <button 
                  onClick={handleAudit}
                  disabled={loading}
                  className="w-full bg-fkBlue hover:bg-blue-600 text-white font-bold py-2 rounded transition-colors"
                >
                  {loading ? 'Analyzing...' : 'Run Analysis'}
                </button>
              </div>
            </div>

            {auditResult && (
              <div className={`p-4 rounded-xl border ${auditResult.status === 'MATCH' ? 'bg-green-900/20 border-green-800' : 'bg-red-900/20 border-red-800'}`}>
                 <div className="text-xl font-bold mb-1">{auditResult.status}</div>
                 <div className="text-sm opacity-80">Variance: {auditResult.variance.toFixed(2)}</div>
              </div>
            )}
          </div>

          <div className="lg:col-span-2 glass-panel p-6 rounded-xl min-h-[400px]">
            {auditResult ? (
              <ResponsiveContainer width="100%" height={350}>
                <BarChart data={auditResult.data}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#333" />
                  <XAxis dataKey="name" stroke="#888" />
                  <YAxis stroke="#888" />
                  <Tooltip contentStyle={{ backgroundColor: '#1e293b', borderColor: '#334155', color: '#fff' }} />
                  <Legend />
                  <Bar dataKey="value" barSize={60} radius={[4, 4, 0, 0]} />
                </BarChart>
              </ResponsiveContainer>
            ) : (
              <div className="h-full flex flex-col items-center justify-center text-gray-500">
                <BarChart3 className="w-16 h-16 mb-4 opacity-20" />
                <p>Run an audit to view visualization</p>
              </div>
            )}
          </div>
        </div>
      ) : (
        <div className="space-y-4">
          {requests.length === 0 ? (
            <div className="text-center py-20 text-gray-500">
              <Check className="w-12 h-12 mx-auto mb-3 opacity-20" />
              <p>No pending approvals. Good job!</p>
            </div>
          ) : (
            requests.map(req => (
              <div key={req.id} className="glass-panel p-4 rounded-xl flex flex-col md:flex-row justify-between items-start md:items-center gap-4 border-l-4 border-yellow-500">
                <div>
                  <div className="flex items-center gap-2 mb-1">
                    <span className="bg-yellow-500/20 text-yellow-400 text-xs px-2 py-0.5 rounded font-mono">CONFLICT</span>
                    <h4 className="font-bold text-white">{req.payload.title} ({req.payload.fsn})</h4>
                  </div>
                  <div className="text-sm text-gray-400 grid grid-cols-2 md:grid-cols-4 gap-x-8 gap-y-1">
                    <span>City: <b className="text-gray-200">{req.payload.city}</b></span>
                    <span>Type: <b className="text-gray-200">{req.payload.type}</b></span>
                    <span>New Value: <b className="text-fkYellow">{req.payload.value}</b></span>
                    <span>By: {req.requestedBy}</span>
                  </div>
                </div>
                <div className="flex gap-2 w-full md:w-auto">
                  <button 
                    onClick={() => handleRequestAction(req.id, 'REJECTED')}
                    className="flex-1 md:flex-none px-4 py-2 rounded bg-slate-700 hover:bg-slate-600 text-white text-sm transition-colors"
                  >
                    Reject
                  </button>
                  <button 
                    onClick={() => handleRequestAction(req.id, 'APPROVED')}
                    className="flex-1 md:flex-none px-4 py-2 rounded bg-green-600 hover:bg-green-500 text-white font-bold text-sm shadow-lg shadow-green-900/20 transition-colors"
                  >
                    Approve Override
                  </button>
                </div>
              </div>
            ))
          )}
        </div>
      )}
    </div>
  );
};

