import React, { useState, useEffect } from 'react';
import { db } from '../services/db';
import { CommercialRecord, CITIES } from '../types';
import { Download, Filter, RefreshCw, Trash2, Edit2 } from 'lucide-react';

export const DataExplorer: React.FC = () => {
  const [records, setRecords] = useState<CommercialRecord[]>([]);
  const [loading, setLoading] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');

  const loadData = async () => {
    setLoading(true);
    const data = await db.getRecords();
    setRecords(data);
    setLoading(false);
  };

  useEffect(() => {
    loadData();
  }, []);

  // Prepare Pivot Data
  // Group by FSN + Type + Dates -> Columns are cities
  const pivotData = React.useMemo(() => {
    const map = new Map<string, any>();

    records.forEach(r => {
      const key = `${r.fsn}_${r.type}_${r.startDate}_${r.endDate}`;
      if (!map.has(key)) {
        map.set(key, {
          key,
          fsn: r.fsn,
          brand: r.brand,
          title: r.title,
          type: r.type,
          startDate: r.startDate,
          endDate: r.endDate,
          values: {}
        });
      }
      const entry = map.get(key);
      entry.values[r.city] = r.value;
    });

    let result = Array.from(map.values());
    if (searchTerm) {
      const lower = searchTerm.toLowerCase();
      result = result.filter(item => 
        item.fsn.toLowerCase().includes(lower) || 
        item.brand.toLowerCase().includes(lower) ||
        item.title.toLowerCase().includes(lower)
      );
    }
    return result;
  }, [records, searchTerm]);

  const exportCSV = () => {
    const headers = ['FSN', 'Brand', 'Title', 'Type', 'Start', 'End', ...CITIES].join(',');
    const rows = pivotData.map(row => {
      const cityVals = CITIES.map(c => row.values[c] || '').join(',');
      return `${row.fsn},${row.brand},${row.title},${row.type},${row.startDate},${row.endDate},${cityVals}`;
    }).join('\n');

    const blob = new Blob([headers + '\n' + rows], { type: 'text/csv' });
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `minutes_master_export_${Date.now()}.csv`;
    a.click();
  };

  return (
    <div className="space-y-4 animate-in fade-in slide-in-from-bottom-2 duration-500 h-full flex flex-col">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <h2 className="text-2xl font-bold text-white">Database Explorer</h2>
        <div className="flex gap-2">
           <div className="relative">
             <Filter className="absolute left-3 top-2.5 h-4 w-4 text-gray-500"/>
             <input 
               className="bg-slate-800 border border-slate-600 rounded-lg py-2 pl-9 pr-4 text-sm text-white focus:ring-2 focus:ring-fkBlue outline-none w-64"
               placeholder="Filter by FSN, Brand..."
               value={searchTerm}
               onChange={e => setSearchTerm(e.target.value)}
             />
           </div>
           <button onClick={loadData} className="p-2 bg-slate-800 rounded-lg hover:bg-slate-700 text-gray-300">
             <RefreshCw className={`h-5 w-5 ${loading ? 'animate-spin' : ''}`} />
           </button>
           <button onClick={exportCSV} className="flex items-center gap-2 px-4 py-2 bg-green-700 hover:bg-green-600 text-white rounded-lg text-sm font-medium">
             <Download className="h-4 w-4" /> Export
           </button>
        </div>
      </div>

      <div className="flex-1 glass-panel rounded-xl overflow-hidden border border-slate-700 flex flex-col">
        <div className="overflow-auto scrollbar-hide flex-1">
          <table className="w-full text-left border-collapse">
            <thead className="bg-slate-900 sticky top-0 z-10 text-xs uppercase text-gray-400">
              <tr>
                <th className="p-4 border-b border-slate-700 min-w-[120px]">FSN</th>
                <th className="p-4 border-b border-slate-700">Brand</th>
                <th className="p-4 border-b border-slate-700">Type</th>
                <th className="p-4 border-b border-slate-700 text-center">Dates</th>
                {CITIES.map(c => (
                  <th key={c} className="p-4 border-b border-slate-700 text-center min-w-[80px] bg-slate-900/90 backdrop-blur">{c}</th>
                ))}
              </tr>
            </thead>
            <tbody className="text-sm divide-y divide-slate-800">
              {pivotData.map((row) => (
                <tr key={row.key} className="hover:bg-white/5 transition-colors group">
                  <td className="p-4 font-mono text-fkBlue font-medium">{row.fsn}</td>
                  <td className="p-4 text-gray-300">{row.brand}</td>
                  <td className="p-4">
                    <span className={`px-2 py-1 rounded text-[10px] border ${
                      row.type.includes('Margin') ? 'border-purple-500 text-purple-300 bg-purple-900/20' : 
                      'border-blue-500 text-blue-300 bg-blue-900/20'
                    }`}>
                      {row.type}
                    </span>
                  </td>
                  <td className="p-4 text-gray-400 text-xs text-center">
                    <div>{row.startDate}</div>
                    <div className="opacity-50">to</div>
                    <div>{row.endDate}</div>
                  </td>
                  {CITIES.map(c => (
                    <td key={c} className="p-4 text-center border-l border-slate-800/50 relative">
                       {row.values[c] !== undefined ? (
                         <span className="font-semibold text-white">{row.values[c]}</span>
                       ) : (
                         <span className="text-gray-700">-</span>
                       )}
                    </td>
                  ))}
                </tr>
              ))}
              {pivotData.length === 0 && !loading && (
                 <tr><td colSpan={CITIES.length + 4} className="p-8 text-center text-gray-500">No records found matching your filters.</td></tr>
              )}
            </tbody>
          </table>
        </div>
        <div className="bg-slate-900 p-2 text-xs text-gray-500 text-center border-t border-slate-700">
          Showing {pivotData.length} grouped records (Pivot View)
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { User, Role } from './types';
import { Login, PinVerification } from './components/Auth';
import { MakerWorkspace } from './components/MakerWorkspace';
import { CheckerWorkspace } from './components/CheckerWorkspace';
import { DataExplorer } from './components/DataExplorer';
import { LayoutDashboard, Database, LogOut, Shield, Briefcase, Menu } from 'lucide-react';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [view, setView] = useState<'WORKSPACE' | 'EXPLORER'>('WORKSPACE');
  const [showPin, setShowPin] = useState(false);
  const [isCheckerVerified, setIsCheckerVerified] = useState(false);
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);

  // Check persisted session
  useEffect(() => {
    const savedUser = localStorage.getItem('mm_session_user');
    if (savedUser) setUser(JSON.parse(savedUser));

    // Check PIN cache
    const pinCache = localStorage.getItem('mm_pin_verified');
    if (pinCache) {
       const { expiry } = JSON.parse(pinCache);
       if (new Date().getTime() < expiry) setIsCheckerVerified(true);
    }
  }, []);

  const handleLogin = (u: User) => {
    setUser(u);
    localStorage.setItem('mm_session_user', JSON.stringify(u));
  };

  const handleLogout = () => {
    setUser(null);
    setIsCheckerVerified(false);
    localStorage.removeItem('mm_session_user');
    localStorage.removeItem('mm_pin_verified');
  };

  const verifyPin = () => {
    setIsCheckerVerified(true);
    setShowPin(false);
    // 30 Days Expiry
    const expiry = new Date();
    expiry.setDate(expiry.getDate() + 30);
    localStorage.setItem('mm_pin_verified', JSON.stringify({ expiry: expiry.getTime() }));
  };

  if (!user) {
    return <Login onLogin={handleLogin} />;
  }

  // Guard Clause for Checker Access
  const renderWorkspace = () => {
    if (user.role === Role.MAKER) return <MakerWorkspace user={user} />;

    // For Checker/Admin
    if (!isCheckerVerified) {
       return (
         <div className="h-full flex flex-col items-center justify-center text-center space-y-4">
            <Shield className="w-20 h-20 text-gray-600 mb-4" />
            <h2 className="text-2xl font-bold text-gray-300">Restricted Access</h2>
            <p className="text-gray-500 max-w-md">Checker workspace contains sensitive auditing tools. Security verification is required.</p>
            <button 
              onClick={() => setShowPin(true)}
              className="bg-fkBlue text-white px-6 py-3 rounded-lg font-bold shadow-lg hover:bg-blue-600 transition-all"
            >
              Verify Identity
            </button>
         </div>
       );
    }
    return <CheckerWorkspace user={user} />;
  };

  return (
    <div className="flex h-screen bg-slate-950 text-white overflow-hidden font-sans">
      {/* Sidebar - Desktop */}
      <aside className={`fixed inset-y-0 left-0 z-40 w-64 bg-slate-900 border-r border-white/5 transform transition-transform duration-300 md:translate-x-0 ${mobileMenuOpen ? 'translate-x-0' : '-translate-x-full'} md:static md:flex flex-col`}>
        <div className="h-20 flex items-center px-6 border-b border-white/5 bg-fkBlue/10">
          <div className="w-8 h-8 bg-fkYellow rounded mr-3 flex items-center justify-center font-bold text-black text-xl">M</div>
          <span className="text-xl font-bold tracking-tight">Minutes<span className="text-fkBlue">Master</span></span>
        </div>

        <nav className="flex-1 p-4 space-y-2">
           <button 
             onClick={() => { setView('WORKSPACE'); setMobileMenuOpen(false); }}
             className={`w-full flex items-center space-x-3 px-4 py-3 rounded-lg transition-all ${view === 'WORKSPACE' ? 'bg-fkBlue text-white shadow-lg shadow-blue-900/20' : 'text-gray-400 hover:bg-white/5 hover:text-white'}`}
           >
             <Briefcase className="w-5 h-5" />
             <span className="font-medium">My Workspace</span>
           </button>

           <button 
             onClick={() => { setView('EXPLORER'); setMobileMenuOpen(false); }}
             className={`w-full flex items-center space-x-3 px-4 py-3 rounded-lg transition-all ${view === 'EXPLORER' ? 'bg-fkBlue text-white shadow-lg shadow-blue-900/20' : 'text-gray-400 hover:bg-white/5 hover:text-white'}`}
           >
             <Database className="w-5 h-5" />
             <span className="font-medium">Data Explorer</span>
           </button>
        </nav>

        <div className="p-4 border-t border-white/5 bg-black/20">
          <div className="flex items-center gap-3 mb-4 px-2">
            <div className={`w-8 h-8 rounded-full flex items-center justify-center text-sm font-bold ${user.role === 'MAKER' ? 'bg-purple-500' : 'bg-green-500'}`}>
              {user.name.charAt(0)}
            </div>
            <div className="overflow-hidden">
              <p className="text-sm font-medium truncate">{user.name}</p>
              <p className="text-xs text-gray-500 capitalize">{user.role}</p>
            </div>
          </div>
          <button 
            onClick={handleLogout}
            className="w-full flex items-center justify-center space-x-2 px-4 py-2 border border-slate-700 rounded-lg text-sm hover:bg-red-900/20 hover:text-red-400 hover:border-red-900/50 transition-colors"
          >
            <LogOut className="w-4 h-4" />
            <span>Sign Out</span>
          </button>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 flex flex-col h-full relative overflow-hidden">
        {/* Mobile Header */}
        <header className="h-16 md:hidden flex items-center justify-between px-4 bg-slate-900 border-b border-white/5">
          <span className="font-bold">MinutesMaster</span>
          <button onClick={() => setMobileMenuOpen(!mobileMenuOpen)} className="p-2">
            <Menu className="w-6 h-6" />
          </button>
        </header>

        <div className="flex-1 overflow-auto p-4 md:p-8 relative">
           {/* Background Decor */}
           <div className="absolute top-[-10%] right-[-5%] w-[500px] h-[500px] bg-fkBlue/10 rounded-full blur-[120px] pointer-events-none" />
           <div className="absolute bottom-[-10%] left-[-5%] w-[400px] h-[400px] bg-fkYellow/5 rounded-full blur-[100px] pointer-events-none" />

           {view === 'WORKSPACE' ? renderWorkspace() : <DataExplorer />}
        </div>
      </main>

      {showPin && (
        <PinVerification 
          user={user} 
          onSuccess={verifyPin} 
          onCancel={() => setShowPin(false)} 
        />
      )}
    </div>
  );
};

export default App;

