          <div className="mx-auto w-12 h-12 bg-fkYellow/20 rounded-full flex items-center justify-center mb-3">
             <ShieldCheck className="text-fkYellow w-6 h-6" />
          </div>
          <h2 className="text-xl font-bold text-white">Security Check</h2>
          <p className="text-sm text-gray-400">Enter PIN to access Checker Workspace</p>
        </div>

        <form onSubmit={verify} className="space-y-4">
          <input
            type="password"
            maxLength={4}
            value={pin}
