            className="w-full text-center text-3xl tracking-[1em] font-bold bg-slate-900/80 border border-slate-600 rounded-lg py-3 text-white focus:border-fkYellow focus:ring-1 focus:ring-fkYellow outline-none"
            autoFocus
          />
          {error && <p className="text-red-400 text-center text-sm">{error}</p>}
          <button
            type="submit"
            disabled={loading || pin.length < 4}
            className="w-full bg-fkYellow hover:bg-yellow-500 text-black font-bold py-3 rounded-lg transition-colors flex justify-center"
          >
            {loading ? <Loader2 className="animate-spin h-5 w-5" /> : 'Unlock Workspace'}
          </button>
        </form>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { db } from '../services/db';
import { CommercialRecord, DuplicateRequest, User, CommercialType, CITIES } from '../types';
import { Check, X, Search, BarChart3, Archive, ShieldCheck } from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer, ReferenceLine } from 'recharts';

interface CheckerProps {
  user: User;
}

export const CheckerWorkspace: React.FC<CheckerProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<'AUDIT' | 'APPROVALS'>('AUDIT');
  const [requests, setRequests] = useState<DuplicateRequest[]>([]);

  // Audit State
  const [auditQuery, setAuditQuery] = useState({ fsn: '', city: 'BLR', targetMargin: 0 });
  const [auditResult, setAuditResult] = useState<any>(null);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    loadRequests();
    // Real-time setup would happen here with onSnapshot
    const interval = setInterval(loadRequests, 5000); // Polling for demo
    return () => clearInterval(interval);
  }, []);

  const loadRequests = async () => {
    const reqs = await db.getDuplicateRequests();
    setRequests(reqs.filter(r => r.status === 'PENDING'));
  };

  const handleAudit = async () => {
    if (!auditQuery.fsn) return;
    setLoading(true);
    const records = await db.getRecords();

    // Filter relevant records
    const relevant = records.filter(r => 
      r.fsn === auditQuery.fsn && 
      (r.city === auditQuery.city || r.city === 'PAN-INDIA')
    );

    // Calc Sums
    const nlc = relevant.find(r => r.type === CommercialType.NLC_VALUE)?.value || 0;
    const onInv = relevant.find(r => r.type === CommercialType.ON_INVOICE)?.value || 0;

    const systemTotal = nlc + onInv; 
    const variance = auditQuery.targetMargin - systemTotal;

    setAuditResult({
      data: [
        { name: 'System Sum', value: systemTotal, fill: '#2874f0' },
        { name: 'Checker Input', value: auditQuery.targetMargin, fill: '#ff9f00' }
      ],
      variance,
      status: Math.abs(variance) < 0.1 ? 'MATCH' : 'MISMATCH',
      details: relevant
    });
    setLoading(false);
  };

  const handleRequestAction = async (reqId: string, action: 'APPROVED' | 'REJECTED') => {
    await db.resolveDuplicateRequest(reqId, action, user.id);
    loadRequests();
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      <div className="flex justify-between items-center border-b border-gray-800 pb-4">
        <h2 className="text-2xl font-bold text-white flex items-center gap-2">
           <ShieldCheck className="text-green-400 w-6 h-6" /> Checker Workspace
        </h2>
        <div className="flex gap-4">
          <button onClick={() => setActiveTab('AUDIT')} className={`text-sm font-bold ${activeTab === 'AUDIT' ? 'text-fkBlue' : 'text-gray-400'}`}>AUDIT TOOL</button>
          <button onClick={() => setActiveTab('APPROVALS')} className={`text-sm font-bold flex items-center gap-2 ${activeTab === 'APPROVALS' ? 'text-fkBlue' : 'text-gray-400'}`}>
            APPROVALS 
            {requests.length > 0 && <span className="bg-red-500 text-white text-[10px] px-1.5 py-0.5 rounded-full">{requests.length}</span>}
          </button>
        </div>
      </div>

      {activeTab === 'AUDIT' ? (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          <div className="lg:col-span-1 space-y-4">
            <div className="glass-panel p-6 rounded-xl">
              <h3 className="text-lg font-semibold mb-4 text-gray-200">Commercial Audit</h3>
              <div className="space-y-3">
                <input 
                  className="w-full bg-slate-800 border border-slate-600 rounded p-2 text-white" 
                  placeholder="FSN to Audit"
                  value={auditQuery.fsn}
                  onChange={e => setAuditQuery({...auditQuery, fsn: e.target.value})}
                />
                <select 
                  className="w-full bg-slate-800 border border-slate-600 rounded p-2 text-white"
                  value={auditQuery.city}
                  onChange={e => setAuditQuery({...auditQuery, city: e.target.value})}
                >
                  {CITIES.map(c => <option key={c} value={c}>{c}</option>)}
                </select>
                <input 
                  type="number"
                  className="w-full bg-slate-800 border border-slate-600 rounded p-2 text-white" 
                  placeholder="Expected Total Value"
                  value={auditQuery.targetMargin || ''}
                  onChange={e => setAuditQuery({...auditQuery, targetMargin: parseFloat(e.target.value)})}
                />
                <button 
                  onClick={handleAudit}
                  disabled={loading}
                  className="w-full bg-fkBlue hover:bg-blue-600 text-white font-bold py-2 rounded transition-colors"
                >
                  {loading ? 'Analyzing...' : 'Run Analysis'}
                </button>
              </div>
            </div>

            {auditResult && (
              <div className={`p-4 rounded-xl border ${auditResult.status === 'MATCH' ? 'bg-green-900/20 border-green-800' : 'bg-red-900/20 border-red-800'}`}>
                 <div className="text-xl font-bold mb-1">{auditResult.status}</div>
                 <div className="text-sm opacity-80">Variance: {auditResult.variance.toFixed(2)}</div>
              </div>
            )}
          </div>

          <div className="lg:col-span-2 glass-panel p-6 rounded-xl min-h-[400px]">
            {auditResult ? (
              <ResponsiveContainer width="100%" height={350}>
                <BarChart data={auditResult.data}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#333" />
                  <XAxis dataKey="name" stroke="#888" />
                  <YAxis stroke="#888" />
                  <Tooltip contentStyle={{ backgroundColor: '#1e293b', borderColor: '#334155', color: '#fff' }} />
                  <Legend />
                  <Bar dataKey="value" barSize={60} radius={[4, 4, 0, 0]} />
                </BarChart>
              </ResponsiveContainer>
            ) : (
              <div className="h-full flex flex-col items-center justify-center text-gray-500">
                <BarChart3 className="w-16 h-16 mb-4 opacity-20" />
                <p>Run an audit to view visualization</p>
              </div>
            )}
          </div>
        </div>
      ) : (
        <div className="space-y-4">
          {requests.length === 0 ? (
            <div className="text-center py-20 text-gray-500">
              <Check className="w-12 h-12 mx-auto mb-3 opacity-20" />
              <p>No pending approvals. Good job!</p>
            </div>
          ) : (
            requests.map(req => (
              <div key={req.id} className="glass-panel p-4 rounded-xl flex flex-col md:flex-row justify-between items-start md:items-center gap-4 border-l-4 border-yellow-500">
                <div>
                  <div className="flex items-center gap-2 mb-1">
                    <span className="bg-yellow-500/20 text-yellow-400 text-xs px-2 py-0.5 rounded font-mono">CONFLICT</span>
                    <h4 className="font-bold text-white">{req.payload.title} ({req.payload.fsn})</h4>
                  </div>
                  <div className="text-sm text-gray-400 grid grid-cols-2 md:grid-cols-4 gap-x-8 gap-y-1">
                    <span>City: <b className="text-gray-200">{req.payload.city}</b></span>
                    <span>Type: <b className="text-gray-200">{req.payload.type}</b></span>
                    <span>New Value: <b className="text-fkYellow">{req.payload.value}</b></span>
                    <span>By: {req.requestedBy}</span>
                  </div>
                </div>
                <div className="flex gap-2 w-full md:w-auto">
                  <button 
                    onClick={() => handleRequestAction(req.id, 'REJECTED')}
                    className="flex-1 md:flex-none px-4 py-2 rounded bg-slate-700 hover:bg-slate-600 text-white text-sm transition-colors"
                  >
                    Reject
                  </button>
                  <button 
                    onClick={() => handleRequestAction(req.id, 'APPROVED')}
                    className="flex-1 md:flex-none px-4 py-2 rounded bg-green-600 hover:bg-green-500 text-white font-bold text-sm shadow-lg shadow-green-900/20 transition-colors"
                  >
                    Approve Override
                  </button>
                </div>
              </div>
            ))
          )}
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { CommercialRecord, CommercialType, CITIES, DuplicateRequest, User } from '../types';
import { db } from '../services/db';
import { Plus, Upload, Save, AlertTriangle, FileText, X, Download } from 'lucide-react';
import Papa from 'papaparse';

interface MakerProps {
  user: User;
}

export const MakerWorkspace: React.FC<MakerProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<'MANUAL' | 'BULK'>('MANUAL');

  // Manual Form State
  const [formData, setFormData] = useState<Partial<CommercialRecord>>({
    city: 'PAN-INDIA',
    type: CommercialType.MARGIN_PERCENT,
    startDate: new Date().toISOString().split('T')[0],
    endDate: new Date(new Date().setMonth(new Date().getMonth() + 3)).toISOString().split('T')[0]
  });
  const [loading, setLoading] = useState(false);
  const [notification, setNotification] = useState<{msg: string, type: 'success' | 'error' | 'warning' | null}>({ msg: '', type: null });

  // Load draft
  useEffect(() => {
    const draft = localStorage.getItem('mm_draft_form');
    if (draft) setFormData(JSON.parse(draft));
  }, []);

  // Save draft
  useEffect(() => {
    localStorage.setItem('mm_draft_form', JSON.stringify(formData));
  }, [formData]);

  const handleManualSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setNotification({ msg: '', type: null });

    if (!formData.fsn || !formData.value || !formData.brand || !formData.title) {
        setNotification({ msg: 'Please fill all fields', type: 'error' });
        return;
    }
    if (formData.endDate! < formData.startDate!) {
        setNotification({ msg: 'End Date cannot be before Start Date', type: 'error' });
        return;
    }

    setLoading(true);

    try {
      const records = await db.getRecords();

      // Strict Duplicate Check
      const isDuplicate = records.some(r => 
        r.fsn === formData.fsn &&
        r.city === formData.city &&
        r.type === formData.type &&
        r.startDate === formData.startDate &&
        r.endDate === formData.endDate &&
        r.value === Number(formData.value)
      );

      const isConflict = records.some(r => 
        r.fsn === formData.fsn &&
        r.city === formData.city &&
        r.type === formData.type &&
        r.startDate === formData.startDate &&
        r.endDate === formData.endDate
      );

      const newRecord: CommercialRecord = {
        id: `rec_${Date.now()}`,
        ...formData as CommercialRecord,
        value: Number(formData.value),
        lastUpdatedBy: user.name,
        lastUpdatedAt: Date.now()
      };

      if (isDuplicate) {
        setNotification({ msg: 'Exact duplicate already exists. No action taken.', type: 'warning' });
      } else if (isConflict) {
        // Create Request
        const req: DuplicateRequest = {
          id: `req_${Date.now()}`,
          originalRecordId: null,
          payload: newRecord,
          requestedBy: user.name,
          requestedAt: Date.now(),
          status: 'PENDING'
        };
        await db.createDuplicateRequest(req);
        setNotification({ msg: 'Conflict found. Override request sent to Checker.', type: 'warning' });
      } else {
        // Save
        await db.addRecords([newRecord]);
        setNotification({ msg: 'Record saved successfully.', type: 'success' });
        // Clear critical fields only
        setFormData(prev => ({ ...prev, fsn: '', value: 0 }));
      }
    } catch (err) {
      setNotification({ msg: 'Failed to save record.', type: 'error' });
    } finally {
      setLoading(false);
    }
  };

  // Bulk Upload Handler
  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    Papa.parse(file, {
      header: true,
      skipEmptyLines: true,
      complete: async (results) => {
        setLoading(true);
        const newRecords: CommercialRecord[] = [];
        const duplicates: CommercialRecord[] = [];

        const existingRecords = await db.getRecords();

        // Expected Columns: FSN, Brand, Title, StartDate, EndDate, Type, Value_BLR, Value_DEL, etc. OR standard flat format.
        // Implementing flexible parser for City columns

        results.data.forEach((row: any) => {
           // Basic validation
           if(!row.FSN || !row.Type) return;

           // Find city columns (keys that match valid cities)
           const cityKeys = Object.keys(row).filter(k => CITIES.includes(k) || k === 'Value');

           cityKeys.forEach(cityKey => {
             const city = cityKey === 'Value' ? 'PAN-INDIA' : cityKey;
             let val = parseFloat(row[cityKey]);
             if (isNaN(val)) return;

             // Auto-convert decimal to percent for Margin/Offers
             if (row.Type !== CommercialType.NLC_VALUE && val <= 1 && val > 0) {
                val = val * 100;
             }

             const rec: CommercialRecord = {
               id: `rec_${Math.random().toString(36).substr(2,9)}`,
               fsn: row.FSN,
               brand: row.Brand || 'Unknown',
               title: row.Title || 'Bulk Upload Item',
               city: city,
               startDate: row.StartDate,
               endDate: row.EndDate,
               type: row.Type as CommercialType,
               value: val,
               lastUpdatedBy: user.name,
               lastUpdatedAt: Date.now()
             };

             // Check duplicate
             const exists = existingRecords.some(r => 
                r.fsn === rec.fsn &&
                r.city === rec.city &&
                r.type === rec.type &&
                r.startDate === rec.startDate &&
                r.endDate === rec.endDate
             );

             if (exists) {
               duplicates.push(rec);
             } else {
               newRecords.push(rec);
             }
           });
        });

        if (newRecords.length > 0) {
          await db.addRecords(newRecords);
        }

        if (duplicates.length > 0) {
           // Auto-create requests for duplicates (Bulk override flow)
           for (const dup of duplicates) {
              const req: DuplicateRequest = {
                id: `req_${Math.random().toString(36).substr(2,9)}`,
                originalRecordId: null,
                payload: dup,
                requestedBy: user.name,
                requestedAt: Date.now(),
                status: 'PENDING'
              };
              await db.createDuplicateRequest(req);
           }
           setNotification({ 
             msg: `Uploaded ${newRecords.length} records. ${duplicates.length} conflicts sent for approval.`, 
             type: 'warning' 
           });
        } else {
           setNotification({ msg: `Successfully uploaded ${newRecords.length} records.`, type: 'success' });
        }
        setLoading(false);
      }
    });
  };

  const downloadTemplate = () => {
    // Generate Template CSV
    const headers = ['FSN', 'Brand', 'Title', 'Type', 'StartDate', 'EndDate', ...CITIES];
    const dummyRows = [
        ['MOBEXAMPLE1', 'BrandX', 'Sample Product 1', 'Margin %', '2024-01-01', '2024-03-31', '10', '12', '11', '10', '10', '10', '10', '10', '10'],
        ['MOBEXAMPLE2', 'BrandY', 'Sample Product 2', 'NLC Value', '2024-01-01', '2024-03-31', '50000', '50000', '50000', '50000', '50000', '50000', '50000', '50000', '50000']
    ];

    const csvContent = [
        headers.join(','),
        ...dummyRows.map(row => row.join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv' });
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'minutes_master_template.csv';
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    window.URL.revokeObjectURL(url);
  };

  return (
    <div className="space-y-6 animate-in slide-in-from-bottom-4 duration-500">
      <div className="flex justify-between items-center">
        <h2 className="text-2xl font-bold text-white">Maker Workspace</h2>
        <div className="flex bg-slate-800 rounded-lg p-1">
          <button
            onClick={() => setActiveTab('MANUAL')}
            className={`px-4 py-2 rounded-md text-sm font-medium transition-all ${activeTab === 'MANUAL' ? 'bg-fkBlue text-white shadow-lg' : 'text-gray-400 hover:text-white'}`}
          >
            Manual Entry
          </button>
          <button
            onClick={() => setActiveTab('BULK')}
            className={`px-4 py-2 rounded-md text-sm font-medium transition-all ${activeTab === 'BULK' ? 'bg-fkBlue text-white shadow-lg' : 'text-gray-400 hover:text-white'}`}
          >
            Bulk Upload
          </button>
        </div>
      </div>

      {notification.msg && (
        <div className={`p-4 rounded-lg border flex items-center gap-3 ${
          notification.type === 'error' ? 'bg-red-900/20 border-red-800 text-red-200' :
          notification.type === 'warning' ? 'bg-yellow-900/20 border-yellow-800 text-yellow-200' :
          'bg-green-900/20 border-green-800 text-green-200'
        }`}>
          {notification.type === 'error' ? <AlertTriangle className="h-5 w-5"/> : <FileText className="h-5 w-5"/>}
          {notification.msg}
          <button onClick={() => setNotification({msg:'', type:null})} className="ml-auto"><X className="h-4 w-4"/></button>
        </div>
      )}

      {activeTab === 'MANUAL' ? (
        <form onSubmit={handleManualSubmit} className="glass-panel p-6 rounded-xl grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          <div className="col-span-1">
            <label className="block text-xs font-medium text-gray-400 mb-1">FSN (Product ID)</label>
            <input 
              className="w-full bg-slate-800 border border-slate-600 rounded p-2 text-white focus:border-fkBlue outline-none" 
              value={formData.fsn || ''}
              onChange={e => setFormData({...formData, fsn: e.target.value})}
              placeholder="e.g. MOB12345"
            />
          </div>
          <div className="col-span-1">
            <label className="block text-xs font-medium text-gray-400 mb-1">Brand</label>
            <input 
              className="w-full bg-slate-800 border border-slate-600 rounded p-2 text-white focus:border-fkBlue outline-none" 
              value={formData.brand || ''}
              onChange={e => setFormData({...formData, brand: e.target.value})}
              placeholder="e.g. Samsung"
            />
          </div>
          <div className="col-span-1">
            <label className="block text-xs font-medium text-gray-400 mb-1">Title</label>
            <input 
              className="w-full bg-slate-800 border border-slate-600 rounded p-2 text-white focus:border-fkBlue outline-none" 
              value={formData.title || ''}
              onChange={e => setFormData({...formData, title: e.target.value})}
              placeholder="Product Title"
            />
          </div>

          <div className="col-span-1">
            <label className="block text-xs font-medium text-gray-400 mb-1">City</label>
            <select 
              className="w-full bg-slate-800 border border-slate-600 rounded p-2 text-white focus:border-fkBlue outline-none"
              value={formData.city}
              onChange={e => setFormData({...formData, city: e.target.value})}
            >
              {CITIES.map(c => <option key={c} value={c}>{c}</option>)}
            </select>
          </div>

          <div className="col-span-1">
            <label className="block text-xs font-medium text-gray-400 mb-1">Type</label>
            <select 
              className="w-full bg-slate-800 border border-slate-600 rounded p-2 text-white focus:border-fkBlue outline-none"
              value={formData.type}
              onChange={e => setFormData({...formData, type: e.target.value as CommercialType})}
            >
              <option value={CommercialType.MARGIN_PERCENT}>Margin %</option>
              <option value={CommercialType.NLC_VALUE}>NLC Value (Amount)</option>
              <option value={CommercialType.ON_INVOICE}>On Invoice %</option>
              <option value={CommercialType.OFF_INVOICE}>Off Invoice %</option>
            </select>
          </div>

          <div className="col-span-1">
            <label className="block text-xs font-medium text-gray-400 mb-1">Value</label>
            <input 
              type="number"
              className="w-full bg-slate-800 border border-slate-600 rounded p-2 text-white focus:border-fkBlue outline-none font-mono" 
              value={formData.value || ''}
              onChange={e => setFormData({...formData, value: parseFloat(e.target.value)})}
              placeholder="0.00"
            />
          </div>

          <div className="col-span-1">
            <label className="block text-xs font-medium text-gray-400 mb-1">Start Date</label>
            <input 
              type="date"
              className="w-full bg-slate-800 border border-slate-600 rounded p-2 text-white focus:border-fkBlue outline-none" 
              value={formData.startDate}
              onChange={e => setFormData({...formData, startDate: e.target.value})}
            />
          </div>
          <div className="col-span-1">
            <label className="block text-xs font-medium text-gray-400 mb-1">End Date</label>
            <input 
              type="date"
              className="w-full bg-slate-800 border border-slate-600 rounded p-2 text-white focus:border-fkBlue outline-none" 
              value={formData.endDate}
              onChange={e => setFormData({...formData, endDate: e.target.value})}
            />
          </div>

          <div className="col-span-full flex justify-end pt-4 border-t border-slate-700">
             <button
               type="submit"
               disabled={loading}
               className="bg-fkYellow hover:bg-yellow-500 text-black font-bold py-2 px-6 rounded-lg flex items-center gap-2 transition-all shadow-lg"
             >
               {loading ? <span className="animate-spin">⌛</span> : <Save className="h-5 w-5" />}
               Save Record
             </button>
          </div>
        </form>
      ) : (
        <div className="space-y-4">
          <div className="flex justify-end">
            <button 
              onClick={downloadTemplate}
              className="flex items-center gap-2 px-4 py-2 bg-slate-800 hover:bg-slate-700 text-fkBlue font-medium rounded-lg text-sm border border-slate-700 transition-colors"
            >
              <Download className="h-4 w-4" /> Download CSV Template
            </button>
          </div>
          <div className="glass-panel p-10 rounded-xl border-dashed border-2 border-slate-600 flex flex-col items-center justify-center text-center hover:border-fkBlue transition-colors group cursor-pointer relative">
            <input 
              type="file" 
              accept=".csv"
              onChange={handleFileUpload}
              className="absolute inset-0 w-full h-full opacity-0 cursor-pointer"
            />
            <div className="bg-slate-800 p-4 rounded-full mb-4 group-hover:scale-110 transition-transform">
               <Upload className="h-8 w-8 text-fkBlue" />
            </div>
            <h3 className="text-lg font-semibold text-white">Click to Upload CSV</h3>
            <p className="text-sm text-gray-400 mt-2 max-w-sm">
              Drag and drop or click to upload. Ensure columns match: FSN, Brand, Type, StartDate, EndDate, [City Codes].
            </p>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { User, Role } from './types';
import { Login, PinVerification } from './components/Auth';
import { MakerWorkspace } from './components/MakerWorkspace';
import { CheckerWorkspace } from './components/CheckerWorkspace';
import { DataExplorer } from './components/DataExplorer';
import { LayoutDashboard, Database, LogOut, Shield, Briefcase, Menu } from 'lucide-react';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [view, setView] = useState<'WORKSPACE' | 'EXPLORER'>('WORKSPACE');
  const [showPin, setShowPin] = useState(false);
  const [isCheckerVerified, setIsCheckerVerified] = useState(false);
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);

  // Check persisted session
  useEffect(() => {
    const savedUser = localStorage.getItem('mm_session_user');
    if (savedUser) setUser(JSON.parse(savedUser));

    // Check PIN cache
    const pinCache = localStorage.getItem('mm_pin_verified');
    if (pinCache) {
       const { expiry } = JSON.parse(pinCache);
       if (new Date().getTime() < expiry) setIsCheckerVerified(true);
    }
  }, []);

  const handleLogin = (u: User) => {
    setUser(u);
    localStorage.setItem('mm_session_user', JSON.stringify(u));
  };

  const handleLogout = () => {
    setUser(null);
    setIsCheckerVerified(false);
    localStorage.removeItem('mm_session_user');
    localStorage.removeItem('mm_pin_verified');
  };

  const verifyPin = () => {
    setIsCheckerVerified(true);
    setShowPin(false);
    // 30 Days Expiry
    const expiry = new Date();
    expiry.setDate(expiry.getDate() + 30);
    localStorage.setItem('mm_pin_verified', JSON.stringify({ expiry: expiry.getTime() }));
  };

  if (!user) {
    return <Login onLogin={handleLogin} />;
  }

  // Guard Clause for Checker Access
  const renderWorkspace = () => {
    if (user.role === Role.MAKER) return <MakerWorkspace user={user} />;

    // For Checker/Admin
    if (!isCheckerVerified) {
       return (
         <div className="h-full flex flex-col items-center justify-center text-center space-y-4">
            <Shield className="w-20 h-20 text-gray-600 mb-4" />
            <h2 className="text-2xl font-bold text-gray-300">Restricted Access</h2>
            <p className="text-gray-500 max-w-md">Checker workspace contains sensitive auditing tools. Security verification is required.</p>
            <button 
              onClick={() => setShowPin(true)}
              className="bg-fkBlue text-white px-6 py-3 rounded-lg font-bold shadow-lg hover:bg-blue-600 transition-all"
            >
              Verify Identity
            </button>
         </div>
       );
    }
    return <CheckerWorkspace user={user} />;
  };

  return (
    <div className="flex h-screen bg-slate-950 text-white overflow-hidden font-sans">
      {/* Sidebar - Desktop */}
      <aside className={`fixed inset-y-0 left-0 z-40 w-64 bg-slate-900 border-r border-white/5 transform transition-transform duration-300 md:translate-x-0 ${mobileMenuOpen ? 'translate-x-0' : '-translate-x-full'} md:static md:flex flex-col`}>
        <div className="h-20 flex items-center px-6 border-b border-white/5 bg-fkBlue/10">
          <div className="w-8 h-8 bg-fkYellow rounded mr-3 flex items-center justify-center font-bold text-black text-xl">M</div>
          <span className="text-xl font-bold tracking-tight">Minutes<span className="text-fkBlue">Master</span></span>
        </div>

        <nav className="flex-1 p-4 space-y-2">
           <button 
             onClick={() => { setView('WORKSPACE'); setMobileMenuOpen(false); }}
             className={`w-full flex items-center space-x-3 px-4 py-3 rounded-lg transition-all ${view === 'WORKSPACE' ? 'bg-fkBlue text-white shadow-lg shadow-blue-900/20' : 'text-gray-400 hover:bg-white/5 hover:text-white'}`}
           >
             <Briefcase className="w-5 h-5" />
             <span className="font-medium">My Workspace</span>
           </button>

           <button 
             onClick={() => { setView('EXPLORER'); setMobileMenuOpen(false); }}
             className={`w-full flex items-center space-x-3 px-4 py-3 rounded-lg transition-all ${view === 'EXPLORER' ? 'bg-fkBlue text-white shadow-lg shadow-blue-900/20' : 'text-gray-400 hover:bg-white/5 hover:text-white'}`}
           >
             <Database className="w-5 h-5" />
             <span className="font-medium">Data Explorer</span>
           </button>
        </nav>

        <div className="p-4 border-t border-white/5 bg-black/20">
          <div className="flex items-center gap-3 mb-4 px-2">
            <div className={`w-8 h-8 rounded-full flex items-center justify-center text-sm font-bold ${user.role === 'MAKER' ? 'bg-purple-500' : 'bg-green-500'}`}>
              {user.name.charAt(0)}
            </div>
            <div className="overflow-hidden">
              <p className="text-sm font-medium truncate">{user.name}</p>
              <p className="text-xs text-gray-500 capitalize">{user.role}</p>
            </div>
          </div>
          <button 
            onClick={handleLogout}
            className="w-full flex items-center justify-center space-x-2 px-4 py-2 border border-slate-700 rounded-lg text-sm hover:bg-red-900/20 hover:text-red-400 hover:border-red-900/50 transition-colors"
          >
            <LogOut className="w-4 h-4" />
            <span>Sign Out</span>
          </button>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 flex flex-col h-full relative overflow-hidden">
        {/* Mobile Header */}
        <header className="h-16 md:hidden flex items-center justify-between px-4 bg-slate-900 border-b border-white/5">
          <span className="font-bold">MinutesMaster</span>
          <button onClick={() => setMobileMenuOpen(!mobileMenuOpen)} className="p-2">
