                    {CITIES.map(c => (
                      <td key={c} className={`p-2 text-center border-l border-slate-800/50 relative ${isEditing ? 'p-1' : ''}`}>
                         {isEditing ? (
                           <input 
                             type="number"
                             className="w-16 bg-slate-900 border border-slate-600 rounded px-1 py-1 text-center text-white text-sm focus:border-fkBlue outline-none"
                             value={editForm?.values?.[c] ?? ''}
                             placeholder="-"
                             onChange={e => {
                               const val = e.target.value;
                               setEditForm(prev => ({
                                 ...prev!,
                                 values: { ...prev!.values, [c]: val === '' ? undefined : parseFloat(val) }
                               }));
                             }}
                           />
                         ) : (
                           row.values[c] !== undefined ? (
                             <span className="font-semibold text-white">{row.values[c]}</span>
                           ) : (
                             <span className="text-gray-700">-</span>
                           )
                         )}
                      </td>
                    ))}

                    {/* Actions Column */}
                    <td className="p-4 border-l border-slate-700 sticky right-0 bg-slate-950 group-hover:bg-slate-900 transition-colors z-10">
                      <div className="flex items-center justify-center gap-2">
                        {isEditing ? (
                          <>
                            <button onClick={() => handleSaveEdit(row)} className="p-1.5 bg-green-600 hover:bg-green-500 rounded text-white shadow-lg" title="Save">
                              <Save className="w-4 h-4" />
                            </button>
                            <button onClick={handleCancelEdit} className="p-1.5 bg-slate-700 hover:bg-slate-600 rounded text-gray-300" title="Cancel">
                              <X className="w-4 h-4" />
                            </button>
                          </>
                        ) : (
                          <>
                            <button onClick={() => handleEditClick(row)} className="p-1.5 hover:bg-fkBlue/20 hover:text-fkBlue rounded text-gray-400 transition-colors" title="Edit Row">
                              <Edit2 className="w-4 h-4" />
                            </button>
                            <button onClick={() => handleDeleteRow(row)} className="p-1.5 hover:bg-red-900/30 hover:text-red-400 rounded text-gray-400 transition-colors" title="Delete Group">
                              <Trash2 className="w-4 h-4" />
                            </button>
                          </>
                        )}
                      </div>
                    </td>
                  </tr>
                );
              })}
              {pivotData.length === 0 && !loading && (
                 <tr><td colSpan={CITIES.length + 5} className="p-8 text-center text-gray-500">No records found matching your filters.</td></tr>
              )}
            </tbody>
          </table>
        </div>
        <div className="bg-slate-900 p-2 text-xs text-gray-500 text-center border-t border-slate-700">
          Showing {pivotData.length} grouped records. Edits apply to all underlying records.
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { CommercialRecord, CommercialType, CITIES, DuplicateRequest, User, COMMERCIAL_TYPES } from '../types';
import { db } from '../services/db';
import { Plus, Upload, Save, AlertTriangle, FileText, X, Download, Filter } from 'lucide-react';
import Papa from 'papaparse';

interface MakerProps {
  user: User;
}

export const MakerWorkspace: React.FC<MakerProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<'MANUAL' | 'BULK'>('MANUAL');

  // Manual Form State
  const [formData, setFormData] = useState<Partial<CommercialRecord>>({
    city: 'PAN-INDIA',
    type: CommercialType.MARGIN_PERCENT,
    startDate: new Date().toISOString().split('T')[0],
    endDate: new Date(new Date().setMonth(new Date().getMonth() + 3)).toISOString().split('T')[0]
  });

  // Bulk State
  const [bulkType, setBulkType] = useState<CommercialType>(CommercialType.MARGIN_PERCENT);

  const [loading, setLoading] = useState(false);
  const [notification, setNotification] = useState<{msg: string, type: 'success' | 'error' | 'warning' | null}>({ msg: '', type: null });

  // Load draft
  useEffect(() => {
    const draft = localStorage.getItem('mm_draft_form');
    if (draft) setFormData(JSON.parse(draft));
  }, []);

  // Save draft
  useEffect(() => {
    localStorage.setItem('mm_draft_form', JSON.stringify(formData));
  }, [formData]);

  const handleManualSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setNotification({ msg: '', type: null });

    if (!formData.fsn || !formData.value || !formData.brand || !formData.title) {
        setNotification({ msg: 'Please fill all fields', type: 'error' });
        return;
    }
    if (formData.endDate! < formData.startDate!) {
        setNotification({ msg: 'End Date cannot be before Start Date', type: 'error' });
        return;
    }

    setLoading(true);

    try {
      const records = await db.getRecords();

      // Strict Duplicate Check
      const isDuplicate = records.some(r => 
        r.fsn === formData.fsn &&
        r.city === formData.city &&
        r.type === formData.type &&
        r.startDate === formData.startDate &&
        r.endDate === formData.endDate &&
        r.value === Number(formData.value)
      );

      const isConflict = records.some(r => 
        r.fsn === formData.fsn &&
        r.city === formData.city &&
        r.type === formData.type &&
        r.startDate === formData.startDate &&
        r.endDate === formData.endDate
      );

      const newRecord: CommercialRecord = {
        id: `rec_${Date.now()}`,
        ...formData as CommercialRecord,
        value: Number(formData.value),
        lastUpdatedBy: user.name,
        lastUpdatedAt: Date.now()
      };

      if (isDuplicate) {
        setNotification({ msg: 'Exact duplicate already exists. No action taken.', type: 'warning' });
      } else if (isConflict) {
        // Create Request
        const req: DuplicateRequest = {
          id: `req_${Date.now()}`,
          originalRecordId: null,
          payload: newRecord,
          requestedBy: user.name,
          requestedAt: Date.now(),
          status: 'PENDING'
        };
        await db.createDuplicateRequest(req);
        setNotification({ msg: 'Conflict found. Override request sent to Checker.', type: 'warning' });
      } else {
        // Save
        await db.addRecords([newRecord]);
        setNotification({ msg: 'Record saved successfully.', type: 'success' });
        // Clear critical fields only
        setFormData(prev => ({ ...prev, fsn: '', value: 0 }));
      }
    } catch (err) {
      setNotification({ msg: 'Failed to save record.', type: 'error' });
    } finally {
      setLoading(false);
    }
  };

  // Bulk Upload Handler
  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    Papa.parse(file, {
      header: true,
      skipEmptyLines: true,
      complete: async (results) => {
        setLoading(true);
        const newRecords: CommercialRecord[] = [];
        const duplicates: CommercialRecord[] = [];

        const existingRecords = await db.getRecords();

        // Expected Columns: FSN, Brand, Title, StartDate, EndDate, [City Codes]
        // Type is determined by the active bulkType state, NOT the CSV column.

        results.data.forEach((row: any) => {
           // Basic validation
           if(!row.FSN) return;

           // Find city columns (keys that match valid cities)
           const cityKeys = Object.keys(row).filter(k => CITIES.includes(k) || k === 'Value');

           cityKeys.forEach(cityKey => {
             const city = cityKey === 'Value' ? 'PAN-INDIA' : cityKey;
             let val = parseFloat(row[cityKey]);
             if (isNaN(val)) return;

             // Auto-convert decimal to percent for Margin/Offers if user provides 0.1 for 10%
             if (bulkType !== CommercialType.NLC_VALUE && val <= 1 && val > 0) {
                val = val * 100;
             }

             const rec: CommercialRecord = {
               id: `rec_${Math.random().toString(36).substr(2,9)}`,
               fsn: row.FSN,
               brand: row.Brand || 'Unknown',
               title: row.Title || 'Bulk Upload Item',
               city: city,
               startDate: row.StartDate,
               endDate: row.EndDate,
               type: bulkType,
               value: val,
               lastUpdatedBy: user.name,
               lastUpdatedAt: Date.now()
             };

             // Check duplicate
             const exists = existingRecords.some(r => 
                r.fsn === rec.fsn &&
                r.city === rec.city &&
                r.type === rec.type &&
                r.startDate === rec.startDate &&
                r.endDate === rec.endDate
             );

             if (exists) {
               duplicates.push(rec);
             } else {
               newRecords.push(rec);
             }
           });
        });

        if (newRecords.length > 0) {
          await db.addRecords(newRecords);
        }

        if (duplicates.length > 0) {
           // Auto-create requests for duplicates (Bulk override flow)
           for (const dup of duplicates) {
              const req: DuplicateRequest = {
                id: `req_${Math.random().toString(36).substr(2,9)}`,
                originalRecordId: null,
                payload: dup,
                requestedBy: user.name,
                requestedAt: Date.now(),
                status: 'PENDING'
              };
              await db.createDuplicateRequest(req);
           }
           setNotification({ 
             msg: `Uploaded ${newRecords.length} records of type ${bulkType}. ${duplicates.length} conflicts sent for approval.`, 
             type: 'warning' 
           });
        } else {
           setNotification({ msg: `Successfully uploaded ${newRecords.length} records.`, type: 'success' });
        }
        setLoading(false);
      }
    });
  };

  const downloadTemplate = () => {
    // Generate Template CSV - Removing Type column as it's selected in UI
    const headers = ['FSN', 'Brand', 'Title', 'StartDate', 'EndDate', ...CITIES];

    // Example value based on current type
    const isNLC = bulkType === CommercialType.NLC_VALUE;
    const exampleVal = isNLC ? '50000' : '10';

    const dummyRows = [
        ['MOBEXAMPLE1', 'BrandX', 'Sample Product 1', '2024-01-01', '2024-03-31', exampleVal, exampleVal, exampleVal, exampleVal, exampleVal, exampleVal, exampleVal, exampleVal, exampleVal],
    ];

    const csvContent = [
        headers.join(','),
        ...dummyRows.map(row => row.join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv' });
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `minutes_master_${bulkType.replace(/\s/g, '').toLowerCase()}_template.csv`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    window.URL.revokeObjectURL(url);
  };

  return (
    <div className="space-y-6 animate-in slide-in-from-bottom-4 duration-500">
      <div className="flex justify-between items-center">
        <h2 className="text-2xl font-bold text-white">Maker Workspace</h2>
        <div className="flex bg-slate-800 rounded-lg p-1">
          <button
            onClick={() => setActiveTab('MANUAL')}
            className={`px-4 py-2 rounded-md text-sm font-medium transition-all ${activeTab === 'MANUAL' ? 'bg-fkBlue text-white shadow-lg' : 'text-gray-400 hover:text-white'}`}
          >
            Manual Entry
          </button>
          <button
            onClick={() => setActiveTab('BULK')}
            className={`px-4 py-2 rounded-md text-sm font-medium transition-all ${activeTab === 'BULK' ? 'bg-fkBlue text-white shadow-lg' : 'text-gray-400 hover:text-white'}`}
          >
            Bulk Upload
          </button>
        </div>
      </div>

      {notification.msg && (
        <div className={`p-4 rounded-lg border flex items-center gap-3 ${
          notification.type === 'error' ? 'bg-red-900/20 border-red-800 text-red-200' :
          notification.type === 'warning' ? 'bg-yellow-900/20 border-yellow-800 text-yellow-200' :
          'bg-green-900/20 border-green-800 text-green-200'
        }`}>
          {notification.type === 'error' ? <AlertTriangle className="h-5 w-5"/> : <FileText className="h-5 w-5"/>}
          {notification.msg}
          <button onClick={() => setNotification({msg:'', type:null})} className="ml-auto"><X className="h-4 w-4"/></button>
        </div>
      )}

      {activeTab === 'MANUAL' ? (
        <form onSubmit={handleManualSubmit} className="glass-panel p-6 rounded-xl grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          <div className="col-span-1">
            <label className="block text-xs font-medium text-gray-400 mb-1">FSN (Product ID)</label>
            <input 
              className="w-full bg-slate-800 border border-slate-600 rounded p-2 text-white focus:border-fkBlue outline-none" 
              value={formData.fsn || ''}
              onChange={e => setFormData({...formData, fsn: e.target.value})}
              placeholder="e.g. MOB12345"
            />
          </div>
          <div className="col-span-1">
            <label className="block text-xs font-medium text-gray-400 mb-1">Brand</label>
            <input 
              className="w-full bg-slate-800 border border-slate-600 rounded p-2 text-white focus:border-fkBlue outline-none" 
              value={formData.brand || ''}
              onChange={e => setFormData({...formData, brand: e.target.value})}
              placeholder="e.g. Samsung"
            />
          </div>
          <div className="col-span-1">
            <label className="block text-xs font-medium text-gray-400 mb-1">Title</label>
            <input 
              className="w-full bg-slate-800 border border-slate-600 rounded p-2 text-white focus:border-fkBlue outline-none" 
              value={formData.title || ''}
              onChange={e => setFormData({...formData, title: e.target.value})}
              placeholder="Product Title"
            />
          </div>

          <div className="col-span-1">
            <label className="block text-xs font-medium text-gray-400 mb-1">City</label>
            <select 
              className="w-full bg-slate-800 border border-slate-600 rounded p-2 text-white focus:border-fkBlue outline-none"
              value={formData.city}
              onChange={e => setFormData({...formData, city: e.target.value})}
            >
              {CITIES.map(c => <option key={c} value={c}>{c}</option>)}
            </select>
          </div>

          <div className="col-span-1">
            <label className="block text-xs font-medium text-gray-400 mb-1">Type</label>
            <select 
              className="w-full bg-slate-800 border border-slate-600 rounded p-2 text-white focus:border-fkBlue outline-none"
              value={formData.type}
              onChange={e => setFormData({...formData, type: e.target.value as CommercialType})}
            >
              <option value={CommercialType.MARGIN_PERCENT}>Margin %</option>
              <option value={CommercialType.NLC_VALUE}>NLC Value (Amount)</option>
              <option value={CommercialType.ON_INVOICE}>On Invoice %</option>
              <option value={CommercialType.OFF_INVOICE}>Off Invoice %</option>
            </select>
          </div>

          <div className="col-span-1">
            <label className="block text-xs font-medium text-gray-400 mb-1">Value</label>
            <input 
              type="number"
              className="w-full bg-slate-800 border border-slate-600 rounded p-2 text-white focus:border-fkBlue outline-none font-mono" 
              value={formData.value || ''}
              onChange={e => setFormData({...formData, value: parseFloat(e.target.value)})}
              placeholder="0.00"
            />
          </div>

          <div className="col-span-1">
            <label className="block text-xs font-medium text-gray-400 mb-1">Start Date</label>
            <input 
              type="date"
              className="w-full bg-slate-800 border border-slate-600 rounded p-2 text-white focus:border-fkBlue outline-none" 
              value={formData.startDate}
              onChange={e => setFormData({...formData, startDate: e.target.value})}
            />
          </div>
          <div className="col-span-1">
            <label className="block text-xs font-medium text-gray-400 mb-1">End Date</label>
            <input 
              type="date"
              className="w-full bg-slate-800 border border-slate-600 rounded p-2 text-white focus:border-fkBlue outline-none" 
              value={formData.endDate}
              onChange={e => setFormData({...formData, endDate: e.target.value})}
            />
          </div>

          <div className="col-span-full flex justify-end pt-4 border-t border-slate-700">
             <button
               type="submit"
               disabled={loading}
               className="bg-fkYellow hover:bg-yellow-500 text-black font-bold py-2 px-6 rounded-lg flex items-center gap-2 transition-all shadow-lg"
             >
               {loading ? <span className="animate-spin">⌛</span> : <Save className="h-5 w-5" />}
               Save Record
             </button>
          </div>
        </form>
      ) : (
        <div className="space-y-6">
          <div className="bg-slate-900/50 p-4 rounded-xl border border-white/5">
             <label className="block text-xs font-bold text-gray-400 mb-3 uppercase tracking-wider">Select Upload Type</label>
             <div className="grid grid-cols-2 md:grid-cols-4 gap-2">
               {COMMERCIAL_TYPES.map(type => (
                 <button
                   key={type}
                   onClick={() => setBulkType(type)}
                   className={`p-3 rounded-lg text-sm font-medium transition-all border ${
                     bulkType === type 
                     ? 'bg-fkBlue text-white border-fkBlue shadow-lg shadow-blue-900/20' 
                     : 'bg-slate-800 text-gray-400 border-slate-700 hover:border-gray-500 hover:text-white'
                   }`}
                 >
                   {type}
                 </button>
               ))}
             </div>
          </div>

          <div className="flex justify-end">
            <button 
              onClick={downloadTemplate}
              className="flex items-center gap-2 px-4 py-2 bg-slate-800 hover:bg-slate-700 text-fkBlue font-medium rounded-lg text-sm border border-slate-700 transition-colors"
            >
              <Download className="h-4 w-4" /> 
              Download {bulkType} Template
            </button>
          </div>

          <div className="glass-panel p-10 rounded-xl border-dashed border-2 border-slate-600 flex flex-col items-center justify-center text-center hover:border-fkBlue transition-colors group cursor-pointer relative">
            <input 
              type="file" 
              accept=".csv"
              onChange={handleFileUpload}
              key={bulkType} // Reset input when type changes
              className="absolute inset-0 w-full h-full opacity-0 cursor-pointer"
            />
            <div className="bg-slate-800 p-4 rounded-full mb-4 group-hover:scale-110 transition-transform">
               <Upload className="h-8 w-8 text-fkBlue" />
            </div>
            <h3 className="text-lg font-semibold text-white">Upload {bulkType} CSV</h3>
            <p className="text-sm text-gray-400 mt-2 max-w-sm">
              Drag and drop or click to upload. 
              <br/>Required columns: FSN, Brand, Title, StartDate, EndDate, [City Codes].
            </p>
          </div>
        </div>
      )}
    </div>
  );
};

import { CommercialRecord, DuplicateRequest, User, Role, CommercialType, CITIES as DEFAULT_CITIES } from '../types';

// In a real scenario, we would import firebase/firestore here.
// For this demo, we simulate the Firestore persistence and latency.

const STORAGE_KEYS = {
  USERS: 'mm_users',
  RECORDS: 'mm_records',
  REQUESTS: 'mm_requests',
  BIN: 'mm_bin',
  CITIES: 'mm_cities'
};

// Seed Data
const SEED_USERS: User[] = [
  { id: '1', employeeId: 'maker1', name: 'Alice Maker', role: Role.MAKER },
  { id: '2', employeeId: 'checker1', name: 'Bob Checker', role: Role.CHECKER, pin: '1234' },
  { id: '3', employeeId: 'admin1', name: 'Charlie Admin', role: Role.ADMIN, pin: '9999' },
];

const SEED_RECORDS: CommercialRecord[] = [
  {
    id: 'rec_1',
    fsn: 'MOB12345',
    brand: 'Samsung',
    title: 'Galaxy S24',
    city: 'BLR',
    startDate: '2023-10-01',
    endDate: '2023-12-31',
    type: CommercialType.NLC_VALUE,
    value: 50000,
    lastUpdatedAt: Date.now(),
    lastUpdatedBy: 'system'
  },
  {
    id: 'rec_2',
    fsn: 'MOB12345',
    brand: 'Samsung',
    title: 'Galaxy S24',
    city: 'BLR',
    startDate: '2023-10-01',
    endDate: '2023-12-31',
    type: CommercialType.ON_INVOICE,
    value: 5.5,
    lastUpdatedAt: Date.now(),
    lastUpdatedBy: 'system'
  }
];

// Helper to simulate network delay
const delay = (ms: number) => new Promise(res => setTimeout(res, ms));

class DBService {
  constructor() {
    this.init();
  }

  init() {
    if (!localStorage.getItem(STORAGE_KEYS.USERS)) {
      localStorage.setItem(STORAGE_KEYS.USERS, JSON.stringify(SEED_USERS));
    }
    if (!localStorage.getItem(STORAGE_KEYS.RECORDS)) {
      localStorage.setItem(STORAGE_KEYS.RECORDS, JSON.stringify(SEED_RECORDS));
    }
    if (!localStorage.getItem(STORAGE_KEYS.REQUESTS)) {
      localStorage.setItem(STORAGE_KEYS.REQUESTS, JSON.stringify([]));
    }
    if (!localStorage.getItem(STORAGE_KEYS.BIN)) {
      localStorage.setItem(STORAGE_KEYS.BIN, JSON.stringify([]));
    }
    if (!localStorage.getItem(STORAGE_KEYS.CITIES)) {
      localStorage.setItem(STORAGE_KEYS.CITIES, JSON.stringify(DEFAULT_CITIES));
    }
  }

  // Auth
  async login(employeeId: string): Promise<User | null> {
    await delay(500);
    const users: User[] = JSON.parse(localStorage.getItem(STORAGE_KEYS.USERS) || '[]');
    return users.find(u => u.employeeId === employeeId) || null;
  }

  async verifyPin(userId: string, pin: string): Promise<boolean> {
    await delay(300);
    const users: User[] = JSON.parse(localStorage.getItem(STORAGE_KEYS.USERS) || '[]');
    const user = users.find(u => u.id === userId);
    return user ? user.pin === pin : false;
  }

  // Cities
  async getCities(): Promise<string[]> {
    await delay(100);
    return JSON.parse(localStorage.getItem(STORAGE_KEYS.CITIES) || JSON.stringify(DEFAULT_CITIES));
  }

  async addCity(city: string): Promise<void> {
    await delay(300);
    const cities = await this.getCities();
    if (!cities.includes(city)) {
      cities.push(city);
      localStorage.setItem(STORAGE_KEYS.CITIES, JSON.stringify(cities));
    }
  }

  // Records
  async getRecords(): Promise<CommercialRecord[]> {
    await delay(200); // Simulate Firestore cache read
    return JSON.parse(localStorage.getItem(STORAGE_KEYS.RECORDS) || '[]');
  }

  async addRecords(records: CommercialRecord[]): Promise<void> {
    await delay(600);
    const current = await this.getRecords();
    const updated = [...current, ...records];
    localStorage.setItem(STORAGE_KEYS.RECORDS, JSON.stringify(updated));
  }

  async updateRecord(updatedRecord: CommercialRecord): Promise<void> {
    await delay(400);
    const current = await this.getRecords();
    const index = current.findIndex(r => r.id === updatedRecord.id);
    if (index !== -1) {
      current[index] = updatedRecord;
      localStorage.setItem(STORAGE_KEYS.RECORDS, JSON.stringify(current));
    }
  }

  async deleteRecord(recordId: string, movedToBinBy: string): Promise<void> {
    await delay(400);
    const current = await this.getRecords();
    const record = current.find(r => r.id === recordId);
    if(record) {
        // Move to Bin
        const bin = JSON.parse(localStorage.getItem(STORAGE_KEYS.BIN) || '[]');
        bin.push({ ...record, deletedBy: movedToBinBy, deletedAt: Date.now() });
        localStorage.setItem(STORAGE_KEYS.BIN, JSON.stringify(bin));

        // Remove
        const updated = current.filter(r => r.id !== recordId);
        localStorage.setItem(STORAGE_KEYS.RECORDS, JSON.stringify(updated));
    }
  }

  async getDuplicateRequests(): Promise<DuplicateRequest[]> {
    await delay(200);
    return JSON.parse(localStorage.getItem(STORAGE_KEYS.REQUESTS) || '[]');
  }

  async createDuplicateRequest(request: DuplicateRequest): Promise<void> {
    await delay(400);
    const current = await this.getDuplicateRequests();
    localStorage.setItem(STORAGE_KEYS.REQUESTS, JSON.stringify([...current, request]));
  }

  async resolveDuplicateRequest(requestId: string, status: 'APPROVED' | 'REJECTED', resolverId: string): Promise<void> {
    await delay(500);
    const requests: DuplicateRequest[] = await this.getDuplicateRequests();
    const requestIndex = requests.findIndex(r => r.id === requestId);

    if (requestIndex === -1) return;

    const request = requests[requestIndex];
    request.status = status;

    if (status === 'APPROVED') {
      // Find existing potential conflict to archive
      const allRecords = await this.getRecords();

      // Strict matching logic for replacement
      const conflictingIndex = allRecords.findIndex(r => 
        r.fsn === request.payload.fsn &&
        r.city === request.payload.city &&
        r.type === request.payload.type &&
        r.startDate === request.payload.startDate &&
        r.endDate === request.payload.endDate
      );

      if (conflictingIndex !== -1) {
        // Move old to bin
        await this.deleteRecord(allRecords[conflictingIndex].id, resolverId);
      }

      // Add new
      await this.addRecords([request.payload]);
    }

    // Update Request List
    requests[requestIndex] = request;
    localStorage.setItem(STORAGE_KEYS.REQUESTS, JSON.stringify(requests));
  }
}

