              onChange={handleFileUpload}
              key={bulkType} // Reset input when type changes
              className="absolute inset-0 w-full h-full opacity-0 cursor-pointer"
            />
            <div className="bg-slate-800 p-4 rounded-full mb-4 group-hover:scale-110 transition-transform">
               <Upload className="h-8 w-8 text-fkBlue" />
            </div>
            <h3 className="text-lg font-semibold text-white">Upload {bulkType} CSV</h3>
            <p className="text-sm text-gray-400 mt-2 max-w-sm">
              Drag and drop or click to upload. 
              <br/>Required columns: FSN, Brand, Title, StartDate, EndDate, [City Codes].
            </p>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { db } from '../services/db';
import { CommercialRecord, DuplicateRequest, User, CommercialType } from '../types';
import { Check, X, Search, BarChart3, Archive, ShieldCheck } from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer, ReferenceLine } from 'recharts';

interface CheckerProps {
  user: User;
}

export const CheckerWorkspace: React.FC<CheckerProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<'AUDIT' | 'APPROVALS'>('AUDIT');
  const [requests, setRequests] = useState<DuplicateRequest[]>([]);
  const [cities, setCities] = useState<string[]>([]);

  // Audit State
  const [auditQuery, setAuditQuery] = useState({ fsn: '', city: 'BLR', targetMargin: 0 });
  const [auditResult, setAuditResult] = useState<any>(null);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    loadRequests();
    loadCities();

    // Real-time setup would happen here with onSnapshot
    const interval = setInterval(loadRequests, 5000); // Polling for demo
    return () => clearInterval(interval);
  }, []);

  const loadCities = async () => {
    const c = await db.getCities();
    setCities(c);
    // Set default if not set
    if (!c.includes(auditQuery.city)) {
       setAuditQuery(prev => ({ ...prev, city: c.includes('BLR') ? 'BLR' : c[0] || '' }));
    }
  };

  const loadRequests = async () => {
    const reqs = await db.getDuplicateRequests();
    setRequests(reqs.filter(r => r.status === 'PENDING'));
  };

  const handleAudit = async () => {
    if (!auditQuery.fsn) return;
    setLoading(true);
    const records = await db.getRecords();

    // Filter relevant records
    const relevant = records.filter(r => 
      r.fsn === auditQuery.fsn && 
      (r.city === auditQuery.city || r.city === 'PAN-INDIA')
    );

    // Calc Sums
    const nlc = relevant.find(r => r.type === CommercialType.NLC_VALUE)?.value || 0;
    const onInv = relevant.find(r => r.type === CommercialType.ON_INVOICE)?.value || 0;

    const systemTotal = nlc + onInv; 
    const variance = auditQuery.targetMargin - systemTotal;

    setAuditResult({
      data: [
        { name: 'System Sum', value: systemTotal, fill: '#2874f0' },
        { name: 'Checker Input', value: auditQuery.targetMargin, fill: '#ff9f00' }
      ],
      variance,
      status: Math.abs(variance) < 0.1 ? 'MATCH' : 'MISMATCH',
      details: relevant
    });
    setLoading(false);
  };

  const handleRequestAction = async (reqId: string, action: 'APPROVED' | 'REJECTED') => {
    await db.resolveDuplicateRequest(reqId, action, user.id);
    loadRequests();
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      <div className="flex justify-between items-center border-b border-gray-800 pb-4">
        <h2 className="text-2xl font-bold text-white flex items-center gap-2">
           <ShieldCheck className="text-green-400 w-6 h-6" /> Checker Workspace
        </h2>
        <div className="flex gap-4">
          <button onClick={() => setActiveTab('AUDIT')} className={`text-sm font-bold ${activeTab === 'AUDIT' ? 'text-fkBlue' : 'text-gray-400'}`}>AUDIT TOOL</button>
          <button onClick={() => setActiveTab('APPROVALS')} className={`text-sm font-bold flex items-center gap-2 ${activeTab === 'APPROVALS' ? 'text-fkBlue' : 'text-gray-400'}`}>
            APPROVALS 
            {requests.length > 0 && <span className="bg-red-500 text-white text-[10px] px-1.5 py-0.5 rounded-full">{requests.length}</span>}
          </button>
        </div>
      </div>

      {activeTab === 'AUDIT' ? (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          <div className="lg:col-span-1 space-y-4">
            <div className="glass-panel p-6 rounded-xl">
              <h3 className="text-lg font-semibold mb-4 text-gray-200">Commercial Audit</h3>
              <div className="space-y-3">
                <input 
                  className="w-full bg-slate-800 border border-slate-600 rounded p-2 text-white" 
                  placeholder="FSN to Audit"
                  value={auditQuery.fsn}
                  onChange={e => setAuditQuery({...auditQuery, fsn: e.target.value})}
                />
                <select 
                  className="w-full bg-slate-800 border border-slate-600 rounded p-2 text-white"
                  value={auditQuery.city}
                  onChange={e => setAuditQuery({...auditQuery, city: e.target.value})}
                >
                  {cities.map(c => <option key={c} value={c}>{c}</option>)}
                </select>
                <input 
                  type="number"
                  className="w-full bg-slate-800 border border-slate-600 rounded p-2 text-white" 
                  placeholder="Expected Total Value"
                  value={auditQuery.targetMargin || ''}
                  onChange={e => setAuditQuery({...auditQuery, targetMargin: parseFloat(e.target.value)})}
                />
                <button 
                  onClick={handleAudit}
                  disabled={loading}
                  className="w-full bg-fkBlue hover:bg-blue-600 text-white font-bold py-2 rounded transition-colors"
                >
                  {loading ? 'Analyzing...' : 'Run Analysis'}
                </button>
              </div>
            </div>

            {auditResult && (
              <div className={`p-4 rounded-xl border ${auditResult.status === 'MATCH' ? 'bg-green-900/20 border-green-800' : 'bg-red-900/20 border-red-800'}`}>
                 <div className="text-xl font-bold mb-1">{auditResult.status}</div>
                 <div className="text-sm opacity-80">Variance: {auditResult.variance.toFixed(2)}</div>
              </div>
            )}
          </div>

          <div className="lg:col-span-2 glass-panel p-6 rounded-xl min-h-[400px]">
            {auditResult ? (
              <ResponsiveContainer width="100%" height={350}>
                <BarChart data={auditResult.data}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#333" />
                  <XAxis dataKey="name" stroke="#888" />
                  <YAxis stroke="#888" />
                  <Tooltip contentStyle={{ backgroundColor: '#1e293b', borderColor: '#334155', color: '#fff' }} />
                  <Legend />
                  <Bar dataKey="value" barSize={60} radius={[4, 4, 0, 0]} />
                </BarChart>
              </ResponsiveContainer>
            ) : (
              <div className="h-full flex flex-col items-center justify-center text-gray-500">
                <BarChart3 className="w-16 h-16 mb-4 opacity-20" />
                <p>Run an audit to view visualization</p>
              </div>
            )}
          </div>
        </div>
      ) : (
        <div className="space-y-4">
          {requests.length === 0 ? (
            <div className="text-center py-20 text-gray-500">
              <Check className="w-12 h-12 mx-auto mb-3 opacity-20" />
              <p>No pending approvals. Good job!</p>
            </div>
          ) : (
            requests.map(req => (
              <div key={req.id} className="glass-panel p-4 rounded-xl flex flex-col md:flex-row justify-between items-start md:items-center gap-4 border-l-4 border-yellow-500">
                <div>
                  <div className="flex items-center gap-2 mb-1">
                    <span className="bg-yellow-500/20 text-yellow-400 text-xs px-2 py-0.5 rounded font-mono">CONFLICT</span>
                    <h4 className="font-bold text-white">{req.payload.title} ({req.payload.fsn})</h4>
                  </div>
                  <div className="text-sm text-gray-400 grid grid-cols-2 md:grid-cols-4 gap-x-8 gap-y-1">
                    <span>City: <b className="text-gray-200">{req.payload.city}</b></span>
                    <span>Type: <b className="text-gray-200">{req.payload.type}</b></span>
                    <span>New Value: <b className="text-fkYellow">{req.payload.value}</b></span>
                    <span>By: {req.requestedBy}</span>
                  </div>
                </div>
                <div className="flex gap-2 w-full md:w-auto">
                  <button 
                    onClick={() => handleRequestAction(req.id, 'REJECTED')}
                    className="flex-1 md:flex-none px-4 py-2 rounded bg-slate-700 hover:bg-slate-600 text-white text-sm transition-colors"
                  >
                    Reject
                  </button>
                  <button 
                    onClick={() => handleRequestAction(req.id, 'APPROVED')}
                    className="flex-1 md:flex-none px-4 py-2 rounded bg-green-600 hover:bg-green-500 text-white font-bold text-sm shadow-lg shadow-green-900/20 transition-colors"
                  >
                    Approve Override
                  </button>
                </div>
              </div>
            ))
          )}
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { db } from '../services/db';
import { CommercialRecord, User } from '../types';
import { Download, Filter, RefreshCw, Trash2, Edit2, Save, X, AlertTriangle } from 'lucide-react';

interface DataExplorerProps {
  user: User;
}

interface PivotRow {
  key: string;
  fsn: string;
  brand: string;
  title: string;
  type: any;
  startDate: string;
  endDate: string;
  cityRecords: { [key: string]: CommercialRecord | undefined };
  values: { [key: string]: number | undefined };
}

export const DataExplorer: React.FC<DataExplorerProps> = ({ user }) => {
  const [records, setRecords] = useState<CommercialRecord[]>([]);
  const [cities, setCities] = useState<string[]>([]);
  const [loading, setLoading] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');

  // Edit State
  const [editingRowKey, setEditingRowKey] = useState<string | null>(null);
  const [editForm, setEditForm] = useState<Partial<PivotRow> | null>(null);
  const [processingAction, setProcessingAction] = useState(false);

  const loadData = async () => {
    setLoading(true);
    const [data, c] = await Promise.all([db.getRecords(), db.getCities()]);
    setRecords(data);
    setCities(c);
    setLoading(false);
    setEditingRowKey(null);
    setEditForm(null);
  };

  useEffect(() => {
    loadData();
  }, []);

  const pivotData: PivotRow[] = useMemo(() => {
    const map = new Map<string, PivotRow>();

    records.forEach(r => {
      const key = `${r.fsn}_${r.type}_${r.startDate}_${r.endDate}`;
      if (!map.has(key)) {
        map.set(key, {
          key,
          fsn: r.fsn,
          brand: r.brand,
          title: r.title,
          type: r.type,
          startDate: r.startDate,
          endDate: r.endDate,
          cityRecords: {},
          values: {}
        });
      }
      const entry = map.get(key)!;
      entry.cityRecords[r.city] = r;
      entry.values[r.city] = r.value;
    });

    let result = Array.from(map.values());
    if (searchTerm) {
      const lower = searchTerm.toLowerCase();
      result = result.filter(item => 
        item.fsn.toLowerCase().includes(lower) || 
        item.brand.toLowerCase().includes(lower) ||
        item.title.toLowerCase().includes(lower)
      );
    }
    return result;
  }, [records, searchTerm]);

  const exportCSV = () => {
    const headers = ['FSN', 'Brand', 'Title', 'Type', 'Start', 'End', ...cities].join(',');
    const rows = pivotData.map(row => {
      const cityVals = cities.map(c => row.values[c] || '').join(',');
      return `${row.fsn},${row.brand},${row.title},${row.type},${row.startDate},${row.endDate},${cityVals}`;
    }).join('\n');

    const blob = new Blob([headers + '\n' + rows], { type: 'text/csv' });
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `minutes_master_export_${Date.now()}.csv`;
    a.click();
  };

  // --- Action Handlers ---

  const handleEditClick = (row: PivotRow) => {
    setEditingRowKey(row.key);
    // Deep copy for form state
    setEditForm({
      ...row,
      values: { ...row.values }
    });
  };

  const handleCancelEdit = () => {
    setEditingRowKey(null);
    setEditForm(null);
  };

  const handleDeleteRow = async (row: PivotRow) => {
    if (!window.confirm(`Are you sure you want to delete all records for ${row.title} (${row.type})? This cannot be undone.`)) return;

    setProcessingAction(true);
    try {
      // Collect all record IDs in this row
      const idsToDelete = Object.values(row.cityRecords).filter(r => r !== undefined).map(r => r!.id);

      await Promise.all(idsToDelete.map(id => db.deleteRecord(id, user.name)));
      await loadData();
    } catch (e) {
      console.error(e);
      alert('Error deleting records');
    } finally {
      setProcessingAction(false);
    }
  };

  const handleSaveEdit = async (originalRow: PivotRow) => {
    if (!editForm) return;
    setProcessingAction(true);

    try {
      // 1. Check for common field changes (Dates)
      const dateChanged = editForm.startDate !== originalRow.startDate || editForm.endDate !== originalRow.endDate;

      // 2. Iterate Cities
      const promises: Promise<void>[] = [];

      for (const city of cities) {
        const oldValue = originalRow.values[city];
        const newValue = editForm.values?.[city];
        const existingRecord = originalRow.cityRecords[city];

        if (existingRecord) {
          // Update existing record if value changed OR dates changed
          if (newValue !== oldValue || dateChanged) {
            promises.push(db.updateRecord({
              ...existingRecord,
              startDate: editForm.startDate!,
              endDate: editForm.endDate!,
              value: newValue !== undefined ? Number(newValue) : existingRecord.value,
              lastUpdatedBy: user.name,
              lastUpdatedAt: Date.now()
            }));
          }
        } else if (newValue !== undefined && newValue !== 0) {
           // CREATE new record for this city if value added to empty cell
           promises.push(db.addRecords([{
             id: `rec_${Date.now()}_${Math.random().toString(36).substr(2,5)}`,
             fsn: originalRow.fsn,
             brand: originalRow.brand,
             title: originalRow.title,
             type: originalRow.type,
             city: city,
             startDate: editForm.startDate!,
             endDate: editForm.endDate!,
             value: Number(newValue),
             lastUpdatedBy: user.name,
             lastUpdatedAt: Date.now()
           }]));
        }
      }

      await Promise.all(promises);
      await loadData(); // Refresh

    } catch (e) {
      console.error(e);
      alert('Failed to save changes');
    } finally {
      setProcessingAction(false);
    }
  };

  return (
    <div className="space-y-4 animate-in fade-in slide-in-from-bottom-2 duration-500 h-full flex flex-col">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <h2 className="text-2xl font-bold text-white">Database Explorer</h2>
        <div className="flex gap-2">
           <div className="relative">
             <Filter className="absolute left-3 top-2.5 h-4 w-4 text-gray-500"/>
             <input 
               className="bg-slate-800 border border-slate-600 rounded-lg py-2 pl-9 pr-4 text-sm text-white focus:ring-2 focus:ring-fkBlue outline-none w-64"
               placeholder="Filter by FSN, Brand..."
               value={searchTerm}
               onChange={e => setSearchTerm(e.target.value)}
             />
           </div>
           <button onClick={loadData} className="p-2 bg-slate-800 rounded-lg hover:bg-slate-700 text-gray-300">
             <RefreshCw className={`h-5 w-5 ${loading ? 'animate-spin' : ''}`} />
           </button>
           <button onClick={exportCSV} className="flex items-center gap-2 px-4 py-2 bg-green-700 hover:bg-green-600 text-white rounded-lg text-sm font-medium">
             <Download className="h-4 w-4" /> Export
           </button>
        </div>
      </div>

      <div className="flex-1 glass-panel rounded-xl overflow-hidden border border-slate-700 flex flex-col relative">
        {processingAction && (
          <div className="absolute inset-0 bg-black/50 z-50 flex items-center justify-center backdrop-blur-sm">
            <RefreshCw className="w-8 h-8 text-fkBlue animate-spin" />
          </div>
        )}

        <div className="overflow-auto scrollbar-hide flex-1">
          <table className="w-full text-left border-collapse min-w-[1200px]">
            <thead className="bg-slate-900 sticky top-0 z-10 text-xs uppercase text-gray-400 shadow-md">
              <tr>
                <th className="p-4 border-b border-slate-700 min-w-[120px] bg-slate-900">FSN</th>
                <th className="p-4 border-b border-slate-700 bg-slate-900">Brand</th>
                <th className="p-4 border-b border-slate-700 bg-slate-900">Type</th>
                <th className="p-4 border-b border-slate-700 text-center min-w-[200px] bg-slate-900">Dates (Start - End)</th>
                {cities.map(c => (
                  <th key={c} className="p-4 border-b border-slate-700 text-center min-w-[80px] bg-slate-900/95 backdrop-blur">{c}</th>
                ))}
                <th className="p-4 border-b border-slate-700 text-center sticky right-0 bg-slate-900 z-20 w-24">Actions</th>
              </tr>
            </thead>
            <tbody className="text-sm divide-y divide-slate-800">
              {pivotData.map((row) => {
                const isEditing = editingRowKey === row.key;

                return (
                  <tr key={row.key} className={`hover:bg-white/5 transition-colors group ${isEditing ? 'bg-slate-800/50' : ''}`}>
                    <td className="p-4 font-mono text-fkBlue font-medium">{row.fsn}</td>
                    <td className="p-4 text-gray-300 max-w-[150px] truncate" title={row.brand}>{row.brand}</td>
                    <td className="p-4">
                      <span className={`px-2 py-1 rounded text-[10px] border whitespace-nowrap ${
                        row.type.includes('Margin') ? 'border-purple-500 text-purple-300 bg-purple-900/20' : 
                        'border-blue-500 text-blue-300 bg-blue-900/20'
                      }`}>
                        {row.type}
                      </span>
                    </td>

                    {/* Dates Column */}
                    <td className="p-4 text-gray-400 text-xs text-center">
                      {isEditing ? (
                        <div className="flex flex-col gap-2">
                           <input 
                             type="date" 
                             className="bg-slate-900 border border-slate-600 rounded px-2 py-1 text-white text-xs w-full"
                             value={editForm?.startDate || row.startDate}
                             onChange={e => setEditForm(prev => ({ ...prev!, startDate: e.target.value }))}
                           />
                           <input 
                             type="date" 
                             className="bg-slate-900 border border-slate-600 rounded px-2 py-1 text-white text-xs w-full"
                             value={editForm?.endDate || row.endDate}
                             onChange={e => setEditForm(prev => ({ ...prev!, endDate: e.target.value }))}
                           />
                        </div>
                      ) : (
                        <>
                          <div className="font-mono">{row.startDate}</div>
                          <div className="opacity-50 text-[10px]">to</div>
                          <div className="font-mono">{row.endDate}</div>
                        </>
                      )}
                    </td>

                    {/* City Columns */}
                    {cities.map(c => (
                      <td key={c} className={`p-2 text-center border-l border-slate-800/50 relative ${isEditing ? 'p-1' : ''}`}>
                         {isEditing ? (
                           <input 
                             type="number"
                             className="w-16 bg-slate-900 border border-slate-600 rounded px-1 py-1 text-center text-white text-sm focus:border-fkBlue outline-none"
                             value={editForm?.values?.[c] ?? ''}
                             placeholder="-"
                             onChange={e => {
                               const val = e.target.value;
                               setEditForm(prev => ({
                                 ...prev!,
                                 values: { ...prev!.values, [c]: val === '' ? undefined : parseFloat(val) }
                               }));
                             }}
                           />
                         ) : (
                           row.values[c] !== undefined ? (
                             <span className="font-semibold text-white">{row.values[c]}</span>
                           ) : (
                             <span className="text-gray-700">-</span>
                           )
                         )}
                      </td>
                    ))}

                    {/* Actions Column */}
                    <td className="p-4 border-l border-slate-700 sticky right-0 bg-slate-950 group-hover:bg-slate-900 transition-colors z-10">
                      <div className="flex items-center justify-center gap-2">
                        {isEditing ? (
                          <>
                            <button onClick={() => handleSaveEdit(row)} className="p-1.5 bg-green-600 hover:bg-green-500 rounded text-white shadow-lg" title="Save">
                              <Save className="w-4 h-4" />
                            </button>
                            <button onClick={handleCancelEdit} className="p-1.5 bg-slate-700 hover:bg-slate-600 rounded text-gray-300" title="Cancel">
                              <X className="w-4 h-4" />
                            </button>
                          </>
                        ) : (
                          <>
                            <button onClick={() => handleEditClick(row)} className="p-1.5 hover:bg-fkBlue/20 hover:text-fkBlue rounded text-gray-400 transition-colors" title="Edit Row">
                              <Edit2 className="w-4 h-4" />
                            </button>
                            <button onClick={() => handleDeleteRow(row)} className="p-1.5 hover:bg-red-900/30 hover:text-red-400 rounded text-gray-400 transition-colors" title="Delete Group">
                              <Trash2 className="w-4 h-4" />
                            </button>
                          </>
                        )}
                      </div>
                    </td>
                  </tr>
                );
              })}
              {pivotData.length === 0 && !loading && (
                 <tr><td colSpan={cities.length + 5} className="p-8 text-center text-gray-500">No records found matching your filters.</td></tr>
              )}
            </tbody>
          </table>
        </div>
        <div className="bg-slate-900 p-2 text-xs text-gray-500 text-center border-t border-slate-700">
          Showing {pivotData.length} grouped records. Edits apply to all underlying records.
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { CommercialRecord, CommercialType, DuplicateRequest, User, COMMERCIAL_TYPES } from '../types';
import { db } from '../services/db';
import { Plus, Upload, Save, AlertTriangle, FileText, X, Download, Check } from 'lucide-react';
import Papa from 'papaparse';

interface MakerProps {
  user: User;
}

export const MakerWorkspace: React.FC<MakerProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<'MANUAL' | 'BULK'>('MANUAL');

  // Dynamic Cities
  const [cities, setCities] = useState<string[]>([]);
  const [isAddingCity, setIsAddingCity] = useState(false);
  const [newCityCode, setNewCityCode] = useState('');

  // Manual Form State
  const [formData, setFormData] = useState<Partial<CommercialRecord>>({
    city: 'PAN-INDIA',
    type: CommercialType.MARGIN_PERCENT,
    startDate: new Date().toISOString().split('T')[0],
    endDate: new Date(new Date().setMonth(new Date().getMonth() + 3)).toISOString().split('T')[0]
  });

  // Bulk State
  const [bulkType, setBulkType] = useState<CommercialType>(CommercialType.MARGIN_PERCENT);

  const [loading, setLoading] = useState(false);
  const [notification, setNotification] = useState<{msg: string, type: 'success' | 'error' | 'warning' | null}>({ msg: '', type: null });

  // Load draft & cities
  useEffect(() => {
    const draft = localStorage.getItem('mm_draft_form');
    if (draft) setFormData(JSON.parse(draft));
    loadCities();
  }, []);

  // Save draft
  useEffect(() => {
    localStorage.setItem('mm_draft_form', JSON.stringify(formData));
  }, [formData]);

  const loadCities = async () => {
    const c = await db.getCities();
    setCities(c);
    // Ensure current selection is valid
    if (!c.includes(formData.city || 'PAN-INDIA')) {
       setFormData(prev => ({ ...prev, city: c[0] || 'PAN-INDIA' }));
    }
  };

  const handleAddNewCity = async () => {
    if (!newCityCode) return;

    const code = newCityCode.toUpperCase().trim();

    // Validation: Max 3 characters (Excluding PAN-INDIA which is system default)
    if (code !== 'PAN-INDIA' && code.length > 3) {
       setNotification({ msg: 'City code must be 3 characters or less (e.g., BLR).', type: 'error' });
       return;
    }

    const cleanCode = code.replace(/[^A-Z0-9]/g, '');

    if (!cleanCode) return;

    if (cities.includes(cleanCode)) {
       setNotification({ msg: `City ${cleanCode} already exists.`, type: 'warning' });
       return;
    }

    if (cleanCode) {
       await db.addCity(cleanCode);
       await loadCities();
       setFormData(prev => ({...prev, city: cleanCode}));
       setNewCityCode('');
       setIsAddingCity(false);
       setNotification({ msg: `City ${cleanCode} added to database.`, type: 'success' });
    }
  };

  const handleManualSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setNotification({ msg: '', type: null });

    if (!formData.fsn || !formData.value || !formData.brand || !formData.title) {
        setNotification({ msg: 'Please fill all fields', type: 'error' });
        return;
    }
    if (formData.endDate! < formData.startDate!) {
        setNotification({ msg: 'End Date cannot be before Start Date', type: 'error' });
        return;
    }

    setLoading(true);

    try {
      const records = await db.getRecords();

      // Strict Duplicate Check
      const isDuplicate = records.some(r => 
        r.fsn === formData.fsn &&
        r.city === formData.city &&
        r.type === formData.type &&
        r.startDate === formData.startDate &&
        r.endDate === formData.endDate &&
        r.value === Number(formData.value)
      );

      const isConflict = records.some(r => 
        r.fsn === formData.fsn &&
        r.city === formData.city &&
        r.type === formData.type &&
        r.startDate === formData.startDate &&
        r.endDate === formData.endDate
      );

      const newRecord: CommercialRecord = {
        id: `rec_${Date.now()}`,
        ...formData as CommercialRecord,
        value: Number(formData.value),
        lastUpdatedBy: user.name,
        lastUpdatedAt: Date.now()
      };

      if (isDuplicate) {
        setNotification({ msg: 'Exact duplicate already exists. No action taken.', type: 'warning' });
      } else if (isConflict) {
        // Create Request
        const req: DuplicateRequest = {
          id: `req_${Date.now()}`,
          originalRecordId: null,
          payload: newRecord,
          requestedBy: user.name,
          requestedAt: Date.now(),
          status: 'PENDING'
        };
        await db.createDuplicateRequest(req);
        setNotification({ msg: 'Conflict found. Override request sent to Checker.', type: 'warning' });
      } else {
        // Save
        await db.addRecords([newRecord]);
        setNotification({ msg: 'Record saved successfully.', type: 'success' });
        // Clear critical fields only
        setFormData(prev => ({ ...prev, fsn: '', value: 0 }));
      }
    } catch (err) {
      setNotification({ msg: 'Failed to save record.', type: 'error' });
    } finally {
      setLoading(false);
    }
  };

  // Bulk Upload Handler
  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    Papa.parse(file, {
      header: true,
      skipEmptyLines: true,
      complete: async (results) => {
        setLoading(true);
        const newRecords: CommercialRecord[] = [];
        const duplicates: CommercialRecord[] = [];

        const existingRecords = await db.getRecords();

        // Expected Columns: FSN, Brand, Title, StartDate, EndDate, [City Codes]
        // Type is determined by the active bulkType state, NOT the CSV column.

        results.data.forEach((row: any) => {
           // Basic validation
           if(!row.FSN) return;

           // Find city columns using Dynamic Cities List
           const cityKeys = Object.keys(row).filter(k => cities.includes(k) || k === 'Value');

           cityKeys.forEach(cityKey => {
             const city = cityKey === 'Value' ? 'PAN-INDIA' : cityKey;
             let val = parseFloat(row[cityKey]);
             if (isNaN(val)) return;

             // Auto-convert decimal to percent for Margin/Offers if user provides 0.1 for 10%
             if (bulkType !== CommercialType.NLC_VALUE && val <= 1 && val > 0) {
                val = val * 100;
             }

             const rec: CommercialRecord = {
               id: `rec_${Math.random().toString(36).substr(2,9)}`,
               fsn: row.FSN,
               brand: row.Brand || 'Unknown',
               title: row.Title || 'Bulk Upload Item',
               city: city,
               startDate: row.StartDate,
               endDate: row.EndDate,
               type: bulkType,
               value: val,
               lastUpdatedBy: user.name,
               lastUpdatedAt: Date.now()
             };

             // Check duplicate
             const exists = existingRecords.some(r => 
                r.fsn === rec.fsn &&
                r.city === rec.city &&
                r.type === rec.type &&
                r.startDate === rec.startDate &&
                r.endDate === rec.endDate
             );

             if (exists) {
               duplicates.push(rec);
             } else {
               newRecords.push(rec);
             }
           });
        });

        if (newRecords.length > 0) {
          await db.addRecords(newRecords);
        }

        if (duplicates.length > 0) {
           // Auto-create requests for duplicates (Bulk override flow)
           for (const dup of duplicates) {
              const req: DuplicateRequest = {
                id: `req_${Math.random().toString(36).substr(2,9)}`,
                originalRecordId: null,
                payload: dup,
                requestedBy: user.name,
                requestedAt: Date.now(),
                status: 'PENDING'
              };
              await db.createDuplicateRequest(req);
           }
           setNotification({ 
             msg: `Uploaded ${newRecords.length} records of type ${bulkType}. ${duplicates.length} conflicts sent for approval.`, 
             type: 'warning' 
           });
        } else {
           setNotification({ msg: `Successfully uploaded ${newRecords.length} records.`, type: 'success' });
        }
        setLoading(false);
      }
    });
  };

  const downloadTemplate = () => {
    // Generate Template CSV using Dynamic Cities
    const headers = ['FSN', 'Brand', 'Title', 'StartDate', 'EndDate', ...cities];

    // Example value based on current type
    const isNLC = bulkType === CommercialType.NLC_VALUE;
    const exampleVal = isNLC ? '50000' : '10';

    const dummyRows = [
        ['MOBEXAMPLE1', 'BrandX', 'Sample Product 1', '2024-01-01', '2024-03-31', ...cities.map(() => exampleVal)],
    ];

    const csvContent = [
        headers.join(','),
        ...dummyRows.map(row => row.join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv' });
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `minutes_master_${bulkType.replace(/\s/g, '').toLowerCase()}_template.csv`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    window.URL.revokeObjectURL(url);
  };

  return (
    <div className="space-y-6 animate-in slide-in-from-bottom-4 duration-500">
      <div className="flex justify-between items-center">
        <h2 className="text-2xl font-bold text-white">Maker Workspace</h2>
