export enum Role {
  MAKER = 'MAKER',
  CHECKER = 'CHECKER',
  ADMIN = 'ADMIN'
}

export enum CommercialType {
  MARGIN_PERCENT = 'Margin %',
  NLC_VALUE = 'NLC Value',
  ON_INVOICE = 'On Invoice %',
  OFF_INVOICE = 'Off Invoice %'
}

export interface User {
  id: string;
  employeeId: string;
  name: string;
  role: Role;
  pin?: string; // Encrypted in real app
}

export interface CommercialRecord {
  id: string;
  fsn: string;
  brand: string;
  title: string;
  city: string;
  startDate: string;
  endDate: string;
  type: CommercialType;
  value: number;
  lastUpdatedBy: string;
  lastUpdatedAt: number;
}

export interface DuplicateRequest {
  id: string;
  originalRecordId: string | null; // Null if it's a new conflict without ID yet, but usually maps to existing
  payload: CommercialRecord;
  requestedBy: string;
  requestedAt: number;
  status: 'PENDING' | 'APPROVED' | 'REJECTED';
}

export const CITIES = [
  'PAN-INDIA', 'BLR', 'DEL', 'MUM', 'KOL', 'CHE', 'HYD', 'PUN'
];

export const COMMERCIAL_TYPES = [
  CommercialType.MARGIN_PERCENT,
  CommercialType.NLC_VALUE,
  CommercialType.ON_INVOICE,
  CommercialType.OFF_INVOICE
];

import { CommercialRecord, DuplicateRequest, User, Role, CommercialType, CITIES as DEFAULT_CITIES } from '../types';

// In a real scenario, we would import firebase/firestore here.
// For this demo, we simulate the Firestore persistence and latency.

const STORAGE_KEYS = {
  USERS: 'mm_users',
  RECORDS: 'mm_records',
  REQUESTS: 'mm_requests',
  BIN: 'mm_bin',
  CITIES: 'mm_cities'
};

// Seed Data
const SEED_USERS: User[] = [
  { id: '1', employeeId: 'maker1', name: 'Alice Maker', role: Role.MAKER },
  { id: '2', employeeId: 'checker1', name: 'Bob Checker', role: Role.CHECKER, pin: '1234' },
  { id: '3', employeeId: 'admin1', name: 'Charlie Admin', role: Role.ADMIN, pin: '9999' },
