import React, { useState, useEffect, useMemo } from 'react';
import { db } from '../services/db';
import { CommercialRecord, User } from '../types';
import { Download, Filter, RefreshCw, Trash2, Edit2, Save, X, AlertTriangle } from 'lucide-react';

interface DataExplorerProps {
  user: User;
}

interface PivotRow {
  key: string;
  fsn: string;
  brand: string;
  title: string;
  type: any;
  startDate: string;
  endDate: string;
  cityRecords: { [key: string]: CommercialRecord | undefined };
  values: { [key: string]: number | undefined };
}

export const DataExplorer: React.FC<DataExplorerProps> = ({ user }) => {
  const [records, setRecords] = useState<CommercialRecord[]>([]);
  const [cities, setCities] = useState<string[]>([]);
  const [loading, setLoading] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');

  // Edit State
  const [editingRowKey, setEditingRowKey] = useState<string | null>(null);
  const [editForm, setEditForm] = useState<Partial<PivotRow> | null>(null);
  const [processingAction, setProcessingAction] = useState(false);

  const loadData = async () => {
    setLoading(true);
    const [data, c] = await Promise.all([db.getRecords(), db.getCities()]);
    setRecords(data);
    setCities(c);
    setLoading(false);
    setEditingRowKey(null);
    setEditForm(null);
  };

  useEffect(() => {
    loadData();
  }, []);

  const pivotData: PivotRow[] = useMemo(() => {
    const map = new Map<string, PivotRow>();

    records.forEach(r => {
      const key = `${r.fsn}_${r.type}_${r.startDate}_${r.endDate}`;
      if (!map.has(key)) {
        map.set(key, {
          key,
          fsn: r.fsn,
          brand: r.brand,
          title: r.title,
          type: r.type,
          startDate: r.startDate,
          endDate: r.endDate,
          cityRecords: {},
          values: {}
        });
      }
      const entry = map.get(key)!;
      entry.cityRecords[r.city] = r;
      entry.values[r.city] = r.value;
    });

    let result = Array.from(map.values());
    if (searchTerm) {
      const lower = searchTerm.toLowerCase();
      result = result.filter(item => 
        item.fsn.toLowerCase().includes(lower) || 
        item.brand.toLowerCase().includes(lower) ||
        item.title.toLowerCase().includes(lower)
      );
    }
    return result;
  }, [records, searchTerm]);

  const exportCSV = () => {
    const headers = ['FSN', 'Brand', 'Title', 'Type', 'Start', 'End', ...cities].join(',');
    const rows = pivotData.map(row => {
      const cityVals = cities.map(c => row.values[c] || '').join(',');
      return `${row.fsn},${row.brand},${row.title},${row.type},${row.startDate},${row.endDate},${cityVals}`;
    }).join('\n');

    const blob = new Blob([headers + '\n' + rows], { type: 'text/csv' });
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `minutes_master_export_${Date.now()}.csv`;
    a.click();
  };

  // --- Action Handlers ---

  const handleEditClick = (row: PivotRow) => {
    setEditingRowKey(row.key);
    // Deep copy for form state
    setEditForm({
      ...row,
      values: { ...row.values }
    });
  };

  const handleCancelEdit = () => {
    setEditingRowKey(null);
    setEditForm(null);
  };

  const handleDeleteRow = async (row: PivotRow) => {
    if (!window.confirm(`Are you sure you want to delete all records for ${row.title} (${row.type})? This cannot be undone.`)) return;

    setProcessingAction(true);
    try {
      // Collect all record IDs in this row
      const idsToDelete = Object.values(row.cityRecords).filter(r => r !== undefined).map(r => r!.id);

      // Use bulk delete to prevent race conditions in simulation
      await db.deleteRecords(idsToDelete, user.name);

      await loadData();
    } catch (e) {
      console.error(e);
      alert('Error deleting records');
    } finally {
      setProcessingAction(false);
    }
  };

  const handleSaveEdit = async (originalRow: PivotRow) => {
    if (!editForm) return;
    setProcessingAction(true);

    try {
      // 1. Check for common field changes (Dates)
      const dateChanged = editForm.startDate !== originalRow.startDate || editForm.endDate !== originalRow.endDate;

      // 2. Iterate Cities
      const promises: Promise<void>[] = [];

      for (const city of cities) {
        const oldValue = originalRow.values[city];
        const newValue = editForm.values?.[city];
        const existingRecord = originalRow.cityRecords[city];

        if (existingRecord) {
          // Update existing record if value changed OR dates changed
          if (newValue !== oldValue || dateChanged) {
            promises.push(db.updateRecord({
              ...existingRecord,
              startDate: editForm.startDate!,
              endDate: editForm.endDate!,
              value: newValue !== undefined ? Number(newValue) : existingRecord.value,
              lastUpdatedBy: user.name,
              lastUpdatedAt: Date.now()
            }));
          }
        } else if (newValue !== undefined && newValue !== 0) {
           // CREATE new record for this city if value added to empty cell
           promises.push(db.addRecords([{
             id: `rec_${Date.now()}_${Math.random().toString(36).substr(2,5)}`,
             fsn: originalRow.fsn,
             brand: originalRow.brand,
             title: originalRow.title,
             type: originalRow.type,
             city: city,
             startDate: editForm.startDate!,
             endDate: editForm.endDate!,
             value: Number(newValue),
             lastUpdatedBy: user.name,
             lastUpdatedAt: Date.now()
           }]));
        }
      }

      await Promise.all(promises);
      await loadData(); // Refresh

    } catch (e) {
      console.error(e);
      alert('Failed to save changes');
    } finally {
      setProcessingAction(false);
    }
  };

  return (
    <div className="space-y-4 animate-in fade-in slide-in-from-bottom-2 duration-500 h-full flex flex-col">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <h2 className="text-2xl font-bold text-white">Database Explorer</h2>
        <div className="flex gap-2">
           <div className="relative">
             <Filter className="absolute left-3 top-2.5 h-4 w-4 text-gray-500"/>
             <input 
               className="bg-slate-800 border border-slate-600 rounded-lg py-2 pl-9 pr-4 text-sm text-white focus:ring-2 focus:ring-fkBlue outline-none w-64"
               placeholder="Filter by FSN, Brand..."
               value={searchTerm}
               onChange={e => setSearchTerm(e.target.value)}
             />
           </div>
           <button onClick={loadData} className="p-2 bg-slate-800 rounded-lg hover:bg-slate-700 text-gray-300">
             <RefreshCw className={`h-5 w-5 ${loading ? 'animate-spin' : ''}`} />
           </button>
           <button onClick={exportCSV} className="flex items-center gap-2 px-4 py-2 bg-green-700 hover:bg-green-600 text-white rounded-lg text-sm font-medium">
             <Download className="h-4 w-4" /> Export
           </button>
        </div>
      </div>

      <div className="flex-1 glass-panel rounded-xl overflow-hidden border border-slate-700 flex flex-col relative">
        {processingAction && (
          <div className="absolute inset-0 bg-black/50 z-50 flex items-center justify-center backdrop-blur-sm">
            <RefreshCw className="w-8 h-8 text-fkBlue animate-spin" />
          </div>
        )}

        <div className="overflow-auto scrollbar-hide flex-1">
          <table className="w-full text-left border-collapse min-w-[1200px]">
            <thead className="bg-slate-900 sticky top-0 z-10 text-xs uppercase text-gray-400 shadow-md">
              <tr>
                <th className="p-4 border-b border-slate-700 min-w-[120px] bg-slate-900">FSN</th>
                <th className="p-4 border-b border-slate-700 bg-slate-900">Brand</th>
                <th className="p-4 border-b border-slate-700 bg-slate-900">Type</th>
                <th className="p-4 border-b border-slate-700 text-center min-w-[200px] bg-slate-900">Dates (Start - End)</th>
                {cities.map(c => (
                  <th key={c} className="p-4 border-b border-slate-700 text-center min-w-[80px] bg-slate-900/95 backdrop-blur">{c}</th>
                ))}
                <th className="p-4 border-b border-slate-700 text-center sticky right-0 bg-slate-900 z-20 w-24">Actions</th>
              </tr>
            </thead>
            <tbody className="text-sm divide-y divide-slate-800">
              {pivotData.map((row) => {
                const isEditing = editingRowKey === row.key;

                return (
                  <tr key={row.key} className={`hover:bg-white/5 transition-colors group ${isEditing ? 'bg-slate-800/50' : ''}`}>
                    <td className="p-4 font-mono text-fkBlue font-medium">{row.fsn}</td>
                    <td className="p-4 text-gray-300 max-w-[150px] truncate" title={row.brand}>{row.brand}</td>
                    <td className="p-4">
                      <span className={`px-2 py-1 rounded text-[10px] border whitespace-nowrap ${
                        row.type.includes('Margin') ? 'border-purple-500 text-purple-300 bg-purple-900/20' : 
                        'border-blue-500 text-blue-300 bg-blue-900/20'
                      }`}>
                        {row.type}
                      </span>
                    </td>

                    {/* Dates Column */}
                    <td className="p-4 text-gray-400 text-xs text-center">
                      {isEditing ? (
                        <div className="flex flex-col gap-2">
                           <input 
                             type="date" 
                             className="bg-slate-900 border border-slate-600 rounded px-2 py-1 text-white text-xs w-full"
                             value={editForm?.startDate || row.startDate}
                             onChange={e => setEditForm(prev => ({ ...prev!, startDate: e.target.value }))}
                           />
                           <input 
                             type="date" 
                             className="bg-slate-900 border border-slate-600 rounded px-2 py-1 text-white text-xs w-full"
                             value={editForm?.endDate || row.endDate}
                             onChange={e => setEditForm(prev => ({ ...prev!, endDate: e.target.value }))}
                           />
                        </div>
                      ) : (
                        <>
                          <div className="font-mono">{row.startDate}</div>
                          <div className="opacity-50 text-[10px]">to</div>
                          <div className="font-mono">{row.endDate}</div>
                        </>
                      )}
                    </td>

                    {/* City Columns */}
                    {cities.map(c => (
                      <td key={c} className={`p-2 text-center border-l border-slate-800/50 relative ${isEditing ? 'p-1' : ''}`}>
                         {isEditing ? (
                           <input 
                             type="number"
                             className="w-16 bg-slate-900 border border-slate-600 rounded px-1 py-1 text-center text-white text-sm focus:border-fkBlue outline-none"
                             value={editForm?.values?.[c] ?? ''}
                             placeholder="-"
                             onChange={e => {
                               const val = e.target.value;
                               setEditForm(prev => ({
                                 ...prev!,
                                 values: { ...prev!.values, [c]: val === '' ? undefined : parseFloat(val) }
                               }));
                             }}
                           />
                         ) : (
                           row.values[c] !== undefined ? (
                             <span className="font-semibold text-white">{row.values[c]}</span>
                           ) : (
                             <span className="text-gray-700">-</span>
                           )
                         )}
                      </td>
                    ))}

                    {/* Actions Column */}
                    <td className="p-4 border-l border-slate-700 sticky right-0 bg-slate-950 group-hover:bg-slate-900 transition-colors z-10">
                      <div className="flex items-center justify-center gap-2">
                        {isEditing ? (
                          <>
                            <button onClick={() => handleSaveEdit(row)} className="p-1.5 bg-green-600 hover:bg-green-500 rounded text-white shadow-lg" title="Save">
                              <Save className="w-4 h-4" />
                            </button>
                            <button onClick={handleCancelEdit} className="p-1.5 bg-slate-700 hover:bg-slate-600 rounded text-gray-300" title="Cancel">
                              <X className="w-4 h-4" />
                            </button>
                          </>
                        ) : (
                          <>
                            <button onClick={() => handleEditClick(row)} className="p-1.5 hover:bg-fkBlue/20 hover:text-fkBlue rounded text-gray-400 transition-colors" title="Edit Row">
                              <Edit2 className="w-4 h-4" />
                            </button>
                            <button onClick={() => handleDeleteRow(row)} className="p-1.5 hover:bg-red-900/30 hover:text-red-400 rounded text-gray-400 transition-colors" title="Delete Group">
                              <Trash2 className="w-4 h-4" />
                            </button>
                          </>
                        )}
                      </div>
                    </td>
                  </tr>
                );
              })}
              {pivotData.length === 0 && !loading && (
                 <tr><td colSpan={cities.length + 5} className="p-8 text-center text-gray-500">No records found matching your filters.</td></tr>
              )}
            </tbody>
          </table>
        </div>
        <div className="bg-slate-900 p-2 text-xs text-gray-500 text-center border-t border-slate-700">
          Showing {pivotData.length} grouped records. Edits apply to all underlying records.
        </div>
      </div>
    </div>
  );
};

