  { id: '1', employeeId: 'maker1', name: 'Alice Maker', role: Role.MAKER },
  { id: '2', employeeId: 'checker1', name: 'Bob Checker', role: Role.CHECKER, pin: '1234' },
  { id: '3', employeeId: 'admin1', name: 'Charlie Admin', role: Role.ADMIN, pin: '9999' },
];

// Empty seed records so data is user-generated only
const SEED_RECORDS: CommercialRecord[] = [];

// Helper to simulate network delay
const delay = (ms: number) => new Promise(res => setTimeout(res, ms));

type RecordListener = (records: CommercialRecord[]) => void;

class DBService {
  private listeners: RecordListener[] = [];

  constructor() {
    this.init();
  }

  init() {
    if (!localStorage.getItem(STORAGE_KEYS.USERS)) {
      localStorage.setItem(STORAGE_KEYS.USERS, JSON.stringify(SEED_USERS));
    }
    if (!localStorage.getItem(STORAGE_KEYS.RECORDS)) {
      localStorage.setItem(STORAGE_KEYS.RECORDS, JSON.stringify(SEED_RECORDS));
    }
    if (!localStorage.getItem(STORAGE_KEYS.REQUESTS)) {
      localStorage.setItem(STORAGE_KEYS.REQUESTS, JSON.stringify([]));
    }
    if (!localStorage.getItem(STORAGE_KEYS.BIN)) {
      localStorage.setItem(STORAGE_KEYS.BIN, JSON.stringify([]));
    }
    if (!localStorage.getItem(STORAGE_KEYS.CITIES)) {
      localStorage.setItem(STORAGE_KEYS.CITIES, JSON.stringify(DEFAULT_CITIES));
    }
  }

  // Real-time Subscription (Simulating onSnapshot)
  subscribeToRecords(callback: RecordListener): () => void {
    this.listeners.push(callback);
    // Initial data push
    this.getRecords().then(records => callback(records));

    // Unsubscribe function
    return () => {
      this.listeners = this.listeners.filter(l => l !== callback);
    };
  }

  private async notifyListeners() {
    const records = await this.getRecords();
    this.listeners.forEach(l => l(records));
  }

  // Auth
  async login(employeeId: string): Promise<User | null> {
    await delay(500);
    try {
      const users: User[] = JSON.parse(localStorage.getItem(STORAGE_KEYS.USERS) || '[]');
      return users.find(u => u.employeeId === employeeId) || null;
    } catch (e) {
      console.error('Error parsing users', e);
      return null;
    }
  }

  async verifyPin(userId: string, pin: string): Promise<boolean> {
    await delay(300);
    try {
      const users: User[] = JSON.parse(localStorage.getItem(STORAGE_KEYS.USERS) || '[]');
      const user = users.find(u => u.id === userId);
      return user ? user.pin === pin : false;
    } catch (e) {
      return false;
    }
  }

  // Cities
  async getCities(): Promise<string[]> {
    await delay(100);
    try {
      return JSON.parse(localStorage.getItem(STORAGE_KEYS.CITIES) || JSON.stringify(DEFAULT_CITIES));
    } catch (e) {
      return DEFAULT_CITIES;
    }
  }

  async addCity(city: string): Promise<void> {
    await delay(300);
    const cities = await this.getCities();
    if (!cities.includes(city)) {
      cities.push(city);
      localStorage.setItem(STORAGE_KEYS.CITIES, JSON.stringify(cities));
    }
  }

  async deleteCity(city: string): Promise<void> {
    await delay(300);
    const cities = await this.getCities();
    const target = city.trim();
    const updated = cities.filter(c => c !== target);
    localStorage.setItem(STORAGE_KEYS.CITIES, JSON.stringify(updated));
  }

  // Records
  async getRecords(): Promise<CommercialRecord[]> {
    await delay(200); // Simulate Firestore cache read
    try {
      return JSON.parse(localStorage.getItem(STORAGE_KEYS.RECORDS) || '[]');
    } catch (e) {
      console.error('Error parsing records', e);
      return [];
    }
  }

  async addRecords(records: CommercialRecord[]): Promise<void> {
    await delay(600);
    const current = await this.getRecords();
    const updated = [...current, ...records];
    localStorage.setItem(STORAGE_KEYS.RECORDS, JSON.stringify(updated));
    this.notifyListeners();
  }

  async updateRecord(updatedRecord: CommercialRecord): Promise<void> {
    await delay(400);
    const current = await this.getRecords();
    const index = current.findIndex(r => r.id === updatedRecord.id);
    if (index !== -1) {
      current[index] = updatedRecord;
      localStorage.setItem(STORAGE_KEYS.RECORDS, JSON.stringify(current));
      this.notifyListeners();
    }
  }

  // Bulk update to prevent race conditions in simulation and support robust editing
  async updateRecords(updatedRecords: CommercialRecord[]): Promise<void> {
    await delay(600);
    const current = await this.getRecords();

    updatedRecords.forEach(update => {
        const index = current.findIndex(r => r.id === update.id);
        if (index !== -1) {
            current[index] = update;
        }
    });

    localStorage.setItem(STORAGE_KEYS.RECORDS, JSON.stringify(current));
    this.notifyListeners();
  }

  async deleteRecord(recordId: string, movedToBinBy: string): Promise<void> {
    await delay(400);
    const current = await this.getRecords();
    const record = current.find(r => r.id === recordId);
    if(record) {
        // Move to Bin
        try {
          const bin = JSON.parse(localStorage.getItem(STORAGE_KEYS.BIN) || '[]');
          bin.push({ ...record, deletedBy: movedToBinBy, deletedAt: Date.now() });
          localStorage.setItem(STORAGE_KEYS.BIN, JSON.stringify(bin));
        } catch (e) { console.error(e); }

        // Remove
        const updated = current.filter(r => r.id !== recordId);
        localStorage.setItem(STORAGE_KEYS.RECORDS, JSON.stringify(updated));
        this.notifyListeners();
    }
  }

  async deleteRecords(recordIds: string[], movedToBinBy: string): Promise<void> {
    await delay(400);
    const current = await this.getRecords();
    let bin = [];
    try {
       bin = JSON.parse(localStorage.getItem(STORAGE_KEYS.BIN) || '[]');
    } catch(e) { console.error('Bin parse error', e); }

    const timestamp = Date.now();

    // Identify records to delete
    const recordsToDelete = current.filter(r => recordIds.includes(r.id));

    // Add to bin
    recordsToDelete.forEach(r => {
        bin.push({ ...r, deletedBy: movedToBinBy, deletedAt: timestamp });
    });

    // Remove from main storage
    const updated = current.filter(r => !recordIds.includes(r.id));

    localStorage.setItem(STORAGE_KEYS.BIN, JSON.stringify(bin));
    localStorage.setItem(STORAGE_KEYS.RECORDS, JSON.stringify(updated));
    this.notifyListeners();
  }

  async getDuplicateRequests(): Promise<DuplicateRequest[]> {
    await delay(200);
    try {
      return JSON.parse(localStorage.getItem(STORAGE_KEYS.REQUESTS) || '[]');
    } catch (e) { return []; }
  }

  async createDuplicateRequest(request: DuplicateRequest): Promise<void> {
    await delay(400);
    const current = await this.getDuplicateRequests();
    localStorage.setItem(STORAGE_KEYS.REQUESTS, JSON.stringify([...current, request]));
  }

  async resolveDuplicateRequest(requestId: string, status: 'APPROVED' | 'REJECTED', resolverId: string): Promise<void> {
    await delay(500);
    const requests: DuplicateRequest[] = await this.getDuplicateRequests();
    const requestIndex = requests.findIndex(r => r.id === requestId);

    if (requestIndex === -1) return;

    const request = requests[requestIndex];
    request.status = status;

    if (status === 'APPROVED') {
      // Find existing potential conflict to archive
      const allRecords = await this.getRecords();

      // Strict matching logic for replacement
      const conflictingIndex = allRecords.findIndex(r => 
        r.fsn === request.payload.fsn &&
        r.city === request.payload.city &&
        r.type === request.payload.type &&
        r.startDate === request.payload.startDate &&
        r.endDate === request.payload.endDate
      );

      if (conflictingIndex !== -1) {
        // Move old to bin
        await this.deleteRecord(allRecords[conflictingIndex].id, resolverId);
      }

      // Add new
      await this.addRecords([request.payload]);
    }

    // Update Request List
    requests[requestIndex] = request;
    localStorage.setItem(STORAGE_KEYS.REQUESTS, JSON.stringify(requests));
  }
}

export const db = new DBService();

import React, { useState, useEffect, useMemo } from 'react';
import { db } from '../services/db';
import { CommercialRecord, User, Role, COMMERCIAL_TYPES, CommercialType } from '../types';
import { Download, Filter, RefreshCw, Trash2, Edit2, Save, X, AlertTriangle } from 'lucide-react';

interface DataExplorerProps {
  user: User;
}

interface PivotRow {
  key: string;
  fsn: string;
  brand: string;
  title: string;
  type: CommercialType;
  startDate: string;
  endDate: string;
  cityRecords: { [key: string]: CommercialRecord | undefined };
  values: { [key: string]: number | undefined };
}

export const DataExplorer: React.FC<DataExplorerProps> = ({ user }) => {
  const [records, setRecords] = useState<CommercialRecord[]>([]);
  const [cities, setCities] = useState<string[]>([]);
  const [loading, setLoading] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');

  // Edit State
  const [editingRowKey, setEditingRowKey] = useState<string | null>(null);
  const [editForm, setEditForm] = useState<Partial<PivotRow> | null>(null);
  const [processingAction, setProcessingAction] = useState(false);

  // Permission Check
  const canEdit = user.role !== Role.MAKER;

  useEffect(() => {
    let unsubscribe: () => void;

    const init = async () => {
      setLoading(true);
      try {
        // Load cities once (or could subscribe if needed)
        const c = await db.getCities();
        setCities(c);

        // Subscribe to real-time updates for records
        unsubscribe = db.subscribeToRecords((data) => {
          setRecords(data);
          setLoading(false);
          // Clear edit mode if data changes externally to prevent conflicts, 
          // or we could keep it if we want persistent forms, but clearing is safer for now.
          // Note: If we are editing, we might not want to clear immediately on every update, 
          // but for this implementation we'll keep the form open but potentially stale if not careful.
          // However, we reset edit state on successful action completion anyway.
        });
      } catch (e) {
        console.error("Failed to load data", e);
        setLoading(false);
      }
    };

    init();

    return () => {
      if (unsubscribe) unsubscribe();
    };
  }, []);

  const pivotData: PivotRow[] = useMemo(() => {
    const map = new Map<string, PivotRow>();

    records.forEach(r => {
      const key = `${r.fsn}_${r.type}_${r.startDate}_${r.endDate}`;
      if (!map.has(key)) {
        map.set(key, {
          key,
          fsn: r.fsn,
          brand: r.brand,
          title: r.title,
          type: r.type,
          startDate: r.startDate,
          endDate: r.endDate,
          cityRecords: {},
          values: {}
        });
      }
      const entry = map.get(key)!;
      entry.cityRecords[r.city] = r;
      entry.values[r.city] = r.value;
    });

    let result = Array.from(map.values());
    if (searchTerm) {
      const lower = searchTerm.toLowerCase();
      result = result.filter(item => 
        item.fsn.toLowerCase().includes(lower) || 
        item.brand.toLowerCase().includes(lower) ||
        item.title.toLowerCase().includes(lower)
      );
    }
    return result;
  }, [records, searchTerm]);

  const exportCSV = () => {
    const headers = ['FSN', 'Brand', 'Title', 'Type', 'Start', 'End', ...cities].join(',');
    const rows = pivotData.map(row => {
      const cityVals = cities.map(c => row.values[c] || '').join(',');
      return `${row.fsn},${row.brand},${row.title},${row.type},${row.startDate},${row.endDate},${cityVals}`;
    }).join('\n');

    const blob = new Blob([headers + '\n' + rows], { type: 'text/csv' });
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `minutes_master_export_${Date.now()}.csv`;
    a.click();
  };

  // --- Action Handlers ---

  const handleEditClick = (row: PivotRow) => {
    setEditingRowKey(row.key);
    // Deep copy for form state
    setEditForm({
      ...row,
      values: { ...row.values }
    });
  };

  const handleCancelEdit = () => {
    setEditingRowKey(null);
    setEditForm(null);
  };

  const handleDeleteRow = async (row: PivotRow) => {
    if (!canEdit) return;
    if (!window.confirm(`Are you sure you want to delete all records for ${row.title} (${row.type})? This cannot be undone.`)) return;

    setProcessingAction(true);
    try {
      // Filter the MAIN records array to find ALL IDs matching this row's criteria.
      const idsToDelete = records
        .filter(r => 
          r.fsn === row.fsn &&
          r.type === row.type &&
          r.startDate === row.startDate &&
          r.endDate === row.endDate
        )
        .map(r => r.id);

      if (idsToDelete.length === 0) {
        alert("No records found to delete.");
        return;
      }

      await db.deleteRecords(idsToDelete, user.name);
      // No need to loadData(), subscription handles it
    } catch (e) {
      console.error(e);
      alert('Error deleting records: ' + (e as any).message);
    } finally {
      setProcessingAction(false);
    }
  };

  const handleSaveEdit = async (originalRow: PivotRow) => {
    if (!editForm || !canEdit) return;
    setProcessingAction(true);

    try {
      // 1. Identify records to update based on ORIGINAL row criteria
      const recordsToUpdate = records.filter(r => 
          r.fsn === originalRow.fsn &&
          r.type === originalRow.type &&
          r.startDate === originalRow.startDate &&
          r.endDate === originalRow.endDate
      );

      const updatePromises: Promise<void>[] = [];
      const recordsForBulkUpdate: CommercialRecord[] = [];

      // 2. Prepare updates for existing records
      recordsToUpdate.forEach(r => {
        const newCityValue = editForm.values?.[r.city];

        // Prepare updated object
        const updatedRecord: CommercialRecord = {
          ...r,
          fsn: editForm.fsn || r.fsn,
          brand: editForm.brand || r.brand,
          title: editForm.title || r.title,
          type: editForm.type || r.type,
          startDate: editForm.startDate || r.startDate,
          endDate: editForm.endDate || r.endDate,
          value: newCityValue !== undefined ? Number(newCityValue) : r.value,
          lastUpdatedBy: user.name,
          lastUpdatedAt: Date.now()
        };

        recordsForBulkUpdate.push(updatedRecord);
      });

      if (recordsForBulkUpdate.length > 0) {
          updatePromises.push(db.updateRecords(recordsForBulkUpdate));
      }

      // 3. Create NEW records for cities that were added during edit
      for (const city of cities) {
        const hasExisting = recordsToUpdate.some(r => r.city === city);
        const newVal = editForm.values?.[city];

        if (!hasExisting && newVal !== undefined && newVal !== '' && Number(newVal) !== 0) {
           updatePromises.push(db.addRecords([{
             id: `rec_${Date.now()}_${Math.random().toString(36).substr(2,5)}`,
             fsn: editForm.fsn!,
             brand: editForm.brand!,
             title: editForm.title!,
             type: editForm.type!,
             city: city,
             startDate: editForm.startDate!,
             endDate: editForm.endDate!,
             value: Number(newVal),
             lastUpdatedBy: user.name,
             lastUpdatedAt: Date.now()
           }]));
        }
      }

      await Promise.all(updatePromises);
      setEditingRowKey(null);
      setEditForm(null);

    } catch (e) {
      console.error(e);
      alert('Failed to save changes');
    } finally {
      setProcessingAction(false);
    }
  };

  // Helper to trigger manual city refresh if needed, though mostly static
  const refreshCities = async () => {
    setLoading(true);
    const c = await db.getCities();
    setCities(c);
    setLoading(false);
  };

  return (
    <div className="space-y-4 animate-in fade-in slide-in-from-bottom-2 duration-500 h-full flex flex-col">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <h2 className="text-2xl font-bold text-white">Database Explorer</h2>
        <div className="flex gap-2">
           <div className="relative">
             <Filter className="absolute left-3 top-2.5 h-4 w-4 text-gray-500"/>
             <input 
               className="bg-slate-800 border border-slate-600 rounded-lg py-2 pl-9 pr-4 text-sm text-white focus:ring-2 focus:ring-fkBlue outline-none w-64"
               placeholder="Filter by FSN, Brand..."
               value={searchTerm}
               onChange={e => setSearchTerm(e.target.value)}
             />
           </div>
           <button onClick={refreshCities} className="p-2 bg-slate-800 rounded-lg hover:bg-slate-700 text-gray-300">
             <RefreshCw className={`h-5 w-5 ${loading ? 'animate-spin' : ''}`} />
           </button>
           <button onClick={exportCSV} className="flex items-center gap-2 px-4 py-2 bg-green-700 hover:bg-green-600 text-white rounded-lg text-sm font-medium">
             <Download className="h-4 w-4" /> Export
           </button>
        </div>
      </div>

      <div className="flex-1 glass-panel rounded-xl overflow-hidden border border-slate-700 flex flex-col relative">
        {processingAction && (
          <div className="absolute inset-0 bg-black/50 z-50 flex items-center justify-center backdrop-blur-sm">
            <RefreshCw className="w-8 h-8 text-fkBlue animate-spin" />
          </div>
        )}

        <div className="overflow-auto scrollbar-hide flex-1">
          <table className="w-full text-left border-collapse min-w-[1400px]">
            <thead className="bg-slate-900 sticky top-0 z-10 text-xs uppercase text-gray-400 shadow-md">
              <tr>
                <th className="p-4 border-b border-slate-700 min-w-[120px] bg-slate-900">FSN</th>
                <th className="p-4 border-b border-slate-700 bg-slate-900">Brand</th>
                <th className="p-4 border-b border-slate-700 bg-slate-900">Title</th>
                <th className="p-4 border-b border-slate-700 bg-slate-900 min-w-[120px]">Type</th>
                <th className="p-4 border-b border-slate-700 text-center min-w-[200px] bg-slate-900">Dates (Start - End)</th>
                {cities.map(c => (
                  <th key={c} className="p-4 border-b border-slate-700 text-center min-w-[80px] bg-slate-900/95 backdrop-blur">{c}</th>
                ))}
                {canEdit && (
                  <th className="p-4 border-b border-slate-700 text-center sticky right-0 bg-slate-900 z-20 w-24">Actions</th>
                )}
              </tr>
            </thead>
            <tbody className="text-sm divide-y divide-slate-800">
              {pivotData.map((row) => {
                const isEditing = editingRowKey === row.key;

                return (
                  <tr key={row.key} className={`hover:bg-white/5 transition-colors group ${isEditing ? 'bg-slate-800/50' : ''}`}>
                    {/* FSN */}
                    <td className="p-4 font-mono text-fkBlue font-medium">
                        {isEditing ? (
                            <input 
                              className="w-full bg-slate-900 border border-slate-600 rounded px-2 py-1 text-white text-xs font-mono"
                              value={editForm?.fsn || ''}
                              onChange={e => setEditForm(prev => ({ ...prev!, fsn: e.target.value }))}
                            />
                        ) : row.fsn}
                    </td>

                    {/* Brand */}
                    <td className="p-4 text-gray-300 max-w-[150px] truncate">
                        {isEditing ? (
                            <input 
                              className="w-full bg-slate-900 border border-slate-600 rounded px-2 py-1 text-white text-xs"
                              value={editForm?.brand || ''}
                              onChange={e => setEditForm(prev => ({ ...prev!, brand: e.target.value }))}
                            />
                        ) : row.brand}
                    </td>

                    {/* Title */}
                    <td className="p-4 text-gray-300 max-w-[200px] truncate" title={row.title}>
                        {isEditing ? (
                            <input 
                              className="w-full bg-slate-900 border border-slate-600 rounded px-2 py-1 text-white text-xs"
                              value={editForm?.title || ''}
                              onChange={e => setEditForm(prev => ({ ...prev!, title: e.target.value }))}
                            />
                        ) : row.title}
                    </td>

                    {/* Type */}
                    <td className="p-4">
                      {isEditing ? (
                          <select 
                             className="w-full bg-slate-900 border border-slate-600 rounded px-2 py-1 text-white text-xs"
                             value={editForm?.type}
                             onChange={e => setEditForm(prev => ({ ...prev!, type: e.target.value as CommercialType }))}
                          >
                            {COMMERCIAL_TYPES.map(t => <option key={t} value={t}>{t}</option>)}
                          </select>
                      ) : (
                          <span className={`px-2 py-1 rounded text-[10px] border whitespace-nowrap ${
                            row.type.includes('Margin') ? 'border-purple-500 text-purple-300 bg-purple-900/20' : 
                            'border-blue-500 text-blue-300 bg-blue-900/20'
                          }`}>
                            {row.type}
                          </span>
                      )}
                    </td>

                    {/* Dates */}
                    <td className="p-4 text-gray-400 text-xs text-center">
                      {isEditing ? (
                        <div className="flex flex-col gap-2">
                           <input 
                             type="date" 
                             className="bg-slate-900 border border-slate-600 rounded px-2 py-1 text-white text-xs w-full"
                             value={editForm?.startDate || row.startDate}
                             onChange={e => setEditForm(prev => ({ ...prev!, startDate: e.target.value }))}
                           />
                           <input 
                             type="date" 
                             className="bg-slate-900 border border-slate-600 rounded px-2 py-1 text-white text-xs w-full"
                             value={editForm?.endDate || row.endDate}
                             onChange={e => setEditForm(prev => ({ ...prev!, endDate: e.target.value }))}
                           />
                        </div>
                      ) : (
                        <>
                          <div className="font-mono">{row.startDate}</div>
                          <div className="opacity-50 text-[10px]">to</div>
                          <div className="font-mono">{row.endDate}</div>
                        </>
                      )}
                    </td>

                    {/* City Values */}
                    {cities.map(c => (
                      <td key={c} className={`p-2 text-center border-l border-slate-800/50 relative ${isEditing ? 'p-1' : ''}`}>
                         {isEditing ? (
                           <input 
                             type="number"
                             className="w-16 bg-slate-900 border border-slate-600 rounded px-1 py-1 text-center text-white text-sm focus:border-fkBlue outline-none"
                             value={editForm?.values?.[c] ?? ''}
                             placeholder="-"
                             onChange={e => {
                               const val = e.target.value;
                               setEditForm(prev => ({
                                 ...prev!,
                                 values: { ...prev!.values, [c]: val === '' ? undefined : parseFloat(val) }
                               }));
                             }}
                           />
                         ) : (
                           row.values[c] !== undefined ? (
                             <span className="font-semibold text-white">{row.values[c]}</span>
                           ) : (
                             <span className="text-gray-700">-</span>
                           )
                         )}
                      </td>
                    ))}

                    {/* Actions */}
                    {canEdit && (
                      <td className="p-4 border-l border-slate-700 sticky right-0 bg-slate-950 group-hover:bg-slate-900 transition-colors z-10">
                        <div className="flex items-center justify-center gap-2">
                          {isEditing ? (
                            <>
                              <button onClick={() => handleSaveEdit(row)} className="p-1.5 bg-green-600 hover:bg-green-500 rounded text-white shadow-lg" title="Save">
                                <Save className="w-4 h-4" />
                              </button>
                              <button onClick={handleCancelEdit} className="p-1.5 bg-slate-700 hover:bg-slate-600 rounded text-gray-300" title="Cancel">
                                <X className="w-4 h-4" />
                              </button>
                            </>
                          ) : (
                            <>
                              <button onClick={() => handleEditClick(row)} className="p-1.5 hover:bg-fkBlue/20 hover:text-fkBlue rounded text-gray-400 transition-colors" title="Edit Row">
                                <Edit2 className="w-4 h-4" />
                              </button>
                              <button onClick={() => handleDeleteRow(row)} className="p-1.5 hover:bg-red-900/30 hover:text-red-400 rounded text-gray-400 transition-colors" title="Delete Group">
                                <Trash2 className="w-4 h-4" />
                              </button>
                            </>
                          )}
                        </div>
                      </td>
                    )}
                  </tr>
                );
              })}
              {pivotData.length === 0 && !loading && (
                 <tr><td colSpan={cities.length + 6} className="p-8 text-center text-gray-500">No records found matching your filters.</td></tr>
              )}
            </tbody>
          </table>
        </div>
        <div className="bg-slate-900 p-2 text-xs text-gray-500 text-center border-t border-slate-700">
          Showing {pivotData.length} grouped records. {canEdit && 'Edits apply to all underlying records.'}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { db } from '../services/db';
import { CommercialRecord, User, Role, COMMERCIAL_TYPES, CommercialType } from '../types';
import { Download, Filter, RefreshCw, Trash2, Edit2, Save, X, AlertTriangle } from 'lucide-react';

interface DataExplorerProps {
  user: User;
}

interface PivotRow {
  key: string;
  fsn: string;
  brand: string;
  title: string;
  type: CommercialType;
  startDate: string;
  endDate: string;
  cityRecords: { [key: string]: CommercialRecord | undefined };
  values: { [key: string]: number | undefined };
}

export const DataExplorer: React.FC<DataExplorerProps> = ({ user }) => {
  const [records, setRecords] = useState<CommercialRecord[]>([]);
  const [cities, setCities] = useState<string[]>([]);
  const [loading, setLoading] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');

  // Edit State
  const [editingRowKey, setEditingRowKey] = useState<string | null>(null);
  const [editForm, setEditForm] = useState<Partial<PivotRow> | null>(null);
  const [processingAction, setProcessingAction] = useState(false);

  // Permission Check
  const canEdit = user.role !== Role.MAKER;

  useEffect(() => {
    let unsubscribe: () => void;

    const init = async () => {
      setLoading(true);
      try {
        // Load cities once (or could subscribe if needed)
        const c = await db.getCities();
        setCities(c);

        // Subscribe to real-time updates for records
        unsubscribe = db.subscribeToRecords((data) => {
          setRecords(data);
          setLoading(false);
          // Clear edit mode if data changes externally to prevent conflicts, 
          // or we could keep it if we want persistent forms, but clearing is safer for now.
          // Note: If we are editing, we might not want to clear immediately on every update, 
          // but for this implementation we'll keep the form open but potentially stale if not careful.
          // However, we reset edit state on successful action completion anyway.
        });
      } catch (e) {
        console.error("Failed to load data", e);
        setLoading(false);
      }
    };

    init();

    return () => {
      if (unsubscribe) unsubscribe();
    };
  }, []);

  const pivotData: PivotRow[] = useMemo(() => {
    const map = new Map<string, PivotRow>();

    records.forEach(r => {
      const key = `${r.fsn}_${r.type}_${r.startDate}_${r.endDate}`;
      if (!map.has(key)) {
        map.set(key, {
          key,
          fsn: r.fsn,
          brand: r.brand,
          title: r.title,
          type: r.type,
          startDate: r.startDate,
          endDate: r.endDate,
          cityRecords: {},
          values: {}
        });
      }
      const entry = map.get(key)!;
      entry.cityRecords[r.city] = r;
      entry.values[r.city] = r.value;
    });

    let result = Array.from(map.values());
    if (searchTerm) {
      const lower = searchTerm.toLowerCase();
      result = result.filter(item => 
        item.fsn.toLowerCase().includes(lower) || 
        item.brand.toLowerCase().includes(lower) ||
        item.title.toLowerCase().includes(lower)
      );
    }
    return result;
  }, [records, searchTerm]);

  const exportCSV = () => {
    const headers = ['FSN', 'Brand', 'Title', 'Type', 'Start', 'End', ...cities].join(',');
    const rows = pivotData.map(row => {
      const cityVals = cities.map(c => row.values[c] || '').join(',');
      return `${row.fsn},${row.brand},${row.title},${row.type},${row.startDate},${row.endDate},${cityVals}`;
    }).join('\n');

    const blob = new Blob([headers + '\n' + rows], { type: 'text/csv' });
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `minutes_master_export_${Date.now()}.csv`;
    a.click();
  };

  // --- Action Handlers ---

  const handleEditClick = (row: PivotRow) => {
    setEditingRowKey(row.key);
    // Deep copy for form state
    setEditForm({
      ...row,
      values: { ...row.values }
    });
  };

  const handleCancelEdit = () => {
    setEditingRowKey(null);
    setEditForm(null);
  };

  const handleDeleteRow = async (row: PivotRow) => {
    if (!canEdit) return;
    if (!window.confirm(`Are you sure you want to delete all records for ${row.title} (${row.type})? This cannot be undone.`)) return;

    setProcessingAction(true);
    try {
      // Filter the MAIN records array to find ALL IDs matching this row's criteria.
      const idsToDelete = records
        .filter(r => 
          r.fsn === row.fsn &&
          r.type === row.type &&
          r.startDate === row.startDate &&
          r.endDate === row.endDate
        )
        .map(r => r.id);

      if (idsToDelete.length === 0) {
        alert("No records found to delete.");
        return;
      }

      await db.deleteRecords(idsToDelete, user.name);
      // No need to loadData(), subscription handles it
    } catch (e) {
      console.error(e);
      alert('Error deleting records: ' + (e as any).message);
    } finally {
      setProcessingAction(false);
    }
  };

  const handleSaveEdit = async (originalRow: PivotRow) => {
    if (!editForm || !canEdit) return;
    setProcessingAction(true);

    try {
      // 1. Identify records to update based on ORIGINAL row criteria
      const recordsToUpdate = records.filter(r => 
          r.fsn === originalRow.fsn &&
          r.type === originalRow.type &&
          r.startDate === originalRow.startDate &&
          r.endDate === originalRow.endDate
      );

      const updatePromises: Promise<void>[] = [];
      const recordsForBulkUpdate: CommercialRecord[] = [];

      // 2. Prepare updates for existing records
      recordsToUpdate.forEach(r => {
        const newCityValue = editForm.values?.[r.city];

        // Prepare updated object
        const updatedRecord: CommercialRecord = {
          ...r,
          fsn: editForm.fsn || r.fsn,
          brand: editForm.brand || r.brand,
          title: editForm.title || r.title,
          type: editForm.type || r.type,
          startDate: editForm.startDate || r.startDate,
          endDate: editForm.endDate || r.endDate,
          value: newCityValue !== undefined ? Number(newCityValue) : r.value,
          lastUpdatedBy: user.name,
          lastUpdatedAt: Date.now()
        };

        recordsForBulkUpdate.push(updatedRecord);
      });

      if (recordsForBulkUpdate.length > 0) {
          updatePromises.push(db.updateRecords(recordsForBulkUpdate));
      }

      // 3. Create NEW records for cities that were added during edit
      for (const city of cities) {
        const hasExisting = recordsToUpdate.some(r => r.city === city);
        const newVal = editForm.values?.[city];

        if (!hasExisting && newVal !== undefined && Number(newVal) !== 0) {
           updatePromises.push(db.addRecords([{
             id: `rec_${Date.now()}_${Math.random().toString(36).substr(2,5)}`,
             fsn: editForm.fsn!,
             brand: editForm.brand!,
             title: editForm.title!,
             type: editForm.type!,
             city: city,
             startDate: editForm.startDate!,
             endDate: editForm.endDate!,
             value: Number(newVal),
             lastUpdatedBy: user.name,
             lastUpdatedAt: Date.now()
           }]));
        }
      }

      await Promise.all(updatePromises);
      setEditingRowKey(null);
      setEditForm(null);

    } catch (e) {
      console.error(e);
      alert('Failed to save changes');
    } finally {
      setProcessingAction(false);
    }
  };

  // Helper to trigger manual city refresh if needed, though mostly static
  const refreshCities = async () => {
    setLoading(true);
    const c = await db.getCities();
    setCities(c);
    setLoading(false);
  };

  return (
    <div className="space-y-4 animate-in fade-in slide-in-from-bottom-2 duration-500 h-full flex flex-col">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <h2 className="text-2xl font-bold text-white">Database Explorer</h2>
        <div className="flex gap-2">
           <div className="relative">
             <Filter className="absolute left-3 top-2.5 h-4 w-4 text-gray-500"/>
             <input 
               className="bg-slate-800 border border-slate-600 rounded-lg py-2 pl-9 pr-4 text-sm text-white focus:ring-2 focus:ring-fkBlue outline-none w-64"
               placeholder="Filter by FSN, Brand..."
               value={searchTerm}
               onChange={e => setSearchTerm(e.target.value)}
             />
           </div>
           <button onClick={refreshCities} className="p-2 bg-slate-800 rounded-lg hover:bg-slate-700 text-gray-300">
             <RefreshCw className={`h-5 w-5 ${loading ? 'animate-spin' : ''}`} />
           </button>
           <button onClick={exportCSV} className="flex items-center gap-2 px-4 py-2 bg-green-700 hover:bg-green-600 text-white rounded-lg text-sm font-medium">
             <Download className="h-4 w-4" /> Export
           </button>
        </div>
      </div>

      <div className="flex-1 glass-panel rounded-xl overflow-hidden border border-slate-700 flex flex-col relative">
        {processingAction && (
          <div className="absolute inset-0 bg-black/50 z-50 flex items-center justify-center backdrop-blur-sm">
            <RefreshCw className="w-8 h-8 text-fkBlue animate-spin" />
          </div>
        )}

        <div className="overflow-auto scrollbar-hide flex-1">
          <table className="w-full text-left border-collapse min-w-[1400px]">
            <thead className="bg-slate-900 sticky top-0 z-10 text-xs uppercase text-gray-400 shadow-md">
              <tr>
                <th className="p-4 border-b border-slate-700 min-w-[120px] bg-slate-900">FSN</th>
                <th className="p-4 border-b border-slate-700 bg-slate-900">Brand</th>
                <th className="p-4 border-b border-slate-700 bg-slate-900">Title</th>
                <th className="p-4 border-b border-slate-700 bg-slate-900 min-w-[120px]">Type</th>
                <th className="p-4 border-b border-slate-700 text-center min-w-[200px] bg-slate-900">Dates (Start - End)</th>
                {cities.map(c => (
                  <th key={c} className="p-4 border-b border-slate-700 text-center min-w-[80px] bg-slate-900/95 backdrop-blur">{c}</th>
                ))}
                {canEdit && (
                  <th className="p-4 border-b border-slate-700 text-center sticky right-0 bg-slate-900 z-20 w-24">Actions</th>
                )}
              </tr>
            </thead>
            <tbody className="text-sm divide-y divide-slate-800">
              {pivotData.map((row) => {
                const isEditing = editingRowKey === row.key;

                return (
                  <tr key={row.key} className={`hover:bg-white/5 transition-colors group ${isEditing ? 'bg-slate-800/50' : ''}`}>
                    {/* FSN */}
                    <td className="p-4 font-mono text-fkBlue font-medium">
                        {isEditing ? (
                            <input 
                              className="w-full bg-slate-900 border border-slate-600 rounded px-2 py-1 text-white text-xs font-mono"
                              value={editForm?.fsn || ''}
                              onChange={e => setEditForm(prev => ({ ...prev!, fsn: e.target.value }))}
                            />
                        ) : row.fsn}
                    </td>

                    {/* Brand */}
                    <td className="p-4 text-gray-300 max-w-[150px] truncate">
                        {isEditing ? (
                            <input 
                              className="w-full bg-slate-900 border border-slate-600 rounded px-2 py-1 text-white text-xs"
                              value={editForm?.brand || ''}
                              onChange={e => setEditForm(prev => ({ ...prev!, brand: e.target.value }))}
                            />
                        ) : row.brand}
                    </td>

                    {/* Title */}
                    <td className="p-4 text-gray-300 max-w-[200px] truncate" title={row.title}>
                        {isEditing ? (
                            <input 
                              className="w-full bg-slate-900 border border-slate-600 rounded px-2 py-1 text-white text-xs"
                              value={editForm?.title || ''}
                              onChange={e => setEditForm(prev => ({ ...prev!, title: e.target.value }))}
                            />
                        ) : row.title}
                    </td>

                    {/* Type */}
                    <td className="p-4">
                      {isEditing ? (
                          <select 
                             className="w-full bg-slate-900 border border-slate-600 rounded px-2 py-1 text-white text-xs"
                             value={editForm?.type}
                             onChange={e => setEditForm(prev => ({ ...prev!, type: e.target.value as CommercialType }))}
                          >
                            {COMMERCIAL_TYPES.map(t => <option key={t} value={t}>{t}</option>)}
                          </select>
                      ) : (
                          <span className={`px-2 py-1 rounded text-[10px] border whitespace-nowrap ${
                            row.type.includes('Margin') ? 'border-purple-500 text-purple-300 bg-purple-900/20' : 
                            'border-blue-500 text-blue-300 bg-blue-900/20'
                          }`}>
                            {row.type}
                          </span>
                      )}
                    </td>

                    {/* Dates */}
                    <td className="p-4 text-gray-400 text-xs text-center">
                      {isEditing ? (
                        <div className="flex flex-col gap-2">
                           <input 
                             type="date" 
                             className="bg-slate-900 border border-slate-600 rounded px-2 py-1 text-white text-xs w-full"
                             value={editForm?.startDate || row.startDate}
                             onChange={e => setEditForm(prev => ({ ...prev!, startDate: e.target.value }))}
                           />
                           <input 
                             type="date" 
                             className="bg-slate-900 border border-slate-600 rounded px-2 py-1 text-white text-xs w-full"
                             value={editForm?.endDate || row.endDate}
                             onChange={e => setEditForm(prev => ({ ...prev!, endDate: e.target.value }))}
                           />
                        </div>
                      ) : (
                        <>
                          <div className="font-mono">{row.startDate}</div>
                          <div className="opacity-50 text-[10px]">to</div>
                          <div className="font-mono">{row.endDate}</div>
                        </>
                      )}
                    </td>

                    {/* City Values */}
                    {cities.map(c => (
                      <td key={c} className={`p-2 text-center border-l border-slate-800/50 relative ${isEditing ? 'p-1' : ''}`}>
                         {isEditing ? (
                           <input 
                             type="number"
                             className="w-16 bg-slate-900 border border-slate-600 rounded px-1 py-1 text-center text-white text-sm focus:border-fkBlue outline-none"
                             value={editForm?.values?.[c] ?? ''}
                             placeholder="-"
                             onChange={e => {
                               const val = e.target.value;
                               setEditForm(prev => ({
                                 ...prev!,
                                 values: { ...prev!.values, [c]: val === '' ? undefined : parseFloat(val) }
                               }));
                             }}
                           />
                         ) : (
                           row.values[c] !== undefined ? (
                             <span className="font-semibold text-white">{row.values[c]}</span>
                           ) : (
                             <span className="text-gray-700">-</span>
                           )
                         )}
                      </td>
                    ))}

                    {/* Actions */}
                    {canEdit && (
                      <td className="p-4 border-l border-slate-700 sticky right-0 bg-slate-950 group-hover:bg-slate-900 transition-colors z-10">
                        <div className="flex items-center justify-center gap-2">
                          {isEditing ? (
                            <>
                              <button onClick={() => handleSaveEdit(row)} className="p-1.5 bg-green-600 hover:bg-green-500 rounded text-white shadow-lg" title="Save">
                                <Save className="w-4 h-4" />
                              </button>
                              <button onClick={handleCancelEdit} className="p-1.5 bg-slate-700 hover:bg-slate-600 rounded text-gray-300" title="Cancel">
                                <X className="w-4 h-4" />
                              </button>
                            </>
                          ) : (
                            <>
                              <button onClick={() => handleEditClick(row)} className="p-1.5 hover:bg-fkBlue/20 hover:text-fkBlue rounded text-gray-400 transition-colors" title="Edit Row">
                                <Edit2 className="w-4 h-4" />
                              </button>
                              <button onClick={() => handleDeleteRow(row)} className="p-1.5 hover:bg-red-900/30 hover:text-red-400 rounded text-gray-400 transition-colors" title="Delete Group">
                                <Trash2 className="w-4 h-4" />
                              </button>
                            </>
                          )}
                        </div>
                      </td>
                    )}
                  </tr>
                );
              })}
              {pivotData.length === 0 && !loading && (
                 <tr><td colSpan={cities.length + 6} className="p-8 text-center text-gray-500">No records found matching your filters.</td></tr>
              )}
            </tbody>
          </table>
        </div>
        <div className="bg-slate-900 p-2 text-xs text-gray-500 text-center border-t border-slate-700">
          Showing {pivotData.length} grouped records. {canEdit && 'Edits apply to all underlying records.'}
        </div>
      </div>
    </div>
  );
};

