        <description>Enhance Audit Tool visualization with stacked bars, variance percentage, and improved status indicators.</description>
        <content><![CDATA[import React, { useState, useEffect } from 'react';
import { db } from '../services/firebase';
import { onValue, ref, update, get } from 'firebase/database';
import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
  ResponsiveContainer,
  LabelList,
  ReferenceLine
} from 'recharts';
import { TrendingUp, AlertCircle } from 'react-feather';
import { useAuth } from '../context/AuthContext';

interface AuditResult {
  status: 'MATCH' | 'MISMATCH' | 'PENDING';
  variance: number;
  variancePercentage: string;
  nlc: number;
  onInv: number;
  systemTotal: number;
  target: number;
}

interface CheckerWorkspaceProps {
  checkerId: string;
}

const CheckerWorkspace: React.FC<CheckerWorkspaceProps> = ({ checkerId }) => {
  const [auditResult, setAuditResult] = useState<AuditResult>({
    status: 'PENDING',
    variance: 0,
    variancePercentage: '',
    nlc: 0,
    onInv: 0,
    systemTotal: 0,
    target: 0,
  });
  const [data, setData] = useState<any[]>([
    { name: 'System', nlc: 0, onInv: 0, target: 0 },
    { name: 'Target', target: 0 },
  ]);
  const { currentUser } = useAuth();
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const auditRef = ref(db, `checkers/${checkerId}/auditResult`);

    const unsubscribe = onValue(auditRef, (snapshot) => {
      const data = snapshot.val();
      if (data) {
        setAuditResult(data);
        setData([
          {
            name: 'System',
            nlc: data.nlc,
            onInv: data.onInv,
            target: 0,
          },
          { name: 'Target', target: data.target },
        ]);
      } else {
        setAuditResult({
          status: 'PENDING',
          variance: 0,
          variancePercentage: '',
          nlc: 0,
          onInv: 0,
          systemTotal: 0,
          target: 0,
        });
      }
      setLoading(false);
    });

    return () => unsubscribe();
  }, [checkerId]);

  const handleManualAudit = async (manualTarget: number) => {
    if (!currentUser || !checkerId) {
      console.error('User not authenticated or checkerId missing');
      return;
    }
    setLoading(true);

    try {
      const checkerRef = ref(db, `checkers/${checkerId}`);
      const snapshot = await get(checkerRef);
      if (!snapshot.exists()) {
        console.error('Checker not found in the database');
        setLoading(false);
        return;
      }

      const existingData = snapshot.val();
      const systemTotal = existingData.systemSum;

      // Ensure that `systemTotal` and `manualTarget` are numbers.
      if (typeof systemTotal !== 'number' || typeof manualTarget !== 'number') {
        console.error('Invalid input: systemSum or manualTarget is not a number');
        setLoading(false);
        return;
      }

      // Calculate variance
      const variance = systemTotal - manualTarget;

      // Calculate variance percentage. Avoid division by zero.
      const variancePercentage = systemTotal !== 0 ? ((variance / systemTotal) * 100) : 0;
