import React, { useState, useEffect } from 'react';
import { db } from '../services/db';
import { CommercialRecord, DuplicateRequest, User, CommercialType } from '../types';
import { Check, X, Search, BarChart3, Archive, ShieldCheck, TrendingUp, AlertCircle } from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer, ReferenceLine, LabelList } from 'recharts';

interface CheckerProps {
  user: User;
}

export const CheckerWorkspace: React.FC<CheckerProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<'AUDIT' | 'APPROVALS'>('AUDIT');
  const [requests, setRequests] = useState<DuplicateRequest[]>([]);
  const [cities, setCities] = useState<string[]>([]);

  // Audit State
  const [auditQuery, setAuditQuery] = useState({ fsn: '', city: 'BLR', targetMargin: 0 });
  const [auditResult, setAuditResult] = useState<any>(null);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    loadRequests();
    loadCities();

    // Real-time setup would happen here with onSnapshot
    const interval = setInterval(loadRequests, 5000); // Polling for demo
    return () => clearInterval(interval);
  }, []);

  const loadCities = async () => {
    const c = await db.getCities();
    setCities(c);
    // Set default if not set
    if (!c.includes(auditQuery.city)) {
       setAuditQuery(prev => ({ ...prev, city: c.includes('BLR') ? 'BLR' : c[0] || '' }));
    }
  };

  const loadRequests = async () => {
    const reqs = await db.getDuplicateRequests();
    setRequests(reqs.filter(r => r.status === 'PENDING'));
  };

  const handleAudit = async () => {
    if (!auditQuery.fsn) return;
    setLoading(true);
    const records = await db.getRecords();

    // Filter relevant records
    const relevant = records.filter(r => 
      r.fsn === auditQuery.fsn && 
      (r.city === auditQuery.city || r.city === 'PAN-INDIA')
    );

    // Calc Sums
    const nlc = relevant.find(r => r.type === CommercialType.NLC_VALUE)?.value || 0;
    const onInv = relevant.find(r => r.type === CommercialType.ON_INVOICE)?.value || 0;

    const systemTotal = nlc + onInv; 
    const variance = auditQuery.targetMargin - systemTotal;
    const variancePercent = auditQuery.targetMargin ? ((variance / auditQuery.targetMargin) * 100) : 0;

    setAuditResult({
      data: [
        { 
            name: 'System', 
            nlc: nlc, 
            onInv: onInv,
            total: systemTotal 
        },
        { 
            name: 'Target', 
            target: auditQuery.targetMargin 
        }
      ],
      systemTotal,
      targetTotal: auditQuery.targetMargin,
      variance,
      variancePercent: variancePercent.toFixed(2),
      status: Math.abs(variance) < 0.1 ? 'MATCH' : 'MISMATCH',
      details: relevant
    });
    setLoading(false);
  };

  const handleRequestAction = async (reqId: string, action: 'APPROVED' | 'REJECTED') => {
    await db.resolveDuplicateRequest(reqId, action, user.id);
    loadRequests();
  };

  const CustomTooltip = ({ active, payload, label }: any) => {
    if (active && payload && payload.length) {
      return (
        <div className="bg-slate-800 border border-slate-600 p-3 rounded-lg shadow-xl text-xs">
          <p className="font-bold text-gray-300 mb-2">{label}</p>
          {payload.map((entry: any, index: number) => (
            <div key={index} className="flex items-center gap-2 mb-1">
               <div className="w-2 h-2 rounded-full" style={{ backgroundColor: entry.color }} />
               <span className="text-gray-400">{entry.name}:</span>
               <span className="text-white font-mono font-bold">{Number(entry.value).toFixed(2)}</span>
            </div>
          ))}
          {label === 'System' && (
             <div className="mt-2 pt-2 border-t border-slate-700 flex justify-between gap-4">
                <span className="text-gray-300 font-bold">Total:</span>
                <span className="text-white font-mono font-bold">{payload.reduce((acc: number, cur: any) => acc + (cur.value || 0), 0).toFixed(2)}</span>
             </div>
          )}
        </div>
      );
    }
    return null;
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      <div className="flex justify-between items-center border-b border-gray-800 pb-4">
        <h2 className="text-2xl font-bold text-white flex items-center gap-2">
           <ShieldCheck className="text-green-400 w-6 h-6" /> Checker Workspace
        </h2>
        <div className="flex gap-4">
          <button onClick={() => setActiveTab('AUDIT')} className={`text-sm font-bold ${activeTab === 'AUDIT' ? 'text-fkBlue' : 'text-gray-400'}`}>AUDIT TOOL</button>
          <button onClick={() => setActiveTab('APPROVALS')} className={`text-sm font-bold flex items-center gap-2 ${activeTab === 'APPROVALS' ? 'text-fkBlue' : 'text-gray-400'}`}>
            APPROVALS 
            {requests.length > 0 && <span className="bg-red-500 text-white text-[10px] px-1.5 py-0.5 rounded-full">{requests.length}</span>}
          </button>
        </div>
      </div>

      {activeTab === 'AUDIT' ? (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          <div className="lg:col-span-1 space-y-4">
            <div className="glass-panel p-6 rounded-xl">
              <h3 className="text-lg font-semibold mb-4 text-gray-200">Commercial Audit</h3>
              <div className="space-y-3">
                <input 
                  className="w-full bg-slate-800 border border-slate-600 rounded p-2 text-white" 
                  placeholder="FSN to Audit"
                  value={auditQuery.fsn}
                  onChange={e => setAuditQuery({...auditQuery, fsn: e.target.value})}
                />
                <select 
                  className="w-full bg-slate-800 border border-slate-600 rounded p-2 text-white"
                  value={auditQuery.city}
                  onChange={e => setAuditQuery({...auditQuery, city: e.target.value})}
                >
                  {cities.map(c => <option key={c} value={c}>{c}</option>)}
                </select>
                <input 
                  type="number"
                  className="w-full bg-slate-800 border border-slate-600 rounded p-2 text-white" 
                  placeholder="Expected Total Value"
                  value={auditQuery.targetMargin || ''}
                  onChange={e => setAuditQuery({...auditQuery, targetMargin: parseFloat(e.target.value)})}
                />
                <button 
                  onClick={handleAudit}
                  disabled={loading}
                  className="w-full bg-fkBlue hover:bg-blue-600 text-white font-bold py-2 rounded transition-colors"
                >
                  {loading ? 'Analyzing...' : 'Run Analysis'}
                </button>
              </div>
            </div>

            {auditResult && (
              <div className={`p-4 rounded-xl border animate-in zoom-in duration-300 ${auditResult.status === 'MATCH' ? 'bg-green-900/20 border-green-800' : 'bg-red-900/20 border-red-800'}`}>
                 <div className="flex justify-between items-start mb-2">
                    <div className={`text-xl font-bold flex items-center gap-2 ${auditResult.status === 'MATCH' ? 'text-green-400' : 'text-red-400'}`}>
                        {auditResult.status === 'MATCH' ? <Check className="w-5 h-5"/> : <AlertCircle className="w-5 h-5"/>}
                        {auditResult.status}
                    </div>
                    {auditResult.status === 'MISMATCH' && (
                        <div className="text-xs font-bold px-2 py-1 bg-red-900/50 text-red-200 rounded">
                             Variance Detected
                        </div>
                    )}
                 </div>

                 <div className="mt-4 grid grid-cols-2 gap-4">
                     <div>
                         <p className="text-xs text-gray-400 uppercase">Variance Val</p>
                         <p className={`text-xl font-mono font-bold ${auditResult.variance > 0 ? 'text-green-300' : 'text-red-300'}`}>
                            {auditResult.variance > 0 ? '+' : ''}{auditResult.variance.toFixed(2)}
                         </p>
                     </div>
                     <div>
                         <p className="text-xs text-gray-400 uppercase">Variance %</p>
                         <div className="flex items-center gap-1">
                            <TrendingUp className={`w-4 h-4 ${parseFloat(auditResult.variancePercent) > 0 ? 'text-green-400' : 'text-red-400'}`} />
                            <p className="text-xl font-mono font-bold text-white">
                                {Math.abs(Number(auditResult.variancePercent))}%
                            </p>
                         </div>
                     </div>
                 </div>
              </div>
            )}
          </div>

          <div className="lg:col-span-2 glass-panel p-6 rounded-xl min-h-[400px]">
            {auditResult ? (
              <div className="h-full w-full">
                <ResponsiveContainer width="100%" height={350}>
                    <BarChart data={auditResult.data} margin={{ top: 20, right: 30, left: 20, bottom: 5 }}>
                        <CartesianGrid strokeDasharray="3 3" stroke="#333" />
                        <XAxis dataKey="name" stroke="#888" tick={{fill: '#9ca3af'}} />
                        <YAxis stroke="#888" tick={{fill: '#9ca3af'}} />
                        <Tooltip content={<CustomTooltip />} cursor={{fill: 'rgba(255,255,255,0.05)'}} />
                        <Legend wrapperStyle={{ paddingTop: '20px' }} />

                        {/* System Stack: Broken down into components */}
                        <Bar dataKey="nlc" stackId="system" name="NLC Value" fill="#2874f0" radius={[0, 0, 4, 4]}>
                           <LabelList dataKey="nlc" position="center" className="fill-white/90 font-bold text-[10px]" formatter={(v: number) => v > 0 ? v.toFixed(0) : ''} />
                        </Bar>
                        <Bar dataKey="onInv" stackId="system" name="On Invoice %" fill="#8b5cf6" radius={[4, 4, 0, 0]}>
                           <LabelList dataKey="onInv" position="center" className="fill-white/90 font-bold text-[10px]" formatter={(v: number) => v > 0 ? v.toFixed(0) : ''} />
                        </Bar>

                        {/* Target Stack: Single bar */}
                        <Bar dataKey="target" stackId="target" name="User Target" fill={auditResult.status === 'MATCH' ? '#10b981' : '#f59e0b'} radius={[4, 4, 4, 4]}>
                             <LabelList dataKey="target" position="top" className="fill-gray-400 font-bold text-xs" formatter={(v: number) => v.toFixed(2)} />
                        </Bar>

                        {/* Reference Line for Target Margin if Mismatch */}
                        {auditResult.status === 'MISMATCH' && (
                             <ReferenceLine 
                                y={auditResult.targetTotal} 
                                stroke="#f59e0b" 
                                strokeDasharray="3 3" 
                                label={{ position: 'right', value: 'Target', fill: '#f59e0b', fontSize: 10 }} 
                             />
                        )}
                    </BarChart>
                </ResponsiveContainer>
              </div>
            ) : (
              <div className="h-full flex flex-col items-center justify-center text-gray-500">
                <BarChart3 className="w-16 h-16 mb-4 opacity-20" />
                <p>Run an audit to view visualization</p>
              </div>
            )}
          </div>
        </div>
      ) : (
        <div className="space-y-4">
          {requests.length === 0 ? (
            <div className="text-center py-20 text-gray-500">
              <Check className="w-12 h-12 mx-auto mb-3 opacity-20" />
              <p>No pending approvals. Good job!</p>
            </div>
          ) : (
            requests.map(req => (
              <div key={req.id} className="glass-panel p-4 rounded-xl flex flex-col md:flex-row justify-between items-start md:items-center gap-4 border-l-4 border-yellow-500">
                <div>
                  <div className="flex items-center gap-2 mb-1">
                    <span className="bg-yellow-500/20 text-yellow-400 text-xs px-2 py-0.5 rounded font-mono">CONFLICT</span>
                    <h4 className="font-bold text-white">{req.payload.title} ({req.payload.fsn})</h4>
                  </div>
                  <div className="text-sm text-gray-400 grid grid-cols-2 md:grid-cols-4 gap-x-8 gap-y-1">
                    <span>City: <b className="text-gray-200">{req.payload.city}</b></span>
                    <span>Type: <b className="text-gray-200">{req.payload.type}</b></span>
                    <span>New Value: <b className="text-fkYellow">{req.payload.value}</b></span>
                    <span>By: {req.requestedBy}</span>
                  </div>
                </div>
                <div className="flex gap-2 w-full md:w-auto">
                  <button 
                    onClick={() => handleRequestAction(req.id, 'REJECTED')}
                    className="flex-1 md:flex-none px-4 py-2 rounded bg-slate-700 hover:bg-slate-600 text-white text-sm transition-colors"
                  >
                    Reject
                  </button>
                  <button 
                    onClick={() => handleRequestAction(req.id, 'APPROVED')}
                    className="flex-1 md:flex-none px-4 py-2 rounded bg-green-600 hover:bg-green-500 text-white font-bold text-sm shadow-lg shadow-green-900/20 transition-colors"
                  >
                    Approve Override
                  </button>
                </div>
              </div>
            ))
          )}
        </div>
      )}
    </div>
  );
};

import { CommercialRecord, DuplicateRequest, User, Role, CommercialType, CITIES as DEFAULT_CITIES } from '../types';

// In a real scenario, we would import firebase/firestore here.
// For this demo, we simulate the Firestore persistence and latency.

const STORAGE_KEYS = {
  USERS: 'mm_users',
  RECORDS: 'mm_records',
  REQUESTS: 'mm_requests',
  BIN: 'mm_bin',
  CITIES: 'mm_cities'
};

// Seed Data
const SEED_USERS: User[] = [
  { id: '1', employeeId: 'maker1', name: 'Alice Maker', role: Role.MAKER },
  { id: '2', employeeId: 'checker1', name: 'Bob Checker', role: Role.CHECKER, pin: '1234' },
  { id: '3', employeeId: 'admin1', name: 'Charlie Admin', role: Role.ADMIN, pin: '9999' },
];

// Empty seed records so data is user-generated only
const SEED_RECORDS: CommercialRecord[] = [];

// Helper to simulate network delay
const delay = (ms: number) => new Promise(res => setTimeout(res, ms));

type RecordListener = (records: CommercialRecord[]) => void;

class DBService {
  private listeners: RecordListener[] = [];

  constructor() {
    this.init();
  }

  init() {
    if (!localStorage.getItem(STORAGE_KEYS.USERS)) {
      localStorage.setItem(STORAGE_KEYS.USERS, JSON.stringify(SEED_USERS));
    }
    if (!localStorage.getItem(STORAGE_KEYS.RECORDS)) {
      localStorage.setItem(STORAGE_KEYS.RECORDS, JSON.stringify(SEED_RECORDS));
    }
    if (!localStorage.getItem(STORAGE_KEYS.REQUESTS)) {
      localStorage.setItem(STORAGE_KEYS.REQUESTS, JSON.stringify([]));
    }
    if (!localStorage.getItem(STORAGE_KEYS.BIN)) {
      localStorage.setItem(STORAGE_KEYS.BIN, JSON.stringify([]));
    }
    if (!localStorage.getItem(STORAGE_KEYS.CITIES)) {
      localStorage.setItem(STORAGE_KEYS.CITIES, JSON.stringify(DEFAULT_CITIES));
    }
  }

  // Real-time Subscription (Simulating onSnapshot)
  subscribeToRecords(callback: RecordListener): () => void {
    this.listeners.push(callback);
    // Initial data push
    this.getRecords().then(records => callback(records));

    // Unsubscribe function
    return () => {
      this.listeners = this.listeners.filter(l => l !== callback);
    };
  }

  private async notifyListeners() {
    const records = await this.getRecords();
    this.listeners.forEach(l => l(records));
  }

  // Auth
  async login(employeeId: string): Promise<User | null> {
    await delay(500);
    try {
      const users: User[] = JSON.parse(localStorage.getItem(STORAGE_KEYS.USERS) || '[]');
      return users.find(u => u.employeeId === employeeId) || null;
    } catch (e) {
      console.error('Error parsing users', e);
      return null;
    }
  }

  async verifyPin(userId: string, pin: string): Promise<boolean> {
    await delay(300);
    try {
      const users: User[] = JSON.parse(localStorage.getItem(STORAGE_KEYS.USERS) || '[]');
      const user = users.find(u => u.id === userId);
      return user ? user.pin === pin : false;
    } catch (e) {
      return false;
    }
  }

  // Cities
  async getCities(): Promise<string[]> {
    await delay(100);
    try {
      return JSON.parse(localStorage.getItem(STORAGE_KEYS.CITIES) || JSON.stringify(DEFAULT_CITIES));
    } catch (e) {
      return DEFAULT_CITIES;
    }
  }

  async addCity(city: string): Promise<void> {
    await delay(300);
    const cities = await this.getCities();
    if (!cities.includes(city)) {
      cities.push(city);
      localStorage.setItem(STORAGE_KEYS.CITIES, JSON.stringify(cities));
    }
  }

  async deleteCity(city: string): Promise<void> {
    await delay(300);
    const cities = await this.getCities();
    const target = city.trim();
    const updated = cities.filter(c => c !== target);
    localStorage.setItem(STORAGE_KEYS.CITIES, JSON.stringify(updated));
  }

  // Records
  async getRecords(): Promise<CommercialRecord[]> {
    await delay(200); // Simulate Firestore cache read
    try {
      return JSON.parse(localStorage.getItem(STORAGE_KEYS.RECORDS) || '[]');
    } catch (e) {
      console.error('Error parsing records', e);
      return [];
    }
  }

  async addRecords(records: CommercialRecord[]): Promise<void> {
    await delay(600);
    const current = await this.getRecords();
    const updated = [...current, ...records];
    localStorage.setItem(STORAGE_KEYS.RECORDS, JSON.stringify(updated));
    this.notifyListeners();
  }

  async updateRecord(updatedRecord: CommercialRecord): Promise<void> {
    await delay(400);
    const current = await this.getRecords();
    const index = current.findIndex(r => r.id === updatedRecord.id);
    if (index !== -1) {
      current[index] = updatedRecord;
      localStorage.setItem(STORAGE_KEYS.RECORDS, JSON.stringify(current));
      this.notifyListeners();
    }
  }

  // Bulk update to prevent race conditions in simulation and support robust editing
  async updateRecords(updatedRecords: CommercialRecord[]): Promise<void> {
    await delay(600);
    const current = await this.getRecords();

    updatedRecords.forEach(update => {
        const index = current.findIndex(r => r.id === update.id);
        if (index !== -1) {
            current[index] = update;
        }
    });

    localStorage.setItem(STORAGE_KEYS.RECORDS, JSON.stringify(current));
    this.notifyListeners();
  }

  async deleteRecord(recordId: string, movedToBinBy: string): Promise<void> {
    await delay(400);
    const current = await this.getRecords();
    const record = current.find(r => r.id === recordId);
    if(record) {
        // Move to Bin
        try {
          const bin = JSON.parse(localStorage.getItem(STORAGE_KEYS.BIN) || '[]');
          bin.push({ ...record, deletedBy: movedToBinBy, deletedAt: Date.now() });
          localStorage.setItem(STORAGE_KEYS.BIN, JSON.stringify(bin));
        } catch (e) { console.error(e); }

        // Remove
        const updated = current.filter(r => r.id !== recordId);
        localStorage.setItem(STORAGE_KEYS.RECORDS, JSON.stringify(updated));
        this.notifyListeners();
    }
  }

  async deleteRecords(recordIds: string[], movedToBinBy: string): Promise<void> {
    await delay(400);
    const current = await this.getRecords();
    let bin = [];
    try {
       bin = JSON.parse(localStorage.getItem(STORAGE_KEYS.BIN) || '[]');
    } catch(e) { console.error('Bin parse error', e); }

    const timestamp = Date.now();

    // Identify records to delete
    const recordsToDelete = current.filter(r => recordIds.includes(r.id));

    // Add to bin
    recordsToDelete.forEach(r => {
        bin.push({ ...r, deletedBy: movedToBinBy, deletedAt: timestamp });
    });

    // Remove from main storage
    const updated = current.filter(r => !recordIds.includes(r.id));

    localStorage.setItem(STORAGE_KEYS.BIN, JSON.stringify(bin));
    localStorage.setItem(STORAGE_KEYS.RECORDS, JSON.stringify(updated));
    this.notifyListeners();
  }

  async clearAllRecords(clearedBy: string): Promise<void> {
    await delay(1000);

    // 1. Archive current data to bin for safety (Backup)
    try {
        const current = await this.getRecords();
        const bin = JSON.parse(localStorage.getItem(STORAGE_KEYS.BIN) || '[]');
        const timestamp = Date.now();
        current.forEach(r => {
             // We treat 'bin' as a loosely typed collection in this simulation
             // In Firestore this would be a batch write to 'bin_records'
             bin.push({ ...r, deletedBy: clearedBy, deletedAt: timestamp, note: 'BATCH_CLEAR_MONTH_END' });
        });
        localStorage.setItem(STORAGE_KEYS.BIN, JSON.stringify(bin));
    } catch(e) { 
        console.error('Backup failed during clearAllRecords', e); 
    }

    // 2. Wipe Active Data
    localStorage.setItem(STORAGE_KEYS.RECORDS, JSON.stringify([]));

    // 3. Wipe Pending Requests (assuming they are irrelevant for new month)
    localStorage.setItem(STORAGE_KEYS.REQUESTS, JSON.stringify([]));

    this.notifyListeners();
  }

  async getDuplicateRequests(): Promise<DuplicateRequest[]> {
    await delay(200);
    try {
      return JSON.parse(localStorage.getItem(STORAGE_KEYS.REQUESTS) || '[]');
    } catch (e) { return []; }
  }

  async createDuplicateRequest(request: DuplicateRequest): Promise<void> {
    await delay(400);
    const current = await this.getDuplicateRequests();
    localStorage.setItem(STORAGE_KEYS.REQUESTS, JSON.stringify([...current, request]));
  }

  async resolveDuplicateRequest(requestId: string, status: 'APPROVED' | 'REJECTED', resolverId: string): Promise<void> {
    await delay(500);
    const requests: DuplicateRequest[] = await this.getDuplicateRequests();
    const requestIndex = requests.findIndex(r => r.id === requestId);

    if (requestIndex === -1) return;

    const request = requests[requestIndex];
    request.status = status;

    if (status === 'APPROVED') {
      // Find existing potential conflict to archive
      const allRecords = await this.getRecords();

      // Strict matching logic for replacement
      const conflictingIndex = allRecords.findIndex(r => 
        r.fsn === request.payload.fsn &&
        r.city === request.payload.city &&
        r.type === request.payload.type &&
        r.startDate === request.payload.startDate &&
        r.endDate === request.payload.endDate
      );

      if (conflictingIndex !== -1) {
        // Move old to bin
        await this.deleteRecord(allRecords[conflictingIndex].id, resolverId);
      }

      // Add new
      await this.addRecords([request.payload]);
    }

    // Update Request List
    requests[requestIndex] = request;
    localStorage.setItem(STORAGE_KEYS.REQUESTS, JSON.stringify(requests));
  }
}

export const db = new DBService();

import React, { useState, useEffect } from 'react';
import { db } from '../services/db';
import { CommercialRecord, DuplicateRequest, User, CommercialType } from '../types';
import { Check, X, Search, BarChart3, Archive, ShieldCheck, TrendingUp, AlertCircle, FileDown, Calendar, Trash2, Database } from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer, ReferenceLine, LabelList } from 'recharts';

interface CheckerProps {
  user: User;
}

export const CheckerWorkspace: React.FC<CheckerProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<'AUDIT' | 'APPROVALS' | 'CLOSURE'>('AUDIT');
  const [requests, setRequests] = useState<DuplicateRequest[]>([]);
  const [cities, setCities] = useState<string[]>([]);

  // Audit State
  const [auditQuery, setAuditQuery] = useState({ fsn: '', city: 'BLR', targetMargin: 0 });
  const [auditResult, setAuditResult] = useState<any>(null);
  const [loading, setLoading] = useState(false);

  // Closure/Export State
  const [selectedMonth, setSelectedMonth] = useState(new Date().toISOString().slice(0, 7)); // YYYY-MM
  const [exportLoading, setExportLoading] = useState(false);

  useEffect(() => {
    loadRequests();
    loadCities();

    // Real-time setup would happen here with onSnapshot
    const interval = setInterval(loadRequests, 5000); // Polling for demo
    return () => clearInterval(interval);
  }, []);

  const loadCities = async () => {
    const c = await db.getCities();
    setCities(c);
    // Set default if not set
    if (!c.includes(auditQuery.city)) {
       setAuditQuery(prev => ({ ...prev, city: c.includes('BLR') ? 'BLR' : c[0] || '' }));
    }
  };

  const loadRequests = async () => {
    const reqs = await db.getDuplicateRequests();
    setRequests(reqs.filter(r => r.status === 'PENDING'));
  };

  const handleAudit = async () => {
    if (!auditQuery.fsn) return;
    setLoading(true);
    const records = await db.getRecords();

    // Filter relevant records
    const relevant = records.filter(r => 
      r.fsn === auditQuery.fsn && 
      (r.city === auditQuery.city || r.city === 'PAN-INDIA')
    );

    // Calc Sums
    const nlc = relevant.find(r => r.type === CommercialType.NLC_VALUE)?.value || 0;
    const onInv = relevant.find(r => r.type === CommercialType.ON_INVOICE)?.value || 0;

    const systemTotal = nlc + onInv; 
    const variance = auditQuery.targetMargin - systemTotal;
    const variancePercent = auditQuery.targetMargin ? ((variance / auditQuery.targetMargin) * 100) : 0;

    setAuditResult({
      data: [
        { 
            name: 'System', 
            nlc: nlc, 
            onInv: onInv,
            total: systemTotal 
        },
        { 
            name: 'Target', 
            target: auditQuery.targetMargin 
        }
      ],
      systemTotal,
      targetTotal: auditQuery.targetMargin,
      variance,
      variancePercent: variancePercent.toFixed(2),
      status: Math.abs(variance) < 0.1 ? 'MATCH' : 'MISMATCH',
      details: relevant
    });
    setLoading(false);
  };

  const handleRequestAction = async (reqId: string, action: 'APPROVED' | 'REJECTED') => {
    await db.resolveDuplicateRequest(reqId, action, user.id);
    loadRequests();
  };

  const handleExport = async (mode: 'MONTH' | 'FULL') => {
    setExportLoading(true);
    try {
        const records = await db.getRecords();
        let dataToExport = records;

        if (mode === 'MONTH') {
            const [year, month] = selectedMonth.split('-').map(Number);
            const startOfMonth = new Date(year, month - 1, 1).toISOString().split('T')[0];
            const endOfMonth = new Date(year, month, 0).toISOString().split('T')[0];

            // Filter records active in this month (overlaps)
            dataToExport = records.filter(r => 
                r.startDate <= endOfMonth && r.endDate >= startOfMonth
            );
        }

        // Generate CSV
        const headers = ['ID', 'FSN', 'Brand', 'Title', 'City', 'Type', 'Value', 'StartDate', 'EndDate', 'LastUpdatedBy', 'LastUpdatedAt'];
        const csvContent = [
            headers.join(','),
            ...dataToExport.map(r => [
                r.id, 
                r.fsn, 
                r.brand, 
                `"${r.title.replace(/"/g, '""')}"`, // Escape quotes
                r.city, 
                r.type, 
                r.value, 
                r.startDate, 
                r.endDate, 
                r.lastUpdatedBy,
                new Date(r.lastUpdatedAt).toISOString()
            ].join(','))
        ].join('\n');

        // Download
        const blob = new Blob([csvContent], { type: 'text/csv' });
        const url = window.URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `minutes_master_${mode.toLowerCase()}_${selectedMonth}_${Date.now()}.csv`;
        a.click();
        window.URL.revokeObjectURL(url);
    } catch (e) {
        console.error(e);
        alert('Export failed');
    } finally {
        setExportLoading(false);
    }
  };

  const handleClearDB = async () => {
    if (window.confirm("CRITICAL WARNING:\n\nThis will permanently DELETE ALL active records and pending requests.\nThis action is intended for Month End Closure after you have exported your data.\n\nAre you sure you want to proceed?")) {
        const confirmText = prompt("To confirm, type 'DELETE' in the box below:");
        if (confirmText === 'DELETE') {
            setLoading(true);
            try {
                await db.clearAllRecords(user.name);
                alert("Database has been reset successfully. All previous records have been archived to bin.");
                setAuditResult(null);
                setRequests([]);
            } catch (e) {
                alert("Failed to clear database.");
            } finally {
                setLoading(false);
            }
        }
    }
  };

  const CustomTooltip = ({ active, payload, label }: any) => {
    if (active && payload && payload.length) {
      return (
        <div className="bg-slate-800 border border-slate-600 p-3 rounded-lg shadow-xl text-xs">
          <p className="font-bold text-gray-300 mb-2">{label}</p>
          {payload.map((entry: any, index: number) => (
            <div key={index} className="flex items-center gap-2 mb-1">
               <div className="w-2 h-2 rounded-full" style={{ backgroundColor: entry.color }} />
               <span className="text-gray-400">{entry.name}:</span>
               <span className="text-white font-mono font-bold">{Number(entry.value).toFixed(2)}</span>
            </div>
          ))}
          {label === 'System' && (
             <div className="mt-2 pt-2 border-t border-slate-700 flex justify-between gap-4">
                <span className="text-gray-300 font-bold">Total:</span>
                <span className="text-white font-mono font-bold">{payload.reduce((acc: number, cur: any) => acc + (cur.value || 0), 0).toFixed(2)}</span>
             </div>
          )}
        </div>
      );
    }
    return null;
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      <div className="flex justify-between items-center border-b border-gray-800 pb-4">
        <h2 className="text-2xl font-bold text-white flex items-center gap-2">
           <ShieldCheck className="text-green-400 w-6 h-6" /> Checker Workspace
        </h2>
        <div className="flex gap-4">
          <button onClick={() => setActiveTab('AUDIT')} className={`text-sm font-bold ${activeTab === 'AUDIT' ? 'text-fkBlue' : 'text-gray-400 hover:text-white'}`}>AUDIT TOOL</button>
          <button onClick={() => setActiveTab('APPROVALS')} className={`text-sm font-bold flex items-center gap-2 ${activeTab === 'APPROVALS' ? 'text-fkBlue' : 'text-gray-400 hover:text-white'}`}>
            APPROVALS 
            {requests.length > 0 && <span className="bg-red-500 text-white text-[10px] px-1.5 py-0.5 rounded-full">{requests.length}</span>}
          </button>
          <button onClick={() => setActiveTab('CLOSURE')} className={`text-sm font-bold flex items-center gap-2 ${activeTab === 'CLOSURE' ? 'text-fkYellow' : 'text-gray-400 hover:text-white'}`}>
            MONTH END
          </button>
        </div>
      </div>

      {activeTab === 'AUDIT' && (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          <div className="lg:col-span-1 space-y-4">
            <div className="glass-panel p-6 rounded-xl">
              <h3 className="text-lg font-semibold mb-4 text-gray-200">Commercial Audit</h3>
              <div className="space-y-3">
                <input 
                  className="w-full bg-slate-800 border border-slate-600 rounded p-2 text-white" 
                  placeholder="FSN to Audit"
                  value={auditQuery.fsn}
                  onChange={e => setAuditQuery({...auditQuery, fsn: e.target.value})}
                />
                <select 
                  className="w-full bg-slate-800 border border-slate-600 rounded p-2 text-white"
                  value={auditQuery.city}
                  onChange={e => setAuditQuery({...auditQuery, city: e.target.value})}
                >
                  {cities.map(c => <option key={c} value={c}>{c}</option>)}
                </select>
                <input 
                  type="number"
                  className="w-full bg-slate-800 border border-slate-600 rounded p-2 text-white" 
                  placeholder="Expected Total Value"
                  value={auditQuery.targetMargin || ''}
                  onChange={e => setAuditQuery({...auditQuery, targetMargin: parseFloat(e.target.value)})}
                />
                <button 
                  onClick={handleAudit}
                  disabled={loading}
                  className="w-full bg-fkBlue hover:bg-blue-600 text-white font-bold py-2 rounded transition-colors"
                >
                  {loading ? 'Analyzing...' : 'Run Analysis'}
                </button>
              </div>
            </div>

            {auditResult && (
              <div className={`p-4 rounded-xl border animate-in zoom-in duration-300 ${auditResult.status === 'MATCH' ? 'bg-green-900/20 border-green-800' : 'bg-red-900/20 border-red-800'}`}>
                 <div className="flex justify-between items-start mb-2">
                    <div className={`text-xl font-bold flex items-center gap-2 ${auditResult.status === 'MATCH' ? 'text-green-400' : 'text-red-400'}`}>
                        {auditResult.status === 'MATCH' ? <Check className="w-5 h-5"/> : <AlertCircle className="w-5 h-5"/>}
                        {auditResult.status}
                    </div>
                    {auditResult.status === 'MISMATCH' && (
                        <div className="text-xs font-bold px-2 py-1 bg-red-900/50 text-red-200 rounded">
                             Variance Detected
                        </div>
                    )}
                 </div>

                 <div className="mt-4 grid grid-cols-2 gap-4">
                     <div>
                         <p className="text-xs text-gray-400 uppercase">Variance Val</p>
                         <p className={`text-xl font-mono font-bold ${auditResult.variance > 0 ? 'text-green-300' : 'text-red-300'}`}>
                            {auditResult.variance > 0 ? '+' : ''}{auditResult.variance.toFixed(2)}
                         </p>
                     </div>
                     <div>
                         <p className="text-xs text-gray-400 uppercase">Variance %</p>
                         <div className="flex items-center gap-1">
                            <TrendingUp className={`w-4 h-4 ${parseFloat(auditResult.variancePercent) > 0 ? 'text-green-400' : 'text-red-400'}`} />
                            <p className="text-xl font-mono font-bold text-white">
                                {Math.abs(Number(auditResult.variancePercent))}%
                            </p>
                         </div>
                     </div>
                 </div>
              </div>
            )}
          </div>

          <div className="lg:col-span-2 glass-panel p-6 rounded-xl min-h-[400px]">
            {auditResult ? (
              <div className="h-full w-full">
                <ResponsiveContainer width="100%" height={350}>
                    <BarChart data={auditResult.data} margin={{ top: 20, right: 30, left: 20, bottom: 5 }}>
                        <CartesianGrid strokeDasharray="3 3" stroke="#333" />
                        <XAxis dataKey="name" stroke="#888" tick={{fill: '#9ca3af'}} />
                        <YAxis stroke="#888" tick={{fill: '#9ca3af'}} />
                        <Tooltip content={<CustomTooltip />} cursor={{fill: 'rgba(255,255,255,0.05)'}} />
                        <Legend wrapperStyle={{ paddingTop: '20px' }} />

                        {/* System Stack: Broken down into components */}
                        <Bar dataKey="nlc" stackId="system" name="NLC Value" fill="#2874f0" radius={[0, 0, 4, 4]}>
                           <LabelList dataKey="nlc" position="center" className="fill-white/90 font-bold text-[10px]" formatter={(v: number) => v > 0 ? v.toFixed(0) : ''} />
                        </Bar>
                        <Bar dataKey="onInv" stackId="system" name="On Invoice %" fill="#8b5cf6" radius={[4, 4, 0, 0]}>
                           <LabelList dataKey="onInv" position="center" className="fill-white/90 font-bold text-[10px]" formatter={(v: number) => v > 0 ? v.toFixed(0) : ''} />
                        </Bar>

                        {/* Target Stack: Single bar */}
                        <Bar dataKey="target" stackId="target" name="User Target" fill={auditResult.status === 'MATCH' ? '#10b981' : '#f59e0b'} radius={[4, 4, 4, 4]}>
                             <LabelList dataKey="target" position="top" className="fill-gray-400 font-bold text-xs" formatter={(v: number) => v.toFixed(2)} />
                        </Bar>

                        {/* Reference Line for Target Margin if Mismatch */}
                        {auditResult.status === 'MISMATCH' && (
                             <ReferenceLine 
                                y={auditResult.targetTotal} 
                                stroke="#f59e0b" 
                                strokeDasharray="3 3" 
                                label={{ position: 'right', value: 'Target', fill: '#f59e0b', fontSize: 10 }} 
                             />
                        )}
                    </BarChart>
                </ResponsiveContainer>
              </div>
            ) : (
              <div className="h-full flex flex-col items-center justify-center text-gray-500">
                <BarChart3 className="w-16 h-16 mb-4 opacity-20" />
                <p>Run an audit to view visualization</p>
              </div>
            )}
          </div>
        </div>
      )}

      {activeTab === 'APPROVALS' && (
        <div className="space-y-4">
          {requests.length === 0 ? (
            <div className="text-center py-20 text-gray-500">
              <Check className="w-12 h-12 mx-auto mb-3 opacity-20" />
              <p>No pending approvals. Good job!</p>
            </div>
          ) : (
            requests.map(req => (
              <div key={req.id} className="glass-panel p-4 rounded-xl flex flex-col md:flex-row justify-between items-start md:items-center gap-4 border-l-4 border-yellow-500">
                <div>
                  <div className="flex items-center gap-2 mb-1">
                    <span className="bg-yellow-500/20 text-yellow-400 text-xs px-2 py-0.5 rounded font-mono">CONFLICT</span>
                    <h4 className="font-bold text-white">{req.payload.title} ({req.payload.fsn})</h4>
                  </div>
                  <div className="text-sm text-gray-400 grid grid-cols-2 md:grid-cols-4 gap-x-8 gap-y-1">
                    <span>City: <b className="text-gray-200">{req.payload.city}</b></span>
                    <span>Type: <b className="text-gray-200">{req.payload.type}</b></span>
                    <span>New Value: <b className="text-fkYellow">{req.payload.value}</b></span>
                    <span>By: {req.requestedBy}</span>
                  </div>
                </div>
                <div className="flex gap-2 w-full md:w-auto">
                  <button 
                    onClick={() => handleRequestAction(req.id, 'REJECTED')}
                    className="flex-1 md:flex-none px-4 py-2 rounded bg-slate-700 hover:bg-slate-600 text-white text-sm transition-colors"
                  >
                    Reject
                  </button>
                  <button 
                    onClick={() => handleRequestAction(req.id, 'APPROVED')}
                    className="flex-1 md:flex-none px-4 py-2 rounded bg-green-600 hover:bg-green-500 text-white font-bold text-sm shadow-lg shadow-green-900/20 transition-colors"
                  >
                    Approve Override
                  </button>
                </div>
              </div>
            ))
          )}
        </div>
      )}

      {activeTab === 'CLOSURE' && (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
            {/* Export Section */}
            <div className="glass-panel p-6 rounded-xl space-y-4">
                <div className="flex items-center gap-3 mb-2">
                    <div className="bg-fkBlue/20 p-3 rounded-lg">
                        <FileDown className="w-6 h-6 text-fkBlue" />
                    </div>
                    <div>
                        <h3 className="text-lg font-bold text-white">Export Data</h3>
                        <p className="text-sm text-gray-400">Download data for records and auditing.</p>
                    </div>
                </div>

                <div className="pt-4 space-y-4 border-t border-slate-700">
                    <div>
                        <label className="block text-xs font-medium text-gray-400 mb-2 flex items-center gap-2">
                            <Calendar className="w-3 h-3" /> Select Month
                        </label>
                        <input 
                            type="month"
                            className="w-full bg-slate-800 border border-slate-600 rounded p-2 text-white"
                            value={selectedMonth}
                            onChange={(e) => setSelectedMonth(e.target.value)}
                        />
                    </div>
                    <div className="flex flex-col gap-3">
                        <button 
                            onClick={() => handleExport('MONTH')}
                            disabled={exportLoading}
                            className="w-full py-2 bg-slate-700 hover:bg-slate-600 rounded text-white text-sm font-medium transition-colors"
                        >
                            {exportLoading ? 'Generating CSV...' : `Export ${selectedMonth} Data`}
                        </button>
                        <button 
                            onClick={() => handleExport('FULL')}
                            disabled={exportLoading}
                            className="w-full py-2 border border-slate-600 hover:bg-slate-800 rounded text-gray-300 text-sm transition-colors"
                        >
                            Export Full Database
                        </button>
                    </div>
                </div>
            </div>

            {/* Clear Section */}
            <div className="glass-panel p-6 rounded-xl space-y-4 border border-red-900/30 relative overflow-hidden">
                <div className="absolute top-0 right-0 p-20 bg-red-900/10 rounded-full blur-3xl pointer-events-none transform translate-x-10 -translate-y-10"></div>

                <div className="flex items-center gap-3 mb-2">
                    <div className="bg-red-900/30 p-3 rounded-lg">
                        <Database className="w-6 h-6 text-red-500" />
                    </div>
                    <div>
                        <h3 className="text-lg font-bold text-red-500">System Reset</h3>
                        <p className="text-sm text-gray-400">Clear database for new operational cycle.</p>
                    </div>
                </div>

                <div className="pt-4 space-y-4 border-t border-red-900/30">
                    <div className="bg-red-950/30 border border-red-900/50 p-4 rounded text-sm text-red-200">
                        <p className="flex items-start gap-2">
                            <AlertCircle className="w-5 h-5 flex-shrink-0" />
                            <span>
                                <strong>Warning:</strong> This action will permanently delete all active commercial records and pending requests. Ensure you have exported the data before proceeding.
                            </span>
                        </p>
                    </div>

                    <button 
                        onClick={handleClearDB}
                        disabled={loading}
                        className="w-full py-3 bg-red-600 hover:bg-red-700 rounded text-white font-bold shadow-lg shadow-red-900/20 flex items-center justify-center gap-2 transition-all"
                    >
                        {loading ? 'Clearing...' : (
                            <>
                                <Trash2 className="w-4 h-4" />
                                Clear Database
                            </>
                        )}
                    </button>
                </div>
            </div>
        </div>
      )}
    </div>
  );
};

