import { useEffect, useState } from 'react';
import { getRecords, clearAllRecords } from './db';
import { Record } from './types';
import { format } from 'date-fns';

interface Props {
  activeTab: string;
  setActiveTab: (tab: string) => void;
  // Other props as needed
}

function CheckerWorkspace({ activeTab, setActiveTab }: Props) {
  const [records, setRecords] = useState<Record[]>([]);
  const [exportMonth, setExportMonth] = useState('');

  useEffect(() => {
    async function fetchData() {
      const data = await getRecords();
      setRecords(data);
    }
    fetchData();
  }, []);

  const handleExport = async () => {
    let recordsToExport: Record[] = [];
    if (exportMonth) {
      const [year, month] = exportMonth.split('-');
      const startOfMonth = new Date(parseInt(year), parseInt(month) - 1, 1);
      const endOfMonth = new Date(parseInt(year), parseInt(month), 0);
      recordsToExport = records.filter(record => {
        const recordStartDate = new Date(record.startDate);
        const recordEndDate = new Date(record.endDate);

        return (
          recordStartDate <= endOfMonth &&
          recordEndDate >= startOfMonth
        );
      });
    } else {
      recordsToExport = records;
    }

    const csvData = convertToCSV(recordsToExport);
    const blob = new Blob([csvData], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.setAttribute('download', 'data.csv');
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

  const handleClearDB = async () => {
    if (window.confirm('Are you sure you want to clear all records? This action is irreversible.')) {
      await clearAllRecords('User');
      const data = await getRecords();
      setRecords(data);
    }
  };

  const convertToCSV = (data: Record[]) => {
    const header = Object.keys(data[0]).join(',') + '\n';
    const rows = data.map(obj => Object.values(obj).join(',') + '\n');
    return header + rows.join('');
  };

  return (
    <div>
      <div className="tabs">
        <button className={activeTab === 'LIST' ? 'active' : ''} onClick={() => setActiveTab('LIST')}>List</button>
        <button className={activeTab === 'CLOSURE' ? 'active' : ''} onClick={() => setActiveTab('CLOSURE')}>Month End Closure</button>
      </div>

      {activeTab === 'LIST' && (
        <ul>
          {records.map((record) => (
            <li key={record.id}>
              {/* Display record details */}
              {`Start: ${format(new Date(record.startDate), 'yyyy-MM-dd')}, End: ${format(new Date(record.endDate), 'yyyy-MM-dd')}, Value: ${record.value}`}
            </li>
          ))}
        </ul>
      )}

      {activeTab === 'CLOSURE' && (
        <div>
          <label htmlFor="exportMonth">Select Month:</label>
          <input
            type="month"
            id="exportMonth"
            value={exportMonth}
            onChange={(e) => setExportMonth(e.target.value)}
          />
          <button onClick={handleExport}>Export Data</button>
          <button onClick={handleClearDB}>Clear Database</button>
        </div>
      )}
    </div>
  );
}

export default CheckerWorkspace;

