        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { db } from '../services/db';
import { CommercialRecord, User, Role, COMMERCIAL_TYPES, CommercialType } from '../types';
import { Download, Filter, RefreshCw, Trash2, Edit2, Save, X, Clock } from 'lucide-react';

interface DataExplorerProps {
  user: User;
}

interface PivotRow {
  key: string;
  fsn: string;
  brand: string;
  title: string;
  type: CommercialType;
  startDate: string;
  endDate: string;
  cityRecords: { [key: string]: CommercialRecord | undefined };
  values: { [key: string]: number | undefined };
  isExpiringSoon: boolean;
}

export const DataExplorer: React.FC<DataExplorerProps> = ({ user }) => {
  const [records, setRecords] = useState<CommercialRecord[]>([]);
  const [cities, setCities] = useState<string[]>([]);
  const [loading, setLoading] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');

  // Edit State
  const [editingRowKey, setEditingRowKey] = useState<string | null>(null);
  const [editForm, setEditForm] = useState<Partial<PivotRow> | null>(null);
  const [processingAction, setProcessingAction] = useState(false);

  // Permission Check
  const canEdit = user.role !== Role.MAKER;

  useEffect(() => {
    let unsubscribe: () => void;

    const init = async () => {
      setLoading(true);
      try {
        const c = await db.getCities();
        setCities(c);
        unsubscribe = db.subscribeToRecords((data) => {
          setRecords(data);
          setLoading(false);
        });
      } catch (e) {
        console.error("Failed to load data", e);
        setLoading(false);
      }
    };

    init();

    return () => {
      if (unsubscribe) unsubscribe();
    };
  }, []);

  const pivotData: PivotRow[] = useMemo(() => {
    const map = new Map<string, PivotRow>();
    const today = new Date();
    const sevenDaysLater = new Date();
    sevenDaysLater.setDate(today.getDate() + 7);

    records.forEach(r => {
      const key = `${r.fsn}_${r.type}_${r.startDate}_${r.endDate}`;
      if (!map.has(key)) {
        const endDate = new Date(r.endDate);
        const isExpiringSoon = endDate >= today && endDate <= sevenDaysLater;

        map.set(key, {
          key,
          fsn: r.fsn,
          brand: r.brand,
          title: r.title,
          type: r.type,
          startDate: r.startDate,
          endDate: r.endDate,
          cityRecords: {},
          values: {},
          isExpiringSoon
        });
      }
      const entry = map.get(key)!;
      entry.cityRecords[r.city] = r;
      entry.values[r.city] = r.value;
    });
    let result = Array.from(map.values());
    if (searchTerm) {
      const lower = searchTerm.toLowerCase();
      result = result.filter(item => 
        item.fsn.toLowerCase().includes(lower) || 
        item.brand.toLowerCase().includes(lower) ||
        item.title.toLowerCase().includes(lower)
      );
    }
    return result;
  }, [records, searchTerm]);

  const exportCSV = () => {
    const headers = ['FSN', 'Brand', 'Title', 'Type', 'Start', 'End', ...cities].join(',');
    const rows = pivotData.map(row => {
      const cityVals = cities.map(c => row.values[c] || '').join(',');
      return `${row.fsn},${row.brand},${row.title},${row.type},${row.startDate},${row.endDate},${cityVals}`;
    }).join('\n');

    const blob = new Blob([headers + '\n' + rows], { type: 'text/csv' });
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `mm_export_${Date.now()}.csv`;
    a.click();
    window.URL.revokeObjectURL(url);
  };

  const handleEditClick = (row: PivotRow) => {
    setEditingRowKey(row.key);
    setEditForm({ ...row, values: { ...row.values } });
  };

  const handleCancelEdit = () => {
    setEditingRowKey(null);
    setEditForm(null);
  };

  const handleDeleteRow = async (row: PivotRow) => {
    if (!canEdit) return;
    if (!window.confirm(`Delete all records for ${row.title} (${row.type})?`)) return;
    setProcessingAction(true);
    try {
      const idsToDelete = records
        .filter(r => r.fsn === row.fsn && r.type === row.type && r.startDate === row.startDate && r.endDate === row.endDate)
        .map(r => r.id);
      if (idsToDelete.length === 0) return;
      await db.deleteRecords(idsToDelete, user.name);
    } catch (e) {
      alert('Error deleting records');
    } finally {
      setProcessingAction(false);
    }
  };

  const handleSaveEdit = async (originalRow: PivotRow) => {
    if (!editForm || !canEdit) return;

    if ((editForm.fsn || originalRow.fsn).length !== 16) {
        alert("FSN must be exactly 16 characters.");
        return;
    }

    setProcessingAction(true);
    try {
      const recordsToUpdate = records.filter(r => 
          r.fsn === originalRow.fsn && r.type === originalRow.type && r.startDate === originalRow.startDate && r.endDate === originalRow.endDate
      );

      const updatePromises: Promise<void>[] = [];
      const recordsForBulkUpdate: CommercialRecord[] = [];

      recordsToUpdate.forEach(r => {
        const newCityValue = editForm.values?.[r.city];
        const updatedRecord: CommercialRecord = {
          ...r,
          fsn: editForm.fsn || r.fsn,
          brand: editForm.brand || r.brand,
          title: editForm.title || r.title,
          type: editForm.type || r.type,
          startDate: editForm.startDate || r.startDate,
          endDate: editForm.endDate || r.endDate,
          value: newCityValue !== undefined ? Number(newCityValue) : r.value,
          lastUpdatedBy: user.name,
          lastUpdatedAt: Date.now()
        };
        recordsForBulkUpdate.push(updatedRecord);
      });

      if (recordsForBulkUpdate.length > 0) updatePromises.push(db.updateRecords(recordsForBulkUpdate));

      for (const city of cities) {
        const hasExisting = recordsToUpdate.some(r => r.city === city);
        const newVal = editForm.values?.[city];
        if (!hasExisting && newVal !== undefined && Number(newVal) !== 0) {
           updatePromises.push(db.addRecords([{
             id: `rec_${Date.now()}_${Math.random().toString(36).substr(2,5)}`,
             fsn: editForm.fsn!,
             brand: editForm.brand!,
             title: editForm.title!,
             type: editForm.type!,
             city: city,
             startDate: editForm.startDate!,
             endDate: editForm.endDate!,
             value: Number(newVal),
             lastUpdatedBy: user.name,
             lastUpdatedAt: Date.now()
           }]));
        }
      }
      await Promise.all(updatePromises);
      setEditingRowKey(null);
      setEditForm(null);
    } catch (e) {
      alert('Failed to save changes');
    } finally {
      setProcessingAction(false);
    }
  };

  const refreshCities = async () => {
    setLoading(true);
    const c = await db.getCities();
    setCities(c);
    setLoading(false);
  };

  return (
    <div className="space-y-4 h-full flex flex-col animate-in fade-in duration-500">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
           <h2 className="text-2xl font-bold text-gray-800">Database Explorer</h2>
           <p className="text-sm text-gray-500">Search and edit active commercial records</p>
        </div>
        <div className="flex gap-2">
           <div className="relative">
             <Filter className="absolute left-3 top-2.5 h-4 w-4 text-gray-400"/>
             <input 
               className="bg-white border border-gray-300 rounded shadow-sm py-2 pl-9 pr-4 text-sm text-gray-800 focus:ring-1 focus:ring-fkBlue focus:border-fkBlue outline-none w-64 transition-shadow"
               placeholder="Filter by FSN, Brand..."
               value={searchTerm}
               onChange={e => setSearchTerm(e.target.value)}
             />
           </div>
           <button onClick={refreshCities} className="p-2 bg-white border border-gray-300 rounded hover:bg-gray-50 text-gray-600 shadow-sm">
             <RefreshCw className={`h-5 w-5 ${loading ? 'animate-spin' : ''}`} />
           </button>
           <button onClick={exportCSV} className="flex items-center gap-2 px-4 py-2 bg-fkGreen hover:bg-green-700 text-white rounded shadow-sm text-sm font-bold transition-colors">
             <Download className="h-4 w-4" /> Export CSV
           </button>
        </div>
      </div>

      <div className="flex-1 bg-white rounded-lg shadow-sm border border-gray-200 overflow-hidden flex flex-col relative">
        {processingAction && (
          <div className="absolute inset-0 bg-white/60 z-50 flex items-center justify-center backdrop-blur-sm">
            <RefreshCw className="w-8 h-8 text-fkBlue animate-spin" />
          </div>
        )}

        <div className="overflow-auto scrollbar-hide flex-1">
          <table className="w-full text-left border-collapse min-w-[1400px]">
            <thead className="bg-gray-50 sticky top-0 z-10 text-xs uppercase text-gray-500 font-semibold shadow-sm">
              <tr>
                <th className="p-4 border-b border-gray-200 min-w-[120px] bg-gray-50">FSN</th>
                <th className="p-4 border-b border-gray-200 bg-gray-50">Brand</th>
                <th className="p-4 border-b border-gray-200 bg-gray-50">Title</th>
                <th className="p-4 border-b border-gray-200 bg-gray-50 min-w-[120px]">Type</th>
                <th className="p-4 border-b border-gray-200 text-center min-w-[200px] bg-gray-50">Dates</th>
                {cities.map(c => (
                  <th key={c} className="p-4 border-b border-gray-200 text-center min-w-[80px] bg-gray-50">{c}</th>
                ))}
                {canEdit && <th className="p-4 border-b border-gray-200 text-center sticky right-0 bg-gray-50 z-20 w-24">Actions</th>}
              </tr>
            </thead>
            <tbody className="text-sm divide-y divide-gray-100">
              {pivotData.map((row) => {
                const isEditing = editingRowKey === row.key;
                return (
                  <tr key={row.key} className={`hover:bg-blue-50/50 transition-colors group ${isEditing ? 'bg-blue-50' : ''}`}>
                    <td className="p-4 font-mono text-fkBlue font-semibold">
                        {isEditing ? (
                            <input className="w-full bg-white border border-gray-300 rounded px-2 py-1 text-gray-800 text-xs font-mono"
                              value={editForm?.fsn || ''} onChange={e => setEditForm(prev => ({ ...prev!, fsn: e.target.value }))} 
                              maxLength={16}
                              />
                        ) : (
                          <div className="flex items-center gap-2">
                             {row.fsn}
                             {row.isExpiringSoon && (
                               <span title="Expiring within 7 days">
                                 <Clock className="w-3 h-3 text-fkYellow animate-pulse" />
                               </span>
                             )}
                          </div>
                        )}
                    </td>
                    <td className="p-4 text-gray-700 max-w-[150px] truncate">
                        {isEditing ? (
                            <input className="w-full bg-white border border-gray-300 rounded px-2 py-1 text-gray-800 text-xs"
                              value={editForm?.brand || ''} onChange={e => setEditForm(prev => ({ ...prev!, brand: e.target.value }))} />
                        ) : row.brand}
                    </td>
                    <td className="p-4 text-gray-700 max-w-[200px] truncate" title={row.title}>
                        {isEditing ? (
                            <input className="w-full bg-white border border-gray-300 rounded px-2 py-1 text-gray-800 text-xs"
                              value={editForm?.title || ''} onChange={e => setEditForm(prev => ({ ...prev!, title: e.target.value }))} />
                        ) : row.title}
                    </td>
                    <td className="p-4">
                      {isEditing ? (
                          <select className="w-full bg-white border border-gray-300 rounded px-2 py-1 text-gray-800 text-xs"
                             value={editForm?.type} onChange={e => setEditForm(prev => ({ ...prev!, type: e.target.value as CommercialType }))}>
                            {COMMERCIAL_TYPES.map(t => <option key={t} value={t}>{t}</option>)}
                          </select>
                      ) : (
                          <span className={`px-2 py-1 rounded text-[10px] border whitespace-nowrap font-medium ${
                            row.type.includes('Margin') ? 'border-purple-200 text-purple-700 bg-purple-50' : 
                            'border-blue-200 text-blue-700 bg-blue-50'
                          }`}>
                            {row.type}
                          </span>
                      )}
                    </td>
                    <td className="p-4 text-gray-500 text-xs text-center">
                      {isEditing ? (
                        <div className="flex flex-col gap-2">
                           <input type="date" className="bg-white border border-gray-300 rounded px-2 py-1 text-gray-800 text-xs w-full"
                             value={editForm?.startDate || row.startDate} onChange={e => setEditForm(prev => ({ ...prev!, startDate: e.target.value }))} />
                           <input type="date" className="bg-white border border-gray-300 rounded px-2 py-1 text-gray-800 text-xs w-full"
                             value={editForm?.endDate || row.endDate} onChange={e => setEditForm(prev => ({ ...prev!, endDate: e.target.value }))} />
                        </div>
                      ) : (
                        <div className="flex flex-col items-center">
                           <span className="font-mono">{row.startDate}</span>
                           <span className="text-[10px] text-gray-400">to</span>
                           <span className={`font-mono ${row.isExpiringSoon ? 'text-fkYellow font-bold' : ''}`}>{row.endDate}</span>
                        </div>
                      )}
                    </td>
                    {cities.map(c => (
                      <td key={c} className={`p-2 text-center border-l border-gray-100 ${isEditing ? 'p-1' : ''}`}>
                         {isEditing ? (
                           <input type="number" className="w-16 bg-white border border-gray-300 rounded px-1 py-1 text-center text-gray-800 text-sm focus:border-fkBlue outline-none"
                             value={editForm?.values?.[c] ?? ''} placeholder="-"
                             onChange={e => {
                               const val = e.target.value;
                               setEditForm(prev => ({ ...prev!, values: { ...prev!.values, [c]: val === '' ? undefined : parseFloat(val) } }));
                             }} />
                         ) : (
                           row.values[c] !== undefined ? <span className="font-bold text-gray-800">{row.values[c]}</span> : <span className="text-gray-300">-</span>
                         )}
                      </td>
                    ))}
                    {canEdit && (
                      <td className="p-4 border-l border-gray-200 sticky right-0 bg-white group-hover:bg-blue-50/50 transition-colors z-10 shadow-[-5px_0_10px_-5px_rgba(0,0,0,0.1)]">
                        <div className="flex items-center justify-center gap-2">
                          {isEditing ? (
                            <>
                              <button onClick={() => handleSaveEdit(row)} className="p-1.5 bg-green-600 hover:bg-green-700 rounded text-white shadow-sm" title="Save">
                                <Save className="w-4 h-4" />
                              </button>
                              <button onClick={handleCancelEdit} className="p-1.5 bg-gray-500 hover:bg-gray-600 rounded text-white" title="Cancel">
                                <X className="w-4 h-4" />
                              </button>
                            </>
                          ) : (
                            <>
                              <button onClick={() => handleEditClick(row)} className="p-1.5 hover:bg-blue-100 text-gray-400 hover:text-fkBlue rounded transition-colors">
                                <Edit2 className="w-4 h-4" />
                              </button>
                              <button onClick={() => handleDeleteRow(row)} className="p-1.5 hover:bg-red-100 text-gray-400 hover:text-red-600 rounded transition-colors">
                                <Trash2 className="w-4 h-4" />
                              </button>
                            </>
                          )}
                        </div>
                      </td>
                    )}
                  </tr>
                );
              })}
              {pivotData.length === 0 && !loading && (
                 <tr><td colSpan={cities.length + 6} className="p-8 text-center text-gray-500">No records found.</td></tr>
              )}
            </tbody>
          </table>
        </div>
        <div className="bg-gray-50 p-2 text-xs text-gray-500 text-center border-t border-gray-200">
          Showing {pivotData.length} records
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { db } from '../services/db';
import { DuplicateRequest, User, CommercialType } from '../types';
import { Check, X, Search, BarChart3, Archive, TrendingUp, AlertCircle, FileDown, Calendar, Trash2, Database, Clock, ChevronDown } from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer, ReferenceLine, LabelList } from 'recharts';
import Papa from 'papaparse';

interface CheckerProps {
  user: User;
}

export const CheckerWorkspace: React.FC<CheckerProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<'AUDIT' | 'APPROVALS' | 'CLOSURE'>('AUDIT');
  const [requests, setRequests] = useState<DuplicateRequest[]>([]);
  const [cities, setCities] = useState<string[]>([]);

  // Audit State
  const [auditQuery, setAuditQuery] = useState({ fsn: '', city: 'BLR', targetMargin: 0 });
  const [auditResult, setAuditResult] = useState<any>(null);
  const [loading, setLoading] = useState(false);

  // Autocomplete State
  const [allFsns, setAllFsns] = useState<string[]>([]);
  const [filteredFsns, setFilteredFsns] = useState<string[]>([]);
  const [showSuggestions, setShowSuggestions] = useState(false);

  // Closure/Export State
  const [selectedMonth, setSelectedMonth] = useState(new Date().toISOString().slice(0, 7)); // YYYY-MM
  const [exportLoading, setExportLoading] = useState(false);

  // Archive View State
  const [showArchive, setShowArchive] = useState(false);
  const [archiveData, setArchiveData] = useState<any[]>([]);

  useEffect(() => {
    loadRequests();
    loadCities();
    loadUniqueFsns();
    const interval = setInterval(loadRequests, 5000);
    return () => clearInterval(interval);
  }, []);

  const loadCities = async () => {
    const c = await db.getCities();
    setCities(c);
    if (!c.includes(auditQuery.city)) {
       setAuditQuery(prev => ({ ...prev, city: c.includes('BLR') ? 'BLR' : c[0] || '' }));
    }
  };

  const loadUniqueFsns = async () => {
    const records = await db.getRecords();
    const unique = Array.from(new Set(records.map(r => r.fsn)));
    setAllFsns(unique);
  };

  const loadRequests = async () => {
    const reqs = await db.getDuplicateRequests();
    setRequests(reqs.filter(r => r.status === 'PENDING'));
  };

  const loadArchive = async () => {
    const data = await db.getBinRecords();
    setArchiveData(data.sort((a: any, b: any) => b.deletedAt - a.deletedAt));
  };

  const toggleArchive = () => {
      if (!showArchive) loadArchive();
      setShowArchive(!showArchive);
  };

  const handleFsnChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = e.target.value;
    setAuditQuery({ ...auditQuery, fsn: val });

    if (val.length > 0) {
        const matches = allFsns.filter(f => f.toLowerCase().includes(val.toLowerCase()));
        setFilteredFsns(matches.slice(0, 5)); // Limit to 5 suggestions
        setShowSuggestions(true);
    } else {
        setShowSuggestions(false);
    }
  };

  const selectSuggestion = (fsn: string) => {
      setAuditQuery({ ...auditQuery, fsn });
      setShowSuggestions(false);
  };

  const handleAudit = async () => {
    if (!auditQuery.fsn) return;

    if (auditQuery.fsn.length !== 16) {
        alert("FSN must be exactly 16 characters.");
        return;
    }

    setLoading(true);
    setShowSuggestions(false); // Hide if open

    const records = await db.getRecords();

    const relevant = records.filter(r => 
      r.fsn === auditQuery.fsn && 
      (r.city === auditQuery.city || r.city === 'PAN-INDIA')
    );

    // Helper to get specific city value or fallback to PAN-INDIA
    const getEffectiveValue = (type: CommercialType) => {
        const specific = relevant.find(r => r.type === type && r.city === auditQuery.city);
        if (specific) return { val: specific.value, source: 'CITY' };

        const pan = relevant.find(r => r.type === type && r.city === 'PAN-INDIA');
        if (pan) return { val: pan.value, source: 'PAN' };

        return { val: 0, source: 'NONE' };
    };

    const nlcObj = getEffectiveValue(CommercialType.NLC_VALUE);
    const onInvObj = getEffectiveValue(CommercialType.ON_INVOICE);

    const nlc = nlcObj.val;
    const onInv = onInvObj.val;

    const systemTotal = nlc + onInv; 
    const variance = auditQuery.targetMargin - systemTotal;
    const variancePercent = auditQuery.targetMargin ? ((variance / auditQuery.targetMargin) * 100) : 0;

    setAuditResult({
      data: [
        { name: 'System', nlc: nlc, onInv: onInv, total: systemTotal },
        { name: 'Target', target: auditQuery.targetMargin }
      ],
      systemTotal,
      targetTotal: auditQuery.targetMargin,
      variance,
      variancePercent: variancePercent.toFixed(2),
      status: Math.abs(variance) < 0.1 ? 'MATCH' : 'MISMATCH',
      details: relevant,
      sources: { nlc: nlcObj.source, onInv: onInvObj.source }
    });
    setLoading(false);
  };

  const handleRequestAction = async (reqId: string, action: 'APPROVED' | 'REJECTED') => {
    await db.resolveDuplicateRequest(reqId, action, user.id);
    loadRequests();
    loadUniqueFsns(); // Reload FSNs in case new ones were added via approval
  };

  const handleExport = async (mode: 'MONTH' | 'FULL') => {
    setExportLoading(true);
    try {
        const records = await db.getRecords();
        let dataToExport = records;

        if (mode === 'MONTH') {
            const [year, month] = selectedMonth.split('-').map(Number);
            const startOfMonth = new Date(year, month - 1, 1).toISOString().split('T')[0];
            const endOfMonth = new Date(year, month, 0).toISOString().split('T')[0];
            dataToExport = records.filter(r => r.startDate <= endOfMonth && r.endDate >= startOfMonth);
        }

        const csv = Papa.unparse(dataToExport.map(r => ({
            ID: r.id,
            FSN: r.fsn,
            Brand: r.brand,
            Title: r.title,
            City: r.city,
            Type: r.type,
            Value: r.value,
            StartDate: r.startDate,
            EndDate: r.endDate,
            LastUpdatedBy: r.lastUpdatedBy,
            LastUpdatedAt: new Date(r.lastUpdatedAt).toISOString()
        })));

        const blob = new Blob([csv], { type: 'text/csv' });
        const url = window.URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `mm_export_${mode.toLowerCase()}_${Date.now()}.csv`;
        a.click();
        window.URL.revokeObjectURL(url);
    } catch (e) {
        alert('Export failed');
    } finally {
        setExportLoading(false);
    }
  };

  const handleClearDB = async () => {
    if (window.confirm("CRITICAL: Delete all active records for Month End?")) {
        const confirmText = prompt("Type 'DELETE' to confirm:");
        if (confirmText === 'DELETE') {
            setLoading(true);
            try {
                await db.clearAllRecords(user.name);
                alert("Database reset. Records archived.");
                setAuditResult(null);
                setRequests([]);
                loadArchive();
                setAllFsns([]); // Clear suggestions
            } catch (e) {
                alert("Failed.");
            } finally {
                setLoading(false);
            }
        }
    }
  };

  const CustomTooltip = ({ active, payload, label }: any) => {
    if (active && payload && payload.length) {
      return (
        <div className="bg-white border border-gray-200 p-3 rounded shadow-lg text-xs">
          <p className="font-bold text-gray-800 mb-2">{label}</p>
          {payload.map((entry: any, index: number) => (
            <div key={index} className="flex items-center gap-2 mb-1">
               <div className="w-2 h-2 rounded-full" style={{ backgroundColor: entry.color }} />
               <span className="text-gray-500">{entry.name}:</span>
               <span className="text-gray-900 font-mono font-bold">{Number(entry.value).toFixed(2)}</span>
            </div>
          ))}
          {label === 'System' && (
             <div className="mt-2 pt-2 border-t border-gray-100 flex justify-between gap-4">
                <span className="text-gray-600 font-bold">Total:</span>
                <span className="text-gray-900 font-mono font-bold">{payload.reduce((acc: number, cur: any) => acc + (cur.value || 0), 0).toFixed(2)}</span>
             </div>
          )}
          {label === 'System' && auditResult?.sources && (
              <div className="mt-1 pt-1 border-t border-gray-50 text-[10px] text-gray-400">
                  {auditResult.sources.nlc === 'PAN' && <div>* NLC from PAN-INDIA</div>}
                  {auditResult.sources.onInv === 'PAN' && <div>* On-Inv from PAN-INDIA</div>}
              </div>
          )}
        </div>
      );
    }
    return null;
  };

  return (
    <div className="space-y-6 max-w-7xl mx-auto animate-in fade-in duration-500">
      <div className="flex justify-between items-center border-b border-gray-200 pb-4">
        <div>
            <h2 className="text-2xl font-bold text-gray-800 flex items-center gap-2">
               Checker Workspace
            </h2>
            <p className="text-sm text-gray-500">Audit commercial logic and approvals</p>
        </div>
        <div className="flex gap-1 bg-white p-1 rounded border border-gray-200">
          <button onClick={() => setActiveTab('AUDIT')} className={`px-4 py-2 rounded text-sm font-semibold transition-all ${activeTab === 'AUDIT' ? 'bg-fkBlue text-white shadow-sm' : 'text-gray-500 hover:text-gray-800'}`}>Audit Tool</button>
          <button onClick={() => setActiveTab('APPROVALS')} className={`px-4 py-2 rounded text-sm font-semibold transition-all flex items-center gap-2 ${activeTab === 'APPROVALS' ? 'bg-fkBlue text-white shadow-sm' : 'text-gray-500 hover:text-gray-800'}`}>
            Approvals
            {requests.length > 0 && <span className="bg-red-500 text-white text-[10px] px-1.5 py-0.5 rounded-full">{requests.length}</span>}
          </button>
          <button onClick={() => setActiveTab('CLOSURE')} className={`px-4 py-2 rounded text-sm font-semibold transition-all ${activeTab === 'CLOSURE' ? 'bg-fkYellow text-white shadow-sm' : 'text-gray-500 hover:text-gray-800'}`}>
            Month End
          </button>
        </div>
      </div>

      {activeTab === 'AUDIT' && (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          <div className="lg:col-span-1 space-y-4">
            <div className="fk-card p-6">
              <h3 className="text-sm font-bold uppercase text-gray-400 mb-4 tracking-wider">Run Audit</h3>
              <div className="space-y-3 relative">
                <div className="relative">
                    <input 
                    className="w-full bg-white border border-gray-300 rounded p-2.5 text-gray-900 focus:border-fkBlue outline-none" 
                    placeholder="Enter FSN"
                    value={auditQuery.fsn}
                    onChange={handleFsnChange}
                    onFocus={() => { if(auditQuery.fsn) setShowSuggestions(true); }}
                    maxLength={16}
                    />
                    <Search className="absolute right-3 top-3 w-4 h-4 text-gray-400" />
                </div>

                {/* Autocomplete Suggestions */}
                {showSuggestions && filteredFsns.length > 0 && (
                    <div className="absolute z-10 w-full bg-white border border-gray-200 rounded shadow-lg mt-1 overflow-hidden animate-in fade-in zoom-in-95 duration-100">
                        {filteredFsns.map(fsn => (
                            <button 
                                key={fsn}
                                onClick={() => selectSuggestion(fsn)}
                                className="w-full text-left px-3 py-2 text-sm text-gray-700 hover:bg-blue-50 hover:text-fkBlue transition-colors border-b border-gray-50 last:border-0"
                            >
                                {fsn}
                            </button>
                        ))}
                    </div>
                )}

                <select 
                  className="w-full bg-white border border-gray-300 rounded p-2.5 text-gray-900 focus:border-fkBlue outline-none"
                  value={auditQuery.city}
                  onChange={e => setAuditQuery({...auditQuery, city: e.target.value})}
                >
                  {cities.map(c => <option key={c} value={c}>{c}</option>)}
                </select>
                <input 
                  type="number"
                  className="w-full bg-white border border-gray-300 rounded p-2.5 text-gray-900 focus:border-fkBlue outline-none" 
                  placeholder="Expected Total Value"
                  value={auditQuery.targetMargin || ''}
                  onChange={e => setAuditQuery({...auditQuery, targetMargin: parseFloat(e.target.value)})}
                />
                <button 
                  onClick={handleAudit}
                  disabled={loading}
                  className="w-full bg-fkBlue hover:bg-blue-600 text-white font-bold py-2.5 rounded shadow-sm transition-colors"
                >
                  {loading ? 'Analyzing...' : 'Analyze Variance'}
                </button>
              </div>
            </div>

            {auditResult && (
              <div className={`p-5 rounded-lg border shadow-sm animate-in zoom-in duration-300 ${auditResult.status === 'MATCH' ? 'bg-green-50 border-green-200' : 'bg-red-50 border-red-200'}`}>
                 <div className="flex justify-between items-start mb-2">
                    <div className={`text-lg font-bold flex items-center gap-2 ${auditResult.status === 'MATCH' ? 'text-green-700' : 'text-red-700'}`}>
                        {auditResult.status === 'MATCH' ? <Check className="w-5 h-5"/> : <AlertCircle className="w-5 h-5"/>}
                        {auditResult.status}
                    </div>
                 </div>

                 <div className="mt-4 grid grid-cols-2 gap-4">
                     <div>
                         <p className="text-xs text-gray-500 uppercase font-semibold">Variance Val</p>
                         <p className={`text-xl font-mono font-bold ${auditResult.variance > 0 ? 'text-green-600' : 'text-red-600'}`}>
                            {auditResult.variance > 0 ? '+' : ''}{auditResult.variance.toFixed(2)}
                         </p>
                     </div>
                     <div>
                         <p className="text-xs text-gray-500 uppercase font-semibold">Variance %</p>
                         <div className="flex items-center gap-1">
                            <TrendingUp className={`w-4 h-4 ${parseFloat(auditResult.variancePercent) > 0 ? 'text-green-600' : 'text-red-600'}`} />
                            <p className="text-xl font-mono font-bold text-gray-800">
                                {Math.abs(Number(auditResult.variancePercent))}%
                            </p>
                         </div>
                     </div>
                 </div>
                 {(auditResult.sources.nlc === 'PAN' || auditResult.sources.onInv === 'PAN') && (
                     <div className="mt-3 bg-white/50 p-2 rounded text-[10px] text-gray-600 border border-gray-100">
                         <strong>Note:</strong> Some values inherited from PAN-INDIA default.
                     </div>
                 )}
              </div>
            )}
          </div>

          <div className="lg:col-span-2 fk-card p-6 min-h-[400px]">
            {auditResult ? (
              <div className="h-full w-full">
                <ResponsiveContainer width="100%" height={350}>
                    <BarChart data={auditResult.data} margin={{ top: 20, right: 30, left: 20, bottom: 5 }}>
                        <CartesianGrid strokeDasharray="3 3" stroke="#e0e0e0" vertical={false} />
                        <XAxis dataKey="name" stroke="#9e9e9e" tick={{fill: '#424242', fontSize: 12}} axisLine={false} tickLine={false} />
                        <YAxis stroke="#9e9e9e" tick={{fill: '#424242', fontSize: 12}} axisLine={false} tickLine={false} />
                        <Tooltip content={<CustomTooltip />} cursor={{fill: '#f5f5f5'}} />
                        <Legend wrapperStyle={{ paddingTop: '20px' }} />

                        <Bar dataKey="nlc" stackId="system" name="NLC Value" fill="#2874f0" radius={[0, 0, 4, 4]}>
                           <LabelList dataKey="nlc" position="center" className="fill-white font-bold text-[10px]" formatter={(v: number) => v > 0 ? v.toFixed(0) : ''} />
                        </Bar>
                        <Bar dataKey="onInv" stackId="system" name="On Invoice %" fill="#8b5cf6" radius={[4, 4, 0, 0]}>
                           <LabelList dataKey="onInv" position="center" className="fill-white font-bold text-[10px]" formatter={(v: number) => v > 0 ? v.toFixed(0) : ''} />
                        </Bar>

                        <Bar dataKey="target" stackId="target" name="User Target" fill={auditResult.status === 'MATCH' ? '#388e3c' : '#ff9f00'} radius={[4, 4, 4, 4]}>
                             <LabelList dataKey="target" position="top" className="fill-gray-600 font-bold text-xs" formatter={(v: number) => v.toFixed(2)} />
                        </Bar>

                        {auditResult.status === 'MISMATCH' && (
                             <ReferenceLine 
                                y={auditResult.targetTotal} 
                                stroke="#ff9f00" 
                                strokeDasharray="3 3" 
                             />
                        )}
                    </BarChart>
                </ResponsiveContainer>
              </div>
            ) : (
              <div className="h-full flex flex-col items-center justify-center text-gray-400">
                <BarChart3 className="w-16 h-16 mb-4 opacity-20" />
                <p>Run analysis to view chart</p>
              </div>
            )}
          </div>
        </div>
      )}

      {activeTab === 'APPROVALS' && (
        <div className="space-y-4">
          {requests.length === 0 ? (
            <div className="text-center py-20 bg-white rounded-lg border border-gray-200">
              <Check className="w-12 h-12 mx-auto mb-3 text-green-500 opacity-50" />
              <p className="text-gray-500 font-medium">No pending approvals.</p>
            </div>
          ) : (
            requests.map(req => (
              <div key={req.id} className="fk-card p-5 flex flex-col md:flex-row justify-between items-start md:items-center gap-4 border-l-4 border-l-fkYellow">
                <div>
                  <div className="flex items-center gap-2 mb-2">
                    <span className="bg-yellow-100 text-yellow-800 text-xs px-2 py-0.5 rounded font-bold">CONFLICT DETECTED</span>
                    <h4 className="font-bold text-gray-800 text-lg">{req.payload.title} <span className="text-gray-400 font-normal">({req.payload.fsn})</span></h4>
                  </div>
                  <div className="text-sm text-gray-500 grid grid-cols-2 md:grid-cols-4 gap-x-8 gap-y-1">
                    <span>City: <b className="text-gray-800">{req.payload.city}</b></span>
                    <span>Type: <b className="text-gray-800">{req.payload.type}</b></span>
                    <span>New Value: <b className="text-fkBlue">{req.payload.value}</b></span>
                    <span>By: {req.requestedBy}</span>
                  </div>
                </div>
                <div className="flex gap-2 w-full md:w-auto">
                  <button 
                    onClick={() => handleRequestAction(req.id, 'REJECTED')}
                    className="flex-1 md:flex-none px-4 py-2 rounded bg-gray-100 hover:bg-gray-200 text-gray-700 text-sm font-medium transition-colors"
                  >
                    Reject
                  </button>
                  <button 
                    onClick={() => handleRequestAction(req.id, 'APPROVED')}
                    className="flex-1 md:flex-none px-4 py-2 rounded bg-fkGreen hover:bg-green-700 text-white font-bold text-sm shadow transition-colors"
                  >
                    Approve Override
                  </button>
                </div>
              </div>
            ))
          )}
        </div>
      )}

      {activeTab === 'CLOSURE' && (
        <div className="space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                {/* Export Section */}
                <div className="fk-card p-6 space-y-4">
                    <div className="flex items-center gap-3 mb-2">
                        <div className="bg-blue-50 p-3 rounded-lg">
                            <FileDown className="w-6 h-6 text-fkBlue" />
                        </div>
                        <div>
                            <h3 className="text-lg font-bold text-gray-800">Export Data</h3>
                            <p className="text-sm text-gray-500">Download data for records and auditing.</p>
                        </div>
                    </div>

                    <div className="pt-4 space-y-4 border-t border-gray-100">
                        <div>
                            <label className="block text-xs font-bold text-gray-500 mb-2 flex items-center gap-2 uppercase">
                                <Calendar className="w-3 h-3" /> Select Month
                            </label>
                            <input 
                                type="month"
                                className="w-full bg-white border border-gray-300 rounded p-2 text-gray-800"
                                value={selectedMonth}
                                onChange={(e) => setSelectedMonth(e.target.value)}
                            />
                        </div>
                        <div className="flex flex-col gap-3">
                            <button 
                                onClick={() => handleExport('MONTH')}
                                disabled={exportLoading}
                                className="w-full py-2 bg-fkBlue hover:bg-blue-600 rounded text-white text-sm font-bold shadow-sm transition-colors"
                            >
                                {exportLoading ? 'Generating CSV...' : `Export ${selectedMonth} Data`}
                            </button>
                            <button 
                                onClick={() => handleExport('FULL')}
                                disabled={exportLoading}
                                className="w-full py-2 border border-gray-300 hover:bg-gray-50 rounded text-gray-600 text-sm font-medium transition-colors"
                            >
                                Export Full Database
                            </button>
                        </div>
                    </div>
                </div>

                {/* Clear Section */}
                <div className="fk-card p-6 space-y-4 border-red-100 bg-red-50/30">
                    <div className="flex items-center gap-3 mb-2">
                        <div className="bg-red-100 p-3 rounded-lg">
                            <Database className="w-6 h-6 text-red-600" />
                        </div>
                        <div>
                            <h3 className="text-lg font-bold text-red-600">System Reset</h3>
                            <p className="text-sm text-gray-500">Clear database for new operational cycle.</p>
                        </div>
                    </div>

                    <div className="pt-4 space-y-4 border-t border-red-100">
                        <div className="bg-red-50 border border-red-100 p-4 rounded text-sm text-red-700">
                            <p className="flex items-start gap-2">
                                <AlertCircle className="w-5 h-5 flex-shrink-0" />
                                <span>
                                    <strong>Warning:</strong> This deletes ALL active records. Export data first.
                                </span>
                            </p>
                        </div>

                        <button 
                            onClick={handleClearDB}
                            disabled={loading}
                            className="w-full py-3 bg-red-600 hover:bg-red-700 rounded text-white font-bold shadow-md flex items-center justify-center gap-2 transition-all"
                        >
                            {loading ? 'Clearing...' : <><Trash2 className="w-4 h-4" /> Clear Database</>}
                        </button>
                    </div>
                </div>
            </div>

            {/* Archive Viewer */}
            <div className="fk-card p-6 space-y-4">
                 <div className="flex items-center justify-between">
                     <h3 className="text-lg font-bold text-gray-800 flex items-center gap-2">
                        <Archive className="w-5 h-5 text-gray-500" /> Archived Records (Bin)
                     </h3>
                     <button onClick={toggleArchive} className="flex items-center gap-2 text-sm text-fkBlue hover:underline transition-colors font-medium">
                        {showArchive ? 'Hide Archive' : 'View Deleted Records'}
                        <Clock className="w-3 h-3" />
                     </button>
                 </div>

                 {showArchive && (
                     <div className="overflow-auto max-h-80 border border-gray-200 rounded-lg animate-in fade-in">
                        <table className="w-full text-left text-xs text-gray-600">
                            <thead className="bg-gray-50 sticky top-0 font-bold text-gray-700 border-b border-gray-200">
                                <tr>
                                    <th className="p-3">Deleted At</th>
                                    <th className="p-3">Deleted By</th>
                                    <th className="p-3">FSN</th>
                                    <th className="p-3">City</th>
                                    <th className="p-3">Reason</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-gray-100 bg-white">
                                {archiveData.map((r, i) => (
                                    <tr key={i} className="hover:bg-gray-50">
                                        <td className="p-3 font-mono text-gray-500">{new Date(r.deletedAt).toLocaleString()}</td>
                                        <td className="p-3">{r.deletedBy}</td>
                                        <td className="p-3 font-medium">{r.fsn}</td>
                                        <td className="p-3">{r.city}</td>
                                        <td className="p-3 text-fkYellow font-medium">{r.note || 'Manual Delete/Override'}</td>
                                    </tr>
                                ))}
                                {archiveData.length === 0 && <tr><td colSpan={5} className="p-6 text-center italic text-gray-400">Bin is empty</td></tr>}
                            </tbody>
                        </table>
                     </div>
                 )}
            </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { db } from '../services/db';
import { CommercialRecord, User, Role, COMMERCIAL_TYPES, CommercialType } from '../types';
import { Download, Filter, RefreshCw, Trash2, Edit2, Save, X, Clock } from 'lucide-react';

interface DataExplorerProps {
  user: User;
}

interface PivotRow {
  key: string;
  fsn: string;
  brand: string;
  title: string;
  type: CommercialType;
  startDate: string;
  endDate: string;
  cityRecords: { [key: string]: CommercialRecord | undefined };
  values: { [key: string]: number | undefined };
  isExpiringSoon: boolean;
}

export const DataExplorer: React.FC<DataExplorerProps> = ({ user }) => {
  const [records, setRecords] = useState<CommercialRecord[]>([]);
  const [cities, setCities] = useState<string[]>([]);
  const [loading, setLoading] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');

  // Edit State
  const [editingRowKey, setEditingRowKey] = useState<string | null>(null);
  const [editForm, setEditForm] = useState<Partial<PivotRow> | null>(null);
  const [processingAction, setProcessingAction] = useState(false);

  // Permission Check
  const canEdit = user.role !== Role.MAKER;

  useEffect(() => {
    let unsubscribe: () => void;

    const init = async () => {
      setLoading(true);
      try {
        const c = await db.getCities();
        setCities(c);
        unsubscribe = db.subscribeToRecords((data) => {
          setRecords(data);
          setLoading(false);
        });
      } catch (e) {
        console.error("Failed to load data", e);
        setLoading(false);
      }
    };

    init();

    return () => {
      if (unsubscribe) unsubscribe();
    };
  }, []);

  const pivotData: PivotRow[] = useMemo(() => {
    const map = new Map<string, PivotRow>();
    const today = new Date();
    const sevenDaysLater = new Date();
    sevenDaysLater.setDate(today.getDate() + 7);

    records.forEach(r => {
      const key = `${r.fsn}_${r.type}_${r.startDate}_${r.endDate}`;
      if (!map.has(key)) {
        const endDate = new Date(r.endDate);
        const isExpiringSoon = endDate >= today && endDate <= sevenDaysLater;

        map.set(key, {
          key,
          fsn: r.fsn,
          brand: r.brand,
          title: r.title,
          type: r.type,
          startDate: r.startDate,
          endDate: r.endDate,
          cityRecords: {},
          values: {},
          isExpiringSoon
        });
      }
      const entry = map.get(key)!;
      entry.cityRecords[r.city] = r;
      entry.values[r.city] = r.value;
    });
    let result = Array.from(map.values());
    if (searchTerm) {
      const lower = searchTerm.toLowerCase();
      result = result.filter(item => 
        item.fsn.toLowerCase().includes(lower) || 
        item.brand.toLowerCase().includes(lower) ||
        item.title.toLowerCase().includes(lower)
      );
    }
    return result;
  }, [records, searchTerm]);

  const exportCSV = () => {
    const headers = ['FSN', 'Brand', 'Title', 'Type', 'Start', 'End', ...cities].join(',');
    const rows = pivotData.map(row => {
      const cityVals = cities.map(c => {
          const val = row.values[c];
          const pan = row.values['PAN-INDIA'];
          // Export effective value
          return val !== undefined ? val : (pan !== undefined ? pan : '');
      }).join(',');
      return `${row.fsn},${row.brand},${row.title},${row.type},${row.startDate},${row.endDate},${cityVals}`;
    }).join('\n');

    const blob = new Blob([headers + '\n' + rows], { type: 'text/csv' });
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `mm_export_${Date.now()}.csv`;
    a.click();
    window.URL.revokeObjectURL(url);
  };

  const handleEditClick = (row: PivotRow) => {
    setEditingRowKey(row.key);
    setEditForm({ ...row, values: { ...row.values } });
  };

  const handleCancelEdit = () => {
    setEditingRowKey(null);
    setEditForm(null);
  };

  const handleDeleteRow = async (row: PivotRow) => {
    if (!canEdit) return;
    if (!window.confirm(`Delete all records for ${row.title} (${row.type})?`)) return;
    setProcessingAction(true);
    try {
      const idsToDelete = records
        .filter(r => r.fsn === row.fsn && r.type === row.type && r.startDate === row.startDate && r.endDate === row.endDate)
        .map(r => r.id);
      if (idsToDelete.length === 0) return;
      await db.deleteRecords(idsToDelete, user.name);
    } catch (e) {
      alert('Error deleting records');
    } finally {
      setProcessingAction(false);
    }
  };

  const handleSaveEdit = async (originalRow: PivotRow) => {
    if (!editForm || !canEdit) return;

    if ((editForm.fsn || originalRow.fsn).length !== 16) {
        alert("FSN must be exactly 16 characters.");
        return;
    }

    setProcessingAction(true);
    try {
      const recordsToUpdate = records.filter(r => 
          r.fsn === originalRow.fsn && r.type === originalRow.type && r.startDate === originalRow.startDate && r.endDate === originalRow.endDate
      );

      const updatePromises: Promise<void>[] = [];
      const recordsForBulkUpdate: CommercialRecord[] = [];

      recordsToUpdate.forEach(r => {
        const newCityValue = editForm.values?.[r.city];
        const updatedRecord: CommercialRecord = {
          ...r,
          fsn: editForm.fsn || r.fsn,
          brand: editForm.brand || r.brand,
          title: editForm.title || r.title,
          type: editForm.type || r.type,
          startDate: editForm.startDate || r.startDate,
          endDate: editForm.endDate || r.endDate,
          value: newCityValue !== undefined ? Number(newCityValue) : r.value,
          lastUpdatedBy: user.name,
          lastUpdatedAt: Date.now()
        };
        recordsForBulkUpdate.push(updatedRecord);
      });

      if (recordsForBulkUpdate.length > 0) updatePromises.push(db.updateRecords(recordsForBulkUpdate));

      for (const city of cities) {
        const hasExisting = recordsToUpdate.some(r => r.city === city);
        const newVal = editForm.values?.[city];
        // Note: We do NOT inherit PAN-INDIA during save. Saving creates an explicit override.
        if (!hasExisting && newVal !== undefined && Number(newVal) !== 0) {
           updatePromises.push(db.addRecords([{
             id: `rec_${Date.now()}_${Math.random().toString(36).substr(2,5)}`,
             fsn: editForm.fsn!,
             brand: editForm.brand!,
             title: editForm.title!,
             type: editForm.type!,
             city: city,
             startDate: editForm.startDate!,
             endDate: editForm.endDate!,
             value: Number(newVal),
             lastUpdatedBy: user.name,
             lastUpdatedAt: Date.now()
           }]));
        }
      }
      await Promise.all(updatePromises);
      setEditingRowKey(null);
      setEditForm(null);
    } catch (e) {
      alert('Failed to save changes');
    } finally {
      setProcessingAction(false);
    }
  };

  const refreshCities = async () => {
    setLoading(true);
    const c = await db.getCities();
    setCities(c);
    setLoading(false);
  };

  return (
    <div className="space-y-4 h-full flex flex-col animate-in fade-in duration-500">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
           <h2 className="text-2xl font-bold text-gray-800">Database Explorer</h2>
           <p className="text-sm text-gray-500">Search and edit active commercial records</p>
        </div>
        <div className="flex gap-2">
           <div className="relative">
             <Filter className="absolute left-3 top-2.5 h-4 w-4 text-gray-400"/>
             <input 
               className="bg-white border border-gray-300 rounded shadow-sm py-2 pl-9 pr-4 text-sm text-gray-800 focus:ring-1 focus:ring-fkBlue focus:border-fkBlue outline-none w-64 transition-shadow"
               placeholder="Filter by FSN, Brand..."
               value={searchTerm}
               onChange={e => setSearchTerm(e.target.value)}
             />
           </div>
           <button onClick={refreshCities} className="p-2 bg-white border border-gray-300 rounded hover:bg-gray-50 text-gray-600 shadow-sm">
             <RefreshCw className={`h-5 w-5 ${loading ? 'animate-spin' : ''}`} />
           </button>
           <button onClick={exportCSV} className="flex items-center gap-2 px-4 py-2 bg-fkGreen hover:bg-green-700 text-white rounded shadow-sm text-sm font-bold transition-colors">
             <Download className="h-4 w-4" /> Export CSV
           </button>
        </div>
      </div>

      <div className="flex-1 bg-white rounded-lg shadow-sm border border-gray-200 overflow-hidden flex flex-col relative">
        {processingAction && (
          <div className="absolute inset-0 bg-white/60 z-50 flex items-center justify-center backdrop-blur-sm">
            <RefreshCw className="w-8 h-8 text-fkBlue animate-spin" />
          </div>
        )}

        <div className="overflow-auto scrollbar-hide flex-1">
          <table className="w-full text-left border-collapse min-w-[1400px]">
            <thead className="bg-gray-50 sticky top-0 z-10 text-xs uppercase text-gray-500 font-semibold shadow-sm">
              <tr>
                <th className="p-4 border-b border-gray-200 min-w-[120px] bg-gray-50">FSN</th>
                <th className="p-4 border-b border-gray-200 bg-gray-50">Brand</th>
                <th className="p-4 border-b border-gray-200 bg-gray-50">Title</th>
                <th className="p-4 border-b border-gray-200 bg-gray-50 min-w-[120px]">Type</th>
                <th className="p-4 border-b border-gray-200 text-center min-w-[200px] bg-gray-50">Dates</th>
                {cities.map(c => (
                  <th key={c} className="p-4 border-b border-gray-200 text-center min-w-[80px] bg-gray-50">{c}</th>
                ))}
                {canEdit && <th className="p-4 border-b border-gray-200 text-center sticky right-0 bg-gray-50 z-20 w-24">Actions</th>}
              </tr>
            </thead>
            <tbody className="text-sm divide-y divide-gray-100">
              {pivotData.map((row) => {
                const isEditing = editingRowKey === row.key;
                return (
                  <tr key={row.key} className={`hover:bg-blue-50/50 transition-colors group ${isEditing ? 'bg-blue-50' : ''}`}>
                    <td className="p-4 font-mono text-fkBlue font-semibold">
                        {isEditing ? (
                            <input className="w-full bg-white border border-gray-300 rounded px-2 py-1 text-gray-800 text-xs font-mono"
                              value={editForm?.fsn || ''} onChange={e => setEditForm(prev => ({ ...prev!, fsn: e.target.value }))} 
                              maxLength={16}
                              />
                        ) : (
                          <div className="flex items-center gap-2">
                             {row.fsn}
                             {row.isExpiringSoon && (
                               <span title="Expiring within 7 days">
                                 <Clock className="w-3 h-3 text-fkYellow animate-pulse" />
                               </span>
                             )}
                          </div>
                        )}
                    </td>
                    <td className="p-4 text-gray-700 max-w-[150px] truncate">
                        {isEditing ? (
                            <input className="w-full bg-white border border-gray-300 rounded px-2 py-1 text-gray-800 text-xs"
                              value={editForm?.brand || ''} onChange={e => setEditForm(prev => ({ ...prev!, brand: e.target.value }))} />
                        ) : row.brand}
                    </td>
                    <td className="p-4 text-gray-700 max-w-[200px] truncate" title={row.title}>
                        {isEditing ? (
                            <input className="w-full bg-white border border-gray-300 rounded px-2 py-1 text-gray-800 text-xs"
                              value={editForm?.title || ''} onChange={e => setEditForm(prev => ({ ...prev!, title: e.target.value }))} />
                        ) : row.title}
                    </td>
                    <td className="p-4">
                      {isEditing ? (
                          <select className="w-full bg-white border border-gray-300 rounded px-2 py-1 text-gray-800 text-xs"
                             value={editForm?.type} onChange={e => setEditForm(prev => ({ ...prev!, type: e.target.value as CommercialType }))}>
                            {COMMERCIAL_TYPES.map(t => <option key={t} value={t}>{t}</option>)}
                          </select>
                      ) : (
                          <span className={`px-2 py-1 rounded text-[10px] border whitespace-nowrap font-medium ${
                            row.type.includes('Margin') ? 'border-purple-200 text-purple-700 bg-purple-50' : 
                            'border-blue-200 text-blue-700 bg-blue-50'
                          }`}>
                            {row.type}
                          </span>
                      )}
                    </td>
                    <td className="p-4 text-gray-500 text-xs text-center">
                      {isEditing ? (
                        <div className="flex flex-col gap-2">
                           <input type="date" className="bg-white border border-gray-300 rounded px-2 py-1 text-gray-800 text-xs w-full"
                             value={editForm?.startDate || row.startDate} onChange={e => setEditForm(prev => ({ ...prev!, startDate: e.target.value }))} />
                           <input type="date" className="bg-white border border-gray-300 rounded px-2 py-1 text-gray-800 text-xs w-full"
                             value={editForm?.endDate || row.endDate} onChange={e => setEditForm(prev => ({ ...prev!, endDate: e.target.value }))} />
                        </div>
                      ) : (
                        <div className="flex flex-col items-center">
                           <span className="font-mono">{row.startDate}</span>
                           <span className="text-[10px] text-gray-400">to</span>
                           <span className={`font-mono ${row.isExpiringSoon ? 'text-fkYellow font-bold' : ''}`}>{row.endDate}</span>
                        </div>
                      )}
                    </td>
                    {cities.map(c => {
                      const specificVal = row.values[c];
                      const panVal = row.values['PAN-INDIA'];
                      const effectiveVal = specificVal !== undefined ? specificVal : (c !== 'PAN-INDIA' ? panVal : undefined);
                      const isInherited = specificVal === undefined && effectiveVal !== undefined;

                      return (
                        <td key={c} className={`p-2 text-center border-l border-gray-100 ${isEditing ? 'p-1' : ''}`}>
                           {isEditing ? (
                             <input type="number" className="w-16 bg-white border border-gray-300 rounded px-1 py-1 text-center text-gray-800 text-sm focus:border-fkBlue outline-none"
                               value={editForm?.values?.[c] ?? ''} placeholder={isInherited ? String(effectiveVal) : '-'}
                               onChange={e => {
                                 const val = e.target.value;
                                 setEditForm(prev => ({ ...prev!, values: { ...prev!.values, [c]: val === '' ? undefined : parseFloat(val) } }));
                               }} />
                           ) : (
                               effectiveVal !== undefined ? (
                                   <span className={isInherited ? "text-gray-400 italic" : "text-gray-800 font-bold"}>
                                     {effectiveVal}
                                     {isInherited && <span className="ml-1 text-[8px] border border-gray-200 rounded px-0.5 text-gray-400 not-italic">PAN</span>}
                                   </span>
                               ) : <span className="text-gray-300">-</span>
                           )}
                        </td>
                      );
                    })}
                    {canEdit && (
                      <td className="p-4 border-l border-gray-200 sticky right-0 bg-white group-hover:bg-blue-50/50 transition-colors z-10 shadow-[-5px_0_10px_-5px_rgba(0,0,0,0.1)]">
                        <div className="flex items-center justify-center gap-2">
                          {isEditing ? (
                            <>
                              <button onClick={() => handleSaveEdit(row)} className="p-1.5 bg-green-600 hover:bg-green-700 rounded text-white shadow-sm" title="Save">
                                <Save className="w-4 h-4" />
                              </button>
                              <button onClick={handleCancelEdit} className="p-1.5 bg-gray-500 hover:bg-gray-600 rounded text-white" title="Cancel">
                                <X className="w-4 h-4" />
                              </button>
                            </>
                          ) : (
                            <>
                              <button onClick={() => handleEditClick(row)} className="p-1.5 hover:bg-blue-100 text-gray-400 hover:text-fkBlue rounded transition-colors">
                                <Edit2 className="w-4 h-4" />
                              </button>
                              <button onClick={() => handleDeleteRow(row)} className="p-1.5 hover:bg-red-100 text-gray-400 hover:text-red-600 rounded transition-colors">
                                <Trash2 className="w-4 h-4" />
                              </button>
                            </>
                          )}
                        </div>
                      </td>
                    )}
                  </tr>
                );
              })}
              {pivotData.length === 0 && !loading && (
                 <tr><td colSpan={cities.length + 6} className="p-8 text-center text-gray-500">No records found.</td></tr>
              )}
            </tbody>
          </table>
        </div>
        <div className="bg-gray-50 p-2 text-xs text-gray-500 text-center border-t border-gray-200">
          Showing {pivotData.length} records
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { CommercialRecord, CommercialType, DuplicateRequest, User, COMMERCIAL_TYPES } from '../types';
import { db } from '../services/db';
import { Plus, Upload, Save, AlertTriangle, FileText, X, Download, Check, Trash2, ArrowUpRight, ShieldAlert } from 'lucide-react';
import Papa from 'papaparse';

interface MakerProps {
  user: User;
}

export const MakerWorkspace: React.FC<MakerProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<'MANUAL' | 'BULK'>('MANUAL');

  // Dynamic Cities
  const [cities, setCities] = useState<string[]>([]);
  const [isAddingCity, setIsAddingCity] = useState(false);
  const [newCityCode, setNewCityCode] = useState('');

  // Manual Form State
  const [formData, setFormData] = useState<Partial<CommercialRecord>>({
    city: 'PAN-INDIA',
    type: CommercialType.MARGIN_PERCENT,
    startDate: new Date().toISOString().split('T')[0],
    endDate: new Date(new Date().setMonth(new Date().getMonth() + 3)).toISOString().split('T')[0]
  });

  // Real-time Validation State
  const [instantConflict, setInstantConflict] = useState<boolean>(false);

  // Bulk State
  const [bulkType, setBulkType] = useState<CommercialType>(CommercialType.MARGIN_PERCENT);

  const [loading, setLoading] = useState(false);
  const [notification, setNotification] = useState<{msg: string, type: 'success' | 'error' | 'warning' | null}>({ msg: '', type: null });

  // Initialize Data
  useEffect(() => {
    const init = async () => {
      // 1. Load Draft
      const draft = localStorage.getItem('mm_draft_form');
      let draftData = {};
      if (draft) {
        draftData = JSON.parse(draft);
        setFormData(draftData);
      }

      // 2. Load Cities and Validate
      const c = await db.getCities();
      setCities(c);

      // Validate the city from draft or current state
      const currentCity = (draftData as any).city || formData.city || 'PAN-INDIA';
      if (!c.includes(currentCity)) {
         setFormData(prev => ({ ...prev, city: c[0] || 'PAN-INDIA' }));
      }
    };

    init();
  }, []);

  // Save draft & Real-time Check
  useEffect(() => {
    localStorage.setItem('mm_draft_form', JSON.stringify(formData));

    // Debounce the conflict check
    const timeoutId = setTimeout(async () => {
        if(formData.fsn && formData.city && formData.type && formData.startDate && formData.endDate) {
            const records = await db.getRecords();
            const conflict = records.some(r => 
                r.fsn === formData.fsn &&
                r.city === formData.city &&
                r.type === formData.type &&
                r.startDate === formData.startDate &&
                r.endDate === formData.endDate
            );
            setInstantConflict(conflict);
        } else {
            setInstantConflict(false);
        }
    }, 500);

    return () => clearTimeout(timeoutId);
  }, [formData]);

  const refreshCities = async () => {
    const c = await db.getCities();
    setCities(c);
    return c;
  };

  const handleAddNewCity = async () => {
    if (!newCityCode) return;
    const code = newCityCode.toUpperCase().trim();
    if (code !== 'PAN-INDIA' && code.length > 3) {
       setNotification({ msg: 'City code must be 3 characters or less.', type: 'error' });
       return;
    }
    const cleanCode = code.replace(/[^A-Z0-9]/g, '');
    if (!cleanCode) return;
    if (cities.includes(cleanCode)) {
       setNotification({ msg: `City ${cleanCode} already exists.`, type: 'warning' });
       return;
    }
    if (cleanCode) {
       await db.addCity(cleanCode);
       await refreshCities();
       setFormData(prev => ({...prev, city: cleanCode}));
       setNewCityCode('');
       setIsAddingCity(false);
       setNotification({ msg: `City ${cleanCode} added.`, type: 'success' });
    }
  };

  const handleDeleteCity = async () => {
    const cityToDelete = formData.city;
    if (!cityToDelete || cityToDelete === 'PAN-INDIA') {
        setNotification({ msg: 'Cannot delete default PAN-INDIA city.', type: 'error' });
        return;
    }
    if (window.confirm(`Delete city code "${cityToDelete}"?`)) {
        try {
            await db.deleteCity(cityToDelete);
            const updatedCities = await refreshCities();
            setFormData(prev => ({ ...prev, city: updatedCities[0] || 'PAN-INDIA' }));
            setNotification({ msg: `City ${cityToDelete} removed.`, type: 'success' });
        } catch (err) {
            setNotification({ msg: 'Failed to delete city.', type: 'error' });
        }
    }
  };

  const handleManualSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setNotification({ msg: '', type: null });

    if (!formData.fsn || !formData.value || !formData.brand || !formData.title) {
        setNotification({ msg: 'Please fill all fields', type: 'error' });
        return;
    }

    // Strict FSN Length Check
    if (formData.fsn.length !== 16) {
        setNotification({ msg: 'FSN must be exactly 16 characters.', type: 'error' });
        return;
    }

    if (formData.type !== CommercialType.MARGIN_PERCENT && formData.endDate! < formData.startDate!) {
        setNotification({ msg: 'End Date cannot be before Start Date', type: 'error' });
        return;
    }

    setLoading(true);

    try {
      const records = await db.getRecords();
      const isDuplicate = records.some(r => 
        r.fsn === formData.fsn &&
        r.city === formData.city &&
        r.type === formData.type &&
        r.startDate === formData.startDate &&
        r.endDate === formData.endDate &&
        r.value === Number(formData.value)
      );

      const isConflict = records.some(r => 
        r.fsn === formData.fsn &&
        r.city === formData.city &&
        r.type === formData.type &&
        r.startDate === formData.startDate &&
        r.endDate === formData.endDate
      );

      const newRecord: CommercialRecord = {
        id: `rec_${Date.now()}`,
        ...formData as CommercialRecord,
        value: Number(formData.value),
        lastUpdatedBy: user.name,
        lastUpdatedAt: Date.now()
      };

      if (isDuplicate) {
        setNotification({ msg: 'Exact duplicate already exists.', type: 'warning' });
      } else if (isConflict) {
        const req: DuplicateRequest = {
          id: `req_${Date.now()}`,
          originalRecordId: null,
          payload: newRecord,
          requestedBy: user.name,
          requestedAt: Date.now(),
          status: 'PENDING'
        };
        await db.createDuplicateRequest(req);
        setNotification({ msg: 'Conflict found. Request sent to Checker.', type: 'warning' });
      } else {
        await db.addRecords([newRecord]);
        setNotification({ msg: 'Record saved successfully.', type: 'success' });
        setFormData(prev => ({ 
            ...prev, 
            fsn: '', 
            value: 0,
            // Reset dates to defaults just in case
            startDate: new Date().toISOString().split('T')[0],
            endDate: new Date(new Date().setMonth(new Date().getMonth() + 3)).toISOString().split('T')[0]
        }));
      }
    } catch (err) {
      setNotification({ msg: 'Failed to save record.', type: 'error' });
    } finally {
      setLoading(false);
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    Papa.parse(file, {
      header: true,
      skipEmptyLines: true,
      complete: async (results) => {
        setLoading(true);
        const newRecords: CommercialRecord[] = [];
        const duplicates: CommercialRecord[] = [];
        const existingRecords = await db.getRecords();

        results.data.forEach((row: any) => {
           if(!row.FSN) return;
           const cityKeys = Object.keys(row).filter(k => cities.includes(k) || k === 'Value');

           cityKeys.forEach(cityKey => {
             const city = cityKey === 'Value' ? 'PAN-INDIA' : cityKey;
             let val = parseFloat(row[cityKey]);
             if (isNaN(val)) return;

             if (bulkType !== CommercialType.NLC_VALUE && val <= 1 && val > 0) {
                val = val * 100;
             }

             // Note: For bulk uploads, we might want to flag invalid FSNs or skip them.
             // Here we just proceed, assuming bulk data might need manual cleanup or stricter parsing logic elsewhere.

             const rec: CommercialRecord = {
               id: `rec_${Math.random().toString(36).substr(2,9)}`,
               fsn: row.FSN,
               brand: row.Brand || 'Unknown',
               title: row.Title || 'Bulk Upload Item',
               city: city,
               startDate: row.StartDate,
               endDate: row.EndDate,
               type: bulkType,
               value: val,
               lastUpdatedBy: user.name,
               lastUpdatedAt: Date.now()
             };

             const exists = existingRecords.some(r => 
                r.fsn === rec.fsn &&
                r.city === rec.city &&
                r.type === rec.type &&
                r.startDate === rec.startDate &&
                r.endDate === rec.endDate
             );

             if (exists) {
               duplicates.push(rec);
             } else {
               newRecords.push(rec);
             }
           });
        });

        if (newRecords.length > 0) {
          await db.addRecords(newRecords);
        }

        if (duplicates.length > 0) {
           for (const dup of duplicates) {
              const req: DuplicateRequest = {
                id: `req_${Math.random().toString(36).substr(2,9)}`,
                originalRecordId: null,
                payload: dup,
                requestedBy: user.name,
                requestedAt: Date.now(),
                status: 'PENDING'
              };
              await db.createDuplicateRequest(req);
           }
           setNotification({ 
             msg: `Uploaded ${newRecords.length} records. ${duplicates.length} conflicts sent for approval.`, 
             type: 'warning' 
           });
        } else {
           setNotification({ msg: `Successfully uploaded ${newRecords.length} records.`, type: 'success' });
        }
        setLoading(false);
      }
    });
  };

  const downloadTemplate = () => {
    const headers = ['FSN', 'Brand', 'Title', 'StartDate', 'EndDate', ...cities];
    const isNLC = bulkType === CommercialType.NLC_VALUE;
    const exampleVal = isNLC ? '50000' : '10';
    const dummyRows = [
        ['MOBEXAMPLE1', 'BrandX', 'Sample Product 1', '2024-01-01', '2024-03-31', ...cities.map(() => exampleVal)],
    ];
    const csvContent = [headers.join(','), ...dummyRows.map(row => row.join(','))].join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv' });
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `template_${bulkType.replace(/\s/g, '')}.csv`;
    a.click();
    window.URL.revokeObjectURL(url);
  };

  return (
    <div className="space-y-6 animate-in slide-in-from-bottom-4 duration-500 max-w-7xl mx-auto">
      <div className="flex justify-between items-center">
        <div>
           <h2 className="text-2xl font-bold text-gray-800">Maker Workspace</h2>
           <p className="text-sm text-gray-500">Manage commercials and offers</p>
        </div>
        <div className="flex bg-white rounded shadow-sm border border-gray-200 p-1">
          <button
            onClick={() => setActiveTab('MANUAL')}
            className={`px-4 py-2 rounded text-sm font-medium transition-all ${activeTab === 'MANUAL' ? 'bg-fkBlue text-white shadow' : 'text-gray-500 hover:text-gray-900'}`}
          >
            Manual Entry
          </button>
          <button
            onClick={() => setActiveTab('BULK')}
            className={`px-4 py-2 rounded text-sm font-medium transition-all ${activeTab === 'BULK' ? 'bg-fkBlue text-white shadow' : 'text-gray-500 hover:text-gray-900'}`}
          >
            Bulk Upload
          </button>
        </div>
      </div>

      {notification.msg && (
        <div className={`p-4 rounded border flex items-center gap-3 shadow-sm ${
          notification.type === 'error' ? 'bg-red-50 border-red-200 text-red-700' :
          notification.type === 'warning' ? 'bg-orange-50 border-orange-200 text-orange-800' :
          'bg-green-50 border-green-200 text-green-700'
        }`}>
          {notification.type === 'error' ? <AlertTriangle className="h-5 w-5"/> : <FileText className="h-5 w-5"/>}
          <span className="font-medium">{notification.msg}</span>
          <button onClick={() => setNotification({msg:'', type:null})} className="ml-auto hover:bg-white/50 rounded p-1"><X className="h-4 w-4"/></button>
        </div>
      )}

      {/* Real-time Conflict Alert */}
      {instantConflict && activeTab === 'MANUAL' && (
        <div className="p-3 bg-yellow-50 border-l-4 border-fkYellow rounded shadow-sm flex items-center gap-3 animate-in fade-in slide-in-from-top-2">
            <ShieldAlert className="text-fkYellow w-6 h-6" />
            <div>
                <p className="font-bold text-gray-800 text-sm">Conflict Detected!</p>
                <p className="text-xs text-gray-600">A record already exists for this FSN, City, Type, and Date Range. Saving will trigger an override request.</p>
            </div>
        </div>
      )}

      {activeTab === 'MANUAL' ? (
        <form onSubmit={handleManualSubmit} className="fk-card p-6 grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          <div className="col-span-1">
            <label className="block text-xs font-semibold text-gray-500 uppercase mb-1">FSN (Product ID)</label>
            <div className="relative">
                <input 
                  className="w-full bg-white border border-gray-300 rounded p-2.5 text-gray-900 focus:border-fkBlue focus:ring-1 focus:ring-fkBlue outline-none transition-colors" 
                  value={formData.fsn || ''}
                  onChange={e => setFormData({...formData, fsn: e.target.value})}
                  placeholder="16 Characters Required"
                  maxLength={16}
                />
                <div className={`text-[10px] text-right mt-1 font-mono ${formData.fsn?.length === 16 ? 'text-green-600' : 'text-gray-400'}`}>
                    {formData.fsn?.length || 0}/16
                </div>
            </div>
          </div>
          <div className="col-span-1">
            <label className="block text-xs font-semibold text-gray-500 uppercase mb-1">Brand</label>
            <input 
              className="w-full bg-white border border-gray-300 rounded p-2.5 text-gray-900 focus:border-fkBlue focus:ring-1 focus:ring-fkBlue outline-none transition-colors" 
              value={formData.brand || ''}
              onChange={e => setFormData({...formData, brand: e.target.value})}
              placeholder="e.g. Samsung"
            />
          </div>
          <div className="col-span-1">
            <label className="block text-xs font-semibold text-gray-500 uppercase mb-1">Title</label>
            <input 
              className="w-full bg-white border border-gray-300 rounded p-2.5 text-gray-900 focus:border-fkBlue focus:ring-1 focus:ring-fkBlue outline-none transition-colors" 
              value={formData.title || ''}
              onChange={e => setFormData({...formData, title: e.target.value})}
              placeholder="Product Title"
            />
          </div>

          <div className="col-span-1">
            <label className="block text-xs font-semibold text-gray-500 uppercase mb-1">City</label>
            <div className="flex gap-2">
              {isAddingCity ? (
                <div className="flex-1 flex gap-1">
                   <input 
                     className="w-full bg-white border border-gray-300 rounded p-2.5 text-gray-900 uppercase"
                     placeholder="XXX"
                     autoFocus
                     value={newCityCode}
                     maxLength={3}
                     onChange={e => setNewCityCode(e.target.value)}
                   />
                   <button 
                     type="button" 
                     onClick={handleAddNewCity}
                     className="bg-fkGreen px-3 rounded text-white hover:bg-green-700"
                   >
                     <Check className="h-4 w-4" />
                   </button>
                   <button 
                     type="button" 
                     onClick={() => setIsAddingCity(false)}
                     className="bg-gray-200 px-3 rounded text-gray-700 hover:bg-gray-300"
                   >
                     <X className="h-4 w-4" />
                   </button>
                </div>
              ) : (
                <div className="flex-1 flex gap-2">
                  <select 
                    className="w-full bg-white border border-gray-300 rounded p-2.5 text-gray-900 focus:border-fkBlue focus:ring-1 focus:ring-fkBlue outline-none"
                    value={formData.city}
                    onChange={e => setFormData({...formData, city: e.target.value})}
                  >
                    {cities.map(c => <option key={c} value={c}>{c}</option>)}
                  </select>

                  <button 
                    type="button" 
                    onClick={() => setIsAddingCity(true)}
                    className="px-3 bg-gray-100 hover:bg-gray-200 rounded border border-gray-300 text-gray-600 transition-colors"
                    title="Add New City"
                  >
                    <Plus className="h-4 w-4" />
                  </button>

                  <button 
                    type="button"
                    onClick={handleDeleteCity}
                    disabled={formData.city === 'PAN-INDIA'}
                    className={`px-3 rounded border transition-colors ${formData.city === 'PAN-INDIA' ? 'bg-gray-100 border-gray-200 text-gray-400 cursor-not-allowed' : 'bg-red-50 border-red-200 text-red-600 hover:bg-red-100'}`}
                  >
                    <Trash2 className="h-4 w-4" />
                  </button>
                </div>
              )}
            </div>
          </div>

          <div className="col-span-1">
            <label className="block text-xs font-semibold text-gray-500 uppercase mb-1">Type</label>
            <select 
              className="w-full bg-white border border-gray-300 rounded p-2.5 text-gray-900 focus:border-fkBlue focus:ring-1 focus:ring-fkBlue outline-none"
              value={formData.type}
              onChange={e => setFormData({...formData, type: e.target.value as CommercialType})}
            >
              <option value={CommercialType.MARGIN_PERCENT}>Margin %</option>
              <option value={CommercialType.NLC_VALUE}>NLC Value (Amount)</option>
              <option value={CommercialType.ON_INVOICE}>On Invoice %</option>
              <option value={CommercialType.OFF_INVOICE}>Off Invoice %</option>
            </select>
          </div>

          <div className="col-span-1">
            <label className="block text-xs font-semibold text-gray-500 uppercase mb-1">Value</label>
            <input 
              type="number"
              className="w-full bg-white border border-gray-300 rounded p-2.5 text-gray-900 focus:border-fkBlue focus:ring-1 focus:ring-fkBlue outline-none font-mono" 
              value={formData.value || ''}
              onChange={e => setFormData({...formData, value: parseFloat(e.target.value)})}
              placeholder="0.00"
            />
          </div>

          {formData.type !== CommercialType.MARGIN_PERCENT && (
            <>
              <div className="col-span-1">
                <label className="block text-xs font-semibold text-gray-500 uppercase mb-1">Start Date</label>
                <input 
                  type="date"
                  className="w-full bg-white border border-gray-300 rounded p-2.5 text-gray-900 focus:border-fkBlue outline-none" 
                  value={formData.startDate}
                  onChange={e => setFormData({...formData, startDate: e.target.value})}
                />
              </div>
              <div className="col-span-1">
                <label className="block text-xs font-semibold text-gray-500 uppercase mb-1">End Date</label>
                <input 
                  type="date"
                  className="w-full bg-white border border-gray-300 rounded p-2.5 text-gray-900 focus:border-fkBlue outline-none" 
                  value={formData.endDate}
                  onChange={e => setFormData({...formData, endDate: e.target.value})}
                />
              </div>
            </>
          )}

          <div className="col-span-full flex justify-end pt-6 border-t border-gray-100">
             <button
               type="submit"
               disabled={loading}
               className="bg-fkYellow hover:bg-yellow-500 text-white font-bold py-2.5 px-8 rounded shadow-md hover:shadow-lg transition-all flex items-center gap-2"
             >
               {loading ? <span className="animate-spin">⌛</span> : <Save className="h-5 w-5" />}
               Save Record
             </button>
          </div>
        </form>
      ) : (
        <div className="space-y-6">
          <div className="bg-white p-6 rounded-lg border border-gray-200 shadow-sm">
             <label className="block text-xs font-bold text-gray-500 mb-4 uppercase tracking-wider">Select Upload Type</label>
             <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
               {COMMERCIAL_TYPES.map(type => (
                 <button
                   key={type}
                   onClick={() => setBulkType(type)}
                   className={`p-4 rounded border text-sm font-semibold transition-all ${
                     bulkType === type 
                     ? 'bg-fkBlue text-white border-fkBlue shadow-md' 
                     : 'bg-gray-50 text-gray-600 border-gray-200 hover:bg-white hover:border-gray-300 hover:shadow-sm'
                   }`}
                 >
                   {type}
                 </button>
               ))}
             </div>
          </div>

          <div className="flex justify-end">
            <button 
              onClick={downloadTemplate}
              className="flex items-center gap-2 px-4 py-2 bg-white hover:bg-gray-50 text-fkBlue font-medium rounded border border-gray-300 shadow-sm transition-colors text-sm"
            >
              <Download className="h-4 w-4" /> 
              Download Template
            </button>
          </div>

          <div className="fk-card border-dashed border-2 border-gray-300 p-12 flex flex-col items-center justify-center text-center hover:border-fkBlue hover:bg-blue-50/30 transition-all group cursor-pointer relative">
            <input 
              type="file" 
              accept=".csv"
              onChange={handleFileUpload}
              key={bulkType}
              className="absolute inset-0 w-full h-full opacity-0 cursor-pointer"
            />
            <div className="bg-blue-50 p-5 rounded-full mb-4 group-hover:scale-110 transition-transform">
               <Upload className="h-10 w-10 text-fkBlue" />
            </div>
            <h3 className="text-xl font-bold text-gray-800">Upload {bulkType} CSV</h3>
            <p className="text-gray-500 mt-2">
              Drag and drop or click to upload
            </p>
          </div>
        </div>
      )}
    </div>
  );
};

export enum Role {
  MAKER = 'MAKER',
  CHECKER = 'CHECKER',
  ADMIN = 'ADMIN'
}

export enum CommercialType {
  MARGIN_PERCENT = 'Margin %',
  NLC_VALUE = 'NLC Value',
  NLC_PERCENT = 'NLC %',
  ON_INVOICE = 'On Invoice %',
  OFF_INVOICE = 'Off Invoice %'
}

export interface User {
  id: string;
  employeeId: string;
  name: string;
  role: Role;
  pin?: string; // Encrypted in real app
}

export interface CommercialRecord {
  id: string;
  fsn: string;
  brand: string;
  title: string;
  city: string;
  vertical?: string;
  kam?: string;
  startDate: string;
  endDate: string;
  type: CommercialType;
  value: number;
  lastUpdatedBy: string;
  lastUpdatedAt: number;
}

export interface DuplicateRequest {
  id: string;
  originalRecordId: string | null; // Null if it's a new conflict without ID yet, but usually maps to existing
  payload: CommercialRecord;
  requestedBy: string;
  requestedAt: number;
  status: 'PENDING' | 'APPROVED' | 'REJECTED';
  reason?: string; // Reason for approval (Conflict, High Margin, etc.)
}

export const CITIES = [
  'PAN-INDIA', 'BLR', 'DEL', 'MUM', 'KOL', 'CHE', 'HYD', 'PUN'
];

export const COMMERCIAL_TYPES = [
  CommercialType.MARGIN_PERCENT,
  CommercialType.NLC_VALUE,
  CommercialType.NLC_PERCENT,
  CommercialType.ON_INVOICE,
  CommercialType.OFF_INVOICE
];

import React, { useState, useEffect } from 'react';
import { CommercialRecord, CommercialType, DuplicateRequest, User, COMMERCIAL_TYPES } from '../types';
import { db } from '../services/db';
import { Plus, Upload, Save, AlertTriangle, FileText, X, Download, Check, Trash2, ArrowUpRight, ShieldAlert, User as UserIcon, Layers } from 'lucide-react';
import Papa from 'papaparse';

interface MakerProps {
  user: User;
}

export const MakerWorkspace: React.FC<MakerProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<'MANUAL' | 'BULK'>('MANUAL');

  // Dynamic Cities
  const [cities, setCities] = useState<string[]>([]);
  const [isAddingCity, setIsAddingCity] = useState(false);
  const [newCityCode, setNewCityCode] = useState('');

  // Manual Form State
  const [formData, setFormData] = useState<Partial<CommercialRecord>>({
    city: 'PAN-INDIA',
    type: CommercialType.MARGIN_PERCENT,
    startDate: new Date().toISOString().split('T')[0],
    endDate: new Date(new Date().setMonth(new Date().getMonth() + 3)).toISOString().split('T')[0],
    vertical: '',
    kam: ''
  });

  // Real-time Validation State
  const [instantConflict, setInstantConflict] = useState<boolean>(false);
  const [highMarginAlert, setHighMarginAlert] = useState<boolean>(false);

  // Bulk State
  const [bulkType, setBulkType] = useState<CommercialType>(CommercialType.MARGIN_PERCENT);

  const [loading, setLoading] = useState(false);
  const [notification, setNotification] = useState<{msg: string, type: 'success' | 'error' | 'warning' | null}>({ msg: '', type: null });

  // Initialize Data
  useEffect(() => {
    const init = async () => {
      // 1. Load Draft
      const draft = localStorage.getItem('mm_draft_form');
      let draftData = {};
      if (draft) {
        draftData = JSON.parse(draft);
        setFormData(draftData);
      }

      // 2. Load Cities and Validate
      const c = await db.getCities();
      setCities(c);

      // Validate the city from draft or current state
      const currentCity = (draftData as any).city || formData.city || 'PAN-INDIA';
      if (!c.includes(currentCity)) {
         setFormData(prev => ({ ...prev, city: c[0] || 'PAN-INDIA' }));
      }
    };

    init();
  }, []);

  // Save draft & Real-time Check
  useEffect(() => {
    localStorage.setItem('mm_draft_form', JSON.stringify(formData));

    // High Margin Check
    if (formData.type === CommercialType.MARGIN_PERCENT && (formData.value || 0) > 60) {
        setHighMarginAlert(true);
    } else {
        setHighMarginAlert(false);
    }

    // Debounce the conflict check
    const timeoutId = setTimeout(async () => {
        if(formData.fsn && formData.fsn.length === 16 && formData.city && formData.type && formData.startDate && formData.endDate) {
            const records = await db.getRecords();
            const conflict = checkForConflict(records, formData as CommercialRecord);
            setInstantConflict(conflict);
        } else {
            setInstantConflict(false);
        }
    }, 500);

    return () => clearTimeout(timeoutId);
  }, [formData]);

  const checkForConflict = (existingRecords: CommercialRecord[], input: CommercialRecord): boolean => {
      return existingRecords.some(r => {
        // 1. Match FSN & Type
        if (r.fsn !== input.fsn) return false;
        if (r.type !== input.type) return false;

        // 2. Check Date Overlap (StartA <= EndB) and (EndA >= StartB)
        const overlap = (input.startDate <= r.endDate) && (input.endDate >= r.startDate);
        if (!overlap) return false;

        // 3. Check City Logic (Exact Match OR PAN-INDIA Collision)
        // If input is PAN-INDIA, it conflicts with ANY city record for that FSN
        // If existing record is PAN-INDIA, it conflicts with ANY input city
        if (input.city === 'PAN-INDIA' || r.city === 'PAN-INDIA') return true; 
        if (input.city === r.city) return true;

        return false;
      });
  };

  const refreshCities = async () => {
    const c = await db.getCities();
    setCities(c);
    return c;
  };

  const handleAddNewCity = async () => {
    if (!newCityCode) return;
    const code = newCityCode.toUpperCase().trim();
    if (code !== 'PAN-INDIA' && code.length > 3) {
       setNotification({ msg: 'City code must be 3 characters or less.', type: 'error' });
       return;
    }
    const cleanCode = code.replace(/[^A-Z0-9]/g, '');
    if (!cleanCode) return;
    if (cities.includes(cleanCode)) {
       setNotification({ msg: `City ${cleanCode} already exists.`, type: 'warning' });
       return;
    }
    if (cleanCode) {
       await db.addCity(cleanCode);
       await refreshCities();
       setFormData(prev => ({...prev, city: cleanCode}));
       setNewCityCode('');
       setIsAddingCity(false);
       setNotification({ msg: `City ${cleanCode} added.`, type: 'success' });
    }
  };

  const handleDeleteCity = async () => {
    const cityToDelete = formData.city;
    if (!cityToDelete || cityToDelete === 'PAN-INDIA') {
        setNotification({ msg: 'Cannot delete default PAN-INDIA city.', type: 'error' });
        return;
    }
    if (window.confirm(`Delete city code "${cityToDelete}"?`)) {
        try {
            await db.deleteCity(cityToDelete);
            const updatedCities = await refreshCities();
            setFormData(prev => ({ ...prev, city: updatedCities[0] || 'PAN-INDIA' }));
            setNotification({ msg: `City ${cityToDelete} removed.`, type: 'success' });
        } catch (err) {
            setNotification({ msg: 'Failed to delete city.', type: 'error' });
        }
    }
  };

  const handleManualSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setNotification({ msg: '', type: null });

    if (!formData.fsn || !formData.value || !formData.brand || !formData.title || !formData.vertical || !formData.kam) {
        setNotification({ msg: 'Please fill all fields', type: 'error' });
        return;
    }

    // Strict FSN Length Check
    if (formData.fsn.length !== 16) {
        setNotification({ msg: 'FSN must be exactly 16 characters.', type: 'error' });
        return;
    }

    // Validate Caps
    const isPercentage = formData.type === CommercialType.MARGIN_PERCENT || 
                         formData.type === CommercialType.NLC_PERCENT || 
                         formData.type === CommercialType.ON_INVOICE || 
                         formData.type === CommercialType.OFF_INVOICE;

    if (isPercentage && formData.value! > 100) {
        setNotification({ msg: `${formData.type} cannot exceed 100%`, type: 'error' });
        return;
    }

    if (formData.type !== CommercialType.MARGIN_PERCENT && formData.endDate! < formData.startDate!) {
        setNotification({ msg: 'End Date cannot be before Start Date', type: 'error' });
        return;
    }

    setLoading(true);

    try {
      const records = await db.getRecords();

      const isConflict = checkForConflict(records, formData as CommercialRecord);
      const isHighMargin = formData.type === CommercialType.MARGIN_PERCENT && (formData.value || 0) > 60;

      const newRecord: CommercialRecord = {
        id: `rec_${Date.now()}`,
        ...formData as CommercialRecord,
        value: Number(formData.value),
        lastUpdatedBy: user.name,
        lastUpdatedAt: Date.now()
      };

      if (isConflict || isHighMargin) {
        let reason = '';
        if (isConflict) reason = 'Duplicate/Overlap Conflict Detected';
        if (isHighMargin) reason = reason ? reason + ' & High Margin (>60%)' : 'High Margin (>60%)';

        const req: DuplicateRequest = {
          id: `req_${Date.now()}`,
          originalRecordId: null,
          payload: newRecord,
          requestedBy: user.name,
          requestedAt: Date.now(),
          status: 'PENDING',
          reason: reason
        };
        await db.createDuplicateRequest(req);
        setNotification({ msg: `Request sent to Checker: ${reason}`, type: 'warning' });
      } else {
        await db.addRecords([newRecord]);
        setNotification({ msg: 'Record saved successfully.', type: 'success' });
        setFormData(prev => ({ 
            ...prev, 
            fsn: '', 
            value: 0,
            // Reset dates to defaults
            startDate: new Date().toISOString().split('T')[0],
            endDate: new Date(new Date().setMonth(new Date().getMonth() + 3)).toISOString().split('T')[0]
        }));
      }
    } catch (err) {
      setNotification({ msg: 'Failed to save record.', type: 'error' });
    } finally {
      setLoading(false);
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    Papa.parse(file, {
      header: true,
      skipEmptyLines: true,
      complete: async (results) => {
        setLoading(true);
        const newRecords: CommercialRecord[] = [];
        const requests: DuplicateRequest[] = [];
        const existingRecords = await db.getRecords();

        let skipped = 0;

        results.data.forEach((row: any) => {
           if(!row.FSN) return;

           // Validation in Loop
           if(row.FSN.length !== 16) {
               skipped++;
               return;
           }

           const cityKeys = Object.keys(row).filter(k => cities.includes(k) || k === 'Value');

           cityKeys.forEach(cityKey => {
             const city = cityKey === 'Value' ? 'PAN-INDIA' : cityKey;
             let val = parseFloat(row[cityKey]);
             if (isNaN(val)) return;

             // Auto-convert decimal to percent only if strictly required, but for NLC Value usually input is raw.
             // Requirement says: "NLC inputs... percent% it be be capped to 100%". 
             // We assume input CSV has raw values.

             const isPercentage = bulkType === CommercialType.MARGIN_PERCENT || 
                                  bulkType === CommercialType.NLC_PERCENT || 
                                  bulkType === CommercialType.ON_INVOICE || 
                                  bulkType === CommercialType.OFF_INVOICE;

             if (isPercentage && val > 100) val = 100; // Cap at 100
             if (isPercentage && val <= 1 && val > 0) val = val * 100; // Handle 0.5 as 50% if common error

             const rec: CommercialRecord = {
               id: `rec_${Math.random().toString(36).substr(2,9)}`,
               fsn: row.FSN,
               brand: row.Brand || 'Unknown',
               title: row.Title || 'Bulk Upload Item',
               vertical: row.Vertical || 'Unknown',
               kam: row.KAM || 'Unknown',
               city: city,
               startDate: row.StartDate,
               endDate: row.EndDate,
               type: bulkType,
               value: val,
               lastUpdatedBy: user.name,
               lastUpdatedAt: Date.now()
             };

             const isConflict = checkForConflict(existingRecords, rec);
             const isHighMargin = bulkType === CommercialType.MARGIN_PERCENT && val > 60;

             if (isConflict || isHighMargin) {
               let reason = '';
               if (isConflict) reason = 'Conflict Detected';
               if (isHighMargin) reason = reason ? reason + ' & High Margin' : 'High Margin';

               const req: DuplicateRequest = {
                 id: `req_${Math.random().toString(36).substr(2,9)}`,
                 originalRecordId: null,
                 payload: rec,
                 requestedBy: user.name,
                 requestedAt: Date.now(),
                 status: 'PENDING',
                 reason: reason
               };
               requests.push(req);
             } else {
               newRecords.push(rec);
             }
           });
        });

        if (newRecords.length > 0) {
          await db.addRecords(newRecords);
        }

        if (requests.length > 0) {
           for (const req of requests) {
              await db.createDuplicateRequest(req);
           }
           setNotification({ 
             msg: `Uploaded ${newRecords.length} records. ${requests.length} sent for approval (Conflict/High Margin). ${skipped > 0 ? skipped + ' skipped (Invalid FSN)' : ''}`, 
             type: 'warning' 
           });
        } else {
           setNotification({ msg: `Successfully uploaded ${newRecords.length} records. ${skipped > 0 ? skipped + ' skipped (Invalid FSN)' : ''}`, type: 'success' });
        }
        setLoading(false);
      }
    });
  };

  const downloadTemplate = () => {
    const headers = ['FSN', 'Brand', 'Title', 'Vertical', 'KAM', 'StartDate', 'EndDate', ...cities];
    const isNLC = bulkType === CommercialType.NLC_VALUE;
    const exampleVal = isNLC ? '50000' : '10';
    const dummyRows = [
        ['MOBEXAMPLE123456', 'BrandX', 'Sample Product 1', 'Mobiles', 'John Doe', '2024-01-01', '2024-03-31', ...cities.map(() => exampleVal)],
    ];
    const csvContent = [headers.join(','), ...dummyRows.map(row => row.join(','))].join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv' });
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `template_${bulkType.replace(/\s/g, '')}.csv`;
    a.click();
    window.URL.revokeObjectURL(url);
  };

  return (
    <div className="space-y-6 animate-in slide-in-from-bottom-4 duration-500 max-w-7xl mx-auto">
      <div className="flex justify-between items-center">
        <div>
           <h2 className="text-2xl font-bold text-gray-800">Maker Workspace</h2>
           <p className="text-sm text-gray-500">Manage commercials and offers</p>
        </div>
        <div className="flex bg-white rounded shadow-sm border border-gray-200 p-1">
          <button
            onClick={() => setActiveTab('MANUAL')}
            className={`px-4 py-2 rounded text-sm font-medium transition-all ${activeTab === 'MANUAL' ? 'bg-fkBlue text-white shadow' : 'text-gray-500 hover:text-gray-900'}`}
          >
            Manual Entry
          </button>
          <button
            onClick={() => setActiveTab('BULK')}
            className={`px-4 py-2 rounded text-sm font-medium transition-all ${activeTab === 'BULK' ? 'bg-fkBlue text-white shadow' : 'text-gray-500 hover:text-gray-900'}`}
          >
            Bulk Upload
          </button>
        </div>
      </div>

      {notification.msg && (
        <div className={`p-4 rounded border flex items-center gap-3 shadow-sm ${
          notification.type === 'error' ? 'bg-red-50 border-red-200 text-red-700' :
          notification.type === 'warning' ? 'bg-orange-50 border-orange-200 text-orange-800' :
          'bg-green-50 border-green-200 text-green-700'
        }`}>
          {notification.type === 'error' ? <AlertTriangle className="h-5 w-5"/> : <FileText className="h-5 w-5"/>}
          <span className="font-medium">{notification.msg}</span>
          <button onClick={() => setNotification({msg:'', type:null})} className="ml-auto hover:bg-white/50 rounded p-1"><X className="h-4 w-4"/></button>
        </div>
      )}

      {/* Alerts */}
      <div className="space-y-2">
          {instantConflict && activeTab === 'MANUAL' && (
            <div className="p-3 bg-red-50 border-l-4 border-red-500 rounded shadow-sm flex items-center gap-3 animate-in fade-in slide-in-from-top-2">
                <ShieldAlert className="text-red-500 w-6 h-6" />
                <div>
                    <p className="font-bold text-gray-800 text-sm">Conflict Detected!</p>
                    <p className="text-xs text-gray-600">Overlap with existing FSN+City/PAN-INDIA record. Saving triggers approval.</p>
                </div>
            </div>
          )}
          {highMarginAlert && activeTab === 'MANUAL' && (
            <div className="p-3 bg-yellow-50 border-l-4 border-fkYellow rounded shadow-sm flex items-center gap-3 animate-in fade-in slide-in-from-top-2">
                <AlertTriangle className="text-fkYellow w-6 h-6" />
                <div>
                    <p className="font-bold text-gray-800 text-sm">High Margin Alert!</p>
                    <p className="text-xs text-gray-600">Margin &gt; 60% requires checker approval.</p>
                </div>
            </div>
          )}
      </div>

      {activeTab === 'MANUAL' ? (
        <form onSubmit={handleManualSubmit} className="fk-card p-6 grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          <div className="col-span-1">
            <label className="block text-xs font-semibold text-gray-500 uppercase mb-1">FSN (Product ID)</label>
            <div className="relative">
                <input 
                  className="w-full bg-white border border-gray-300 rounded p-2.5 text-gray-900 focus:border-fkBlue focus:ring-1 focus:ring-fkBlue outline-none transition-colors" 
                  value={formData.fsn || ''}
                  onChange={e => setFormData({...formData, fsn: e.target.value})}
                  placeholder="16 Characters Required"
                  maxLength={16}
                />
                <div className={`text-[10px] text-right mt-1 font-mono ${formData.fsn?.length === 16 ? 'text-green-600' : 'text-gray-400'}`}>
                    {formData.fsn?.length || 0}/16
                </div>
            </div>
          </div>
          <div className="col-span-1">
            <label className="block text-xs font-semibold text-gray-500 uppercase mb-1">Brand</label>
            <input 
              className="w-full bg-white border border-gray-300 rounded p-2.5 text-gray-900 focus:border-fkBlue focus:ring-1 focus:ring-fkBlue outline-none transition-colors" 
              value={formData.brand || ''}
              onChange={e => setFormData({...formData, brand: e.target.value})}
              placeholder="e.g. Samsung"
            />
          </div>
          <div className="col-span-1">
            <label className="block text-xs font-semibold text-gray-500 uppercase mb-1">Title</label>
            <input 
              className="w-full bg-white border border-gray-300 rounded p-2.5 text-gray-900 focus:border-fkBlue focus:ring-1 focus:ring-fkBlue outline-none transition-colors" 
              value={formData.title || ''}
              onChange={e => setFormData({...formData, title: e.target.value})}
              placeholder="Product Title"
            />
          </div>

          <div className="col-span-1">
            <label className="block text-xs font-semibold text-gray-500 uppercase mb-1 flex items-center gap-1"><Layers className="w-3 h-3"/> Vertical</label>
            <input 
              className="w-full bg-white border border-gray-300 rounded p-2.5 text-gray-900 focus:border-fkBlue focus:ring-1 focus:ring-fkBlue outline-none transition-colors" 
              value={formData.vertical || ''}
              onChange={e => setFormData({...formData, vertical: e.target.value})}
              placeholder="e.g. Mobiles"
            />
          </div>

          <div className="col-span-1">
            <label className="block text-xs font-semibold text-gray-500 uppercase mb-1 flex items-center gap-1"><UserIcon className="w-3 h-3"/> KAM</label>
            <input 
              className="w-full bg-white border border-gray-300 rounded p-2.5 text-gray-900 focus:border-fkBlue focus:ring-1 focus:ring-fkBlue outline-none transition-colors" 
              value={formData.kam || ''}
              onChange={e => setFormData({...formData, kam: e.target.value})}
              placeholder="Account Manager Name"
            />
          </div>

          <div className="col-span-1">
            <label className="block text-xs font-semibold text-gray-500 uppercase mb-1">City</label>
            <div className="flex gap-2">
              {isAddingCity ? (
                <div className="flex-1 flex gap-1">
                   <input 
                     className="w-full bg-white border border-gray-300 rounded p-2.5 text-gray-900 uppercase"
                     placeholder="XXX"
                     autoFocus
                     value={newCityCode}
                     maxLength={3}
                     onChange={e => setNewCityCode(e.target.value)}
                   />
                   <button 
                     type="button" 
                     onClick={handleAddNewCity}
                     className="bg-fkGreen px-3 rounded text-white hover:bg-green-700"
                   >
                     <Check className="h-4 w-4" />
                   </button>
                   <button 
                     type="button" 
                     onClick={() => setIsAddingCity(false)}
                     className="bg-gray-200 px-3 rounded text-gray-700 hover:bg-gray-300"
                   >
                     <X className="h-4 w-4" />
                   </button>
                </div>
              ) : (
                <div className="flex-1 flex gap-2">
                  <select 
                    className="w-full bg-white border border-gray-300 rounded p-2.5 text-gray-900 focus:border-fkBlue focus:ring-1 focus:ring-fkBlue outline-none"
                    value={formData.city}
                    onChange={e => setFormData({...formData, city: e.target.value})}
                  >
                    {cities.map(c => <option key={c} value={c}>{c}</option>)}
                  </select>

                  <button 
                    type="button" 
                    onClick={() => setIsAddingCity(true)}
                    className="px-3 bg-gray-100 hover:bg-gray-200 rounded border border-gray-300 text-gray-600 transition-colors"
                    title="Add New City"
                  >
                    <Plus className="h-4 w-4" />
                  </button>

                  <button 
                    type="button"
                    onClick={handleDeleteCity}
                    disabled={formData.city === 'PAN-INDIA'}
                    className={`px-3 rounded border transition-colors ${formData.city === 'PAN-INDIA' ? 'bg-gray-100 border-gray-200 text-gray-400 cursor-not-allowed' : 'bg-red-50 border-red-200 text-red-600 hover:bg-red-100'}`}
                  >
                    <Trash2 className="h-4 w-4" />
                  </button>
                </div>
              )}
            </div>
          </div>

          <div className="col-span-1">
            <label className="block text-xs font-semibold text-gray-500 uppercase mb-1">Type</label>
            <select 
              className="w-full bg-white border border-gray-300 rounded p-2.5 text-gray-900 focus:border-fkBlue focus:ring-1 focus:ring-fkBlue outline-none"
              value={formData.type}
              onChange={e => setFormData({...formData, type: e.target.value as CommercialType})}
            >
              <option value={CommercialType.MARGIN_PERCENT}>Margin %</option>
              <option value={CommercialType.NLC_VALUE}>NLC Value (Amount)</option>
              <option value={CommercialType.NLC_PERCENT}>NLC %</option>
              <option value={CommercialType.ON_INVOICE}>On Invoice %</option>
              <option value={CommercialType.OFF_INVOICE}>Off Invoice %</option>
            </select>
          </div>

          <div className="col-span-1">
            <label className="block text-xs font-semibold text-gray-500 uppercase mb-1">Value</label>
            <input 
              type="number"
              className="w-full bg-white border border-gray-300 rounded p-2.5 text-gray-900 focus:border-fkBlue focus:ring-1 focus:ring-fkBlue outline-none font-mono" 
              value={formData.value || ''}
              onChange={e => setFormData({...formData, value: parseFloat(e.target.value)})}
              placeholder="0.00"
            />
            {/* Helper Text for Caps */}
            {formData.type?.includes('%') && (
                <p className="text-[10px] text-gray-400 mt-1">Capped at 100%</p>
            )}
          </div>

          {formData.type !== CommercialType.MARGIN_PERCENT && (
            <>
              <div className="col-span-1">
                <label className="block text-xs font-semibold text-gray-500 uppercase mb-1">Start Date</label>
                <input 
                  type="date"
                  className="w-full bg-white border border-gray-300 rounded p-2.5 text-gray-900 focus:border-fkBlue outline-none" 
                  value={formData.startDate}
                  onChange={e => setFormData({...formData, startDate: e.target.value})}
                />
              </div>
              <div className="col-span-1">
                <label className="block text-xs font-semibold text-gray-500 uppercase mb-1">End Date</label>
                <input 
                  type="date"
                  className="w-full bg-white border border-gray-300 rounded p-2.5 text-gray-900 focus:border-fkBlue outline-none" 
                  value={formData.endDate}
                  onChange={e => setFormData({...formData, endDate: e.target.value})}
                />
              </div>
            </>
          )}

          <div className="col-span-full flex justify-end pt-6 border-t border-gray-100">
             <button
               type="submit"
               disabled={loading}
               className="bg-fkYellow hover:bg-yellow-500 text-white font-bold py-2.5 px-8 rounded shadow-md hover:shadow-lg transition-all flex items-center gap-2"
             >
               {loading ? <span className="animate-spin">⌛</span> : <Save className="h-5 w-5" />}
               Save Record
             </button>
          </div>
        </form>
      ) : (
        <div className="space-y-6">
          <div className="bg-white p-6 rounded-lg border border-gray-200 shadow-sm">
             <label className="block text-xs font-bold text-gray-500 mb-4 uppercase tracking-wider">Select Upload Type</label>
             <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
               {COMMERCIAL_TYPES.map(type => (
                 <button
                   key={type}
                   onClick={() => setBulkType(type)}
                   className={`p-4 rounded border text-sm font-semibold transition-all ${
                     bulkType === type 
                     ? 'bg-fkBlue text-white border-fkBlue shadow-md' 
                     : 'bg-gray-50 text-gray-600 border-gray-200 hover:bg-white hover:border-gray-300 hover:shadow-sm'
                   }`}
                 >
                   {type}
                 </button>
               ))}
             </div>
          </div>

          <div className="flex justify-end">
            <button 
              onClick={downloadTemplate}
              className="flex items-center gap-2 px-4 py-2 bg-white hover:bg-gray-50 text-fkBlue font-medium rounded border border-gray-300 shadow-sm transition-colors text-sm"
            >
              <Download className="h-4 w-4" /> 
              Download Template
            </button>
          </div>

          <div className="fk-card border-dashed border-2 border-gray-300 p-12 flex flex-col items-center justify-center text-center hover:border-fkBlue hover:bg-blue-50/30 transition-all group cursor-pointer relative">
            <input 
              type="file" 
              accept=".csv"
              onChange={handleFileUpload}
              key={bulkType}
              className="absolute inset-0 w-full h-full opacity-0 cursor-pointer"
            />
            <div className="bg-blue-50 p-5 rounded-full mb-4 group-hover:scale-110 transition-transform">
               <Upload className="h-10 w-10 text-fkBlue" />
            </div>
            <h3 className="text-xl font-bold text-gray-800">Upload {bulkType} CSV</h3>
            <p className="text-gray-500 mt-2">
              Drag and drop or click to upload
            </p>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { db } from '../services/db';
import { DuplicateRequest, User, CommercialType } from '../types';
import { Check, X, Search, BarChart3, Archive, TrendingUp, AlertCircle, FileDown, Calendar, Trash2, Database, Clock, ChevronDown, User as UserIcon, Layers } from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer, ReferenceLine, LabelList } from 'recharts';
import Papa from 'papaparse';

interface CheckerProps {
  user: User;
}

export const CheckerWorkspace: React.FC<CheckerProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<'AUDIT' | 'APPROVALS' | 'CLOSURE'>('AUDIT');
  const [requests, setRequests] = useState<DuplicateRequest[]>([]);
  const [cities, setCities] = useState<string[]>([]);

  // Audit State
  const [auditQuery, setAuditQuery] = useState({ fsn: '', city: 'BLR', targetMargin: 0 });
  const [auditResult, setAuditResult] = useState<any>(null);
  const [loading, setLoading] = useState(false);

  // Autocomplete State
  const [allFsns, setAllFsns] = useState<string[]>([]);
  const [filteredFsns, setFilteredFsns] = useState<string[]>([]);
  const [showSuggestions, setShowSuggestions] = useState(false);

  // Closure/Export State
  const [selectedMonth, setSelectedMonth] = useState(new Date().toISOString().slice(0, 7)); // YYYY-MM
  const [exportLoading, setExportLoading] = useState(false);

  // Archive View State
  const [showArchive, setShowArchive] = useState(false);
  const [archiveData, setArchiveData] = useState<any[]>([]);

  useEffect(() => {
    loadRequests();
    loadCities();
    loadUniqueFsns();
    const interval = setInterval(loadRequests, 5000);
    return () => clearInterval(interval);
  }, []);

  const loadCities = async () => {
    const c = await db.getCities();
    setCities(c);
    if (!c.includes(auditQuery.city)) {
       setAuditQuery(prev => ({ ...prev, city: c.includes('BLR') ? 'BLR' : c[0] || '' }));
    }
  };

  const loadUniqueFsns = async () => {
    const records = await db.getRecords();
    const unique = Array.from(new Set(records.map(r => r.fsn)));
    setAllFsns(unique);
  };

  const loadRequests = async () => {
    const reqs = await db.getDuplicateRequests();
    setRequests(reqs.filter(r => r.status === 'PENDING'));
  };

  const loadArchive = async () => {
    const data = await db.getBinRecords();
    setArchiveData(data.sort((a: any, b: any) => b.deletedAt - a.deletedAt));
  };

  const toggleArchive = () => {
      if (!showArchive) loadArchive();
      setShowArchive(!showArchive);
  };

  const handleFsnChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = e.target.value;
    setAuditQuery({ ...auditQuery, fsn: val });

    if (val.length > 0) {
        const matches = allFsns.filter(f => f.toLowerCase().includes(val.toLowerCase()));
        setFilteredFsns(matches.slice(0, 5)); // Limit to 5 suggestions
        setShowSuggestions(true);
    } else {
        setShowSuggestions(false);
    }
  };

  const selectSuggestion = (fsn: string) => {
      setAuditQuery({ ...auditQuery, fsn });
      setShowSuggestions(false);
  };

  const handleAudit = async () => {
    if (!auditQuery.fsn) return;

    if (auditQuery.fsn.length !== 16) {
        alert("FSN must be exactly 16 characters.");
        return;
    }

    setLoading(true);
    setShowSuggestions(false); // Hide if open

    const records = await db.getRecords();

    const relevant = records.filter(r => 
      r.fsn === auditQuery.fsn && 
      (r.city === auditQuery.city || r.city === 'PAN-INDIA')
    );

    // Helper to get specific city value or fallback to PAN-INDIA
    const getEffectiveValue = (type: CommercialType) => {
        const specific = relevant.find(r => r.type === type && r.city === auditQuery.city);
        if (specific) return { val: specific.value, source: 'CITY' };

        const pan = relevant.find(r => r.type === type && r.city === 'PAN-INDIA');
        if (pan) return { val: pan.value, source: 'PAN' };

        return { val: 0, source: 'NONE' };
    };

    const nlcObj = getEffectiveValue(CommercialType.NLC_VALUE);
    const nlcPercObj = getEffectiveValue(CommercialType.NLC_PERCENT); // Handle NLC Percent? 
    // For Audit chart, we currently mix NLC Value and OnInvoice. NLC % is tricky to sum with value without base price.
    // For now, we visualize known absolute/simple % components.

    const nlc = nlcObj.val; 
    const onInv = onInvObj.val;

    // Simplification: In a real app we'd need base price to calculate NLC % impact.
    // Here we just sum the raw numbers for the demo chart.
    const systemTotal = nlc + onInv; 
    const variance = auditQuery.targetMargin - systemTotal;
    const variancePercent = auditQuery.targetMargin ? ((variance / auditQuery.targetMargin) * 100) : 0;

    setAuditResult({
      data: [
        { name: 'System', nlc: nlc, onInv: onInv, total: systemTotal },
        { name: 'Target', target: auditQuery.targetMargin }
      ],
      systemTotal,
      targetTotal: auditQuery.targetMargin,
      variance,
      variancePercent: variancePercent.toFixed(2),
      status: Math.abs(variance) < 0.1 ? 'MATCH' : 'MISMATCH',
      details: relevant,
      sources: { nlc: nlcObj.source, onInv: onInvObj.source }
    });
    setLoading(false);
  };

  const handleRequestAction = async (reqId: string, action: 'APPROVED' | 'REJECTED') => {
    await db.resolveDuplicateRequest(reqId, action, user.id);
    loadRequests();
    loadUniqueFsns(); // Reload FSNs in case new ones were added via approval
  };

  const handleExport = async (mode: 'MONTH' | 'FULL') => {
    setExportLoading(true);
    try {
        const records = await db.getRecords();
        let dataToExport = records;

        if (mode === 'MONTH') {
            const [year, month] = selectedMonth.split('-').map(Number);
            const startOfMonth = new Date(year, month - 1, 1).toISOString().split('T')[0];
            const endOfMonth = new Date(year, month, 0).toISOString().split('T')[0];
            dataToExport = records.filter(r => r.startDate <= endOfMonth && r.endDate >= startOfMonth);
        }

        const csv = Papa.unparse(dataToExport.map(r => ({
            ID: r.id,
            FSN: r.fsn,
            Brand: r.brand,
            Title: r.title,
            Vertical: r.vertical,
            KAM: r.kam,
            City: r.city,
            Type: r.type,
            Value: r.value,
            StartDate: r.startDate,
            EndDate: r.endDate,
            LastUpdatedBy: r.lastUpdatedBy,
            LastUpdatedAt: new Date(r.lastUpdatedAt).toISOString()
        })));

        const blob = new Blob([csv], { type: 'text/csv' });
        const url = window.URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `mm_export_${mode.toLowerCase()}_${Date.now()}.csv`;
        a.click();
        window.URL.revokeObjectURL(url);
    } catch (e) {
        alert('Export failed');
    } finally {
        setExportLoading(false);
    }
  };

  const handleClearDB = async () => {
    if (window.confirm("CRITICAL: Delete all active records for Month End?")) {
        const confirmText = prompt("Type 'DELETE' to confirm:");
        if (confirmText === 'DELETE') {
            setLoading(true);
            try {
                await db.clearAllRecords(user.name);
                alert("Database reset. Records archived.");
                setAuditResult(null);
                setRequests([]);
                loadArchive();
                setAllFsns([]); // Clear suggestions
            } catch (e) {
                alert("Failed.");
            } finally {
                setLoading(false);
            }
        }
    }
  };

  const CustomTooltip = ({ active, payload, label }: any) => {
    if (active && payload && payload.length) {
      return (
        <div className="bg-white border border-gray-200 p-3 rounded shadow-lg text-xs">
          <p className="font-bold text-gray-800 mb-2">{label}</p>
          {payload.map((entry: any, index: number) => (
            <div key={index} className="flex items-center gap-2 mb-1">
               <div className="w-2 h-2 rounded-full" style={{ backgroundColor: entry.color }} />
               <span className="text-gray-500">{entry.name}:</span>
               <span className="text-gray-900 font-mono font-bold">{Number(entry.value).toFixed(2)}</span>
            </div>
          ))}
          {label === 'System' && (
             <div className="mt-2 pt-2 border-t border-gray-100 flex justify-between gap-4">
                <span className="text-gray-600 font-bold">Total:</span>
                <span className="text-gray-900 font-mono font-bold">{payload.reduce((acc: number, cur: any) => acc + (cur.value || 0), 0).toFixed(2)}</span>
             </div>
          )}
          {label === 'System' && auditResult?.sources && (
              <div className="mt-1 pt-1 border-t border-gray-50 text-[10px] text-gray-400">
                  {auditResult.sources.nlc === 'PAN' && <div>* NLC from PAN-INDIA</div>}
                  {auditResult.sources.onInv === 'PAN' && <div>* On-Inv from PAN-INDIA</div>}
              </div>
          )}
        </div>
      );
    }
    return null;
  };

  return (
    <div className="space-y-6 max-w-7xl mx-auto animate-in fade-in duration-500">
      <div className="flex justify-between items-center border-b border-gray-200 pb-4">
        <div>
            <h2 className="text-2xl font-bold text-gray-800 flex items-center gap-2">
               Checker Workspace
            </h2>
            <p className="text-sm text-gray-500">Audit commercial logic and approvals</p>
        </div>
        <div className="flex gap-1 bg-white p-1 rounded border border-gray-200">
          <button onClick={() => setActiveTab('AUDIT')} className={`px-4 py-2 rounded text-sm font-semibold transition-all ${activeTab === 'AUDIT' ? 'bg-fkBlue text-white shadow-sm' : 'text-gray-500 hover:text-gray-800'}`}>Audit Tool</button>
          <button onClick={() => setActiveTab('APPROVALS')} className={`px-4 py-2 rounded text-sm font-semibold transition-all flex items-center gap-2 ${activeTab === 'APPROVALS' ? 'bg-fkBlue text-white shadow-sm' : 'text-gray-500 hover:text-gray-800'}`}>
            Approvals
            {requests.length > 0 && <span className="bg-red-500 text-white text-[10px] px-1.5 py-0.5 rounded-full">{requests.length}</span>}
          </button>
          <button onClick={() => setActiveTab('CLOSURE')} className={`px-4 py-2 rounded text-sm font-semibold transition-all ${activeTab === 'CLOSURE' ? 'bg-fkYellow text-white shadow-sm' : 'text-gray-500 hover:text-gray-800'}`}>
            Month End
          </button>
        </div>
      </div>

      {activeTab === 'AUDIT' && (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          <div className="lg:col-span-1 space-y-4">
            <div className="fk-card p-6">
              <h3 className="text-sm font-bold uppercase text-gray-400 mb-4 tracking-wider">Run Audit</h3>
              <div className="space-y-3 relative">
                <div className="relative">
                    <input 
                    className="w-full bg-white border border-gray-300 rounded p-2.5 text-gray-900 focus:border-fkBlue outline-none" 
                    placeholder="Enter FSN"
                    value={auditQuery.fsn}
                    onChange={handleFsnChange}
                    onFocus={() => { if(auditQuery.fsn) setShowSuggestions(true); }}
                    maxLength={16}
                    />
                    <Search className="absolute right-3 top-3 w-4 h-4 text-gray-400" />
                </div>

                {/* Autocomplete Suggestions */}
                {showSuggestions && filteredFsns.length > 0 && (
                    <div className="absolute z-10 w-full bg-white border border-gray-200 rounded shadow-lg mt-1 overflow-hidden animate-in fade-in zoom-in-95 duration-100">
                        {filteredFsns.map(fsn => (
                            <button 
                                key={fsn}
                                onClick={() => selectSuggestion(fsn)}
                                className="w-full text-left px-3 py-2 text-sm text-gray-700 hover:bg-blue-50 hover:text-fkBlue transition-colors border-b border-gray-50 last:border-0"
                            >
                                {fsn}
                            </button>
                        ))}
                    </div>
                )}

                <select 
                  className="w-full bg-white border border-gray-300 rounded p-2.5 text-gray-900 focus:border-fkBlue outline-none"
                  value={auditQuery.city}
                  onChange={e => setAuditQuery({...auditQuery, city: e.target.value})}
                >
                  {cities.map(c => <option key={c} value={c}>{c}</option>)}
                </select>
                <input 
                  type="number"
                  className="w-full bg-white border border-gray-300 rounded p-2.5 text-gray-900 focus:border-fkBlue outline-none" 
                  placeholder="Expected Total Value"
                  value={auditQuery.targetMargin || ''}
                  onChange={e => setAuditQuery({...auditQuery, targetMargin: parseFloat(e.target.value)})}
                />
                <button 
                  onClick={handleAudit}
                  disabled={loading}
                  className="w-full bg-fkBlue hover:bg-blue-600 text-white font-bold py-2.5 rounded shadow-sm transition-colors"
                >
                  {loading ? 'Analyzing...' : 'Analyze Variance'}
                </button>
              </div>
            </div>

            {auditResult && (
              <div className={`p-5 rounded-lg border shadow-sm animate-in zoom-in duration-300 ${auditResult.status === 'MATCH' ? 'bg-green-50 border-green-200' : 'bg-red-50 border-red-200'}`}>
                 <div className="flex justify-between items-start mb-2">
                    <div className={`text-lg font-bold flex items-center gap-2 ${auditResult.status === 'MATCH' ? 'text-green-700' : 'text-red-700'}`}>
                        {auditResult.status === 'MATCH' ? <Check className="w-5 h-5"/> : <AlertCircle className="w-5 h-5"/>}
                        {auditResult.status}
                    </div>
                 </div>

                 <div className="mt-4 grid grid-cols-2 gap-4">
                     <div>
                         <p className="text-xs text-gray-500 uppercase font-semibold">Variance Val</p>
                         <p className={`text-xl font-mono font-bold ${auditResult.variance > 0 ? 'text-green-600' : 'text-red-600'}`}>
                            {auditResult.variance > 0 ? '+' : ''}{auditResult.variance.toFixed(2)}
                         </p>
                     </div>
                     <div>
                         <p className="text-xs text-gray-500 uppercase font-semibold">Variance %</p>
                         <div className="flex items-center gap-1">
                            <TrendingUp className={`w-4 h-4 ${parseFloat(auditResult.variancePercent) > 0 ? 'text-green-600' : 'text-red-600'}`} />
                            <p className="text-xl font-mono font-bold text-gray-800">
                                {Math.abs(Number(auditResult.variancePercent))}%
                            </p>
                         </div>
                     </div>
                 </div>
                 {(auditResult.sources.nlc === 'PAN' || auditResult.sources.onInv === 'PAN') && (
                     <div className="mt-3 bg-white/50 p-2 rounded text-[10px] text-gray-600 border border-gray-100">
                         <strong>Note:</strong> Some values inherited from PAN-INDIA default.
                     </div>
                 )}
              </div>
            )}
          </div>

          <div className="lg:col-span-2 fk-card p-6 min-h-[400px]">
            {auditResult ? (
              <div className="h-full w-full">
                <ResponsiveContainer width="100%" height={350}>
                    <BarChart data={auditResult.data} margin={{ top: 20, right: 30, left: 20, bottom: 5 }}>
                        <CartesianGrid strokeDasharray="3 3" stroke="#e0e0e0" vertical={false} />
                        <XAxis dataKey="name" stroke="#9e9e9e" tick={{fill: '#424242', fontSize: 12}} axisLine={false} tickLine={false} />
                        <YAxis stroke="#9e9e9e" tick={{fill: '#424242', fontSize: 12}} axisLine={false} tickLine={false} />
                        <Tooltip content={<CustomTooltip />} cursor={{fill: '#f5f5f5'}} />
                        <Legend wrapperStyle={{ paddingTop: '20px' }} />

                        <Bar dataKey="nlc" stackId="system" name="NLC Value" fill="#2874f0" radius={[0, 0, 4, 4]}>
                           <LabelList dataKey="nlc" position="center" className="fill-white font-bold text-[10px]" formatter={(v: number) => v > 0 ? v.toFixed(0) : ''} />
                        </Bar>
                        <Bar dataKey="onInv" stackId="system" name="On Invoice %" fill="#8b5cf6" radius={[4, 4, 0, 0]}>
                           <LabelList dataKey="onInv" position="center" className="fill-white font-bold text-[10px]" formatter={(v: number) => v > 0 ? v.toFixed(0) : ''} />
                        </Bar>

                        <Bar dataKey="target" stackId="target" name="User Target" fill={auditResult.status === 'MATCH' ? '#388e3c' : '#ff9f00'} radius={[4, 4, 4, 4]}>
                             <LabelList dataKey="target" position="top" className="fill-gray-600 font-bold text-xs" formatter={(v: number) => v.toFixed(2)} />
                        </Bar>

                        {auditResult.status === 'MISMATCH' && (
                             <ReferenceLine 
                                y={auditResult.targetTotal} 
                                stroke="#ff9f00" 
                                strokeDasharray="3 3" 
                             />
                        )}
                    </BarChart>
                </ResponsiveContainer>
              </div>
            ) : (
              <div className="h-full flex flex-col items-center justify-center text-gray-400">
                <BarChart3 className="w-16 h-16 mb-4 opacity-20" />
                <p>Run analysis to view chart</p>
              </div>
            )}
          </div>
        </div>
      )}

      {activeTab === 'APPROVALS' && (
        <div className="space-y-4">
          {requests.length === 0 ? (
            <div className="text-center py-20 bg-white rounded-lg border border-gray-200">
              <Check className="w-12 h-12 mx-auto mb-3 text-green-500 opacity-50" />
              <p className="text-gray-500 font-medium">No pending approvals.</p>
            </div>
          ) : (
            requests.map(req => (
              <div key={req.id} className="fk-card p-5 flex flex-col md:flex-row justify-between items-start md:items-center gap-4 border-l-4 border-l-fkYellow">
                <div>
                  <div className="flex items-center gap-2 mb-2">
                    <span className="bg-yellow-100 text-yellow-800 text-xs px-2 py-0.5 rounded font-bold">ACTION REQUIRED</span>
                    <h4 className="font-bold text-gray-800 text-lg">{req.payload.title} <span className="text-gray-400 font-normal">({req.payload.fsn})</span></h4>
                  </div>
                  <div className="text-sm text-gray-500 grid grid-cols-2 md:grid-cols-4 gap-x-8 gap-y-1 mb-2">
                    <span>City: <b className="text-gray-800">{req.payload.city}</b></span>
                    <span>Type: <b className="text-gray-800">{req.payload.type}</b></span>
                    <span>New Value: <b className="text-fkBlue">{req.payload.value}</b></span>
                    <span>By: {req.requestedBy}</span>
                  </div>
                  <div className="text-xs flex gap-4 text-gray-400">
                      <span className="flex items-center gap-1"><Layers className="w-3 h-3"/> {req.payload.vertical || 'N/A'}</span>
                      <span className="flex items-center gap-1"><UserIcon className="w-3 h-3"/> {req.payload.kam || 'N/A'}</span>
                  </div>
                  {req.reason && (
                      <div className="mt-2 bg-red-50 text-red-600 text-xs px-2 py-1 rounded inline-block font-semibold">
                          Reason: {req.reason}
                      </div>
                  )}
                </div>
                <div className="flex gap-2 w-full md:w-auto">
                  <button 
                    onClick={() => handleRequestAction(req.id, 'REJECTED')}
                    className="flex-1 md:flex-none px-4 py-2 rounded bg-gray-100 hover:bg-gray-200 text-gray-700 text-sm font-medium transition-colors"
                  >
                    Reject
                  </button>
                  <button 
                    onClick={() => handleRequestAction(req.id, 'APPROVED')}
                    className="flex-1 md:flex-none px-4 py-2 rounded bg-fkGreen hover:bg-green-700 text-white font-bold text-sm shadow transition-colors"
                  >
                    Approve
                  </button>
                </div>
              </div>
            ))
          )}
        </div>
      )}

      {activeTab === 'CLOSURE' && (
        <div className="space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                {/* Export Section */}
                <div className="fk-card p-6 space-y-4">
                    <div className="flex items-center gap-3 mb-2">
                        <div className="bg-blue-50 p-3 rounded-lg">
                            <FileDown className="w-6 h-6 text-fkBlue" />
                        </div>
                        <div>
                            <h3 className="text-lg font-bold text-gray-800">Export Data</h3>
                            <p className="text-sm text-gray-500">Download data for records and auditing.</p>
                        </div>
                    </div>

                    <div className="pt-4 space-y-4 border-t border-gray-100">
                        <div>
                            <label className="block text-xs font-bold text-gray-500 mb-2 flex items-center gap-2 uppercase">
                                <Calendar className="w-3 h-3" /> Select Month
                            </label>
                            <input 
                                type="month"
                                className="w-full bg-white border border-gray-300 rounded p-2 text-gray-800"
                                value={selectedMonth}
                                onChange={(e) => setSelectedMonth(e.target.value)}
                            />
                        </div>
                        <div className="flex flex-col gap-3">
                            <button 
                                onClick={() => handleExport('MONTH')}
                                disabled={exportLoading}
                                className="w-full py-2 bg-fkBlue hover:bg-blue-600 rounded text-white text-sm font-bold shadow-sm transition-colors"
                            >
                                {exportLoading ? 'Generating CSV...' : `Export ${selectedMonth} Data`}
                            </button>
                            <button 
                                onClick={() => handleExport('FULL')}
                                disabled={exportLoading}
                                className="w-full py-2 border border-gray-300 hover:bg-gray-50 rounded text-gray-600 text-sm font-medium transition-colors"
                            >
                                Export Full Database
                            </button>
                        </div>
                    </div>
                </div>

                {/* Clear Section */}
                <div className="fk-card p-6 space-y-4 border-red-100 bg-red-50/30">
                    <div className="flex items-center gap-3 mb-2">
                        <div className="bg-red-100 p-3 rounded-lg">
                            <Database className="w-6 h-6 text-red-600" />
                        </div>
                        <div>
                            <h3 className="text-lg font-bold text-red-600">System Reset</h3>
                            <p className="text-sm text-gray-500">Clear database for new operational cycle.</p>
                        </div>
                    </div>

                    <div className="pt-4 space-y-4 border-t border-red-100">
                        <div className="bg-red-50 border border-red-100 p-4 rounded text-sm text-red-700">
                            <p className="flex items-start gap-2">
                                <AlertCircle className="w-5 h-5 flex-shrink-0" />
                                <span>
                                    <strong>Warning:</strong> This deletes ALL active records. Export data first.
                                </span>
                            </p>
                        </div>

                        <button 
                            onClick={handleClearDB}
                            disabled={loading}
                            className="w-full py-3 bg-red-600 hover:bg-red-700 rounded text-white font-bold shadow-md flex items-center justify-center gap-2 transition-all"
                        >
                            {loading ? 'Clearing...' : <><Trash2 className="w-4 h-4" /> Clear Database</>}
                        </button>
                    </div>
                </div>
            </div>

            {/* Archive Viewer */}
            <div className="fk-card p-6 space-y-4">
                 <div className="flex items-center justify-between">
                     <h3 className="text-lg font-bold text-gray-800 flex items-center gap-2">
                        <Archive className="w-5 h-5 text-gray-500" /> Archived Records (Bin)
                     </h3>
                     <button onClick={toggleArchive} className="flex items-center gap-2 text-sm text-fkBlue hover:underline transition-colors font-medium">
                        {showArchive ? 'Hide Archive' : 'View Deleted Records'}
                        <Clock className="w-3 h-3" />
                     </button>
                 </div>

                 {showArchive && (
                     <div className="overflow-auto max-h-80 border border-gray-200 rounded-lg animate-in fade-in">
                        <table className="w-full text-left text-xs text-gray-600">
                            <thead className="bg-gray-50 sticky top-0 font-bold text-gray-700 border-b border-gray-200">
                                <tr>
                                    <th className="p-3">Deleted At</th>
                                    <th className="p-3">Deleted By</th>
                                    <th className="p-3">FSN</th>
                                    <th className="p-3">City</th>
                                    <th className="p-3">Reason</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-gray-100 bg-white">
                                {archiveData.map((r, i) => (
                                    <tr key={i} className="hover:bg-gray-50">
                                        <td className="p-3 font-mono text-gray-500">{new Date(r.deletedAt).toLocaleString()}</td>
                                        <td className="p-3">{r.deletedBy}</td>
                                        <td className="p-3 font-medium">{r.fsn}</td>
                                        <td className="p-3">{r.city}</td>
                                        <td className="p-3 text-fkYellow font-medium">{r.note || 'Manual Delete/Override'}</td>
                                    </tr>
                                ))}
                                {archiveData.length === 0 && <tr><td colSpan={5} className="p-6 text-center italic text-gray-400">Bin is empty</td></tr>}
                            </tbody>
                        </table>
                     </div>
                 )}
            </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { db } from '../services/db';
import { CommercialRecord, User, Role, COMMERCIAL_TYPES, CommercialType } from '../types';
import { Download, Filter, RefreshCw, Trash2, Edit2, Save, X, Clock } from 'lucide-react';

interface DataExplorerProps {
  user: User;
}

interface PivotRow {
  key: string;
  fsn: string;
  brand: string;
  title: string;
  vertical: string;
  kam: string;
  type: CommercialType;
  startDate: string;
  endDate: string;
  cityRecords: { [key: string]: CommercialRecord | undefined };
  values: { [key: string]: number | undefined };
  isExpiringSoon: boolean;
}

export const DataExplorer: React.FC<DataExplorerProps> = ({ user }) => {
  const [records, setRecords] = useState<CommercialRecord[]>([]);
  const [cities, setCities] = useState<string[]>([]);
  const [loading, setLoading] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');

  // Edit State
  const [editingRowKey, setEditingRowKey] = useState<string | null>(null);
  const [editForm, setEditForm] = useState<Partial<PivotRow> | null>(null);
  const [processingAction, setProcessingAction] = useState(false);

  // Permission Check
  const canEdit = user.role !== Role.MAKER;

  useEffect(() => {
    let unsubscribe: () => void;

    const init = async () => {
      setLoading(true);
      try {
        const c = await db.getCities();
        setCities(c);
        unsubscribe = db.subscribeToRecords((data) => {
          setRecords(data);
          setLoading(false);
        });
      } catch (e) {
        console.error("Failed to load data", e);
        setLoading(false);
      }
    };

    init();

    return () => {
      if (unsubscribe) unsubscribe();
    };
  }, []);

  const pivotData: PivotRow[] = useMemo(() => {
    const map = new Map<string, PivotRow>();
    const today = new Date();
    const sevenDaysLater = new Date();
    sevenDaysLater.setDate(today.getDate() + 7);

    records.forEach(r => {
      const key = `${r.fsn}_${r.type}_${r.startDate}_${r.endDate}`;
      if (!map.has(key)) {
        const endDate = new Date(r.endDate);
        const isExpiringSoon = endDate >= today && endDate <= sevenDaysLater;

        map.set(key, {
          key,
          fsn: r.fsn,
          brand: r.brand,
          title: r.title,
          vertical: r.vertical || '',
          kam: r.kam || '',
          type: r.type,
          startDate: r.startDate,
          endDate: r.endDate,
          cityRecords: {},
          values: {},
          isExpiringSoon
        });
      }
      const entry = map.get(key)!;
      entry.cityRecords[r.city] = r;
      entry.values[r.city] = r.value;

      // Update inherited fields if needed
      if(r.vertical && !entry.vertical) entry.vertical = r.vertical;
      if(r.kam && !entry.kam) entry.kam = r.kam;
    });
    let result = Array.from(map.values());
    if (searchTerm) {
      const lower = searchTerm.toLowerCase();
      result = result.filter(item => 
        item.fsn.toLowerCase().includes(lower) || 
        item.brand.toLowerCase().includes(lower) ||
        item.title.toLowerCase().includes(lower)
      );
    }
    return result;
  }, [records, searchTerm]);

  const exportCSV = () => {
    const headers = ['FSN', 'Brand', 'Title', 'Vertical', 'KAM', 'Type', 'Start', 'End', ...cities].join(',');
    const rows = pivotData.map(row => {
      const cityVals = cities.map(c => {
          const val = row.values[c];
          const pan = row.values['PAN-INDIA'];
          // Export effective value
          return val !== undefined ? val : (pan !== undefined ? pan : '');
      }).join(',');
      return `${row.fsn},${row.brand},${row.title},${row.vertical},${row.kam},${row.type},${row.startDate},${row.endDate},${cityVals}`;
    }).join('\n');

    const blob = new Blob([headers + '\n' + rows], { type: 'text/csv' });
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `mm_export_${Date.now()}.csv`;
    a.click();
    window.URL.revokeObjectURL(url);
  };

  const handleEditClick = (row: PivotRow) => {
    setEditingRowKey(row.key);
    setEditForm({ ...row, values: { ...row.values } });
  };

  const handleCancelEdit = () => {
    setEditingRowKey(null);
    setEditForm(null);
  };

  const handleDeleteRow = async (row: PivotRow) => {
    if (!canEdit) return;
    if (!window.confirm(`Delete all records for ${row.title} (${row.type})?`)) return;
    setProcessingAction(true);
    try {
      const idsToDelete = records
        .filter(r => r.fsn === row.fsn && r.type === row.type && r.startDate === row.startDate && r.endDate === row.endDate)
        .map(r => r.id);
      if (idsToDelete.length === 0) return;
      await db.deleteRecords(idsToDelete, user.name);
    } catch (e) {
      alert('Error deleting records');
    } finally {
      setProcessingAction(false);
    }
  };

  const handleSaveEdit = async (originalRow: PivotRow) => {
    if (!editForm || !canEdit) return;

    if ((editForm.fsn || originalRow.fsn).length !== 16) {
        alert("FSN must be exactly 16 characters.");
        return;
    }

    setProcessingAction(true);
    try {
      const recordsToUpdate = records.filter(r => 
          r.fsn === originalRow.fsn && r.type === originalRow.type && r.startDate === originalRow.startDate && r.endDate === originalRow.endDate
      );

      const updatePromises: Promise<void>[] = [];
      const recordsForBulkUpdate: CommercialRecord[] = [];

      recordsToUpdate.forEach(r => {
        const newCityValue = editForm.values?.[r.city];
        const updatedRecord: CommercialRecord = {
          ...r,
          fsn: editForm.fsn || r.fsn,
          brand: editForm.brand || r.brand,
          title: editForm.title || r.title,
          vertical: editForm.vertical || r.vertical,
          kam: editForm.kam || r.kam,
          type: editForm.type || r.type,
          startDate: editForm.startDate || r.startDate,
          endDate: editForm.endDate || r.endDate,
          value: newCityValue !== undefined ? Number(newCityValue) : r.value,
          lastUpdatedBy: user.name,
          lastUpdatedAt: Date.now()
        };
        recordsForBulkUpdate.push(updatedRecord);
      });

      if (recordsForBulkUpdate.length > 0) updatePromises.push(db.updateRecords(recordsForBulkUpdate));

      for (const city of cities) {
        const hasExisting = recordsToUpdate.some(r => r.city === city);
        const newVal = editForm.values?.[city];
        // Note: We do NOT inherit PAN-INDIA during save. Saving creates an explicit override.
        if (!hasExisting && newVal !== undefined && Number(newVal) !== 0) {
           updatePromises.push(db.addRecords([{
             id: `rec_${Date.now()}_${Math.random().toString(36).substr(2,5)}`,
             fsn: editForm.fsn!,
             brand: editForm.brand!,
             title: editForm.title!,
             vertical: editForm.vertical || '',
             kam: editForm.kam || '',
             type: editForm.type!,
             city: city,
             startDate: editForm.startDate!,
             endDate: editForm.endDate!,
             value: Number(newVal),
             lastUpdatedBy: user.name,
             lastUpdatedAt: Date.now()
           }]));
        }
      }
      await Promise.all(updatePromises);
      setEditingRowKey(null);
      setEditForm(null);
    } catch (e) {
      alert('Failed to save changes');
    } finally {
      setProcessingAction(false);
    }
  };

  const refreshCities = async () => {
    setLoading(true);
    const c = await db.getCities();
    setCities(c);
    setLoading(false);
  };

  return (
    <div className="space-y-4 h-full flex flex-col animate-in fade-in duration-500">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
           <h2 className="text-2xl font-bold text-gray-800">Database Explorer</h2>
           <p className="text-sm text-gray-500">Search and edit active commercial records</p>
        </div>
        <div className="flex gap-2">
           <div className="relative">
             <Filter className="absolute left-3 top-2.5 h-4 w-4 text-gray-400"/>
             <input 
               className="bg-white border border-gray-300 rounded shadow-sm py-2 pl-9 pr-4 text-sm text-gray-800 focus:ring-1 focus:ring-fkBlue focus:border-fkBlue outline-none w-64 transition-shadow"
               placeholder="Filter by FSN, Brand..."
               value={searchTerm}
               onChange={e => setSearchTerm(e.target.value)}
             />
           </div>
           <button onClick={refreshCities} className="p-2 bg-white border border-gray-300 rounded hover:bg-gray-50 text-gray-600 shadow-sm">
             <RefreshCw className={`h-5 w-5 ${loading ? 'animate-spin' : ''}`} />
           </button>
           <button onClick={exportCSV} className="flex items-center gap-2 px-4 py-2 bg-fkGreen hover:bg-green-700 text-white rounded shadow-sm text-sm font-bold transition-colors">
             <Download className="h-4 w-4" /> Export CSV
           </button>
        </div>
      </div>

      <div className="flex-1 bg-white rounded-lg shadow-sm border border-gray-200 overflow-hidden flex flex-col relative">
        {processingAction && (
          <div className="absolute inset-0 bg-white/60 z-50 flex items-center justify-center backdrop-blur-sm">
            <RefreshCw className="w-8 h-8 text-fkBlue animate-spin" />
          </div>
        )}

        <div className="overflow-auto scrollbar-hide flex-1">
          <table className="w-full text-left border-collapse min-w-[1400px]">
            <thead className="bg-gray-50 sticky top-0 z-10 text-xs uppercase text-gray-500 font-semibold shadow-sm">
              <tr>
                <th className="p-4 border-b border-gray-200 min-w-[120px] bg-gray-50">FSN</th>
                <th className="p-4 border-b border-gray-200 bg-gray-50">Brand</th>
                <th className="p-4 border-b border-gray-200 bg-gray-50">Title</th>
                <th className="p-4 border-b border-gray-200 bg-gray-50">Vertical</th>
                <th className="p-4 border-b border-gray-200 bg-gray-50">KAM</th>
                <th className="p-4 border-b border-gray-200 bg-gray-50 min-w-[120px]">Type</th>
                <th className="p-4 border-b border-gray-200 text-center min-w-[200px] bg-gray-50">Dates</th>
                {cities.map(c => (
                  <th key={c} className="p-4 border-b border-gray-200 text-center min-w-[80px] bg-gray-50">{c}</th>
                ))}
                {canEdit && <th className="p-4 border-b border-gray-200 text-center sticky right-0 bg-gray-50 z-20 w-24">Actions</th>}
              </tr>
            </thead>
            <tbody className="text-sm divide-y divide-gray-100">
              {pivotData.map((row) => {
                const isEditing = editingRowKey === row.key;
                return (
                  <tr key={row.key} className={`hover:bg-blue-50/50 transition-colors group ${isEditing ? 'bg-blue-50' : ''}`}>
                    <td className="p-4 font-mono text-fkBlue font-semibold">
                        {isEditing ? (
                            <input className="w-full bg-white border border-gray-300 rounded px-2 py-1 text-gray-800 text-xs font-mono"
                              value={editForm?.fsn || ''} onChange={e => setEditForm(prev => ({ ...prev!, fsn: e.target.value }))} 
                              maxLength={16}
                              />
                        ) : (
                          <div className="flex items-center gap-2">
                             {row.fsn}
                             {row.isExpiringSoon && (
                               <span title="Expiring within 7 days">
                                 <Clock className="w-3 h-3 text-fkYellow animate-pulse" />
                               </span>
                             )}
                          </div>
                        )}
                    </td>
                    <td className="p-4 text-gray-700 max-w-[150px] truncate">
                        {isEditing ? (
                            <input className="w-full bg-white border border-gray-300 rounded px-2 py-1 text-gray-800 text-xs"
                              value={editForm?.brand || ''} onChange={e => setEditForm(prev => ({ ...prev!, brand: e.target.value }))} />
                        ) : row.brand}
                    </td>
                    <td className="p-4 text-gray-700 max-w-[200px] truncate" title={row.title}>
                        {isEditing ? (
                            <input className="w-full bg-white border border-gray-300 rounded px-2 py-1 text-gray-800 text-xs"
                              value={editForm?.title || ''} onChange={e => setEditForm(prev => ({ ...prev!, title: e.target.value }))} />
                        ) : row.title}
                    </td>
                    <td className="p-4 text-gray-700 max-w-[150px] truncate">
                        {isEditing ? (
                            <input className="w-full bg-white border border-gray-300 rounded px-2 py-1 text-gray-800 text-xs"
                              value={editForm?.vertical || ''} onChange={e => setEditForm(prev => ({ ...prev!, vertical: e.target.value }))} />
                        ) : row.vertical}
                    </td>
                    <td className="p-4 text-gray-700 max-w-[150px] truncate">
                        {isEditing ? (
                            <input className="w-full bg-white border border-gray-300 rounded px-2 py-1 text-gray-800 text-xs"
                              value={editForm?.kam || ''} onChange={e => setEditForm(prev => ({ ...prev!, kam: e.target.value }))} />
                        ) : row.kam}
                    </td>
                    <td className="p-4">
                      {isEditing ? (
                          <select className="w-full bg-white border border-gray-300 rounded px-2 py-1 text-gray-800 text-xs"
                             value={editForm?.type} onChange={e => setEditForm(prev => ({ ...prev!, type: e.target.value as CommercialType }))}>
                            {COMMERCIAL_TYPES.map(t => <option key={t} value={t}>{t}</option>)}
                          </select>
                      ) : (
                          <span className={`px-2 py-1 rounded text-[10px] border whitespace-nowrap font-medium ${
                            row.type.includes('Margin') ? 'border-purple-200 text-purple-700 bg-purple-50' : 
                            'border-blue-200 text-blue-700 bg-blue-50'
                          }`}>
                            {row.type}
                          </span>
                      )}
                    </td>
                    <td className="p-4 text-gray-500 text-xs text-center">
                      {isEditing ? (
                        <div className="flex flex-col gap-2">
                           <input type="date" className="bg-white border border-gray-300 rounded px-2 py-1 text-gray-800 text-xs w-full"
                             value={editForm?.startDate || row.startDate} onChange={e => setEditForm(prev => ({ ...prev!, startDate: e.target.value }))} />
                           <input type="date" className="bg-white border border-gray-300 rounded px-2 py-1 text-gray-800 text-xs w-full"
                             value={editForm?.endDate || row.endDate} onChange={e => setEditForm(prev => ({ ...prev!, endDate: e.target.value }))} />
                        </div>
                      ) : (
                        <div className="flex flex-col items-center">
                           <span className="font-mono">{row.startDate}</span>
                           <span className="text-[10px] text-gray-400">to</span>
                           <span className={`font-mono ${row.isExpiringSoon ? 'text-fkYellow font-bold' : ''}`}>{row.endDate}</span>
                        </div>
                      )}
                    </td>
                    {cities.map(c => {
                      const specificVal = row.values[c];
                      const panVal = row.values['PAN-INDIA'];
                      const effectiveVal = specificVal !== undefined ? specificVal : (c !== 'PAN-INDIA' ? panVal : undefined);
                      const isInherited = specificVal === undefined && effectiveVal !== undefined;

                      return (
                        <td key={c} className={`p-2 text-center border-l border-gray-100 ${isEditing ? 'p-1' : ''}`}>
                           {isEditing ? (
                             <input type="number" className="w-16 bg-white border border-gray-300 rounded px-1 py-1 text-center text-gray-800 text-sm focus:border-fkBlue outline-none"
                               value={editForm?.values?.[c] ?? ''} placeholder={isInherited ? String(effectiveVal) : '-'}
                               onChange={e => {
                                 const val = e.target.value;
                                 setEditForm(prev => ({ ...prev!, values: { ...prev!.values, [c]: val === '' ? undefined : parseFloat(val) } }));
                               }} />
                           ) : (
                               effectiveVal !== undefined ? (
                                   <span className={isInherited ? "text-gray-400 italic" : "text-gray-800 font-bold"}>
                                     {effectiveVal}
                                     {isInherited && <span className="ml-1 text-[8px] border border-gray-200 rounded px-0.5 text-gray-400 not-italic">PAN</span>}
                                   </span>
                               ) : <span className="text-gray-300">-</span>
                           )}
                        </td>
                      );
                    })}
                    {canEdit && (
                      <td className="p-4 border-l border-gray-200 sticky right-0 bg-white group-hover:bg-blue-50/50 transition-colors z-10 shadow-[-5px_0_10px_-5px_rgba(0,0,0,0.1)]">
                        <div className="flex items-center justify-center gap-2">
                          {isEditing ? (
                            <>
                              <button onClick={() => handleSaveEdit(row)} className="p-1.5 bg-green-600 hover:bg-green-700 rounded text-white shadow-sm" title="Save">
                                <Save className="w-4 h-4" />
                              </button>
                              <button onClick={handleCancelEdit} className="p-1.5 bg-gray-500 hover:bg-gray-600 rounded text-white" title="Cancel">
                                <X className="w-4 h-4" />
                              </button>
                            </>
                          ) : (
                            <>
                              <button onClick={() => handleEditClick(row)} className="p-1.5 hover:bg-blue-100 text-gray-400 hover:text-fkBlue rounded transition-colors">
                                <Edit2 className="w-4 h-4" />
                              </button>
                              <button onClick={() => handleDeleteRow(row)} className="p-1.5 hover:bg-red-100 text-gray-400 hover:text-red-600 rounded transition-colors">
                                <Trash2 className="w-4 h-4" />
                              </button>
                            </>
                          )}
                        </div>
                      </td>
                    )}
                  </tr>
                );
              })}
              {pivotData.length === 0 && !loading && (
                 <tr><td colSpan={cities.length + 6} className="p-8 text-center text-gray-500">No records found.</td></tr>
              )}
            </tbody>
          </table>
        </div>
        <div className="bg-gray-50 p-2 text-xs text-gray-500 text-center border-t border-gray-200">
          Showing {pivotData.length} records
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { db } from '../services/db';
import { DuplicateRequest, User, CommercialType } from '../types';
import { Check, X, Search, BarChart3, Archive, TrendingUp, AlertCircle, FileDown, Calendar, Trash2, Database, Clock, ChevronDown, User as UserIcon, Layers } from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer, ReferenceLine, LabelList } from 'recharts';
import Papa from 'papaparse';

interface CheckerProps {
  user: User;
}

export const CheckerWorkspace: React.FC<CheckerProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<'AUDIT' | 'APPROVALS' | 'CLOSURE'>('AUDIT');
  const [requests, setRequests] = useState<DuplicateRequest[]>([]);
  const [cities, setCities] = useState<string[]>([]);

  // Audit State
  const [auditQuery, setAuditQuery] = useState({ fsn: '', city: 'BLR', targetMargin: 0 });
  const [auditResult, setAuditResult] = useState<any>(null);
  const [loading, setLoading] = useState(false);

  // Autocomplete State
  const [allFsns, setAllFsns] = useState<string[]>([]);
  const [filteredFsns, setFilteredFsns] = useState<string[]>([]);
  const [showSuggestions, setShowSuggestions] = useState(false);

  // Closure/Export State
  const [selectedMonth, setSelectedMonth] = useState(new Date().toISOString().slice(0, 7)); // YYYY-MM
  const [exportLoading, setExportLoading] = useState(false);

  // Archive View State
  const [showArchive, setShowArchive] = useState(false);
  const [archiveData, setArchiveData] = useState<any[]>([]);

  useEffect(() => {
    loadRequests();
    loadCities();
    loadUniqueFsns();
    const interval = setInterval(loadRequests, 5000);
    return () => clearInterval(interval);
  }, []);

  const loadCities = async () => {
    const c = await db.getCities();
    setCities(c);
    if (!c.includes(auditQuery.city)) {
       setAuditQuery(prev => ({ ...prev, city: c.includes('BLR') ? 'BLR' : c[0] || '' }));
    }
  };

  const loadUniqueFsns = async () => {
    const records = await db.getRecords();
    const unique = Array.from(new Set(records.map(r => r.fsn)));
    setAllFsns(unique);
  };

  const loadRequests = async () => {
    const reqs = await db.getDuplicateRequests();
    setRequests(reqs.filter(r => r.status === 'PENDING'));
  };

  const loadArchive = async () => {
    const data = await db.getBinRecords();
    setArchiveData(data.sort((a: any, b: any) => b.deletedAt - a.deletedAt));
  };

  const toggleArchive = () => {
      if (!showArchive) loadArchive();
      setShowArchive(!showArchive);
  };

  const handleFsnChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = e.target.value;
    setAuditQuery({ ...auditQuery, fsn: val });

    if (val.length > 0) {
        const matches = allFsns.filter(f => f.toLowerCase().includes(val.toLowerCase()));
        setFilteredFsns(matches.slice(0, 5)); // Limit to 5 suggestions
        setShowSuggestions(true);
    } else {
        setShowSuggestions(false);
    }
  };

  const selectSuggestion = (fsn: string) => {
      setAuditQuery({ ...auditQuery, fsn });
      setShowSuggestions(false);
  };

  const handleAudit = async () => {
    if (!auditQuery.fsn) return;

    if (auditQuery.fsn.length !== 16) {
        alert("FSN must be exactly 16 characters.");
        return;
    }

    setLoading(true);
    setShowSuggestions(false); // Hide if open

    const records = await db.getRecords();

    const relevant = records.filter(r => 
      r.fsn === auditQuery.fsn && 
      (r.city === auditQuery.city || r.city === 'PAN-INDIA')
    );

    // Helper to get specific city value or fallback to PAN-INDIA
    const getEffectiveValue = (type: CommercialType) => {
        const specific = relevant.find(r => r.type === type && r.city === auditQuery.city);
        if (specific) return { val: specific.value, source: 'CITY' };

        const pan = relevant.find(r => r.type === type && r.city === 'PAN-INDIA');
        if (pan) return { val: pan.value, source: 'PAN' };

        return { val: 0, source: 'NONE' };
    };

    const nlcObj = getEffectiveValue(CommercialType.NLC_VALUE);
    const nlcPercObj = getEffectiveValue(CommercialType.NLC_PERCENT); // Handle NLC Percent? 
    // For Audit chart, we currently mix NLC Value and OnInvoice. NLC % is tricky to sum with value without base price.
    // For now, we visualize known absolute/simple % components.

    const onInvObj = getEffectiveValue(CommercialType.ON_INVOICE);

    const nlc = nlcObj.val; 
    const onInv = onInvObj.val;

    // Simplification: In a real app we'd need base price to calculate NLC % impact.
    // Here we just sum the raw numbers for the demo chart.
    const systemTotal = nlc + onInv; 
    const variance = auditQuery.targetMargin - systemTotal;
    const variancePercent = auditQuery.targetMargin ? ((variance / auditQuery.targetMargin) * 100) : 0;

    setAuditResult({
      data: [
        { name: 'System', nlc: nlc, onInv: onInv, total: systemTotal },
        { name: 'Target', target: auditQuery.targetMargin }
      ],
      systemTotal,
      targetTotal: auditQuery.targetMargin,
      variance,
      variancePercent: variancePercent.toFixed(2),
      status: Math.abs(variance) < 0.1 ? 'MATCH' : 'MISMATCH',
      details: relevant,
      sources: { nlc: nlcObj.source, onInv: onInvObj.source }
    });
    setLoading(false);
  };

  const handleRequestAction = async (reqId: string, action: 'APPROVED' | 'REJECTED') => {
    await db.resolveDuplicateRequest(reqId, action, user.id);
    loadRequests();
    loadUniqueFsns(); // Reload FSNs in case new ones were added via approval
  };

  const handleExport = async (mode: 'MONTH' | 'FULL') => {
    setExportLoading(true);
    try {
        const records = await db.getRecords();
        let dataToExport = records;

        if (mode === 'MONTH') {
            const [year, month] = selectedMonth.split('-').map(Number);
            const startOfMonth = new Date(year, month - 1, 1).toISOString().split('T')[0];
            const endOfMonth = new Date(year, month, 0).toISOString().split('T')[0];
            dataToExport = records.filter(r => r.startDate <= endOfMonth && r.endDate >= startOfMonth);
        }

        const csv = Papa.unparse(dataToExport.map(r => ({
            ID: r.id,
            FSN: r.fsn,
            Brand: r.brand,
            Title: r.title,
            Vertical: r.vertical,
            KAM: r.kam,
            City: r.city,
            Type: r.type,
            Value: r.value,
            StartDate: r.startDate,
            EndDate: r.endDate,
            LastUpdatedBy: r.lastUpdatedBy,
            LastUpdatedAt: new Date(r.lastUpdatedAt).toISOString()
        })));

        const blob = new Blob([csv], { type: 'text/csv' });
        const url = window.URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `mm_export_${mode.toLowerCase()}_${Date.now()}.csv`;
        a.click();
        window.URL.revokeObjectURL(url);
    } catch (e) {
        alert('Export failed');
    } finally {
        setExportLoading(false);
    }
  };

  const handleClearDB = async () => {
    if (window.confirm("CRITICAL: Delete all active records for Month End?")) {
        const confirmText = prompt("Type 'DELETE' to confirm:");
        if (confirmText === 'DELETE') {
            setLoading(true);
            try {
                await db.clearAllRecords(user.name);
                alert("Database reset. Records archived.");
                setAuditResult(null);
                setRequests([]);
                loadArchive();
                setAllFsns([]); // Clear suggestions
            } catch (e) {
                alert("Failed.");
            } finally {
                setLoading(false);
            }
        }
    }
  };

  const CustomTooltip = ({ active, payload, label }: any) => {
    if (active && payload && payload.length) {
      return (
        <div className="bg-white border border-gray-200 p-3 rounded shadow-lg text-xs">
          <p className="font-bold text-gray-800 mb-2">{label}</p>
          {payload.map((entry: any, index: number) => (
            <div key={index} className="flex items-center gap-2 mb-1">
               <div className="w-2 h-2 rounded-full" style={{ backgroundColor: entry.color }} />
               <span className="text-gray-500">{entry.name}:</span>
               <span className="text-gray-900 font-mono font-bold">{Number(entry.value).toFixed(2)}</span>
            </div>
          ))}
          {label === 'System' && (
             <div className="mt-2 pt-2 border-t border-gray-100 flex justify-between gap-4">
                <span className="text-gray-600 font-bold">Total:</span>
                <span className="text-gray-900 font-mono font-bold">{payload.reduce((acc: number, cur: any) => acc + (cur.value || 0), 0).toFixed(2)}</span>
             </div>
          )}
          {label === 'System' && auditResult?.sources && (
              <div className="mt-1 pt-1 border-t border-gray-50 text-[10px] text-gray-400">
                  {auditResult.sources.nlc === 'PAN' && <div>* NLC from PAN-INDIA</div>}
                  {auditResult.sources.onInv === 'PAN' && <div>* On-Inv from PAN-INDIA</div>}
              </div>
          )}
        </div>
      );
    }
    return null;
  };

  return (
    <div className="space-y-6 max-w-7xl mx-auto animate-in fade-in duration-500">
      <div className="flex justify-between items-center border-b border-gray-200 pb-4">
        <div>
            <h2 className="text-2xl font-bold text-gray-800 flex items-center gap-2">
               Checker Workspace
            </h2>
            <p className="text-sm text-gray-500">Audit commercial logic and approvals</p>
        </div>
        <div className="flex gap-1 bg-white p-1 rounded border border-gray-200">
          <button onClick={() => setActiveTab('AUDIT')} className={`px-4 py-2 rounded text-sm font-semibold transition-all ${activeTab === 'AUDIT' ? 'bg-fkBlue text-white shadow-sm' : 'text-gray-500 hover:text-gray-800'}`}>Audit Tool</button>
          <button onClick={() => setActiveTab('APPROVALS')} className={`px-4 py-2 rounded text-sm font-semibold transition-all flex items-center gap-2 ${activeTab === 'APPROVALS' ? 'bg-fkBlue text-white shadow-sm' : 'text-gray-500 hover:text-gray-800'}`}>
            Approvals
            {requests.length > 0 && <span className="bg-red-500 text-white text-[10px] px-1.5 py-0.5 rounded-full">{requests.length}</span>}
          </button>
          <button onClick={() => setActiveTab('CLOSURE')} className={`px-4 py-2 rounded text-sm font-semibold transition-all ${activeTab === 'CLOSURE' ? 'bg-fkYellow text-white shadow-sm' : 'text-gray-500 hover:text-gray-800'}`}>
            Month End
          </button>
        </div>
      </div>

      {activeTab === 'AUDIT' && (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          <div className="lg:col-span-1 space-y-4">
            <div className="fk-card p-6">
              <h3 className="text-sm font-bold uppercase text-gray-400 mb-4 tracking-wider">Run Audit</h3>
              <div className="space-y-3 relative">
                <div className="relative">
                    <input 
                    className="w-full bg-white border border-gray-300 rounded p-2.5 text-gray-900 focus:border-fkBlue outline-none" 
                    placeholder="Enter FSN"
                    value={auditQuery.fsn}
                    onChange={handleFsnChange}
                    onFocus={() => { if(auditQuery.fsn) setShowSuggestions(true); }}
                    maxLength={16}
                    />
                    <Search className="absolute right-3 top-3 w-4 h-4 text-gray-400" />
                </div>

                {/* Autocomplete Suggestions */}
                {showSuggestions && filteredFsns.length > 0 && (
                    <div className="absolute z-10 w-full bg-white border border-gray-200 rounded shadow-lg mt-1 overflow-hidden animate-in fade-in zoom-in-95 duration-100">
                        {filteredFsns.map(fsn => (
                            <button 
                                key={fsn}
                                onClick={() => selectSuggestion(fsn)}
                                className="w-full text-left px-3 py-2 text-sm text-gray-700 hover:bg-blue-50 hover:text-fkBlue transition-colors border-b border-gray-50 last:border-0"
                            >
                                {fsn}
                            </button>
                        ))}
                    </div>
                )}

                <select 
                  className="w-full bg-white border border-gray-300 rounded p-2.5 text-gray-900 focus:border-fkBlue outline-none"
                  value={auditQuery.city}
                  onChange={e => setAuditQuery({...auditQuery, city: e.target.value})}
                >
                  {cities.map(c => <option key={c} value={c}>{c}</option>)}
                </select>
                <input 
                  type="number"
                  className="w-full bg-white border border-gray-300 rounded p-2.5 text-gray-900 focus:border-fkBlue outline-none" 
                  placeholder="Expected Total Value"
                  value={auditQuery.targetMargin || ''}
                  onChange={e => setAuditQuery({...auditQuery, targetMargin: parseFloat(e.target.value)})}
                />
                <button 
                  onClick={handleAudit}
                  disabled={loading}
                  className="w-full bg-fkBlue hover:bg-blue-600 text-white font-bold py-2.5 rounded shadow-sm transition-colors"
                >
                  {loading ? 'Analyzing...' : 'Analyze Variance'}
                </button>
              </div>
            </div>

            {auditResult && (
              <div className={`p-5 rounded-lg border shadow-sm animate-in zoom-in duration-300 ${auditResult.status === 'MATCH' ? 'bg-green-50 border-green-200' : 'bg-red-50 border-red-200'}`}>
                 <div className="flex justify-between items-start mb-2">
                    <div className={`text-lg font-bold flex items-center gap-2 ${auditResult.status === 'MATCH' ? 'text-green-700' : 'text-red-700'}`}>
                        {auditResult.status === 'MATCH' ? <Check className="w-5 h-5"/> : <AlertCircle className="w-5 h-5"/>}
                        {auditResult.status}
                    </div>
                 </div>

                 <div className="mt-4 grid grid-cols-2 gap-4">
                     <div>
                         <p className="text-xs text-gray-500 uppercase font-semibold">Variance Val</p>
                         <p className={`text-xl font-mono font-bold ${auditResult.variance > 0 ? 'text-green-600' : 'text-red-600'}`}>
                            {auditResult.variance > 0 ? '+' : ''}{auditResult.variance.toFixed(2)}
                         </p>
                     </div>
                     <div>
                         <p className="text-xs text-gray-500 uppercase font-semibold">Variance %</p>
                         <div className="flex items-center gap-1">
                            <TrendingUp className={`w-4 h-4 ${parseFloat(auditResult.variancePercent) > 0 ? 'text-green-600' : 'text-red-600'}`} />
                            <p className="text-xl font-mono font-bold text-gray-800">
                                {Math.abs(Number(auditResult.variancePercent))}%
                            </p>
                         </div>
                     </div>
                 </div>
                 {(auditResult.sources.nlc === 'PAN' || auditResult.sources.onInv === 'PAN') && (
                     <div className="mt-3 bg-white/50 p-2 rounded text-[10px] text-gray-600 border border-gray-100">
                         <strong>Note:</strong> Some values inherited from PAN-INDIA default.
                     </div>
                 )}
              </div>
            )}
          </div>

          <div className="lg:col-span-2 fk-card p-6 min-h-[400px]">
            {auditResult ? (
              <div className="h-full w-full">
                <ResponsiveContainer width="100%" height={350}>
                    <BarChart data={auditResult.data} margin={{ top: 20, right: 30, left: 20, bottom: 5 }}>
                        <CartesianGrid strokeDasharray="3 3" stroke="#e0e0e0" vertical={false} />
                        <XAxis dataKey="name" stroke="#9e9e9e" tick={{fill: '#424242', fontSize: 12}} axisLine={false} tickLine={false} />
                        <YAxis stroke="#9e9e9e" tick={{fill: '#424242', fontSize: 12}} axisLine={false} tickLine={false} />
                        <Tooltip content={<CustomTooltip />} cursor={{fill: '#f5f5f5'}} />
                        <Legend wrapperStyle={{ paddingTop: '20px' }} />

                        <Bar dataKey="nlc" stackId="system" name="NLC Value" fill="#2874f0" radius={[0, 0, 4, 4]}>
                           <LabelList dataKey="nlc" position="center" className="fill-white font-bold text-[10px]" formatter={(v: number) => v > 0 ? v.toFixed(0) : ''} />
                        </Bar>
                        <Bar dataKey="onInv" stackId="system" name="On Invoice %" fill="#8b5cf6" radius={[4, 4, 0, 0]}>
                           <LabelList dataKey="onInv" position="center" className="fill-white font-bold text-[10px]" formatter={(v: number) => v > 0 ? v.toFixed(0) : ''} />
                        </Bar>

                        <Bar dataKey="target" stackId="target" name="User Target" fill={auditResult.status === 'MATCH' ? '#388e3c' : '#ff9f00'} radius={[4, 4, 4, 4]}>
                             <LabelList dataKey="target" position="top" className="fill-gray-600 font-bold text-xs" formatter={(v: number) => v.toFixed(2)} />
                        </Bar>

                        {auditResult.status === 'MISMATCH' && (
                             <ReferenceLine 
                                y={auditResult.targetTotal} 
                                stroke="#ff9f00" 
                                strokeDasharray="3 3" 
                             />
                        )}
                    </BarChart>
                </ResponsiveContainer>
              </div>
            ) : (
              <div className="h-full flex flex-col items-center justify-center text-gray-400">
                <BarChart3 className="w-16 h-16 mb-4 opacity-20" />
                <p>Run analysis to view chart</p>
              </div>
            )}
          </div>
        </div>
      )}

      {activeTab === 'APPROVALS' && (
        <div className="space-y-4">
          {requests.length === 0 ? (
            <div className="text-center py-20 bg-white rounded-lg border border-gray-200">
              <Check className="w-12 h-12 mx-auto mb-3 text-green-500 opacity-50" />
              <p className="text-gray-500 font-medium">No pending approvals.</p>
            </div>
          ) : (
            requests.map(req => (
              <div key={req.id} className="fk-card p-5 flex flex-col md:flex-row justify-between items-start md:items-center gap-4 border-l-4 border-l-fkYellow">
                <div>
                  <div className="flex items-center gap-2 mb-2">
                    <span className="bg-yellow-100 text-yellow-800 text-xs px-2 py-0.5 rounded font-bold">ACTION REQUIRED</span>
                    <h4 className="font-bold text-gray-800 text-lg">{req.payload.title} <span className="text-gray-400 font-normal">({req.payload.fsn})</span></h4>
                  </div>
                  <div className="text-sm text-gray-500 grid grid-cols-2 md:grid-cols-4 gap-x-8 gap-y-1 mb-2">
                    <span>City: <b className="text-gray-800">{req.payload.city}</b></span>
                    <span>Type: <b className="text-gray-800">{req.payload.type}</b></span>
                    <span>New Value: <b className="text-fkBlue">{req.payload.value}</b></span>
                    <span>By: {req.requestedBy}</span>
                  </div>
                  <div className="text-xs flex gap-4 text-gray-400">
                      <span className="flex items-center gap-1"><Layers className="w-3 h-3"/> {req.payload.vertical || 'N/A'}</span>
                      <span className="flex items-center gap-1"><UserIcon className="w-3 h-3"/> {req.payload.kam || 'N/A'}</span>
                  </div>
                  {req.reason && (
                      <div className="mt-2 bg-red-50 text-red-600 text-xs px-2 py-1 rounded inline-block font-semibold">
                          Reason: {req.reason}
                      </div>
                  )}
                </div>
                <div className="flex gap-2 w-full md:w-auto">
                  <button 
                    onClick={() => handleRequestAction(req.id, 'REJECTED')}
                    className="flex-1 md:flex-none px-4 py-2 rounded bg-gray-100 hover:bg-gray-200 text-gray-700 text-sm font-medium transition-colors"
                  >
                    Reject
                  </button>
                  <button 
                    onClick={() => handleRequestAction(req.id, 'APPROVED')}
                    className="flex-1 md:flex-none px-4 py-2 rounded bg-fkGreen hover:bg-green-700 text-white font-bold text-sm shadow transition-colors"
                  >
                    Approve
                  </button>
                </div>
              </div>
            ))
          )}
        </div>
      )}

      {activeTab === 'CLOSURE' && (
        <div className="space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                {/* Export Section */}
                <div className="fk-card p-6 space-y-4">
                    <div className="flex items-center gap-3 mb-2">
                        <div className="bg-blue-50 p-3 rounded-lg">
                            <FileDown className="w-6 h-6 text-fkBlue" />
                        </div>
                        <div>
                            <h3 className="text-lg font-bold text-gray-800">Export Data</h3>
                            <p className="text-sm text-gray-500">Download data for records and auditing.</p>
                        </div>
                    </div>

                    <div className="pt-4 space-y-4 border-t border-gray-100">
                        <div>
                            <label className="block text-xs font-bold text-gray-500 mb-2 flex items-center gap-2 uppercase">
                                <Calendar className="w-3 h-3" /> Select Month
                            </label>
                            <input 
                                type="month"
                                className="w-full bg-white border border-gray-300 rounded p-2 text-gray-800"
                                value={selectedMonth}
                                onChange={(e) => setSelectedMonth(e.target.value)}
                            />
                        </div>
                        <div className="flex flex-col gap-3">
                            <button 
                                onClick={() => handleExport('MONTH')}
                                disabled={exportLoading}
                                className="w-full py-2 bg-fkBlue hover:bg-blue-600 rounded text-white text-sm font-bold shadow-sm transition-colors"
                            >
                                {exportLoading ? 'Generating CSV...' : `Export ${selectedMonth} Data`}
                            </button>
                            <button 
                                onClick={() => handleExport('FULL')}
                                disabled={exportLoading}
                                className="w-full py-2 border border-gray-300 hover:bg-gray-50 rounded text-gray-600 text-sm font-medium transition-colors"
                            >
                                Export Full Database
                            </button>
                        </div>
                    </div>
                </div>

                {/* Clear Section */}
                <div className="fk-card p-6 space-y-4 border-red-100 bg-red-50/30">
                    <div className="flex items-center gap-3 mb-2">
                        <div className="bg-red-100 p-3 rounded-lg">
                            <Database className="w-6 h-6 text-red-600" />
                        </div>
                        <div>
                            <h3 className="text-lg font-bold text-red-600">System Reset</h3>
                            <p className="text-sm text-gray-500">Clear database for new operational cycle.</p>
                        </div>
                    </div>

                    <div className="pt-4 space-y-4 border-t border-red-100">
                        <div className="bg-red-50 border border-red-100 p-4 rounded text-sm text-red-700">
                            <p className="flex items-start gap-2">
                                <AlertCircle className="w-5 h-5 flex-shrink-0" />
                                <span>
                                    <strong>Warning:</strong> This deletes ALL active records. Export data first.
                                </span>
                            </p>
                        </div>

                        <button 
                            onClick={handleClearDB}
                            disabled={loading}
                            className="w-full py-3 bg-red-600 hover:bg-red-700 rounded text-white font-bold shadow-md flex items-center justify-center gap-2 transition-all"
                        >
                            {loading ? 'Clearing...' : <><Trash2 className="w-4 h-4" /> Clear Database</>}
                        </button>
                    </div>
                </div>
            </div>

            {/* Archive Viewer */}
            <div className="fk-card p-6 space-y-4">
                 <div className="flex items-center justify-between">
                     <h3 className="text-lg font-bold text-gray-800 flex items-center gap-2">
                        <Archive className="w-5 h-5 text-gray-500" /> Archived Records (Bin)
                     </h3>
                     <button onClick={toggleArchive} className="flex items-center gap-2 text-sm text-fkBlue hover:underline transition-colors font-medium">
                        {showArchive ? 'Hide Archive' : 'View Deleted Records'}
                        <Clock className="w-3 h-3" />
                     </button>
                 </div>

                 {showArchive && (
                     <div className="overflow-auto max-h-80 border border-gray-200 rounded-lg animate-in fade-in">
                        <table className="w-full text-left text-xs text-gray-600">
                            <thead className="bg-gray-50 sticky top-0 font-bold text-gray-700 border-b border-gray-200">
                                <tr>
                                    <th className="p-3">Deleted At</th>
                                    <th className="p-3">Deleted By</th>
                                    <th className="p-3">FSN</th>
                                    <th className="p-3">City</th>
                                    <th className="p-3">Reason</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-gray-100 bg-white">
                                {archiveData.map((r, i) => (
                                    <tr key={i} className="hover:bg-gray-50">
                                        <td className="p-3 font-mono text-gray-500">{new Date(r.deletedAt).toLocaleString()}</td>
                                        <td className="p-3">{r.deletedBy}</td>
                                        <td className="p-3 font-medium">{r.fsn}</td>
                                        <td className="p-3">{r.city}</td>
                                        <td className="p-3 text-fkYellow font-medium">{r.note || 'Manual Delete/Override'}</td>
                                    </tr>
                                ))}
                                {archiveData.length === 0 && <tr><td colSpan={5} className="p-6 text-center italic text-gray-400">Bin is empty</td></tr>}
                            </tbody>
                        </table>
                     </div>
                 )}
            </div>
        </div>
      )}
    </div>
  );
};

export enum Role {
  MAKER = 'MAKER',
  CHECKER = 'CHECKER',
  ADMIN = 'ADMIN'
}

export enum CommercialType {
  MARGIN_PERCENT = 'Margin %',
  NLC_VALUE = 'NLC Value',
  NLC_PERCENT = 'NLC %',
  ON_INVOICE = 'On Invoice %',
  OFF_INVOICE = 'Off Invoice %'
}

export interface User {
  id: string;
  employeeId: string;
  name: string;
  role: Role;
  pin?: string; // Encrypted in real app
}

export interface CommercialRecord {
  id: string;
  fsn: string;
  brand: string;
  title: string;
  city: string;
  vertical: string;
  kam: string;
  startDate: string;
  endDate: string;
  type: CommercialType;
  value: number;
  lastUpdatedBy: string;
  lastUpdatedAt: number;
}

export interface DuplicateRequest {
  id: string;
  originalRecordId: string | null; // Null if it's a new conflict without ID yet, but usually maps to existing
  payload: CommercialRecord;
  requestedBy: string;
  requestedAt: number;
  status: 'PENDING' | 'APPROVED' | 'REJECTED';
  reason?: string; // Reason for approval (Conflict, High Margin, etc.)
}

export const CITIES = [
  'PAN-INDIA', 'BLR', 'DEL', 'MUM', 'KOL', 'CHE', 'HYD', 'PUN'
];

export const COMMERCIAL_TYPES = [
  CommercialType.MARGIN_PERCENT,
  CommercialType.NLC_VALUE,
  CommercialType.NLC_PERCENT,
  CommercialType.ON_INVOICE,
  CommercialType.OFF_INVOICE
];

import React, { useState, useEffect } from 'react';
import { CommercialRecord, CommercialType, DuplicateRequest, User, COMMERCIAL_TYPES } from '../types';
import { db } from '../services/db';
import { Plus, Upload, Save, AlertTriangle, FileText, X, Download, Check, Trash2, ArrowUpRight, ShieldAlert, User as UserIcon, Layers } from 'lucide-react';
import Papa from 'papaparse';

interface MakerProps {
  user: User;
}

export const MakerWorkspace: React.FC<MakerProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<'MANUAL' | 'BULK'>('MANUAL');

  // Dynamic Cities
  const [cities, setCities] = useState<string[]>([]);
  const [isAddingCity, setIsAddingCity] = useState(false);
  const [newCityCode, setNewCityCode] = useState('');

  // Manual Form State
  const [formData, setFormData] = useState<Partial<CommercialRecord>>({
    city: 'PAN-INDIA',
    type: CommercialType.MARGIN_PERCENT,
    startDate: new Date().toISOString().split('T')[0],
    endDate: new Date(new Date().setMonth(new Date().getMonth() + 3)).toISOString().split('T')[0],
    vertical: '',
    kam: ''
  });

  // Real-time Validation State
  const [instantConflict, setInstantConflict] = useState<boolean>(false);
  const [highMarginAlert, setHighMarginAlert] = useState<boolean>(false);

  // Bulk State
  const [bulkType, setBulkType] = useState<CommercialType>(CommercialType.MARGIN_PERCENT);

  const [loading, setLoading] = useState(false);
  const [notification, setNotification] = useState<{msg: string, type: 'success' | 'error' | 'warning' | null}>({ msg: '', type: null });

  // Initialize Data
  useEffect(() => {
    const init = async () => {
      // 1. Load Draft
      const draft = localStorage.getItem('mm_draft_form');
      let draftData = {};
      if (draft) {
        draftData = JSON.parse(draft);
        setFormData(draftData);
      }

      // 2. Load Cities and Validate
      const c = await db.getCities();
      setCities(c);

      // Validate the city from draft or current state
      const currentCity = (draftData as any).city || formData.city || 'PAN-INDIA';
      if (!c.includes(currentCity)) {
         setFormData(prev => ({ ...prev, city: c[0] || 'PAN-INDIA' }));
      }
    };

    init();
  }, []);

  // Save draft & Real-time Check
  useEffect(() => {
    localStorage.setItem('mm_draft_form', JSON.stringify(formData));

    // High Margin Check
    if (formData.type === CommercialType.MARGIN_PERCENT && (formData.value || 0) > 60) {
        setHighMarginAlert(true);
    } else {
        setHighMarginAlert(false);
    }

    // Debounce the conflict check
    const timeoutId = setTimeout(async () => {
        if(formData.fsn && formData.fsn.length === 16 && formData.city && formData.type && formData.startDate && formData.endDate) {
            const records = await db.getRecords();
            const conflict = checkForConflict(records, formData as CommercialRecord);
            setInstantConflict(conflict);
        } else {
            setInstantConflict(false);
        }
    }, 500);

    return () => clearTimeout(timeoutId);
  }, [formData]);

  const checkForConflict = (existingRecords: CommercialRecord[], input: CommercialRecord): boolean => {
      return existingRecords.some(r => {
        // 1. Match FSN & Type
        if (r.fsn !== input.fsn) return false;
        if (r.type !== input.type) return false;

        // 2. Check Date Overlap (StartA <= EndB) and (EndA >= StartB)
        const overlap = (input.startDate <= r.endDate) && (input.endDate >= r.startDate);
        if (!overlap) return false;

        // 3. Check City Logic (Exact Match OR PAN-INDIA Collision)
        // If input is PAN-INDIA, it conflicts with ANY city record for that FSN
        // If existing record is PAN-INDIA, it conflicts with ANY input city
        if (input.city === 'PAN-INDIA' || r.city === 'PAN-INDIA') return true; 
        if (input.city === r.city) return true;

        return false;
      });
  };

  const refreshCities = async () => {
    const c = await db.getCities();
    setCities(c);
    return c;
  };

  const handleAddNewCity = async () => {
    if (!newCityCode) return;
    const code = newCityCode.toUpperCase().trim();
    if (code !== 'PAN-INDIA' && code.length > 3) {
       setNotification({ msg: 'City code must be 3 characters or less.', type: 'error' });
       return;
    }
    const cleanCode = code.replace(/[^A-Z0-9]/g, '');
    if (!cleanCode) return;
    if (cities.includes(cleanCode)) {
       setNotification({ msg: `City ${cleanCode} already exists.`, type: 'warning' });
       return;
    }
    if (cleanCode) {
       await db.addCity(cleanCode);
       await refreshCities();
       setFormData(prev => ({...prev, city: cleanCode}));
       setNewCityCode('');
       setIsAddingCity(false);
       setNotification({ msg: `City ${cleanCode} added.`, type: 'success' });
    }
  };

  const handleDeleteCity = async () => {
    const cityToDelete = formData.city;
    if (!cityToDelete || cityToDelete === 'PAN-INDIA') {
        setNotification({ msg: 'Cannot delete default PAN-INDIA city.', type: 'error' });
        return;
    }
    if (window.confirm(`Delete city code "${cityToDelete}"?`)) {
        try {
            await db.deleteCity(cityToDelete);
            const updatedCities = await refreshCities();
            setFormData(prev => ({ ...prev, city: updatedCities[0] || 'PAN-INDIA' }));
            setNotification({ msg: `City ${cityToDelete} removed.`, type: 'success' });
        } catch (err) {
            setNotification({ msg: 'Failed to delete city.', type: 'error' });
        }
    }
  };

  const handleManualSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setNotification({ msg: '', type: null });

    if (!formData.fsn || !formData.value || !formData.brand || !formData.title || !formData.vertical || !formData.kam) {
        setNotification({ msg: 'Please fill all fields', type: 'error' });
        return;
    }

    // Strict FSN Length Check
    if (formData.fsn.length !== 16) {
        setNotification({ msg: 'FSN must be exactly 16 characters.', type: 'error' });
        return;
    }

    // Validate Caps
    const isPercentage = formData.type === CommercialType.MARGIN_PERCENT || 
                         formData.type === CommercialType.NLC_PERCENT || 
                         formData.type === CommercialType.ON_INVOICE || 
                         formData.type === CommercialType.OFF_INVOICE;

    if (isPercentage && formData.value! > 100) {
        setNotification({ msg: `${formData.type} cannot exceed 100%`, type: 'error' });
        return;
    }

    if (formData.type !== CommercialType.MARGIN_PERCENT && formData.endDate! < formData.startDate!) {
        setNotification({ msg: 'End Date cannot be before Start Date', type: 'error' });
        return;
    }

    setLoading(true);

    try {
      const records = await db.getRecords();

      const isConflict = checkForConflict(records, formData as CommercialRecord);
      const isHighMargin = formData.type === CommercialType.MARGIN_PERCENT && (formData.value || 0) > 60;

      const newRecord: CommercialRecord = {
        id: `rec_${Date.now()}`,
        ...formData as CommercialRecord,
        value: Number(formData.value),
        lastUpdatedBy: user.name,
        lastUpdatedAt: Date.now()
      };

      if (isConflict || isHighMargin) {
        let reason = '';
        if (isConflict) reason = 'Duplicate/Overlap Conflict Detected';
        if (isHighMargin) reason = reason ? reason + ' & High Margin (>60%)' : 'High Margin (>60%)';

        const req: DuplicateRequest = {
          id: `req_${Date.now()}`,
          originalRecordId: null,
          payload: newRecord,
          requestedBy: user.name,
          requestedAt: Date.now(),
          status: 'PENDING',
          reason: reason
        };
        await db.createDuplicateRequest(req);
        setNotification({ msg: `Request sent to Checker: ${reason}`, type: 'warning' });
      } else {
        await db.addRecords([newRecord]);
        setNotification({ msg: 'Record saved successfully.', type: 'success' });
        setFormData(prev => ({ 
            ...prev, 
            fsn: '', 
            value: 0,
            // Reset dates to defaults
            startDate: new Date().toISOString().split('T')[0],
            endDate: new Date(new Date().setMonth(new Date().getMonth() + 3)).toISOString().split('T')[0]
        }));
      }
    } catch (err) {
      setNotification({ msg: 'Failed to save record.', type: 'error' });
    } finally {
      setLoading(false);
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    Papa.parse(file, {
      header: true,
      skipEmptyLines: true,
      complete: async (results) => {
        setLoading(true);
        const newRecords: CommercialRecord[] = [];
        const requests: DuplicateRequest[] = [];
        const existingRecords = await db.getRecords();

        let skipped = 0;
        let missingKam = 0;

        results.data.forEach((row: any) => {
           if(!row.FSN) return;

           // Validation in Loop
           if(row.FSN.length !== 16) {
               skipped++;
               return;
           }

           // Check KAM presence
           if (!row.KAM || !row.KAM.trim()) {
               missingKam++;
               return; // Skip if KAM is missing
           }

           const cityKeys = Object.keys(row).filter(k => cities.includes(k) || k === 'Value');

           cityKeys.forEach(cityKey => {
             const city = cityKey === 'Value' ? 'PAN-INDIA' : cityKey;
             let val = parseFloat(row[cityKey]);
             if (isNaN(val)) return;

             const isPercentage = bulkType === CommercialType.MARGIN_PERCENT || 
                                  bulkType === CommercialType.NLC_PERCENT || 
                                  bulkType === CommercialType.ON_INVOICE || 
                                  bulkType === CommercialType.OFF_INVOICE;

             if (isPercentage && val > 100) val = 100; // Cap at 100
             if (isPercentage && val <= 1 && val > 0) val = val * 100; // Handle 0.5 as 50% if common error

             const rec: CommercialRecord = {
               id: `rec_${Math.random().toString(36).substr(2,9)}`,
               fsn: row.FSN,
               brand: row.Brand || 'Unknown',
               title: row.Title || 'Bulk Upload Item',
               vertical: row.Vertical || 'Unknown',
               kam: row.KAM,
               city: city,
               startDate: row.StartDate,
               endDate: row.EndDate,
               type: bulkType,
               value: val,
               lastUpdatedBy: user.name,
               lastUpdatedAt: Date.now()
             };

             const isConflict = checkForConflict(existingRecords, rec);
             const isHighMargin = bulkType === CommercialType.MARGIN_PERCENT && val > 60;

             if (isConflict || isHighMargin) {
               let reason = '';
               if (isConflict) reason = 'Conflict Detected';
               if (isHighMargin) reason = reason ? reason + ' & High Margin' : 'High Margin';

               const req: DuplicateRequest = {
                 id: `req_${Math.random().toString(36).substr(2,9)}`,
                 originalRecordId: null,
                 payload: rec,
                 requestedBy: user.name,
                 requestedAt: Date.now(),
                 status: 'PENDING',
                 reason: reason
               };
               requests.push(req);
             } else {
               newRecords.push(rec);
             }
           });
        });

        if (newRecords.length > 0) {
          await db.addRecords(newRecords);
        }

        if (requests.length > 0) {
           for (const req of requests) {
              await db.createDuplicateRequest(req);
           }
        }

        // Notification Logic
        let msg = '';
        let type: 'success' | 'warning' | 'error' = 'success';

        if (newRecords.length > 0) msg += `Successfully uploaded ${newRecords.length} records. `;
        if (requests.length > 0) {
            msg += `${requests.length} sent for approval (Conflict/High Margin). `;
            type = 'warning';
        }
        if (skipped > 0) {
            msg += `${skipped} skipped (Invalid FSN). `;
            type = 'warning';
        }
        if (missingKam > 0) {
            msg += `${missingKam} skipped (Missing KAM). `;
            type = 'warning';
        }

        if (newRecords.length === 0 && requests.length === 0 && (skipped > 0 || missingKam > 0)) {
            type = 'error';
        }

        setNotification({ msg, type });
        setLoading(false);
      }
    });
  };

  const downloadTemplate = () => {
    const headers = ['FSN', 'Brand', 'Title', 'Vertical', 'KAM', 'StartDate', 'EndDate', ...cities];
    const isNLC = bulkType === CommercialType.NLC_VALUE;
    const exampleVal = isNLC ? '50000' : '10';
    const dummyRows = [
        ['MOBEXAMPLE123456', 'BrandX', 'Sample Product 1', 'Mobiles', 'John Doe', '2024-01-01', '2024-03-31', ...cities.map(() => exampleVal)],
    ];
    const csvContent = [headers.join(','), ...dummyRows.map(row => row.join(','))].join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv' });
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `template_${bulkType.replace(/\s/g, '')}.csv`;
    a.click();
    window.URL.revokeObjectURL(url);
  };

  return (
    <div className="space-y-6 animate-in slide-in-from-bottom-4 duration-500 max-w-7xl mx-auto">
      <div className="flex justify-between items-center">
        <div>
           <h2 className="text-2xl font-bold text-gray-800">Maker Workspace</h2>
           <p className="text-sm text-gray-500">Manage commercials and offers</p>
        </div>
        <div className="flex bg-white rounded shadow-sm border border-gray-200 p-1">
          <button
            onClick={() => setActiveTab('MANUAL')}
            className={`px-4 py-2 rounded text-sm font-medium transition-all ${activeTab === 'MANUAL' ? 'bg-fkBlue text-white shadow' : 'text-gray-500 hover:text-gray-900'}`}
          >
            Manual Entry
          </button>
          <button
            onClick={() => setActiveTab('BULK')}
            className={`px-4 py-2 rounded text-sm font-medium transition-all ${activeTab === 'BULK' ? 'bg-fkBlue text-white shadow' : 'text-gray-500 hover:text-gray-900'}`}
          >
            Bulk Upload
          </button>
        </div>
      </div>

      {notification.msg && (
        <div className={`p-4 rounded border flex items-center gap-3 shadow-sm ${
          notification.type === 'error' ? 'bg-red-50 border-red-200 text-red-700' :
          notification.type === 'warning' ? 'bg-orange-50 border-orange-200 text-orange-800' :
          'bg-green-50 border-green-200 text-green-700'
        }`}>
          {notification.type === 'error' ? <AlertTriangle className="h-5 w-5"/> : <FileText className="h-5 w-5"/>}
          <span className="font-medium">{notification.msg}</span>
          <button onClick={() => setNotification({msg:'', type:null})} className="ml-auto hover:bg-white/50 rounded p-1"><X className="h-4 w-4"/></button>
        </div>
      )}

      {/* Alerts */}
      <div className="space-y-2">
          {instantConflict && activeTab === 'MANUAL' && (
            <div className="p-3 bg-red-50 border-l-4 border-red-500 rounded shadow-sm flex items-center gap-3 animate-in fade-in slide-in-from-top-2">
                <ShieldAlert className="text-red-500 w-6 h-6" />
                <div>
                    <p className="font-bold text-gray-800 text-sm">Conflict Detected!</p>
                    <p className="text-xs text-gray-600">Overlap with existing FSN+City/PAN-INDIA record. Saving triggers approval.</p>
                </div>
            </div>
          )}
          {highMarginAlert && activeTab === 'MANUAL' && (
            <div className="p-3 bg-yellow-50 border-l-4 border-fkYellow rounded shadow-sm flex items-center gap-3 animate-in fade-in slide-in-from-top-2">
                <AlertTriangle className="text-fkYellow w-6 h-6" />
                <div>
                    <p className="font-bold text-gray-800 text-sm">High Margin Alert!</p>
                    <p className="text-xs text-gray-600">Margin &gt; 60% requires checker approval.</p>
                </div>
            </div>
          )}
      </div>

      {activeTab === 'MANUAL' ? (
        <form onSubmit={handleManualSubmit} className="fk-card p-6 grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          <div className="col-span-1">
            <label className="block text-xs font-semibold text-gray-500 uppercase mb-1">FSN (Product ID) <span className="text-red-500">*</span></label>
            <div className="relative">
                <input 
                  className="w-full bg-white border border-gray-300 rounded p-2.5 text-gray-900 focus:border-fkBlue focus:ring-1 focus:ring-fkBlue outline-none transition-colors" 
                  value={formData.fsn || ''}
                  onChange={e => setFormData({...formData, fsn: e.target.value})}
                  placeholder="16 Characters Required"
                  maxLength={16}
                />
                <div className={`text-[10px] text-right mt-1 font-mono ${formData.fsn?.length === 16 ? 'text-green-600' : 'text-gray-400'}`}>
                    {formData.fsn?.length || 0}/16
                </div>
            </div>
          </div>
          <div className="col-span-1">
            <label className="block text-xs font-semibold text-gray-500 uppercase mb-1">Brand <span className="text-red-500">*</span></label>
            <input 
              className="w-full bg-white border border-gray-300 rounded p-2.5 text-gray-900 focus:border-fkBlue focus:ring-1 focus:ring-fkBlue outline-none transition-colors" 
              value={formData.brand || ''}
              onChange={e => setFormData({...formData, brand: e.target.value})}
              placeholder="e.g. Samsung"
            />
          </div>
          <div className="col-span-1">
            <label className="block text-xs font-semibold text-gray-500 uppercase mb-1">Title <span className="text-red-500">*</span></label>
            <input 
              className="w-full bg-white border border-gray-300 rounded p-2.5 text-gray-900 focus:border-fkBlue focus:ring-1 focus:ring-fkBlue outline-none transition-colors" 
              value={formData.title || ''}
              onChange={e => setFormData({...formData, title: e.target.value})}
              placeholder="Product Title"
            />
          </div>

          <div className="col-span-1">
            <label className="block text-xs font-semibold text-gray-500 uppercase mb-1 flex items-center gap-1"><Layers className="w-3 h-3"/> Vertical <span className="text-red-500">*</span></label>
            <input 
              className="w-full bg-white border border-gray-300 rounded p-2.5 text-gray-900 focus:border-fkBlue focus:ring-1 focus:ring-fkBlue outline-none transition-colors" 
              value={formData.vertical || ''}
              onChange={e => setFormData({...formData, vertical: e.target.value})}
              placeholder="e.g. Mobiles"
            />
          </div>

          <div className="col-span-1">
            <label className="block text-xs font-semibold text-gray-500 uppercase mb-1 flex items-center gap-1"><UserIcon className="w-3 h-3"/> KAM <span className="text-red-500">*</span></label>
            <input 
              className="w-full bg-white border border-gray-300 rounded p-2.5 text-gray-900 focus:border-fkBlue focus:ring-1 focus:ring-fkBlue outline-none transition-colors" 
              value={formData.kam || ''}
              onChange={e => setFormData({...formData, kam: e.target.value})}
              placeholder="Account Manager Name"
            />
          </div>

          <div className="col-span-1">
            <label className="block text-xs font-semibold text-gray-500 uppercase mb-1">City <span className="text-red-500">*</span></label>
            <div className="flex gap-2">
              {isAddingCity ? (
                <div className="flex-1 flex gap-1">
                   <input 
                     className="w-full bg-white border border-gray-300 rounded p-2.5 text-gray-900 uppercase"
                     placeholder="XXX"
                     autoFocus
                     value={newCityCode}
                     maxLength={3}
                     onChange={e => setNewCityCode(e.target.value)}
                   />
                   <button 
                     type="button" 
                     onClick={handleAddNewCity}
                     className="bg-fkGreen px-3 rounded text-white hover:bg-green-700"
                   >
                     <Check className="h-4 w-4" />
                   </button>
                   <button 
                     type="button" 
                     onClick={() => setIsAddingCity(false)}
                     className="bg-gray-200 px-3 rounded text-gray-700 hover:bg-gray-300"
                   >
                     <X className="h-4 w-4" />
                   </button>
                </div>
              ) : (
                <div className="flex-1 flex gap-2">
                  <select 
                    className="w-full bg-white border border-gray-300 rounded p-2.5 text-gray-900 focus:border-fkBlue focus:ring-1 focus:ring-fkBlue outline-none"
                    value={formData.city}
                    onChange={e => setFormData({...formData, city: e.target.value})}
                  >
                    {cities.map(c => <option key={c} value={c}>{c}</option>)}
                  </select>

                  <button 
                    type="button" 
                    onClick={() => setIsAddingCity(true)}
                    className="px-3 bg-gray-100 hover:bg-gray-200 rounded border border-gray-300 text-gray-600 transition-colors"
                    title="Add New City"
                  >
                    <Plus className="h-4 w-4" />
                  </button>

                  <button 
                    type="button"
                    onClick={handleDeleteCity}
                    disabled={formData.city === 'PAN-INDIA'}
                    className={`px-3 rounded border transition-colors ${formData.city === 'PAN-INDIA' ? 'bg-gray-100 border-gray-200 text-gray-400 cursor-not-allowed' : 'bg-red-50 border-red-200 text-red-600 hover:bg-red-100'}`}
                  >
                    <Trash2 className="h-4 w-4" />
                  </button>
                </div>
              )}
            </div>
          </div>

          <div className="col-span-1">
            <label className="block text-xs font-semibold text-gray-500 uppercase mb-1">Type <span className="text-red-500">*</span></label>
            <select 
              className="w-full bg-white border border-gray-300 rounded p-2.5 text-gray-900 focus:border-fkBlue focus:ring-1 focus:ring-fkBlue outline-none"
              value={formData.type}
              onChange={e => setFormData({...formData, type: e.target.value as CommercialType})}
            >
              <option value={CommercialType.MARGIN_PERCENT}>Margin %</option>
              <option value={CommercialType.NLC_VALUE}>NLC Value (Amount)</option>
              <option value={CommercialType.NLC_PERCENT}>NLC %</option>
              <option value={CommercialType.ON_INVOICE}>On Invoice %</option>
              <option value={CommercialType.OFF_INVOICE}>Off Invoice %</option>
            </select>
          </div>

          <div className="col-span-1">
            <label className="block text-xs font-semibold text-gray-500 uppercase mb-1">Value <span className="text-red-500">*</span></label>
            <input 
              type="number"
              className="w-full bg-white border border-gray-300 rounded p-2.5 text-gray-900 focus:border-fkBlue focus:ring-1 focus:ring-fkBlue outline-none font-mono" 
              value={formData.value || ''}
              onChange={e => setFormData({...formData, value: parseFloat(e.target.value)})}
              placeholder="0.00"
            />
            {/* Helper Text for Caps */}
            {formData.type?.includes('%') && (
                <p className="text-[10px] text-gray-400 mt-1">Capped at 100%</p>
            )}
          </div>

          {formData.type !== CommercialType.MARGIN_PERCENT && (
            <>
              <div className="col-span-1">
                <label className="block text-xs font-semibold text-gray-500 uppercase mb-1">Start Date</label>
                <input 
                  type="date"
                  className="w-full bg-white border border-gray-300 rounded p-2.5 text-gray-900 focus:border-fkBlue outline-none" 
                  value={formData.startDate}
                  onChange={e => setFormData({...formData, startDate: e.target.value})}
                />
              </div>
              <div className="col-span-1">
                <label className="block text-xs font-semibold text-gray-500 uppercase mb-1">End Date</label>
                <input 
                  type="date"
                  className="w-full bg-white border border-gray-300 rounded p-2.5 text-gray-900 focus:border-fkBlue outline-none" 
                  value={formData.endDate}
                  onChange={e => setFormData({...formData, endDate: e.target.value})}
                />
              </div>
            </>
          )}

          <div className="col-span-full flex justify-end pt-6 border-t border-gray-100">
             <button
               type="submit"
               disabled={loading}
               className="bg-fkYellow hover:bg-yellow-500 text-white font-bold py-2.5 px-8 rounded shadow-md hover:shadow-lg transition-all flex items-center gap-2"
             >
               {loading ? <span className="animate-spin">⌛</span> : <Save className="h-5 w-5" />}
               Save Record
             </button>
          </div>
        </form>
      ) : (
        <div className="space-y-6">
          <div className="bg-white p-6 rounded-lg border border-gray-200 shadow-sm">
             <label className="block text-xs font-bold text-gray-500 mb-4 uppercase tracking-wider">Select Upload Type</label>
             <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
               {COMMERCIAL_TYPES.map(type => (
                 <button
                   key={type}
                   onClick={() => setBulkType(type)}
                   className={`p-4 rounded border text-sm font-semibold transition-all ${
                     bulkType === type 
                     ? 'bg-fkBlue text-white border-fkBlue shadow-md' 
                     : 'bg-gray-50 text-gray-600 border-gray-200 hover:bg-white hover:border-gray-300 hover:shadow-sm'
                   }`}
                 >
                   {type}
                 </button>
               ))}
             </div>
          </div>

          <div className="flex justify-end">
            <button 
              onClick={downloadTemplate}
              className="flex items-center gap-2 px-4 py-2 bg-white hover:bg-gray-50 text-fkBlue font-medium rounded border border-gray-300 shadow-sm transition-colors text-sm"
            >
              <Download className="h-4 w-4" /> 
              Download Template
            </button>
          </div>

          <div className="fk-card border-dashed border-2 border-gray-300 p-12 flex flex-col items-center justify-center text-center hover:border-fkBlue hover:bg-blue-50/30 transition-all group cursor-pointer relative">
            <input 
              type="file" 
              accept=".csv"
              onChange={handleFileUpload}
              key={bulkType}
              className="absolute inset-0 w-full h-full opacity-0 cursor-pointer"
            />
            <div className="bg-blue-50 p-5 rounded-full mb-4 group-hover:scale-110 transition-transform">
               <Upload className="h-10 w-10 text-fkBlue" />
            </div>
            <h3 className="text-xl font-bold text-gray-800">Upload {bulkType} CSV</h3>
            <p className="text-gray-500 mt-2">
              Drag and drop or click to upload
            </p>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { CommercialRecord, CommercialType, DuplicateRequest, User, COMMERCIAL_TYPES } from '../types';
import { db } from '../services/db';
import { Plus, Upload, Save, AlertTriangle, FileText, X, Download, Check, Trash2, ArrowUpRight, ShieldAlert, User as UserIcon, Layers } from 'lucide-react';
import Papa from 'papaparse';

interface MakerProps {
  user: User;
}

export const MakerWorkspace: React.FC<MakerProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<'MANUAL' | 'BULK'>('MANUAL');

  // Dynamic Cities
  const [cities, setCities] = useState<string[]>([]);
  const [isAddingCity, setIsAddingCity] = useState(false);
  const [newCityCode, setNewCityCode] = useState('');

  // Manual Form State
  const [formData, setFormData] = useState<Partial<CommercialRecord>>({
    city: 'PAN-INDIA',
    type: CommercialType.MARGIN_PERCENT,
    startDate: new Date().toISOString().split('T')[0],
    endDate: new Date(new Date().setMonth(new Date().getMonth() + 3)).toISOString().split('T')[0],
    vertical: '',
    kam: ''
  });

  // Real-time Validation State
  const [instantConflict, setInstantConflict] = useState<boolean>(false);
  const [highMarginAlert, setHighMarginAlert] = useState<boolean>(false);

  // Bulk State
  const [bulkType, setBulkType] = useState<CommercialType>(CommercialType.MARGIN_PERCENT);

  const [loading, setLoading] = useState(false);
  const [notification, setNotification] = useState<{msg: string, type: 'success' | 'error' | 'warning' | null}>({ msg: '', type: null });

  // Initialize Data
  useEffect(() => {
    const init = async () => {
      // 1. Load Draft
      const draft = localStorage.getItem('mm_draft_form');
      let draftData = {};
      if (draft) {
        draftData = JSON.parse(draft);
        setFormData(draftData);
      }

      // 2. Load Cities and Validate
      const c = await db.getCities();
      setCities(c);

      // Validate the city from draft or current state
      const currentCity = (draftData as any).city || formData.city || 'PAN-INDIA';
      if (!c.includes(currentCity)) {
         setFormData(prev => ({ ...prev, city: c[0] || 'PAN-INDIA' }));
      }
    };

    init();
  }, []);

  // Save draft & Real-time Check
  useEffect(() => {
    localStorage.setItem('mm_draft_form', JSON.stringify(formData));

    // High Margin Check
    if (formData.type === CommercialType.MARGIN_PERCENT && (formData.value || 0) > 60) {
        setHighMarginAlert(true);
    } else {
        setHighMarginAlert(false);
    }

    // Debounce the conflict check
    const timeoutId = setTimeout(async () => {
        if(formData.fsn && formData.fsn.length === 16 && formData.city && formData.type && formData.startDate && formData.endDate) {
            const records = await db.getRecords();
            const conflict = checkForConflict(records, formData as CommercialRecord);
            setInstantConflict(conflict);
        } else {
            setInstantConflict(false);
        }
    }, 500);

    return () => clearTimeout(timeoutId);
  }, [formData]);

  const checkForConflict = (existingRecords: CommercialRecord[], input: CommercialRecord): boolean => {
      return existingRecords.some(r => {
        // 1. Match FSN & Type
        if (r.fsn !== input.fsn) return false;
        if (r.type !== input.type) return false;

        // 2. Check Date Overlap (StartA <= EndB) and (EndA >= StartB)
        const overlap = (input.startDate <= r.endDate) && (input.endDate >= r.startDate);
        if (!overlap) return false;

        // 3. Check City Logic (Exact Match OR PAN-INDIA Collision)
        // If input is PAN-INDIA, it conflicts with ANY city record for that FSN
        // If existing record is PAN-INDIA, it conflicts with ANY input city
        if (input.city === 'PAN-INDIA' || r.city === 'PAN-INDIA') return true; 
        if (input.city === r.city) return true;

        return false;
      });
  };

  const refreshCities = async () => {
    const c = await db.getCities();
    setCities(c);
    return c;
  };

  const handleAddNewCity = async () => {
    if (!newCityCode) return;
    const code = newCityCode.toUpperCase().trim();
    if (code !== 'PAN-INDIA' && code.length > 3) {
       setNotification({ msg: 'City code must be 3 characters or less.', type: 'error' });
       return;
    }
    const cleanCode = code.replace(/[^A-Z0-9]/g, '');
    if (!cleanCode) return;
    if (cities.includes(cleanCode)) {
       setNotification({ msg: `City ${cleanCode} already exists.`, type: 'warning' });
       return;
    }
    if (cleanCode) {
       await db.addCity(cleanCode);
       await refreshCities();
       setFormData(prev => ({...prev, city: cleanCode}));
       setNewCityCode('');
       setIsAddingCity(false);
       setNotification({ msg: `City ${cleanCode} added.`, type: 'success' });
    }
  };

  const handleDeleteCity = async () => {
    const cityToDelete = formData.city;
    if (!cityToDelete || cityToDelete === 'PAN-INDIA') {
        setNotification({ msg: 'Cannot delete default PAN-INDIA city.', type: 'error' });
        return;
    }
    if (window.confirm(`Delete city code "${cityToDelete}"?`)) {
        try {
            await db.deleteCity(cityToDelete);
            const updatedCities = await refreshCities();
            setFormData(prev => ({ ...prev, city: updatedCities[0] || 'PAN-INDIA' }));
            setNotification({ msg: `City ${cityToDelete} removed.`, type: 'success' });
        } catch (err) {
            setNotification({ msg: 'Failed to delete city.', type: 'error' });
        }
    }
  };

  const handleManualSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setNotification({ msg: '', type: null });

    if (!formData.fsn || !formData.value || !formData.brand || !formData.title || !formData.vertical || !formData.kam) {
        setNotification({ msg: 'Please fill all fields', type: 'error' });
        return;
    }

    // Strict FSN Length Check
    if (formData.fsn.length !== 16) {
        setNotification({ msg: 'FSN must be exactly 16 characters.', type: 'error' });
        return;
    }

    // Validate Caps
    const isPercentage = formData.type === CommercialType.MARGIN_PERCENT || 
                         formData.type === CommercialType.NLC_PERCENT || 
                         formData.type === CommercialType.ON_INVOICE || 
                         formData.type === CommercialType.OFF_INVOICE;

    if (isPercentage && formData.value! > 100) {
        setNotification({ msg: `${formData.type} cannot exceed 100%`, type: 'error' });
        return;
    }

    if (formData.type !== CommercialType.MARGIN_PERCENT && formData.endDate! < formData.startDate!) {
        setNotification({ msg: 'End Date cannot be before Start Date', type: 'error' });
        return;
    }

    setLoading(true);

    try {
      const records = await db.getRecords();

      const isConflict = checkForConflict(records, formData as CommercialRecord);
      const isHighMargin = formData.type === CommercialType.MARGIN_PERCENT && (formData.value || 0) > 60;

      const newRecord: CommercialRecord = {
        id: `rec_${Date.now()}`,
        ...formData as CommercialRecord,
        value: Number(formData.value),
        lastUpdatedBy: user.name,
        lastUpdatedAt: Date.now()
      };

      if (isConflict || isHighMargin) {
        let reason = '';
        if (isConflict) reason = 'Duplicate/Overlap Conflict Detected';
        if (isHighMargin) reason = reason ? reason + ' & High Margin (>60%)' : 'High Margin (>60%)';

        const req: DuplicateRequest = {
          id: `req_${Date.now()}`,
          originalRecordId: null,
          payload: newRecord,
          requestedBy: user.name,
          requestedAt: Date.now(),
          status: 'PENDING',
          reason: reason
        };
        await db.createDuplicateRequest(req);
        setNotification({ msg: `Request sent to Checker: ${reason}`, type: 'warning' });
      } else {
        await db.addRecords([newRecord]);
        setNotification({ msg: 'Record saved successfully.', type: 'success' });
        setFormData(prev => ({ 
            ...prev, 
            fsn: '', 
            value: 0,
            // Reset dates to defaults
            startDate: new Date().toISOString().split('T')[0],
            endDate: new Date(new Date().setMonth(new Date().getMonth() + 3)).toISOString().split('T')[0]
        }));
      }
    } catch (err) {
      setNotification({ msg: 'Failed to save record.', type: 'error' });
    } finally {
      setLoading(false);
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    Papa.parse(file, {
      header: true,
      skipEmptyLines: true,
      complete: async (results) => {
        setLoading(true);

        // 1. Validate Headers
        const headers = results.meta.fields || [];
        // Flexible check for KAM (case insensitive)
        const kamHeader = headers.find(h => h.toUpperCase() === 'KAM');

        if (!kamHeader) {
            setNotification({ msg: "Upload Failed: 'KAM' column is missing in the CSV file.", type: 'error' });
            setLoading(false);
            e.target.value = ''; // Reset input
            return;
        }

        const newRecords: CommercialRecord[] = [];
        const requests: DuplicateRequest[] = [];
        const existingRecords = await db.getRecords();

        let skipped = 0;
        let missingKam = 0;

        results.data.forEach((row: any) => {
           if(!row.FSN) return;

           // Validation in Loop
           if(row.FSN.length !== 16) {
               skipped++;
               return;
           }

           // Check KAM presence using the identified header key
           const kamValue = row[kamHeader] || row['KAM']; // Fallback
           if (!kamValue || !kamValue.trim()) {
               missingKam++;
               return; // Skip if KAM is missing
           }

           const cityKeys = Object.keys(row).filter(k => cities.includes(k) || k === 'Value');

           cityKeys.forEach(cityKey => {
             const city = cityKey === 'Value' ? 'PAN-INDIA' : cityKey;
             let val = parseFloat(row[cityKey]);
             if (isNaN(val)) return;

             const isPercentage = bulkType === CommercialType.MARGIN_PERCENT || 
                                  bulkType === CommercialType.NLC_PERCENT || 
                                  bulkType === CommercialType.ON_INVOICE || 
                                  bulkType === CommercialType.OFF_INVOICE;

             if (isPercentage && val > 100) val = 100; // Cap at 100
             if (isPercentage && val <= 1 && val > 0) val = val * 100; // Handle 0.5 as 50% if common error

             const rec: CommercialRecord = {
               id: `rec_${Math.random().toString(36).substr(2,9)}`,
               fsn: row.FSN,
               brand: row.Brand || 'Unknown',
               title: row.Title || 'Bulk Upload Item',
               vertical: row.Vertical || 'Unknown',
               kam: kamValue,
               city: city,
               startDate: row.StartDate,
               endDate: row.EndDate,
               type: bulkType,
               value: val,
               lastUpdatedBy: user.name,
               lastUpdatedAt: Date.now()
             };

             const isConflict = checkForConflict(existingRecords, rec);
             const isHighMargin = bulkType === CommercialType.MARGIN_PERCENT && val > 60;

             if (isConflict || isHighMargin) {
               let reason = '';
               if (isConflict) reason = 'Conflict Detected';
               if (isHighMargin) reason = reason ? reason + ' & High Margin' : 'High Margin';

               const req: DuplicateRequest = {
                 id: `req_${Math.random().toString(36).substr(2,9)}`,
                 originalRecordId: null,
                 payload: rec,
                 requestedBy: user.name,
                 requestedAt: Date.now(),
                 status: 'PENDING',
                 reason: reason
               };
               requests.push(req);
             } else {
               newRecords.push(rec);
             }
           });
        });

        if (newRecords.length > 0) {
          await db.addRecords(newRecords);
        }

        if (requests.length > 0) {
           for (const req of requests) {
              await db.createDuplicateRequest(req);
           }
        }

        // Notification Logic
        let msg = '';
        let type: 'success' | 'warning' | 'error' = 'success';

        if (newRecords.length > 0) msg += `Successfully uploaded ${newRecords.length} records. `;
        if (requests.length > 0) {
            msg += `${requests.length} sent for approval (Conflict/High Margin). `;
            type = 'warning';
        }
        if (skipped > 0) {
            msg += `${skipped} skipped (Invalid FSN length). `;
            type = 'warning';
        }
        if (missingKam > 0) {
            msg += `${missingKam} skipped (KAM name is missing). `;
            type = 'warning';
        }

        if (newRecords.length === 0 && requests.length === 0) {
            if (missingKam > 0 || skipped > 0) {
                 type = 'error';
                 if (!msg) msg = "No valid records found (check FSN length or missing KAM).";
            } else {
                 type = 'error';
                 msg = "No valid records found in file.";
            }
        }

        setNotification({ msg, type });
        setLoading(false);
        e.target.value = ''; // Reset input to allow re-upload of same file
      }
    });
  };

  const downloadTemplate = () => {
    const headers = ['FSN', 'Brand', 'Title', 'Vertical', 'KAM', 'StartDate', 'EndDate', ...cities];
    const isNLC = bulkType === CommercialType.NLC_VALUE;
    const exampleVal = isNLC ? '50000' : '10';
    const dummyRows = [
        ['MOBEXAMPLE123456', 'BrandX', 'Sample Product 1', 'Mobiles', 'John Doe', '2024-01-01', '2024-03-31', ...cities.map(() => exampleVal)],
    ];
    const csvContent = [headers.join(','), ...dummyRows.map(row => row.join(','))].join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv' });
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `template_${bulkType.replace(/\s/g, '')}.csv`;
    a.click();
    window.URL.revokeObjectURL(url);
  };

  return (
    <div className="space-y-6 animate-in slide-in-from-bottom-4 duration-500 max-w-7xl mx-auto">
      <div className="flex justify-between items-center">
        <div>
           <h2 className="text-2xl font-bold text-gray-800">Maker Workspace</h2>
           <p className="text-sm text-gray-500">Manage commercials and offers</p>
        </div>
        <div className="flex bg-white rounded shadow-sm border border-gray-200 p-1">
          <button
            onClick={() => setActiveTab('MANUAL')}
            className={`px-4 py-2 rounded text-sm font-medium transition-all ${activeTab === 'MANUAL' ? 'bg-fkBlue text-white shadow' : 'text-gray-500 hover:text-gray-900'}`}
          >
            Manual Entry
          </button>
          <button
            onClick={() => setActiveTab('BULK')}
            className={`px-4 py-2 rounded text-sm font-medium transition-all ${activeTab === 'BULK' ? 'bg-fkBlue text-white shadow' : 'text-gray-500 hover:text-gray-900'}`}
          >
            Bulk Upload
          </button>
        </div>
      </div>

      {notification.msg && (
        <div className={`p-4 rounded border flex items-center gap-3 shadow-sm ${
          notification.type === 'error' ? 'bg-red-50 border-red-200 text-red-700' :
          notification.type === 'warning' ? 'bg-orange-50 border-orange-200 text-orange-800' :
          'bg-green-50 border-green-200 text-green-700'
        }`}>
          {notification.type === 'error' ? <AlertTriangle className="h-5 w-5"/> : <FileText className="h-5 w-5"/>}
          <span className="font-medium">{notification.msg}</span>
          <button onClick={() => setNotification({msg:'', type:null})} className="ml-auto hover:bg-white/50 rounded p-1"><X className="h-4 w-4"/></button>
        </div>
      )}

      {/* Alerts */}
      <div className="space-y-2">
          {instantConflict && activeTab === 'MANUAL' && (
            <div className="p-3 bg-red-50 border-l-4 border-red-500 rounded shadow-sm flex items-center gap-3 animate-in fade-in slide-in-from-top-2">
                <ShieldAlert className="text-red-500 w-6 h-6" />
                <div>
                    <p className="font-bold text-gray-800 text-sm">Conflict Detected!</p>
                    <p className="text-xs text-gray-600">Overlap with existing FSN+City/PAN-INDIA record. Saving triggers approval.</p>
                </div>
            </div>
          )}
          {highMarginAlert && activeTab === 'MANUAL' && (
            <div className="p-3 bg-yellow-50 border-l-4 border-fkYellow rounded shadow-sm flex items-center gap-3 animate-in fade-in slide-in-from-top-2">
                <AlertTriangle className="text-fkYellow w-6 h-6" />
                <div>
                    <p className="font-bold text-gray-800 text-sm">High Margin Alert!</p>
                    <p className="text-xs text-gray-600">Margin &gt; 60% requires checker approval.</p>
                </div>
            </div>
          )}
      </div>

      {activeTab === 'MANUAL' ? (
        <form onSubmit={handleManualSubmit} className="fk-card p-6 grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          <div className="col-span-1">
            <label className="block text-xs font-semibold text-gray-500 uppercase mb-1">FSN (Product ID) <span className="text-red-500">*</span></label>
            <div className="relative">
                <input 
                  className="w-full bg-white border border-gray-300 rounded p-2.5 text-gray-900 focus:border-fkBlue focus:ring-1 focus:ring-fkBlue outline-none transition-colors" 
                  value={formData.fsn || ''}
                  onChange={e => setFormData({...formData, fsn: e.target.value})}
                  placeholder="16 Characters Required"
                  maxLength={16}
                />
                <div className={`text-[10px] text-right mt-1 font-mono ${formData.fsn?.length === 16 ? 'text-green-600' : 'text-gray-400'}`}>
                    {formData.fsn?.length || 0}/16
                </div>
            </div>
          </div>
          <div className="col-span-1">
            <label className="block text-xs font-semibold text-gray-500 uppercase mb-1">Brand <span className="text-red-500">*</span></label>
            <input 
              className="w-full bg-white border border-gray-300 rounded p-2.5 text-gray-900 focus:border-fkBlue focus:ring-1 focus:ring-fkBlue outline-none transition-colors" 
              value={formData.brand || ''}
              onChange={e => setFormData({...formData, brand: e.target.value})}
              placeholder="e.g. Samsung"
            />
          </div>
          <div className="col-span-1">
            <label className="block text-xs font-semibold text-gray-500 uppercase mb-1">Title <span className="text-red-500">*</span></label>
            <input 
              className="w-full bg-white border border-gray-300 rounded p-2.5 text-gray-900 focus:border-fkBlue focus:ring-1 focus:ring-fkBlue outline-none transition-colors" 
              value={formData.title || ''}
              onChange={e => setFormData({...formData, title: e.target.value})}
              placeholder="Product Title"
            />
          </div>

          <div className="col-span-1">
            <label className="block text-xs font-semibold text-gray-500 uppercase mb-1 flex items-center gap-1"><Layers className="w-3 h-3"/> Vertical <span className="text-red-500">*</span></label>
            <input 
              className="w-full bg-white border border-gray-300 rounded p-2.5 text-gray-900 focus:border-fkBlue focus:ring-1 focus:ring-fkBlue outline-none transition-colors" 
              value={formData.vertical || ''}
              onChange={e => setFormData({...formData, vertical: e.target.value})}
              placeholder="e.g. Mobiles"
            />
          </div>

          <div className="col-span-1">
            <label className="block text-xs font-semibold text-gray-500 uppercase mb-1 flex items-center gap-1"><UserIcon className="w-3 h-3"/> KAM <span className="text-red-500">*</span></label>
            <input 
              className="w-full bg-white border border-gray-300 rounded p-2.5 text-gray-900 focus:border-fkBlue focus:ring-1 focus:ring-fkBlue outline-none transition-colors" 
              value={formData.kam || ''}
              onChange={e => setFormData({...formData, kam: e.target.value})}
              placeholder="Account Manager Name"
            />
          </div>

          <div className="col-span-1">
            <label className="block text-xs font-semibold text-gray-500 uppercase mb-1">City <span className="text-red-500">*</span></label>
            <div className="flex gap-2">
              {isAddingCity ? (
                <div className="flex-1 flex gap-1">
                   <input 
                     className="w-full bg-white border border-gray-300 rounded p-2.5 text-gray-900 uppercase"
                     placeholder="XXX"
                     autoFocus
                     value={newCityCode}
                     maxLength={3}
                     onChange={e => setNewCityCode(e.target.value)}
                   />
                   <button 
                     type="button" 
                     onClick={handleAddNewCity}
                     className="bg-fkGreen px-3 rounded text-white hover:bg-green-700"
                   >
                     <Check className="h-4 w-4" />
                   </button>
                   <button 
                     type="button" 
                     onClick={() => setIsAddingCity(false)}
                     className="bg-gray-200 px-3 rounded text-gray-700 hover:bg-gray-300"
                   >
                     <X className="h-4 w-4" />
                   </button>
                </div>
              ) : (
                <div className="flex-1 flex gap-2">
                  <select 
                    className="w-full bg-white border border-gray-300 rounded p-2.5 text-gray-900 focus:border-fkBlue focus:ring-1 focus:ring-fkBlue outline-none"
                    value={formData.city}
                    onChange={e => setFormData({...formData, city: e.target.value})}
                  >
                    {cities.map(c => <option key={c} value={c}>{c}</option>)}
                  </select>

                  <button 
                    type="button" 
                    onClick={() => setIsAddingCity(true)}
                    className="px-3 bg-gray-100 hover:bg-gray-200 rounded border border-gray-300 text-gray-600 transition-colors"
                    title="Add New City"
                  >
                    <Plus className="h-4 w-4" />
                  </button>

                  <button 
                    type="button"
                    onClick={handleDeleteCity}
                    disabled={formData.city === 'PAN-INDIA'}
                    className={`px-3 rounded border transition-colors ${formData.city === 'PAN-INDIA' ? 'bg-gray-100 border-gray-200 text-gray-400 cursor-not-allowed' : 'bg-red-50 border-red-200 text-red-600 hover:bg-red-100'}`}
                  >
                    <Trash2 className="h-4 w-4" />
                  </button>
                </div>
              )}
            </div>
          </div>

          <div className="col-span-1">
            <label className="block text-xs font-semibold text-gray-500 uppercase mb-1">Type <span className="text-red-500">*</span></label>
            <select 
              className="w-full bg-white border border-gray-300 rounded p-2.5 text-gray-900 focus:border-fkBlue focus:ring-1 focus:ring-fkBlue outline-none"
              value={formData.type}
              onChange={e => setFormData({...formData, type: e.target.value as CommercialType})}
            >
              <option value={CommercialType.MARGIN_PERCENT}>Margin %</option>
              <option value={CommercialType.NLC_VALUE}>NLC Value (Amount)</option>
              <option value={CommercialType.NLC_PERCENT}>NLC %</option>
              <option value={CommercialType.ON_INVOICE}>On Invoice %</option>
              <option value={CommercialType.OFF_INVOICE}>Off Invoice %</option>
            </select>
          </div>

          <div className="col-span-1">
            <label className="block text-xs font-semibold text-gray-500 uppercase mb-1">Value <span className="text-red-500">*</span></label>
            <input 
              type="number"
              className="w-full bg-white border border-gray-300 rounded p-2.5 text-gray-900 focus:border-fkBlue focus:ring-1 focus:ring-fkBlue outline-none font-mono" 
              value={formData.value || ''}
              onChange={e => setFormData({...formData, value: parseFloat(e.target.value)})}
              placeholder="0.00"
            />
            {/* Helper Text for Caps */}
            {formData.type?.includes('%') && (
                <p className="text-[10px] text-gray-400 mt-1">Capped at 100%</p>
            )}
          </div>

          {formData.type !== CommercialType.MARGIN_PERCENT && (
            <>
              <div className="col-span-1">
                <label className="block text-xs font-semibold text-gray-500 uppercase mb-1">Start Date</label>
                <input 
                  type="date"
                  className="w-full bg-white border border-gray-300 rounded p-2.5 text-gray-900 focus:border-fkBlue outline-none" 
                  value={formData.startDate}
                  onChange={e => setFormData({...formData, startDate: e.target.value})}
                />
              </div>
              <div className="col-span-1">
                <label className="block text-xs font-semibold text-gray-500 uppercase mb-1">End Date</label>
                <input 
                  type="date"
                  className="w-full bg-white border border-gray-300 rounded p-2.5 text-gray-900 focus:border-fkBlue outline-none" 
                  value={formData.endDate}
                  onChange={e => setFormData({...formData, endDate: e.target.value})}
                />
              </div>
            </>
          )}

          <div className="col-span-full flex justify-end pt-6 border-t border-gray-100">
             <button
               type="submit"
               disabled={loading}
               className="bg-fkYellow hover:bg-yellow-500 text-white font-bold py-2.5 px-8 rounded shadow-md hover:shadow-lg transition-all flex items-center gap-2"
             >
               {loading ? <span className="animate-spin">⌛</span> : <Save className="h-5 w-5" />}
               Save Record
             </button>
          </div>
        </form>
      ) : (
        <div className="space-y-6">
          <div className="bg-white p-6 rounded-lg border border-gray-200 shadow-sm">
             <label className="block text-xs font-bold text-gray-500 mb-4 uppercase tracking-wider">Select Upload Type</label>
             <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
               {COMMERCIAL_TYPES.map(type => (
                 <button
                   key={type}
                   onClick={() => setBulkType(type)}
                   className={`p-4 rounded border text-sm font-semibold transition-all ${
                     bulkType === type 
                     ? 'bg-fkBlue text-white border-fkBlue shadow-md' 
                     : 'bg-gray-50 text-gray-600 border-gray-200 hover:bg-white hover:border-gray-300 hover:shadow-sm'
                   }`}
                 >
                   {type}
                 </button>
               ))}
             </div>
          </div>

          <div className="flex justify-end">
            <button 
              onClick={downloadTemplate}
              className="flex items-center gap-2 px-4 py-2 bg-white hover:bg-gray-50 text-fkBlue font-medium rounded border border-gray-300 shadow-sm transition-colors text-sm"
            >
              <Download className="h-4 w-4" /> 
              Download Template
            </button>
          </div>

          <div className="fk-card border-dashed border-2 border-gray-300 p-12 flex flex-col items-center justify-center text-center hover:border-fkBlue hover:bg-blue-50/30 transition-all group cursor-pointer relative">
            <input 
              type="file" 
              accept=".csv"
              onChange={handleFileUpload}
              key={bulkType}
              className="absolute inset-0 w-full h-full opacity-0 cursor-pointer"
            />
            <div className="bg-blue-50 p-5 rounded-full mb-4 group-hover:scale-110 transition-transform">
               <Upload className="h-10 w-10 text-fkBlue" />
            </div>
            <h3 className="text-xl font-bold text-gray-800">Upload {bulkType} CSV</h3>
            <p className="text-gray-500 mt-2">
              Drag and drop or click to upload
            </p>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { CommercialRecord, CommercialType, DuplicateRequest, User, COMMERCIAL_TYPES } from '../types';
import { db } from '../services/db';
import { Plus, Upload, Save, AlertTriangle, FileText, X, Download, Check, Trash2, ArrowUpRight, ShieldAlert, User as UserIcon, Layers } from 'lucide-react';
import Papa from 'papaparse';

interface MakerProps {
  user: User;
}

export const MakerWorkspace: React.FC<MakerProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<'MANUAL' | 'BULK'>('MANUAL');

  // Dynamic Cities
  const [cities, setCities] = useState<string[]>([]);
  const [isAddingCity, setIsAddingCity] = useState(false);
  const [newCityCode, setNewCityCode] = useState('');

  // Manual Form State
  const [formData, setFormData] = useState<Partial<CommercialRecord>>({
    city: 'PAN-INDIA',
    type: CommercialType.MARGIN_PERCENT,
    startDate: new Date().toISOString().split('T')[0],
    endDate: new Date(new Date().setMonth(new Date().getMonth() + 3)).toISOString().split('T')[0],
    vertical: '',
    kam: ''
  });

  // Real-time Validation State
  const [instantConflict, setInstantConflict] = useState<boolean>(false);
  const [highMarginAlert, setHighMarginAlert] = useState<boolean>(false);

  // Bulk State
  const [bulkType, setBulkType] = useState<CommercialType>(CommercialType.MARGIN_PERCENT);

  const [loading, setLoading] = useState(false);
  const [notification, setNotification] = useState<{msg: string, type: 'success' | 'error' | 'warning' | null}>({ msg: '', type: null });

  // Initialize Data
  useEffect(() => {
    const init = async () => {
      // 1. Load Draft
      const draft = localStorage.getItem('mm_draft_form');
      let draftData = {};
      if (draft) {
        draftData = JSON.parse(draft);
        setFormData(draftData);
      }

      // 2. Load Cities and Validate
      const c = await db.getCities();
      setCities(c);

      // Validate the city from draft or current state
      const currentCity = (draftData as any).city || formData.city || 'PAN-INDIA';
      if (!c.includes(currentCity)) {
         setFormData(prev => ({ ...prev, city: c[0] || 'PAN-INDIA' }));
      }
    };

    init();
  }, []);

  // Save draft & Real-time Check
  useEffect(() => {
    localStorage.setItem('mm_draft_form', JSON.stringify(formData));

    // High Margin Check
    if (formData.type === CommercialType.MARGIN_PERCENT && (formData.value || 0) > 60) {
        setHighMarginAlert(true);
    } else {
        setHighMarginAlert(false);
    }

    // Debounce the conflict check
    const timeoutId = setTimeout(async () => {
        if(formData.fsn && formData.fsn.length === 16 && formData.city && formData.type && formData.startDate && formData.endDate) {
            const records = await db.getRecords();
            const conflict = checkForConflict(records, formData as CommercialRecord);
            setInstantConflict(conflict);
        } else {
            setInstantConflict(false);
        }
    }, 500);

    return () => clearTimeout(timeoutId);
  }, [formData]);

  const checkForConflict = (existingRecords: CommercialRecord[], input: CommercialRecord): boolean => {
      return existingRecords.some(r => {
        // 1. Match FSN & Type
        if (r.fsn !== input.fsn) return false;
        if (r.type !== input.type) return false;

        // 2. Check City Logic (Exact Match OR PAN-INDIA Collision)
        // If input is PAN-INDIA, it conflicts with ANY city record for that FSN
        // If existing record is PAN-INDIA, it conflicts with ANY input city
        const cityConflict = (input.city === 'PAN-INDIA' || r.city === 'PAN-INDIA' || input.city === r.city);

        if (!cityConflict) return false;

        // 3. Date Logic based on Commercial Type
        const isOnOrOffInvoice = input.type === CommercialType.ON_INVOICE || input.type === CommercialType.OFF_INVOICE;

        if (isOnOrOffInvoice) {
            // SPECIAL RULE: For On/Off Invoice, overlaps are allowed (stacking).
            // Conflict ONLY if Exact Date Duplicate (Start & End match exactly).
            return input.startDate === r.startDate && input.endDate === r.endDate;
        } else {
            // STANDARD RULE: For Margin/NLC, NO overlaps allowed.
            // Check intersection: (StartA <= EndB) and (EndA >= StartB)
            return (input.startDate <= r.endDate) && (input.endDate >= r.startDate);
        }
      });
  };

  const refreshCities = async () => {
    const c = await db.getCities();
    setCities(c);
    return c;
  };

  const handleAddNewCity = async () => {
    if (!newCityCode) return;
    const code = newCityCode.toUpperCase().trim();
    if (code !== 'PAN-INDIA' && code.length > 3) {
       setNotification({ msg: 'City code must be 3 characters or less.', type: 'error' });
       return;
    }
    const cleanCode = code.replace(/[^A-Z0-9]/g, '');
    if (!cleanCode) return;
    if (cities.includes(cleanCode)) {
       setNotification({ msg: `City ${cleanCode} already exists.`, type: 'warning' });
       return;
    }
    if (cleanCode) {
       await db.addCity(cleanCode);
       await refreshCities();
       setFormData(prev => ({...prev, city: cleanCode}));
       setNewCityCode('');
       setIsAddingCity(false);
       setNotification({ msg: `City ${cleanCode} added.`, type: 'success' });
    }
  };

  const handleDeleteCity = async () => {
    const cityToDelete = formData.city;
    if (!cityToDelete || cityToDelete === 'PAN-INDIA') {
        setNotification({ msg: 'Cannot delete default PAN-INDIA city.', type: 'error' });
        return;
    }
    if (window.confirm(`Delete city code "${cityToDelete}"?`)) {
        try {
            await db.deleteCity(cityToDelete);
            const updatedCities = await refreshCities();
            setFormData(prev => ({ ...prev, city: updatedCities[0] || 'PAN-INDIA' }));
            setNotification({ msg: `City ${cityToDelete} removed.`, type: 'success' });
        } catch (err) {
            setNotification({ msg: 'Failed to delete city.', type: 'error' });
        }
    }
  };

  const handleManualSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setNotification({ msg: '', type: null });

    if (!formData.fsn || !formData.value || !formData.brand || !formData.title || !formData.vertical || !formData.kam) {
        setNotification({ msg: 'Please fill all fields', type: 'error' });
        return;
    }

    // Strict FSN Length Check
    if (formData.fsn.length !== 16) {
        setNotification({ msg: 'FSN must be exactly 16 characters.', type: 'error' });
        return;
    }

    // Validate Caps
    const isPercentage = formData.type === CommercialType.MARGIN_PERCENT || 
                         formData.type === CommercialType.NLC_PERCENT || 
                         formData.type === CommercialType.ON_INVOICE || 
                         formData.type === CommercialType.OFF_INVOICE;

    if (isPercentage && formData.value! > 100) {
        setNotification({ msg: `${formData.type} cannot exceed 100%`, type: 'error' });
        return;
    }

    if (formData.type !== CommercialType.MARGIN_PERCENT && formData.endDate! < formData.startDate!) {
        setNotification({ msg: 'End Date cannot be before Start Date', type: 'error' });
        return;
    }

    setLoading(true);

    try {
      const records = await db.getRecords();

      const isConflict = checkForConflict(records, formData as CommercialRecord);
      const isHighMargin = formData.type === CommercialType.MARGIN_PERCENT && (formData.value || 0) > 60;

      const newRecord: CommercialRecord = {
        id: `rec_${Date.now()}`,
        ...formData as CommercialRecord,
        value: Number(formData.value),
        lastUpdatedBy: user.name,
        lastUpdatedAt: Date.now()
      };

      if (isConflict || isHighMargin) {
        let reason = '';
        if (isConflict) reason = 'Duplicate/Overlap Conflict Detected';
        if (isHighMargin) reason = reason ? reason + ' & High Margin (>60%)' : 'High Margin (>60%)';

        const req: DuplicateRequest = {
          id: `req_${Date.now()}`,
          originalRecordId: null,
          payload: newRecord,
          requestedBy: user.name,
          requestedAt: Date.now(),
          status: 'PENDING',
          reason: reason
        };
        await db.createDuplicateRequest(req);
        setNotification({ msg: `Request sent to Checker: ${reason}`, type: 'warning' });
      } else {
        await db.addRecords([newRecord]);
        setNotification({ msg: 'Record saved successfully.', type: 'success' });
        setFormData(prev => ({ 
            ...prev, 
            fsn: '', 
            value: 0,
            // Reset dates to defaults
            startDate: new Date().toISOString().split('T')[0],
            endDate: new Date(new Date().setMonth(new Date().getMonth() + 3)).toISOString().split('T')[0]
        }));
      }
    } catch (err) {
      setNotification({ msg: 'Failed to save record.', type: 'error' });
    } finally {
      setLoading(false);
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    Papa.parse(file, {
      header: true,
      skipEmptyLines: true,
      complete: async (results) => {
        setLoading(true);

        // 1. Validate Headers
        const headers = results.meta.fields || [];
        // Flexible check for KAM (case insensitive)
        const kamHeader = headers.find(h => h.toUpperCase() === 'KAM');

        if (!kamHeader) {
            setNotification({ msg: "Upload Failed: 'KAM' column is missing in the CSV file.", type: 'error' });
            setLoading(false);
            e.target.value = ''; // Reset input
            return;
        }

        const newRecords: CommercialRecord[] = [];
        const requests: DuplicateRequest[] = [];
        const existingRecords = await db.getRecords();

        let skipped = 0;
        let missingKam = 0;

        results.data.forEach((row: any) => {
           if(!row.FSN) return;

           // Validation in Loop
           if(row.FSN.length !== 16) {
               skipped++;
               return;
           }

           // Check KAM presence using the identified header key
           const kamValue = row[kamHeader] || row['KAM']; // Fallback
           if (!kamValue || !kamValue.trim()) {
               missingKam++;
               return; // Skip if KAM is missing
           }

           const cityKeys = Object.keys(row).filter(k => cities.includes(k) || k === 'Value');

           cityKeys.forEach(cityKey => {
             const city = cityKey === 'Value' ? 'PAN-INDIA' : cityKey;
             let val = parseFloat(row[cityKey]);
             if (isNaN(val)) return;

             const isPercentage = bulkType === CommercialType.MARGIN_PERCENT || 
                                  bulkType === CommercialType.NLC_PERCENT || 
                                  bulkType === CommercialType.ON_INVOICE || 
                                  bulkType === CommercialType.OFF_INVOICE;

             if (isPercentage && val > 100) val = 100; // Cap at 100
             if (isPercentage && val <= 1 && val > 0) val = val * 100; // Handle 0.5 as 50% if common error

             const rec: CommercialRecord = {
               id: `rec_${Math.random().toString(36).substr(2,9)}`,
               fsn: row.FSN,
               brand: row.Brand || 'Unknown',
               title: row.Title || 'Bulk Upload Item',
               vertical: row.Vertical || 'Unknown',
               kam: kamValue,
               city: city,
               startDate: row.StartDate,
               endDate: row.EndDate,
               type: bulkType,
               value: val,
               lastUpdatedBy: user.name,
               lastUpdatedAt: Date.now()
             };

             const isConflict = checkForConflict(existingRecords, rec);
             const isHighMargin = bulkType === CommercialType.MARGIN_PERCENT && val > 60;

             if (isConflict || isHighMargin) {
               let reason = '';
               if (isConflict) reason = 'Conflict Detected';
               if (isHighMargin) reason = reason ? reason + ' & High Margin' : 'High Margin';

               const req: DuplicateRequest = {
                 id: `req_${Math.random().toString(36).substr(2,9)}`,
                 originalRecordId: null,
                 payload: rec,
                 requestedBy: user.name,
                 requestedAt: Date.now(),
                 status: 'PENDING',
                 reason: reason
               };
               requests.push(req);
             } else {
               newRecords.push(rec);
             }
           });
        });

        if (newRecords.length > 0) {
          await db.addRecords(newRecords);
        }

        if (requests.length > 0) {
           for (const req of requests) {
              await db.createDuplicateRequest(req);
           }
        }

        // Notification Logic
        let msg = '';
        let type: 'success' | 'warning' | 'error' = 'success';

        if (newRecords.length > 0) msg += `Successfully uploaded ${newRecords.length} records. `;
        if (requests.length > 0) {
            msg += `${requests.length} sent for approval (Conflict/High Margin). `;
            type = 'warning';
        }
        if (skipped > 0) {
            msg += `${skipped} skipped (Invalid FSN length). `;
            type = 'warning';
        }
        if (missingKam > 0) {
            msg += `${missingKam} skipped (KAM name is missing). `;
            type = 'warning';
        }

        if (newRecords.length === 0 && requests.length === 0) {
            if (missingKam > 0 || skipped > 0) {
                 type = 'error';
                 if (!msg) msg = "No valid records found (check FSN length or missing KAM).";
            } else {
                 type = 'error';
                 msg = "No valid records found in file.";
            }
        }

        setNotification({ msg, type });
        setLoading(false);
        e.target.value = ''; // Reset input to allow re-upload of same file
      }
    });
  };

  const downloadTemplate = () => {
    const headers = ['FSN', 'Brand', 'Title', 'Vertical', 'KAM', 'StartDate', 'EndDate', ...cities];
    const isNLC = bulkType === CommercialType.NLC_VALUE;
    const exampleVal = isNLC ? '50000' : '10';
    const dummyRows = [
        ['MOBEXAMPLE123456', 'BrandX', 'Sample Product 1', 'Mobiles', 'John Doe', '2024-01-01', '2024-03-31', ...cities.map(() => exampleVal)],
    ];
    const csvContent = [headers.join(','), ...dummyRows.map(row => row.join(','))].join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv' });
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `template_${bulkType.replace(/\s/g, '')}.csv`;
    a.click();
    window.URL.revokeObjectURL(url);
  };

  return (
    <div className="space-y-6 animate-in slide-in-from-bottom-4 duration-500 max-w-7xl mx-auto">
      <div className="flex justify-between items-center">
        <div>
           <h2 className="text-2xl font-bold text-gray-800">Maker Workspace</h2>
           <p className="text-sm text-gray-500">Manage commercials and offers</p>
        </div>
        <div className="flex bg-white rounded shadow-sm border border-gray-200 p-1">
          <button
            onClick={() => setActiveTab('MANUAL')}
            className={`px-4 py-2 rounded text-sm font-medium transition-all ${activeTab === 'MANUAL' ? 'bg-fkBlue text-white shadow' : 'text-gray-500 hover:text-gray-900'}`}
          >
            Manual Entry
          </button>
          <button
            onClick={() => setActiveTab('BULK')}
            className={`px-4 py-2 rounded text-sm font-medium transition-all ${activeTab === 'BULK' ? 'bg-fkBlue text-white shadow' : 'text-gray-500 hover:text-gray-900'}`}
          >
            Bulk Upload
          </button>
        </div>
      </div>

      {notification.msg && (
        <div className={`p-4 rounded border flex items-center gap-3 shadow-sm ${
          notification.type === 'error' ? 'bg-red-50 border-red-200 text-red-700' :
          notification.type === 'warning' ? 'bg-orange-50 border-orange-200 text-orange-800' :
          'bg-green-50 border-green-200 text-green-700'
        }`}>
          {notification.type === 'error' ? <AlertTriangle className="h-5 w-5"/> : <FileText className="h-5 w-5"/>}
          <span className="font-medium">{notification.msg}</span>
          <button onClick={() => setNotification({msg:'', type:null})} className="ml-auto hover:bg-white/50 rounded p-1"><X className="h-4 w-4"/></button>
        </div>
      )}

      {/* Alerts */}
      <div className="space-y-2">
          {instantConflict && activeTab === 'MANUAL' && (
            <div className="p-3 bg-red-50 border-l-4 border-red-500 rounded shadow-sm flex items-center gap-3 animate-in fade-in slide-in-from-top-2">
                <ShieldAlert className="text-red-500 w-6 h-6" />
                <div>
                    <p className="font-bold text-gray-800 text-sm">Conflict Detected!</p>
                    <p className="text-xs text-gray-600">Overlap with existing FSN+City/PAN-INDIA record. Saving triggers approval.</p>
                </div>
            </div>
          )}
          {highMarginAlert && activeTab === 'MANUAL' && (
            <div className="p-3 bg-yellow-50 border-l-4 border-fkYellow rounded shadow-sm flex items-center gap-3 animate-in fade-in slide-in-from-top-2">
                <AlertTriangle className="text-fkYellow w-6 h-6" />
                <div>
                    <p className="font-bold text-gray-800 text-sm">High Margin Alert!</p>
                    <p className="text-xs text-gray-600">Margin &gt; 60% requires checker approval.</p>
                </div>
            </div>
          )}
      </div>

      {activeTab === 'MANUAL' ? (
        <form onSubmit={handleManualSubmit} className="fk-card p-6 grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          <div className="col-span-1">
            <label className="block text-xs font-semibold text-gray-500 uppercase mb-1">FSN (Product ID) <span className="text-red-500">*</span></label>
            <div className="relative">
                <input 
                  className="w-full bg-white border border-gray-300 rounded p-2.5 text-gray-900 focus:border-fkBlue focus:ring-1 focus:ring-fkBlue outline-none transition-colors" 
                  value={formData.fsn || ''}
                  onChange={e => setFormData({...formData, fsn: e.target.value})}
                  placeholder="16 Characters Required"
                  maxLength={16}
                />
                <div className={`text-[10px] text-right mt-1 font-mono ${formData.fsn?.length === 16 ? 'text-green-600' : 'text-gray-400'}`}>
                    {formData.fsn?.length || 0}/16
                </div>
            </div>
          </div>
          <div className="col-span-1">
            <label className="block text-xs font-semibold text-gray-500 uppercase mb-1">Brand <span className="text-red-500">*</span></label>
            <input 
              className="w-full bg-white border border-gray-300 rounded p-2.5 text-gray-900 focus:border-fkBlue focus:ring-1 focus:ring-fkBlue outline-none transition-colors" 
              value={formData.brand || ''}
              onChange={e => setFormData({...formData, brand: e.target.value})}
              placeholder="e.g. Samsung"
            />
          </div>
          <div className="col-span-1">
            <label className="block text-xs font-semibold text-gray-500 uppercase mb-1">Title <span className="text-red-500">*</span></label>
            <input 
              className="w-full bg-white border border-gray-300 rounded p-2.5 text-gray-900 focus:border-fkBlue focus:ring-1 focus:ring-fkBlue outline-none transition-colors" 
              value={formData.title || ''}
              onChange={e => setFormData({...formData, title: e.target.value})}
              placeholder="Product Title"
            />
          </div>

          <div className="col-span-1">
            <label className="block text-xs font-semibold text-gray-500 uppercase mb-1 flex items-center gap-1"><Layers className="w-3 h-3"/> Vertical <span className="text-red-500">*</span></label>
            <input 
              className="w-full bg-white border border-gray-300 rounded p-2.5 text-gray-900 focus:border-fkBlue focus:ring-1 focus:ring-fkBlue outline-none transition-colors" 
              value={formData.vertical || ''}
              onChange={e => setFormData({...formData, vertical: e.target.value})}
              placeholder="e.g. Mobiles"
            />
          </div>

          <div className="col-span-1">
            <label className="block text-xs font-semibold text-gray-500 uppercase mb-1 flex items-center gap-1"><UserIcon className="w-3 h-3"/> KAM <span className="text-red-500">*</span></label>
            <input 
              className="w-full bg-white border border-gray-300 rounded p-2.5 text-gray-900 focus:border-fkBlue focus:ring-1 focus:ring-fkBlue outline-none transition-colors" 
              value={formData.kam || ''}
              onChange={e => setFormData({...formData, kam: e.target.value})}
              placeholder="Account Manager Name"
            />
          </div>

          <div className="col-span-1">
            <label className="block text-xs font-semibold text-gray-500 uppercase mb-1">City <span className="text-red-500">*</span></label>
            <div className="flex gap-2">
              {isAddingCity ? (
                <div className="flex-1 flex gap-1">
                   <input 
                     className="w-full bg-white border border-gray-300 rounded p-2.5 text-gray-900 uppercase"
                     placeholder="XXX"
                     autoFocus
                     value={newCityCode}
                     maxLength={3}
                     onChange={e => setNewCityCode(e.target.value)}
                   />
                   <button 
                     type="button" 
                     onClick={handleAddNewCity}
                     className="bg-fkGreen px-3 rounded text-white hover:bg-green-700"
                   >
                     <Check className="h-4 w-4" />
                   </button>
                   <button 
                     type="button" 
                     onClick={() => setIsAddingCity(false)}
                     className="bg-gray-200 px-3 rounded text-gray-700 hover:bg-gray-300"
                   >
                     <X className="h-4 w-4" />
                   </button>
                </div>
              ) : (
                <div className="flex-1 flex gap-2">
                  <select 
                    className="w-full bg-white border border-gray-300 rounded p-2.5 text-gray-900 focus:border-fkBlue focus:ring-1 focus:ring-fkBlue outline-none"
                    value={formData.city}
                    onChange={e => setFormData({...formData, city: e.target.value})}
                  >
                    {cities.map(c => <option key={c} value={c}>{c}</option>)}
                  </select>

                  <button 
                    type="button" 
                    onClick={() => setIsAddingCity(true)}
                    className="px-3 bg-gray-100 hover:bg-gray-200 rounded border border-gray-300 text-gray-600 transition-colors"
                    title="Add New City"
                  >
                    <Plus className="h-4 w-4" />
                  </button>

                  <button 
                    type="button"
                    onClick={handleDeleteCity}
                    disabled={formData.city === 'PAN-INDIA'}
                    className={`px-3 rounded border transition-colors ${formData.city === 'PAN-INDIA' ? 'bg-gray-100 border-gray-200 text-gray-400 cursor-not-allowed' : 'bg-red-50 border-red-200 text-red-600 hover:bg-red-100'}`}
                  >
                    <Trash2 className="h-4 w-4" />
                  </button>
                </div>
              )}
            </div>
          </div>

          <div className="col-span-1">
            <label className="block text-xs font-semibold text-gray-500 uppercase mb-1">Type <span className="text-red-500">*</span></label>
            <select 
              className="w-full bg-white border border-gray-300 rounded p-2.5 text-gray-900 focus:border-fkBlue focus:ring-1 focus:ring-fkBlue outline-none"
              value={formData.type}
              onChange={e => setFormData({...formData, type: e.target.value as CommercialType})}
            >
              <option value={CommercialType.MARGIN_PERCENT}>Margin %</option>
              <option value={CommercialType.NLC_VALUE}>NLC Value (Amount)</option>
              <option value={CommercialType.NLC_PERCENT}>NLC %</option>
              <option value={CommercialType.ON_INVOICE}>On Invoice %</option>
              <option value={CommercialType.OFF_INVOICE}>Off Invoice %</option>
            </select>
          </div>

          <div className="col-span-1">
            <label className="block text-xs font-semibold text-gray-500 uppercase mb-1">Value <span className="text-red-500">*</span></label>
            <input 
              type="number"
              className="w-full bg-white border border-gray-300 rounded p-2.5 text-gray-900 focus:border-fkBlue focus:ring-1 focus:ring-fkBlue outline-none font-mono" 
              value={formData.value || ''}
              onChange={e => setFormData({...formData, value: parseFloat(e.target.value)})}
              placeholder="0.00"
            />
            {/* Helper Text for Caps */}
            {formData.type?.includes('%') && (
                <p className="text-[10px] text-gray-400 mt-1">Capped at 100%</p>
            )}
          </div>

          {formData.type !== CommercialType.MARGIN_PERCENT && (
            <>
              <div className="col-span-1">
                <label className="block text-xs font-semibold text-gray-500 uppercase mb-1">Start Date</label>
                <input 
                  type="date"
                  className="w-full bg-white border border-gray-300 rounded p-2.5 text-gray-900 focus:border-fkBlue outline-none" 
                  value={formData.startDate}
                  onChange={e => setFormData({...formData, startDate: e.target.value})}
                />
              </div>
              <div className="col-span-1">
                <label className="block text-xs font-semibold text-gray-500 uppercase mb-1">End Date</label>
                <input 
                  type="date"
                  className="w-full bg-white border border-gray-300 rounded p-2.5 text-gray-900 focus:border-fkBlue outline-none" 
                  value={formData.endDate}
                  onChange={e => setFormData({...formData, endDate: e.target.value})}
                />
              </div>
            </>
          )}

          <div className="col-span-full flex justify-end pt-6 border-t border-gray-100">
             <button
               type="submit"
               disabled={loading}
               className="bg-fkYellow hover:bg-yellow-500 text-white font-bold py-2.5 px-8 rounded shadow-md hover:shadow-lg transition-all flex items-center gap-2"
             >
               {loading ? <span className="animate-spin">⌛</span> : <Save className="h-5 w-5" />}
               Save Record
             </button>
          </div>
        </form>
      ) : (
        <div className="space-y-6">
          <div className="bg-white p-6 rounded-lg border border-gray-200 shadow-sm">
             <label className="block text-xs font-bold text-gray-500 mb-4 uppercase tracking-wider">Select Upload Type</label>
             <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
               {COMMERCIAL_TYPES.map(type => (
                 <button
                   key={type}
                   onClick={() => setBulkType(type)}
                   className={`p-4 rounded border text-sm font-semibold transition-all ${
                     bulkType === type 
                     ? 'bg-fkBlue text-white border-fkBlue shadow-md' 
                     : 'bg-gray-50 text-gray-600 border-gray-200 hover:bg-white hover:border-gray-300 hover:shadow-sm'
                   }`}
                 >
                   {type}
                 </button>
               ))}
             </div>
          </div>

          <div className="flex justify-end">
            <button 
              onClick={downloadTemplate}
              className="flex items-center gap-2 px-4 py-2 bg-white hover:bg-gray-50 text-fkBlue font-medium rounded border border-gray-300 shadow-sm transition-colors text-sm"
            >
              <Download className="h-4 w-4" /> 
              Download Template
            </button>
          </div>

          <div className="fk-card border-dashed border-2 border-gray-300 p-12 flex flex-col items-center justify-center text-center hover:border-fkBlue hover:bg-blue-50/30 transition-all group cursor-pointer relative">
            <input 
              type="file" 
              accept=".csv"
              onChange={handleFileUpload}
              key={bulkType}
              className="absolute inset-0 w-full h-full opacity-0 cursor-pointer"
            />
            <div className="bg-blue-50 p-5 rounded-full mb-4 group-hover:scale-110 transition-transform">
               <Upload className="h-10 w-10 text-fkBlue" />
            </div>
            <h3 className="text-xl font-bold text-gray-800">Upload {bulkType} CSV</h3>
            <p className="text-gray-500 mt-2">
              Drag and drop or click to upload
            </p>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { CommercialRecord, CommercialType, DuplicateRequest, User, COMMERCIAL_TYPES } from '../types';
import { db } from '../services/db';
import { Plus, Upload, Save, AlertTriangle, FileText, X, Download, Check, Trash2, ArrowUpRight, ShieldAlert, User as UserIcon, Layers, Info } from 'lucide-react';
import Papa from 'papaparse';

interface MakerProps {
  user: User;
}

export const MakerWorkspace: React.FC<MakerProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<'MANUAL' | 'BULK'>('MANUAL');

  // Dynamic Cities
  const [cities, setCities] = useState<string[]>([]);
  const [isAddingCity, setIsAddingCity] = useState(false);
  const [newCityCode, setNewCityCode] = useState('');

  // Manual Form State
  const [formData, setFormData] = useState<Partial<CommercialRecord>>({
    city: 'PAN-INDIA',
    type: CommercialType.MARGIN_PERCENT,
    startDate: new Date().toISOString().split('T')[0],
    endDate: new Date(new Date().setMonth(new Date().getMonth() + 3)).toISOString().split('T')[0],
    vertical: '',
    kam: ''
  });

  // Real-time Validation State
  const [instantConflict, setInstantConflict] = useState<boolean>(false);
  const [highMarginAlert, setHighMarginAlert] = useState<boolean>(false);

  // Bulk State
  const [bulkType, setBulkType] = useState<CommercialType>(CommercialType.MARGIN_PERCENT);

  const [loading, setLoading] = useState(false);
  const [notification, setNotification] = useState<{msg: string, type: 'success' | 'error' | 'warning' | null}>({ msg: '', type: null });

  // Initialize Data
  useEffect(() => {
    const init = async () => {
      // 1. Load Draft
      const draft = localStorage.getItem('mm_draft_form');
      let draftData = {};
      if (draft) {
        draftData = JSON.parse(draft);
        setFormData(draftData);
      }

      // 2. Load Cities and Validate
      const c = await db.getCities();
      setCities(c);

      // Validate the city from draft or current state
      const currentCity = (draftData as any).city || formData.city || 'PAN-INDIA';
      if (!c.includes(currentCity)) {
         setFormData(prev => ({ ...prev, city: c[0] || 'PAN-INDIA' }));
      }
    };

    init();
  }, []);

  // Save draft & Real-time Check
  useEffect(() => {
    localStorage.setItem('mm_draft_form', JSON.stringify(formData));

    // High Margin Check
    if (formData.type === CommercialType.MARGIN_PERCENT && (formData.value || 0) > 60) {
        setHighMarginAlert(true);
    } else {
        setHighMarginAlert(false);
    }

    // Debounce the conflict check
    const timeoutId = setTimeout(async () => {
        if(formData.fsn && formData.fsn.length === 16 && formData.city && formData.type && formData.startDate && formData.endDate) {
            const records = await db.getRecords();
            const conflict = checkForConflict(records, formData as CommercialRecord);
            setInstantConflict(conflict);
        } else {
            setInstantConflict(false);
        }
    }, 500);

    return () => clearTimeout(timeoutId);
  }, [formData]);

  const checkForConflict = (existingRecords: CommercialRecord[], input: CommercialRecord): boolean => {
      return existingRecords.some(r => {
        // 1. Match FSN & Type
        if (r.fsn !== input.fsn) return false;
        if (r.type !== input.type) return false;

        // 2. Check City Logic (Exact Match OR PAN-INDIA Collision)
        const cityConflict = (input.city === 'PAN-INDIA' || r.city === 'PAN-INDIA' || input.city === r.city);

        if (!cityConflict) return false;

        // 3. Date Logic based on Commercial Type
        const isOnOrOffInvoice = input.type === CommercialType.ON_INVOICE || input.type === CommercialType.OFF_INVOICE;

        if (isOnOrOffInvoice) {
            // SPECIAL RULE: For On/Off Invoice, overlaps are allowed (stacking).
            // Conflict ONLY if Exact Date Duplicate (Start & End match exactly).
            return input.startDate === r.startDate && input.endDate === r.endDate;
        } else {
            // STANDARD RULE: For Margin/NLC, NO overlaps allowed.
            // Check intersection: (StartA <= EndB) and (EndA >= StartB)
            return (input.startDate <= r.endDate) && (input.endDate >= r.startDate);
        }
      });
  };

  const refreshCities = async () => {
    const c = await db.getCities();
    setCities(c);
    return c;
  };

  const handleAddNewCity = async () => {
    if (!newCityCode) return;
    const code = newCityCode.toUpperCase().trim();
    if (code !== 'PAN-INDIA' && code.length > 3) {
       setNotification({ msg: 'City code must be 3 characters or less.', type: 'error' });
       return;
    }
    const cleanCode = code.replace(/[^A-Z0-9]/g, '');
    if (!cleanCode) return;
    if (cities.includes(cleanCode)) {
       setNotification({ msg: `City ${cleanCode} already exists.`, type: 'warning' });
       return;
    }
    if (cleanCode) {
       await db.addCity(cleanCode);
       await refreshCities();
       setFormData(prev => ({...prev, city: cleanCode}));
       setNewCityCode('');
       setIsAddingCity(false);
       setNotification({ msg: `City ${cleanCode} added.`, type: 'success' });
    }
  };

  const handleDeleteCity = async () => {
    const cityToDelete = formData.city;
    if (!cityToDelete || cityToDelete === 'PAN-INDIA') {
        setNotification({ msg: 'Cannot delete default PAN-INDIA city.', type: 'error' });
        return;
    }
    if (window.confirm(`Delete city code "${cityToDelete}"?`)) {
        try {
            await db.deleteCity(cityToDelete);
            const updatedCities = await refreshCities();
            setFormData(prev => ({ ...prev, city: updatedCities[0] || 'PAN-INDIA' }));
            setNotification({ msg: `City ${cityToDelete} removed.`, type: 'success' });
        } catch (err) {
            setNotification({ msg: 'Failed to delete city.', type: 'error' });
        }
    }
  };

  const handleManualSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setNotification({ msg: '', type: null });

    if (!formData.fsn || !formData.value || !formData.brand || !formData.title || !formData.vertical || !formData.kam) {
        setNotification({ msg: 'Please fill all fields', type: 'error' });
        return;
    }

    // Strict FSN Length Check
    if (formData.fsn.length !== 16) {
        setNotification({ msg: 'FSN must be exactly 16 characters.', type: 'error' });
        return;
    }

    // Validate Caps
    const isPercentage = formData.type === CommercialType.MARGIN_PERCENT || 
                         formData.type === CommercialType.NLC_PERCENT || 
                         formData.type === CommercialType.ON_INVOICE || 
                         formData.type === CommercialType.OFF_INVOICE;

    if (isPercentage && formData.value! > 100) {
        setNotification({ msg: `${formData.type} cannot exceed 100%`, type: 'error' });
        return;
    }

    if (formData.type !== CommercialType.MARGIN_PERCENT && formData.endDate! < formData.startDate!) {
        setNotification({ msg: 'End Date cannot be before Start Date', type: 'error' });
        return;
    }

    setLoading(true);

    try {
      const records = await db.getRecords();

      const isConflict = checkForConflict(records, formData as CommercialRecord);
      const isHighMargin = formData.type === CommercialType.MARGIN_PERCENT && (formData.value || 0) > 60;

      const newRecord: CommercialRecord = {
        id: `rec_${Date.now()}`,
        ...formData as CommercialRecord,
        value: Number(formData.value),
        lastUpdatedBy: user.name,
        lastUpdatedAt: Date.now()
      };

      if (isConflict || isHighMargin) {
        let reason = '';
        if (isConflict) {
            const isInvoice = formData.type === CommercialType.ON_INVOICE || formData.type === CommercialType.OFF_INVOICE;
            reason = isInvoice ? 'Exact Duplicate Conflict' : 'Duplicate/Overlap Conflict';
        }
        if (isHighMargin) reason = reason ? reason + ' & High Margin (>60%)' : 'High Margin (>60%)';

        const req: DuplicateRequest = {
          id: `req_${Date.now()}`,
          originalRecordId: null,
          payload: newRecord,
          requestedBy: user.name,
          requestedAt: Date.now(),
          status: 'PENDING',
          reason: reason
        };
        await db.createDuplicateRequest(req);
        setNotification({ msg: `Request sent to Checker: ${reason}`, type: 'warning' });
      } else {
        await db.addRecords([newRecord]);
        setNotification({ msg: 'Record saved successfully.', type: 'success' });
        setFormData(prev => ({ 
            ...prev, 
            fsn: '', 
            value: 0,
            // Reset dates to defaults
            startDate: new Date().toISOString().split('T')[0],
            endDate: new Date(new Date().setMonth(new Date().getMonth() + 3)).toISOString().split('T')[0]
        }));
      }
    } catch (err) {
      setNotification({ msg: 'Failed to save record.', type: 'error' });
    } finally {
      setLoading(false);
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    Papa.parse(file, {
      header: true,
      skipEmptyLines: true,
      complete: async (results) => {
        setLoading(true);

        // 1. Validate Headers
        const headers = results.meta.fields || [];
        const kamHeader = headers.find(h => h.toUpperCase() === 'KAM');

        if (!kamHeader) {
            setNotification({ msg: "Upload Failed: 'KAM' column is missing in the CSV file.", type: 'error' });
            setLoading(false);
            e.target.value = ''; 
            return;
        }

        const newRecords: CommercialRecord[] = [];
        const requests: DuplicateRequest[] = [];
        const existingRecords = await db.getRecords();

        let skipped = 0;
        let missingKam = 0;

        results.data.forEach((row: any) => {
           if(!row.FSN) return;

           if(row.FSN.length !== 16) {
               skipped++;
               return;
           }

           const kamValue = row[kamHeader] || row['KAM']; 
           if (!kamValue || !kamValue.trim()) {
               missingKam++;
               return; 
           }

           const cityKeys = Object.keys(row).filter(k => cities.includes(k) || k === 'Value');

           cityKeys.forEach(cityKey => {
             const city = cityKey === 'Value' ? 'PAN-INDIA' : cityKey;
             let val = parseFloat(row[cityKey]);
             if (isNaN(val)) return;

             const isPercentage = bulkType === CommercialType.MARGIN_PERCENT || 
                                  bulkType === CommercialType.NLC_PERCENT || 
                                  bulkType === CommercialType.ON_INVOICE || 
                                  bulkType === CommercialType.OFF_INVOICE;

             if (isPercentage && val > 100) val = 100;
             if (isPercentage && val <= 1 && val > 0) val = val * 100;

             const rec: CommercialRecord = {
               id: `rec_${Math.random().toString(36).substr(2,9)}`,
               fsn: row.FSN,
               brand: row.Brand || 'Unknown',
               title: row.Title || 'Bulk Upload Item',
               vertical: row.Vertical || 'Unknown',
               kam: kamValue,
               city: city,
               startDate: row.StartDate,
               endDate: row.EndDate,
               type: bulkType,
               value: val,
               lastUpdatedBy: user.name,
               lastUpdatedAt: Date.now()
             };

             const isConflict = checkForConflict(existingRecords, rec);
             const isHighMargin = bulkType === CommercialType.MARGIN_PERCENT && val > 60;

             if (isConflict || isHighMargin) {
               let reason = '';
               if (isConflict) {
                   const isInvoice = bulkType === CommercialType.ON_INVOICE || bulkType === CommercialType.OFF_INVOICE;
                   reason = isInvoice ? 'Exact Duplicate' : 'Duplicate/Overlap';
               }
               if (isHighMargin) reason = reason ? reason + ' & High Margin' : 'High Margin';

               const req: DuplicateRequest = {
                 id: `req_${Math.random().toString(36).substr(2,9)}`,
                 originalRecordId: null,
                 payload: rec,
                 requestedBy: user.name,
                 requestedAt: Date.now(),
                 status: 'PENDING',
                 reason: reason
               };
               requests.push(req);
             } else {
               newRecords.push(rec);
             }
           });
        });

        if (newRecords.length > 0) {
          await db.addRecords(newRecords);
        }

        if (requests.length > 0) {
           for (const req of requests) {
              await db.createDuplicateRequest(req);
           }
        }

        let msg = '';
        let type: 'success' | 'warning' | 'error' = 'success';

        if (newRecords.length > 0) msg += `Successfully uploaded ${newRecords.length} records. `;
        if (requests.length > 0) {
            msg += `${requests.length} sent for approval. `;
            type = 'warning';
        }
        if (skipped > 0) msg += `${skipped} skipped (Invalid FSN). `;
        if (missingKam > 0) msg += `${missingKam} skipped (Missing KAM). `;

        if (newRecords.length === 0 && requests.length === 0) {
            if (missingKam > 0 || skipped > 0) {
                 type = 'error';
                 if (!msg) msg = "No valid records found (check FSN or KAM).";
            } else {
                 type = 'error';
                 msg = "No valid records found in file.";
            }
        }

        setNotification({ msg, type });
        setLoading(false);
        e.target.value = '';
      }
    });
  };

  const downloadTemplate = () => {
    const headers = ['FSN', 'Brand', 'Title', 'Vertical', 'KAM', 'StartDate', 'EndDate', ...cities];
    const isNLC = bulkType === CommercialType.NLC_VALUE;
    const exampleVal = isNLC ? '50000' : '10';
    const dummyRows = [
        ['MOBEXAMPLE123456', 'BrandX', 'Sample Product 1', 'Mobiles', 'John Doe', '2024-01-01', '2024-03-31', ...cities.map(() => exampleVal)],
    ];
    const csvContent = [headers.join(','), ...dummyRows.map(row => row.join(','))].join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv' });
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `template_${bulkType.replace(/\s/g, '')}.csv`;
    a.click();
    window.URL.revokeObjectURL(url);
  };

  return (
    <div className="space-y-6 animate-in slide-in-from-bottom-4 duration-500 max-w-7xl mx-auto">
      <div className="flex justify-between items-center">
        <div>
           <h2 className="text-2xl font-bold text-gray-800">Maker Workspace</h2>
           <p className="text-sm text-gray-500">Manage commercials and offers</p>
        </div>
        <div className="flex bg-white rounded shadow-sm border border-gray-200 p-1">
          <button
            onClick={() => setActiveTab('MANUAL')}
            className={`px-4 py-2 rounded text-sm font-medium transition-all ${activeTab === 'MANUAL' ? 'bg-fkBlue text-white shadow' : 'text-gray-500 hover:text-gray-900'}`}
          >
            Manual Entry
          </button>
          <button
            onClick={() => setActiveTab('BULK')}
            className={`px-4 py-2 rounded text-sm font-medium transition-all ${activeTab === 'BULK' ? 'bg-fkBlue text-white shadow' : 'text-gray-500 hover:text-gray-900'}`}
          >
            Bulk Upload
          </button>
        </div>
      </div>

      {notification.msg && (
        <div className={`p-4 rounded border flex items-center gap-3 shadow-sm ${
          notification.type === 'error' ? 'bg-red-50 border-red-200 text-red-700' :
          notification.type === 'warning' ? 'bg-orange-50 border-orange-200 text-orange-800' :
          'bg-green-50 border-green-200 text-green-700'
        }`}>
          {notification.type === 'error' ? <AlertTriangle className="h-5 w-5"/> : <FileText className="h-5 w-5"/>}
          <span className="font-medium">{notification.msg}</span>
          <button onClick={() => setNotification({msg:'', type:null})} className="ml-auto hover:bg-white/50 rounded p-1"><X className="h-4 w-4"/></button>
        </div>
      )}

      {/* Alerts */}
      <div className="space-y-2">
          {instantConflict && activeTab === 'MANUAL' && (
            <div className="p-3 bg-red-50 border-l-4 border-red-500 rounded shadow-sm flex items-center gap-3 animate-in fade-in slide-in-from-top-2">
                <ShieldAlert className="text-red-500 w-6 h-6" />
                <div>
                    <p className="font-bold text-gray-800 text-sm">Conflict Detected!</p>
                    <p className="text-xs text-gray-600">
                        {(formData.type === CommercialType.ON_INVOICE || formData.type === CommercialType.OFF_INVOICE) 
                         ? 'Exact duplicate date range exists. Saving triggers approval.' 
                         : 'Overlap with existing record. Saving triggers approval.'}
                    </p>
                </div>
            </div>
          )}
          {highMarginAlert && activeTab === 'MANUAL' && (
            <div className="p-3 bg-yellow-50 border-l-4 border-fkYellow rounded shadow-sm flex items-center gap-3 animate-in fade-in slide-in-from-top-2">
                <AlertTriangle className="text-fkYellow w-6 h-6" />
                <div>
                    <p className="font-bold text-gray-800 text-sm">High Margin Alert!</p>
                    <p className="text-xs text-gray-600">Margin &gt; 60% requires checker approval.</p>
                </div>
            </div>
          )}
      </div>

      {activeTab === 'MANUAL' ? (
        <form onSubmit={handleManualSubmit} className="fk-card p-6 grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          <div className="col-span-1">
            <label className="block text-xs font-semibold text-gray-500 uppercase mb-1">FSN (Product ID) <span className="text-red-500">*</span></label>
            <div className="relative">
                <input 
                  className="w-full bg-white border border-gray-300 rounded p-2.5 text-gray-900 focus:border-fkBlue focus:ring-1 focus:ring-fkBlue outline-none transition-colors" 
                  value={formData.fsn || ''}
                  onChange={e => setFormData({...formData, fsn: e.target.value})}
                  placeholder="16 Characters Required"
                  maxLength={16}
                />
                <div className={`text-[10px] text-right mt-1 font-mono ${formData.fsn?.length === 16 ? 'text-green-600' : 'text-gray-400'}`}>
                    {formData.fsn?.length || 0}/16
                </div>
            </div>
          </div>
          <div className="col-span-1">
            <label className="block text-xs font-semibold text-gray-500 uppercase mb-1">Brand <span className="text-red-500">*</span></label>
            <input 
              className="w-full bg-white border border-gray-300 rounded p-2.5 text-gray-900 focus:border-fkBlue focus:ring-1 focus:ring-fkBlue outline-none transition-colors" 
              value={formData.brand || ''}
              onChange={e => setFormData({...formData, brand: e.target.value})}
              placeholder="e.g. Samsung"
            />
          </div>
          <div className="col-span-1">
            <label className="block text-xs font-semibold text-gray-500 uppercase mb-1">Title <span className="text-red-500">*</span></label>
            <input 
              className="w-full bg-white border border-gray-300 rounded p-2.5 text-gray-900 focus:border-fkBlue focus:ring-1 focus:ring-fkBlue outline-none transition-colors" 
              value={formData.title || ''}
              onChange={e => setFormData({...formData, title: e.target.value})}
              placeholder="Product Title"
            />
          </div>

          <div className="col-span-1">
            <label className="block text-xs font-semibold text-gray-500 uppercase mb-1 flex items-center gap-1"><Layers className="w-3 h-3"/> Vertical <span className="text-red-500">*</span></label>
            <input 
              className="w-full bg-white border border-gray-300 rounded p-2.5 text-gray-900 focus:border-fkBlue focus:ring-1 focus:ring-fkBlue outline-none transition-colors" 
              value={formData.vertical || ''}
              onChange={e => setFormData({...formData, vertical: e.target.value})}
              placeholder="e.g. Mobiles"
            />
          </div>

          <div className="col-span-1">
            <label className="block text-xs font-semibold text-gray-500 uppercase mb-1 flex items-center gap-1"><UserIcon className="w-3 h-3"/> KAM <span className="text-red-500">*</span></label>
            <input 
              className="w-full bg-white border border-gray-300 rounded p-2.5 text-gray-900 focus:border-fkBlue focus:ring-1 focus:ring-fkBlue outline-none transition-colors" 
              value={formData.kam || ''}
              onChange={e => setFormData({...formData, kam: e.target.value})}
              placeholder="Account Manager Name"
            />
          </div>

          <div className="col-span-1">
            <label className="block text-xs font-semibold text-gray-500 uppercase mb-1">City <span className="text-red-500">*</span></label>
            <div className="flex gap-2">
              {isAddingCity ? (
                <div className="flex-1 flex gap-1">
                   <input 
                     className="w-full bg-white border border-gray-300 rounded p-2.5 text-gray-900 uppercase"
                     placeholder="XXX"
                     autoFocus
                     value={newCityCode}
                     maxLength={3}
                     onChange={e => setNewCityCode(e.target.value)}
                   />
                   <button 
                     type="button" 
                     onClick={handleAddNewCity}
                     className="bg-fkGreen px-3 rounded text-white hover:bg-green-700"
                   >
                     <Check className="h-4 w-4" />
                   </button>
                   <button 
                     type="button" 
                     onClick={() => setIsAddingCity(false)}
                     className="bg-gray-200 px-3 rounded text-gray-700 hover:bg-gray-300"
                   >
                     <X className="h-4 w-4" />
                   </button>
                </div>
              ) : (
                <div className="flex-1 flex gap-2">
                  <select 
                    className="w-full bg-white border border-gray-300 rounded p-2.5 text-gray-900 focus:border-fkBlue focus:ring-1 focus:ring-fkBlue outline-none"
                    value={formData.city}
                    onChange={e => setFormData({...formData, city: e.target.value})}
                  >
                    {cities.map(c => <option key={c} value={c}>{c}</option>)}
                  </select>

                  <button 
                    type="button" 
                    onClick={() => setIsAddingCity(true)}
                    className="px-3 bg-gray-100 hover:bg-gray-200 rounded border border-gray-300 text-gray-600 transition-colors"
                    title="Add New City"
                  >
                    <Plus className="h-4 w-4" />
                  </button>

                  <button 
                    type="button"
                    onClick={handleDeleteCity}
                    disabled={formData.city === 'PAN-INDIA'}
                    className={`px-3 rounded border transition-colors ${formData.city === 'PAN-INDIA' ? 'bg-gray-100 border-gray-200 text-gray-400 cursor-not-allowed' : 'bg-red-50 border-red-200 text-red-600 hover:bg-red-100'}`}
                  >
                    <Trash2 className="h-4 w-4" />
                  </button>
                </div>
              )}
            </div>
          </div>

          <div className="col-span-1">
            <label className="block text-xs font-semibold text-gray-500 uppercase mb-1">Type <span className="text-red-500">*</span></label>
            <select 
              className="w-full bg-white border border-gray-300 rounded p-2.5 text-gray-900 focus:border-fkBlue focus:ring-1 focus:ring-fkBlue outline-none"
              value={formData.type}
              onChange={e => setFormData({...formData, type: e.target.value as CommercialType})}
            >
              <option value={CommercialType.MARGIN_PERCENT}>Margin %</option>
              <option value={CommercialType.NLC_VALUE}>NLC Value (Amount)</option>
              <option value={CommercialType.NLC_PERCENT}>NLC %</option>
              <option value={CommercialType.ON_INVOICE}>On Invoice %</option>
              <option value={CommercialType.OFF_INVOICE}>Off Invoice %</option>
            </select>
          </div>

          <div className="col-span-1">
            <label className="block text-xs font-semibold text-gray-500 uppercase mb-1">Value <span className="text-red-500">*</span></label>
            <input 
              type="number"
              className="w-full bg-white border border-gray-300 rounded p-2.5 text-gray-900 focus:border-fkBlue focus:ring-1 focus:ring-fkBlue outline-none font-mono" 
              value={formData.value || ''}
              onChange={e => setFormData({...formData, value: parseFloat(e.target.value)})}
              placeholder="0.00"
            />
            {/* Helper Text for Caps */}
            {formData.type?.includes('%') && (
                <p className="text-[10px] text-gray-400 mt-1">Capped at 100%</p>
            )}
          </div>

          {formData.type !== CommercialType.MARGIN_PERCENT && (
            <>
              <div className="col-span-1">
                <label className="block text-xs font-semibold text-gray-500 uppercase mb-1">Start Date</label>
                <input 
                  type="date"
                  className="w-full bg-white border border-gray-300 rounded p-2.5 text-gray-900 focus:border-fkBlue outline-none" 
                  value={formData.startDate}
                  onChange={e => setFormData({...formData, startDate: e.target.value})}
                />
              </div>
              <div className="col-span-1">
                <label className="block text-xs font-semibold text-gray-500 uppercase mb-1">End Date</label>
                <input 
                  type="date"
                  className="w-full bg-white border border-gray-300 rounded p-2.5 text-gray-900 focus:border-fkBlue outline-none" 
                  value={formData.endDate}
                  onChange={e => setFormData({...formData, endDate: e.target.value})}
                />
              </div>
            </>
          )}

          {/* Helper for Dates */}
          {(formData.type === CommercialType.ON_INVOICE || formData.type === CommercialType.OFF_INVOICE) && (
              <div className="col-span-full -mt-2 mb-2">
                  <p className="text-[10px] text-blue-600 flex items-center gap-1 bg-blue-50 w-fit px-2 py-1 rounded">
                      <Info className="w-3 h-3"/> 
                      Overlapping dates allowed for this type. Only exact duplicates require approval.
                  </p>
              </div>
          )}

          <div className="col-span-full flex justify-end pt-6 border-t border-gray-100">
             <button
               type="submit"
               disabled={loading}
               className="bg-fkYellow hover:bg-yellow-500 text-white font-bold py-2.5 px-8 rounded shadow-md hover:shadow-lg transition-all flex items-center gap-2"
             >
               {loading ? <span className="animate-spin">⌛</span> : <Save className="h-5 w-5" />}
               Save Record
             </button>
          </div>
        </form>
      ) : (
        <div className="space-y-6">
          <div className="bg-white p-6 rounded-lg border border-gray-200 shadow-sm">
             <label className="block text-xs font-bold text-gray-500 mb-4 uppercase tracking-wider">Select Upload Type</label>
             <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
               {COMMERCIAL_TYPES.map(type => (
                 <button
                   key={type}
                   onClick={() => setBulkType(type)}
                   className={`p-4 rounded border text-sm font-semibold transition-all ${
                     bulkType === type 
                     ? 'bg-fkBlue text-white border-fkBlue shadow-md' 
                     : 'bg-gray-50 text-gray-600 border-gray-200 hover:bg-white hover:border-gray-300 hover:shadow-sm'
                   }`}
                 >
                   {type}
                 </button>
               ))}
             </div>
          </div>

          <div className="flex justify-end">
            <button 
              onClick={downloadTemplate}
              className="flex items-center gap-2 px-4 py-2 bg-white hover:bg-gray-50 text-fkBlue font-medium rounded border border-gray-300 shadow-sm transition-colors text-sm"
            >
              <Download className="h-4 w-4" /> 
              Download Template
            </button>
          </div>

          <div className="fk-card border-dashed border-2 border-gray-300 p-12 flex flex-col items-center justify-center text-center hover:border-fkBlue hover:bg-blue-50/30 transition-all group cursor-pointer relative">
            <input 
              type="file" 
              accept=".csv"
              onChange={handleFileUpload}
              key={bulkType}
              className="absolute inset-0 w-full h-full opacity-0 cursor-pointer"
            />
            <div className="bg-blue-50 p-5 rounded-full mb-4 group-hover:scale-110 transition-transform">
               <Upload className="h-10 w-10 text-fkBlue" />
            </div>
            <h3 className="text-xl font-bold text-gray-800">Upload {bulkType} CSV</h3>
            <p className="text-gray-500 mt-2">
              Drag and drop or click to upload
            </p>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { db } from '../services/db';
import { DuplicateRequest, User, CommercialType } from '../types';
import { Check, X, Search, BarChart3, Archive, TrendingUp, AlertCircle, FileDown, Calendar, Trash2, Database, Clock, ChevronDown, User as UserIcon, Layers, Upload, FileText, RefreshCw } from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer, ReferenceLine, LabelList } from 'recharts';
import Papa from 'papaparse';

interface CheckerProps {
  user: User;
}

export const CheckerWorkspace: React.FC<CheckerProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<'AUDIT' | 'APPROVALS' | 'CLOSURE'>('AUDIT');
  const [requests, setRequests] = useState<DuplicateRequest[]>([]);
  const [cities, setCities] = useState<string[]>([]);

  // Audit State (Single)
  const [auditMode, setAuditMode] = useState<'SINGLE' | 'BULK'>('SINGLE');
  const [auditQuery, setAuditQuery] = useState({ fsn: '', city: 'BLR', targetMargin: 0 });
  const [auditResult, setAuditResult] = useState<any>(null);

  // Audit State (Bulk)
  const [bulkAuditData, setBulkAuditData] = useState<any[]>([]);
  const [bulkAuditCity, setBulkAuditCity] = useState('BLR');
  const [bulkResults, setBulkResults] = useState<any[] | null>(null);
  const [bulkFile, setBulkFile] = useState<string | null>(null);

  const [loading, setLoading] = useState(false);

  // Autocomplete State
  const [allFsns, setAllFsns] = useState<string[]>([]);
  const [filteredFsns, setFilteredFsns] = useState<string[]>([]);
  const [showSuggestions, setShowSuggestions] = useState(false);

  // Closure/Export State
  const [selectedMonth, setSelectedMonth] = useState(new Date().toISOString().slice(0, 7)); // YYYY-MM
  const [exportLoading, setExportLoading] = useState(false);

  // Archive View State
  const [showArchive, setShowArchive] = useState(false);
  const [archiveData, setArchiveData] = useState<any[]>([]);

  useEffect(() => {
    loadRequests();
    loadCities();
    loadUniqueFsns();
    const interval = setInterval(loadRequests, 5000);
    return () => clearInterval(interval);
  }, []);

  const loadCities = async () => {
    const c = await db.getCities();
    setCities(c);
    if (!c.includes(auditQuery.city)) {
       setAuditQuery(prev => ({ ...prev, city: c.includes('BLR') ? 'BLR' : c[0] || '' }));
    }
  };

  const loadUniqueFsns = async () => {
    const records = await db.getRecords();
    const unique = Array.from(new Set(records.map(r => r.fsn)));
    setAllFsns(unique);
  };

  const loadRequests = async () => {
    const reqs = await db.getDuplicateRequests();
    setRequests(reqs.filter(r => r.status === 'PENDING'));
  };

  const loadArchive = async () => {
    const data = await db.getBinRecords();
    setArchiveData(data.sort((a: any, b: any) => b.deletedAt - a.deletedAt));
  };

  const toggleArchive = () => {
      if (!showArchive) loadArchive();
      setShowArchive(!showArchive);
  };

  const handleFsnChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = e.target.value;
    setAuditQuery({ ...auditQuery, fsn: val });

    if (val.length > 0) {
        const matches = allFsns.filter(f => f.toLowerCase().includes(val.toLowerCase()));
        setFilteredFsns(matches.slice(0, 5)); // Limit to 5 suggestions
        setShowSuggestions(true);
    } else {
        setShowSuggestions(false);
    }
  };

  const selectSuggestion = (fsn: string) => {
      setAuditQuery({ ...auditQuery, fsn });
      setShowSuggestions(false);
  };

  // SINGLE AUDIT Logic
  const handleAudit = async () => {
    if (!auditQuery.fsn) return;

    if (auditQuery.fsn.length !== 16) {
        alert("FSN must be exactly 16 characters.");
        return;
    }

    setLoading(true);
    setShowSuggestions(false); 

    const records = await db.getRecords();

    const relevant = records.filter(r => 
      r.fsn === auditQuery.fsn && 
      (r.city === auditQuery.city || r.city === 'PAN-INDIA')
    );

    const getEffectiveValue = (type: CommercialType) => {
        const specific = relevant.find(r => r.type === type && r.city === auditQuery.city);
        if (specific) return { val: specific.value, source: 'CITY' };

        const pan = relevant.find(r => r.type === type && r.city === 'PAN-INDIA');
        if (pan) return { val: pan.value, source: 'PAN' };

        return { val: 0, source: 'NONE' };
    };

    const nlcObj = getEffectiveValue(CommercialType.NLC_VALUE);
    const onInvObj = getEffectiveValue(CommercialType.ON_INVOICE);

    const nlc = nlcObj.val; 
    const onInv = onInvObj.val;

    const systemTotal = nlc + onInv; 
    const variance = auditQuery.targetMargin - systemTotal;
    const variancePercent = auditQuery.targetMargin ? ((variance / auditQuery.targetMargin) * 100) : 0;

    setAuditResult({
      data: [
        { name: 'System', nlc: nlc, onInv: onInv, total: systemTotal },
        { name: 'Target', target: auditQuery.targetMargin }
      ],
      systemTotal,
      targetTotal: auditQuery.targetMargin,
      variance,
      variancePercent: variancePercent.toFixed(2),
      status: Math.abs(variance) < 0.1 ? 'MATCH' : 'MISMATCH',
      details: relevant,
      sources: { nlc: nlcObj.source, onInv: onInvObj.source }
    });
    setLoading(false);
  };

  // BULK AUDIT Handlers
  const handleBulkUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (!file) return;
      setBulkFile(file.name);
      Papa.parse(file, {
          header: true,
          skipEmptyLines: true,
          complete: (results) => {
              setBulkAuditData(results.data);
              setBulkResults(null);
          }
      });
  };

  const runBulkAudit = async () => {
      if (bulkAuditData.length === 0) return;
      setLoading(true);

      const records = await db.getRecords();
      const today = new Date().toISOString().split('T')[0];

      const processed = bulkAuditData.map((row: any) => {
          const fsn = row['FSN'];
          const targetVal = parseFloat(row['Margin Value'] || '0');
          const unit = (row['Margin Value Unit'] || '').toUpperCase();

          if (!fsn) return null;

          // 1. Filter relevant records (Active & City Match)
          const activeRecords = records.filter(r => 
              r.fsn === fsn && 
              (r.city === bulkAuditCity || r.city === 'PAN-INDIA') &&
              r.startDate <= today && r.endDate >= today
          );

          let baseVal = 0;
          let baseType = '-';
          let offInvVal = 0;
          let offInvSource = '-';

          // 2. Logic based on Unit
          // "if Margin Value Unit contains PERCENT than fetch data based on FSN and City from Margin % if not check NLC %"
          if (unit.includes('PERCENT')) {
             // Priority: Margin % > NLC %
             // Check Specific City First, then PAN-INDIA
             const getRec = (type: CommercialType) => 
                activeRecords.find(r => r.type === type && r.city === bulkAuditCity) ||
                activeRecords.find(r => r.type === type && r.city === 'PAN-INDIA');

             const marginRec = getRec(CommercialType.MARGIN_PERCENT);
             if (marginRec) {
                 baseVal = marginRec.value;
                 baseType = 'Margin %';
             } else {
                 const nlcRec = getRec(CommercialType.NLC_PERCENT);
                 if (nlcRec) {
                     baseVal = nlcRec.value;
                     baseType = 'NLC %';
                 }
             }
          } else {
             // Assume Value/Amount
             // "if Margin Value Unit contains Value than fetch data based on FSN and City from NLC Value (Amount)"
             const getRec = (type: CommercialType) => 
                activeRecords.find(r => r.type === type && r.city === bulkAuditCity) ||
                activeRecords.find(r => r.type === type && r.city === 'PAN-INDIA');

             const nlcValRec = getRec(CommercialType.NLC_VALUE);
             if (nlcValRec) {
                 baseVal = nlcValRec.value;
                 baseType = 'NLC Value';
             }
          }

          // 3. Off Invoice Logic
          // "if found consider current date and fetch off invoice %"
          const getOffRec = () => 
            activeRecords.find(r => r.type === CommercialType.OFF_INVOICE && r.city === bulkAuditCity) ||
            activeRecords.find(r => r.type === CommercialType.OFF_INVOICE && r.city === 'PAN-INDIA');

          const offRec = getOffRec();
          if (offRec) {
              offInvVal = offRec.value;
              offInvSource = offRec.city === 'PAN-INDIA' ? 'PAN' : 'City';
          }

          // 4. Calculate System Total & Variance
          let systemTotal = 0;
          let variance = 0;

          if (unit.includes('PERCENT')) {
              // Can sum percentages
              systemTotal = baseVal + offInvVal;
              variance = targetVal - systemTotal;
          } else {
              // Value Audit: Cannot add % to Amount. 
              // Compare Target (Amount) vs Base (Amount). Off Invoice is just informational.
              systemTotal = baseVal;
              variance = targetVal - systemTotal;
          }

          const status = Math.abs(variance) < 0.01 ? 'MATCH' : 'MISMATCH';

          // Get Title for display
          const title = activeRecords[0]?.title || 'Unknown Title';

          return {
              fsn,
              title,
              targetVal,
              unit,
              baseVal,
              baseType,
              offInvVal,
              offInvSource,
              systemTotal,
              variance,
              status
          };
      }).filter(Boolean);

      setBulkResults(processed);
      setLoading(false);
  };

  const handleRequestAction = async (reqId: string, action: 'APPROVED' | 'REJECTED') => {
    await db.resolveDuplicateRequest(reqId, action, user.id);
    loadRequests();
    loadUniqueFsns();
  };

  const handleExport = async (mode: 'MONTH' | 'FULL') => {
    setExportLoading(true);
    try {
        const records = await db.getRecords();
        let dataToExport = records;

        if (mode === 'MONTH') {
            const [year, month] = selectedMonth.split('-').map(Number);
            const startOfMonth = new Date(year, month - 1, 1).toISOString().split('T')[0];
            const endOfMonth = new Date(year, month, 0).toISOString().split('T')[0];
            dataToExport = records.filter(r => r.startDate <= endOfMonth && r.endDate >= startOfMonth);
        }

        const csv = Papa.unparse(dataToExport.map(r => ({
            ID: r.id,
            FSN: r.fsn,
            Brand: r.brand,
            Title: r.title,
            Vertical: r.vertical,
            KAM: r.kam,
            City: r.city,
            Type: r.type,
            Value: r.value,
            StartDate: r.startDate,
            EndDate: r.endDate,
            LastUpdatedBy: r.lastUpdatedBy,
            LastUpdatedAt: new Date(r.lastUpdatedAt).toISOString()
        })));

        const blob = new Blob([csv], { type: 'text/csv' });
        const url = window.URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `mm_export_${mode.toLowerCase()}_${Date.now()}.csv`;
        a.click();
        window.URL.revokeObjectURL(url);
    } catch (e) {
        alert('Export failed');
    } finally {
        setExportLoading(false);
    }
  };

  const handleClearDB = async () => {
    if (window.confirm("CRITICAL: Delete all active records for Month End?")) {
        const confirmText = prompt("Type 'DELETE' to confirm:");
        if (confirmText === 'DELETE') {
            setLoading(true);
            try {
                await db.clearAllRecords(user.name);
                alert("Database reset. Records archived.");
                setAuditResult(null);
                setRequests([]);
                loadArchive();
                setAllFsns([]);
                setBulkResults(null);
            } catch (e) {
                alert("Failed.");
            } finally {
                setLoading(false);
            }
        }
    }
  };

  const CustomTooltip = ({ active, payload, label }: any) => {
    if (active && payload && payload.length) {
      return (
        <div className="bg-white border border-gray-200 p-3 rounded shadow-lg text-xs">
          <p className="font-bold text-gray-800 mb-2">{label}</p>
          {payload.map((entry: any, index: number) => (
            <div key={index} className="flex items-center gap-2 mb-1">
               <div className="w-2 h-2 rounded-full" style={{ backgroundColor: entry.color }} />
               <span className="text-gray-500">{entry.name}:</span>
               <span className="text-gray-900 font-mono font-bold">{Number(entry.value).toFixed(2)}</span>
            </div>
          ))}
          {label === 'System' && (
             <div className="mt-2 pt-2 border-t border-gray-100 flex justify-between gap-4">
                <span className="text-gray-600 font-bold">Total:</span>
