import { CommercialRecord, DuplicateRequest, User, Role, CommercialType, CITIES as DEFAULT_CITIES } from '../types';

const DB_NAME = 'MinutesMasterDB';
const DB_VERSION = 1;

// Store Names
const STORE_RECORDS = 'records';
const STORE_REQUESTS = 'requests';
const STORE_BIN = 'bin';
const STORE_USERS = 'users';
const STORE_CONFIG = 'config';

const STORAGE_KEYS_LEGACY = {
  USERS: 'mm_users',
  RECORDS: 'mm_records',
  REQUESTS: 'mm_requests',
  BIN: 'mm_bin',
  CITIES: 'mm_cities'
};

// Seed Data
const SEED_USERS: User[] = [
  { id: '1', employeeId: 'maker1', name: 'Maker', role: Role.MAKER },
  { id: '2', employeeId: 'checker1', name: 'Checker', role: Role.CHECKER, pin: '1234' },
  { id: '3', employeeId: 'admin1', name: 'Admin', role: Role.ADMIN, pin: '9999' },
];

type RecordListener = (records: CommercialRecord[]) => void;

class DBService {
  private dbPromise: Promise<IDBDatabase> | null = null;
  private listeners: RecordListener[] = [];

  constructor() {
    this.init();
  }

  // --- IndexedDB Core Wrappers ---

  private async getDB(): Promise<IDBDatabase> {
    if (this.dbPromise) return this.dbPromise;

    this.dbPromise = new Promise((resolve, reject) => {
      const request = indexedDB.open(DB_NAME, DB_VERSION);

      request.onupgradeneeded = (event) => {
        const db = (event.target as IDBOpenDBRequest).result;

        if (!db.objectStoreNames.contains(STORE_RECORDS)) {
          db.createObjectStore(STORE_RECORDS, { keyPath: 'id' });
        }
        if (!db.objectStoreNames.contains(STORE_REQUESTS)) {
          db.createObjectStore(STORE_REQUESTS, { keyPath: 'id' });
        }
        if (!db.objectStoreNames.contains(STORE_BIN)) {
          // Bin needs to allow multiple deleted versions, so we use autoIncrement
          db.createObjectStore(STORE_BIN, { keyPath: 'binId', autoIncrement: true });
        }
        if (!db.objectStoreNames.contains(STORE_USERS)) {
          db.createObjectStore(STORE_USERS, { keyPath: 'id' });
        }
        if (!db.objectStoreNames.contains(STORE_CONFIG)) {
          db.createObjectStore(STORE_CONFIG, { keyPath: 'key' });
        }
      };

      request.onsuccess = (event) => {
        resolve((event.target as IDBOpenDBRequest).result);
      };

      request.onerror = (event) => {
        console.error("IDB Open Error:", (event.target as IDBOpenDBRequest).error);
        reject((event.target as IDBOpenDBRequest).error);
      };
    });

    return this.dbPromise;
  }

  private async transaction<T>(
    storeNames: string | string[], 
    mode: IDBTransactionMode, 
    callback: (store: IDBObjectStore) => IDBRequest<T> | void
  ): Promise<T> {
    const db = await this.getDB();
    return new Promise((resolve, reject) => {
      const tx = db.transaction(storeNames, mode);
      const store = tx.objectStore(Array.isArray(storeNames) ? storeNames[0] : storeNames);

      let req: IDBRequest | void;
      try {
        req = callback(store);
      } catch (e) {
        reject(e);
        return;
      }

      tx.oncomplete = () => {
        resolve(req ? req.result : undefined);
      };
      tx.onerror = () => reject(tx.error);
    });
  }

  private async getAll<T>(storeName: string): Promise<T[]> {
    return this.transaction(storeName, 'readonly', (store) => store.getAll());
  }

  private async get<T>(storeName: string, key: string): Promise<T | undefined> {
    return this.transaction(storeName, 'readonly', (store) => store.get(key));
  }

  private async put(storeName: string, value: any): Promise<void> {
    await this.transaction(storeName, 'readwrite', (store) => store.put(value));
  }

  private async bulkPut(storeName: string, values: any[]): Promise<void> {
    const db = await this.getDB();
    return new Promise((resolve, reject) => {
      const tx = db.transaction(storeName, 'readwrite');
      const store = tx.objectStore(storeName);

      values.forEach(v => store.put(v));

      tx.oncomplete = () => resolve();
      tx.onerror = () => reject(tx.error);
    });
  }

  private async delete(storeName: string, key: string | number): Promise<void> {
    await this.transaction(storeName, 'readwrite', (store) => store.delete(key));
  }

  private async bulkDelete(storeName: string, keys: string[]): Promise<void> {
      const db = await this.getDB();
      return new Promise((resolve, reject) => {
        const tx = db.transaction(storeName, 'readwrite');
        const store = tx.objectStore(storeName);
        keys.forEach(k => store.delete(k));
        tx.oncomplete = () => resolve();
        tx.onerror = () => reject(tx.error);
      });
  }

  private async clear(storeName: string): Promise<void> {
    await this.transaction(storeName, 'readwrite', (store) => store.clear());
  }

  // --- Initialization & Migration ---

  async init() {
    try {
        const db = await this.getDB();

        // 1. Check if we need to migrate from LocalStorage
        const legacyRecords = localStorage.getItem(STORAGE_KEYS_LEGACY.RECORDS);
        if (legacyRecords) {
            await this.migrateFromLocalStorage();
        } else {
            // 2. Check if we need to seed initial data (Users/Cities)
            const users = await this.getAll<User>(STORE_USERS);
            if (users.length === 0) {
                await this.bulkPut(STORE_USERS, SEED_USERS);
            }

            const cityConfig = await this.get<{key: string, value: string[]}>(STORE_CONFIG, 'cities');
            if (!cityConfig) {
                await this.put(STORE_CONFIG, { key: 'cities', value: DEFAULT_CITIES });
            }
        }
    } catch (e) {
        console.error("DB Init Failed", e);
    }
  }

  private async migrateFromLocalStorage() {
      console.log("Migrating from LocalStorage to IndexedDB...");
      try {
          // Records
          const records = JSON.parse(localStorage.getItem(STORAGE_KEYS_LEGACY.RECORDS) || '[]');
          if(records.length > 0) await this.bulkPut(STORE_RECORDS, records);

          // Users
          let users = JSON.parse(localStorage.getItem(STORAGE_KEYS_LEGACY.USERS) || '[]');
          if (users.length === 0) users = SEED_USERS;
          await this.bulkPut(STORE_USERS, users);

          // Requests
          const requests = JSON.parse(localStorage.getItem(STORAGE_KEYS_LEGACY.REQUESTS) || '[]');
          if(requests.length > 0) await this.bulkPut(STORE_REQUESTS, requests);

          // Bin
          const bin = JSON.parse(localStorage.getItem(STORAGE_KEYS_LEGACY.BIN) || '[]');
          // Bin items in legacy didn't have a binId, autoIncrement will handle it
          if(bin.length > 0) await this.bulkPut(STORE_BIN, bin);

          // Cities
          const cities = JSON.parse(localStorage.getItem(STORAGE_KEYS_LEGACY.CITIES) || JSON.stringify(DEFAULT_CITIES));
          await this.put(STORE_CONFIG, { key: 'cities', value: cities });

          // Cleanup LocalStorage
          localStorage.removeItem(STORAGE_KEYS_LEGACY.RECORDS);
          localStorage.removeItem(STORAGE_KEYS_LEGACY.REQUESTS);
          localStorage.removeItem(STORAGE_KEYS_LEGACY.BIN);
          // We keep USERS and CITIES keys in LS as backups or remove them? 
          // Let's remove to ensure single source of truth, but AUTH component might be reading LS in this demo.
          // Wait, the Auth component in this app calls db.login(), which we will update.
          localStorage.removeItem(STORAGE_KEYS_LEGACY.USERS); 
          localStorage.removeItem(STORAGE_KEYS_LEGACY.CITIES);

          console.log("Migration Complete.");
      } catch (e) {
          console.error("Migration Failed", e);
      }
  }

  // --- Public API ---

  // Subscriptions
  subscribeToRecords(callback: RecordListener): () => void {
    this.listeners.push(callback);
    this.getRecords().then(records => callback(records));
    return () => {
      this.listeners = this.listeners.filter(l => l !== callback);
    };
  }

  private async notifyListeners() {
    const records = await this.getRecords();
    this.listeners.forEach(l => l(records));
  }

  // Auth
  async login(employeeId: string): Promise<User | null> {
    const users = await this.getAll<User>(STORE_USERS);
    return users.find(u => u.employeeId === employeeId) || null;
  }

  async verifyPin(userId: string, pin: string): Promise<boolean> {
    const user = await this.get<User>(STORE_USERS, userId);
    return user ? user.pin === pin : false;
  }

  // Cities
  async getCities(): Promise<string[]> {
    const config = await this.get<{key: string, value: string[]}>(STORE_CONFIG, 'cities');
    return config ? config.value : DEFAULT_CITIES;
  }

  async addCity(city: string): Promise<void> {
    const cities = await this.getCities();
    if (!cities.includes(city)) {
      cities.push(city);
      await this.put(STORE_CONFIG, { key: 'cities', value: cities });
    }
  }

  async deleteCity(city: string): Promise<void> {
    const cities = await this.getCities();
    const updated = cities.filter(c => c !== city);
    await this.put(STORE_CONFIG, { key: 'cities', value: updated });
  }

  // Records
  async getRecords(): Promise<CommercialRecord[]> {
    return this.getAll<CommercialRecord>(STORE_RECORDS);
  }

  async addRecords(records: CommercialRecord[]): Promise<void> {
    await this.bulkPut(STORE_RECORDS, records);
    await this.notifyListeners();
  }

  async updateRecord(updatedRecord: CommercialRecord): Promise<void> {
    await this.put(STORE_RECORDS, updatedRecord);
    await this.notifyListeners();
  }

  async updateRecords(updatedRecords: CommercialRecord[]): Promise<void> {
    await this.bulkPut(STORE_RECORDS, updatedRecords);
    await this.notifyListeners();
  }

  async deleteRecord(recordId: string, movedToBinBy: string): Promise<void> {
      const record = await this.get<CommercialRecord>(STORE_RECORDS, recordId);
      if (record) {
          await this.put(STORE_BIN, { ...record, deletedBy: movedToBinBy, deletedAt: Date.now() });
          await this.delete(STORE_RECORDS, recordId);
          await this.notifyListeners();
      }
  }

  async deleteRecords(recordIds: string[], movedToBinBy: string): Promise<void> {
      const db = await this.getDB();
      const tx = db.transaction([STORE_RECORDS, STORE_BIN], 'readwrite');
      const recordStore = tx.objectStore(STORE_RECORDS);
      const binStore = tx.objectStore(STORE_BIN);
      const timestamp = Date.now();

      // We need to fetch, then move to bin, then delete
      // To do this in one transaction for consistency

      // Since we can't easily await inside the tx loop for 'getAll', we do it optimistically or one by one
      // Let's do a cursor or multiple requests.

      for (const id of recordIds) {
          // 1. Get
          const getReq = recordStore.get(id);
          getReq.onsuccess = () => {
              const rec = getReq.result;
              if (rec) {
                  // 2. Put to Bin
                  binStore.put({ ...rec, deletedBy: movedToBinBy, deletedAt: timestamp });
                  // 3. Delete
                  recordStore.delete(id);
              }
          };
      }

      return new Promise((resolve, reject) => {
          tx.oncomplete = () => {
              this.notifyListeners(); // Notify after complete
              resolve();
          };
          tx.onerror = () => reject(tx.error);
      });
  }

  async getBinRecords(): Promise<any[]> {
    return this.getAll(STORE_BIN);
  }

  async clearAllRecords(clearedBy: string): Promise<void> {
    // Transaction to move all active to bin and clear active
    const db = await this.getDB();
    const tx = db.transaction([STORE_RECORDS, STORE_BIN, STORE_REQUESTS], 'readwrite');
    const recordStore = tx.objectStore(STORE_RECORDS);
    const binStore = tx.objectStore(STORE_BIN);
    const reqStore = tx.objectStore(STORE_REQUESTS);
    const timestamp = Date.now();

    const cursorReq = recordStore.openCursor();

    cursorReq.onsuccess = (e) => {
        const cursor = (e.target as IDBRequest).result as IDBCursorWithValue;
        if (cursor) {
            const rec = cursor.value;
            binStore.put({ ...rec, deletedBy: clearedBy, deletedAt: timestamp, note: 'BATCH_CLEAR_MONTH_END' });
            cursor.continue();
        }
    };

    // After cursor finishes? No, openCursor iterates. 
    // Actually, getting all then clearing is safer logic for simple code
    // But inside a transaction, 'clear' happens immediately. 
    // Let's use the helper methods for simplicity, though transaction is atomic.

    // Safer implementation:
    const records = await this.getAll<CommercialRecord>(STORE_RECORDS);

    // Re-open atomic transaction for the write part
    const writeTx = db.transaction([STORE_RECORDS, STORE_BIN, STORE_REQUESTS], 'readwrite');
    const wRecStore = writeTx.objectStore(STORE_RECORDS);
    const wBinStore = writeTx.objectStore(STORE_BIN);
    const wReqStore = writeTx.objectStore(STORE_REQUESTS);

    records.forEach(r => {
        wBinStore.put({ ...r, deletedBy: clearedBy, deletedAt: timestamp, note: 'BATCH_CLEAR_MONTH_END' });
    });

    wRecStore.clear();
    wReqStore.clear();

    return new Promise((resolve, reject) => {
        writeTx.oncomplete = () => {
            this.notifyListeners();
            resolve();
        };
        writeTx.onerror = () => reject(writeTx.error);
    });
  }

  // Requests
  async getDuplicateRequests(): Promise<DuplicateRequest[]> {
    return this.getAll<DuplicateRequest>(STORE_REQUESTS);
  }

  async createDuplicateRequest(request: DuplicateRequest): Promise<void> {
    await this.put(STORE_REQUESTS, request);
  }

  async createDuplicateRequests(requests: DuplicateRequest[]): Promise<void> {
    await this.bulkPut(STORE_REQUESTS, requests);
  }

  async resolveDuplicateRequest(requestId: string, status: 'APPROVED' | 'REJECTED', resolverId: string): Promise<void> {
    const request = await this.get<DuplicateRequest>(STORE_REQUESTS, requestId);
    if (!request) return;

    request.status = status;
    await this.put(STORE_REQUESTS, request); // Update status

    if (status === 'APPROVED') {
        const newRec = request.payload;
        const allRecords = await this.getRecords();
        const isInvoice = newRec.type === CommercialType.ON_INVOICE || newRec.type === CommercialType.OFF_INVOICE;

        // Find Conflicts
        let idsToDelete: string[] = [];

        if (isInvoice) {
            idsToDelete = allRecords.filter(r => 
                r.fsn === newRec.fsn &&
                r.city === newRec.city &&
                r.type === newRec.type &&
                r.startDate === newRec.startDate &&
                r.endDate === newRec.endDate
            ).map(r => r.id);
        } else {
             idsToDelete = allRecords.filter(r => 
                r.fsn === newRec.fsn &&
                r.city === newRec.city &&
                r.type === newRec.type &&
                (newRec.startDate <= r.endDate && newRec.endDate >= r.startDate)
            ).map(r => r.id);
        }

        if (idsToDelete.length > 0) {
            await this.deleteRecords(idsToDelete, resolverId);
        }
        await this.addRecords([newRec]);
    }
  }
}

export const db = new DBService();

import React, { useState, useEffect } from 'react';
import { CommercialRecord, CommercialType, DuplicateRequest, User, COMMERCIAL_TYPES } from '../types';
import { db } from '../services/db';
import { Plus, Upload, Save, AlertTriangle, FileText, X, Download, Check, Trash2, ArrowUpRight, ShieldAlert, User as UserIcon, Layers, Info } from 'lucide-react';
import Papa from 'papaparse';

interface MakerProps {
  user: User;
}

export const MakerWorkspace: React.FC<MakerProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<'MANUAL' | 'BULK'>('MANUAL');

  // Dynamic Cities
  const [cities, setCities] = useState<string[]>([]);
  const [isAddingCity, setIsAddingCity] = useState(false);
  const [newCityCode, setNewCityCode] = useState('');

  // Manual Form State
  const [formData, setFormData] = useState<Partial<CommercialRecord>>({
    city: 'PAN-INDIA',
    type: CommercialType.MARGIN_PERCENT,
    startDate: new Date().toISOString().split('T')[0],
    endDate: new Date(new Date().setMonth(new Date().getMonth() + 3)).toISOString().split('T')[0],
    vertical: '',
    kam: ''
  });

  // Real-time Validation State
  const [instantConflict, setInstantConflict] = useState<boolean>(false);
  const [highMarginAlert, setHighMarginAlert] = useState<boolean>(false);

  // Bulk State
  const [bulkType, setBulkType] = useState<CommercialType>(CommercialType.MARGIN_PERCENT);

  const [loading, setLoading] = useState(false);
  const [notification, setNotification] = useState<{msg: string, type: 'success' | 'error' | 'warning' | null}>({ msg: '', type: null });

  // Initialize Data
  useEffect(() => {
    const init = async () => {
      // 1. Load Draft
      const draft = localStorage.getItem('mm_draft_form');
      let draftData = {};
      if (draft) {
        draftData = JSON.parse(draft);
        setFormData(draftData);
      }

      // 2. Load Cities and Validate
      const c = await db.getCities();
      setCities(c);

      // Validate the city from draft or current state
      const currentCity = (draftData as any).city || formData.city || 'PAN-INDIA';
      if (!c.includes(currentCity)) {
         setFormData(prev => ({ ...prev, city: c[0] || 'PAN-INDIA' }));
      }
    };

    init();
  }, []);

  // Save draft & Real-time Check
  useEffect(() => {
    localStorage.setItem('mm_draft_form', JSON.stringify(formData));

    // High Margin Check
    if (formData.type === CommercialType.MARGIN_PERCENT && (formData.value || 0) > 60) {
        setHighMarginAlert(true);
    } else {
        setHighMarginAlert(false);
    }

    // Debounce the conflict check
    const timeoutId = setTimeout(async () => {
        if(formData.fsn && formData.fsn.length === 16 && formData.city && formData.type && formData.startDate && formData.endDate) {
            const records = await db.getRecords();
            const conflict = checkForConflict(records, formData as CommercialRecord);
            setInstantConflict(conflict);
        } else {
            setInstantConflict(false);
        }
    }, 500);

    return () => clearTimeout(timeoutId);
  }, [formData]);

  const checkForConflict = (existingRecords: CommercialRecord[], input: CommercialRecord): boolean => {
      return existingRecords.some(r => {
        // 1. Match FSN & Type
        if (r.fsn !== input.fsn) return false;
        if (r.type !== input.type) return false;

        // 2. Check City Logic (Exact Match OR PAN-INDIA Collision)
        // If entering specific city, check against existing specific city OR PAN-INDIA
        const cityConflict = (input.city === 'PAN-INDIA' || r.city === 'PAN-INDIA' || input.city === r.city);

        if (!cityConflict) return false;

        // 3. Date Logic based on Commercial Type
        const isOnOrOffInvoice = input.type === CommercialType.ON_INVOICE || input.type === CommercialType.OFF_INVOICE;

        if (isOnOrOffInvoice) {
            // SPECIAL RULE: For On/Off Invoice, overlaps are allowed (stacking).
            // Conflict ONLY if Exact Date Duplicate (Start & End match exactly).
            return input.startDate === r.startDate && input.endDate === r.endDate;
        } else {
            // STANDARD RULE: For Margin/NLC, NO overlaps allowed.
            // Check intersection: (StartA <= EndB) and (EndA >= StartB)
            return (input.startDate <= r.endDate) && (input.endDate >= r.startDate);
        }
      });
  };

  const refreshCities = async () => {
    const c = await db.getCities();
    setCities(c);
    return c;
  };

  const handleAddNewCity = async () => {
    if (!newCityCode) return;
    const code = newCityCode.toUpperCase().trim();
    if (code !== 'PAN-INDIA' && code.length > 3) {
       setNotification({ msg: 'City code must be 3 characters or less.', type: 'error' });
       return;
    }
    const cleanCode = code.replace(/[^A-Z0-9]/g, '');
    if (!cleanCode) return;
    if (cities.includes(cleanCode)) {
       setNotification({ msg: `City ${cleanCode} already exists.`, type: 'warning' });
       return;
    }
    if (cleanCode) {
       await db.addCity(cleanCode);
       await refreshCities();
       setFormData(prev => ({...prev, city: cleanCode}));
       setNewCityCode('');
       setIsAddingCity(false);
       setNotification({ msg: `City ${cleanCode} added.`, type: 'success' });
    }
  };

  const handleDeleteCity = async () => {
    const cityToDelete = formData.city;
    if (!cityToDelete || cityToDelete === 'PAN-INDIA') {
        setNotification({ msg: 'Cannot delete default PAN-INDIA city.', type: 'error' });
        return;
    }
    if (window.confirm(`Delete city code "${cityToDelete}"?`)) {
        try {
            await db.deleteCity(cityToDelete);
            const updatedCities = await refreshCities();
            setFormData(prev => ({ ...prev, city: updatedCities[0] || 'PAN-INDIA' }));
            setNotification({ msg: `City ${cityToDelete} removed.`, type: 'success' });
        } catch (err) {
            setNotification({ msg: 'Failed to delete city.', type: 'error' });
        }
    }
  };

  const handleManualSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setNotification({ msg: '', type: null });

    if (!formData.fsn || !formData.value || !formData.brand || !formData.title || !formData.vertical || !formData.kam) {
        setNotification({ msg: 'Please fill all fields', type: 'error' });
        return;
    }

    // Strict FSN Length Check
    if (formData.fsn.length !== 16) {
        setNotification({ msg: 'FSN must be exactly 16 characters.', type: 'error' });
        return;
    }

    // Validate Caps
    const isPercentage = formData.type === CommercialType.MARGIN_PERCENT || 
                         formData.type === CommercialType.NLC_PERCENT || 
                         formData.type === CommercialType.ON_INVOICE || 
                         formData.type === CommercialType.OFF_INVOICE;

    if (isPercentage && formData.value! > 100) {
        setNotification({ msg: `${formData.type} cannot exceed 100%`, type: 'error' });
        return;
    }

    if (formData.type !== CommercialType.MARGIN_PERCENT && formData.endDate! < formData.startDate!) {
        setNotification({ msg: 'End Date cannot be before Start Date', type: 'error' });
        return;
    }

    setLoading(true);

    try {
      const records = await db.getRecords();

      const isConflict = checkForConflict(records, formData as CommercialRecord);
      const isHighMargin = formData.type === CommercialType.MARGIN_PERCENT && (formData.value || 0) > 60;

      const newRecord: CommercialRecord = {
        id: `rec_${Date.now()}`,
        ...formData as CommercialRecord,
        value: Number(formData.value),
        lastUpdatedBy: user.name,
        lastUpdatedAt: Date.now()
      };

      if (isConflict || isHighMargin) {
        let reason = '';
        if (isConflict) {
            const isInvoice = formData.type === CommercialType.ON_INVOICE || formData.type === CommercialType.OFF_INVOICE;
            reason = isInvoice ? 'Exact Duplicate Conflict' : 'Duplicate/Overlap Conflict';
        }
        if (isHighMargin) reason = reason ? reason + ' & High Margin (>60%)' : 'High Margin (>60%)';

        const req: DuplicateRequest = {
          id: `req_${Date.now()}`,
          originalRecordId: null, // Logic updated in DB service to find conflict by content
          payload: newRecord,
          requestedBy: user.name,
          requestedAt: Date.now(),
          status: 'PENDING',
          reason: reason
        };
        await db.createDuplicateRequest(req);
        setNotification({ msg: `Request sent to Checker: ${reason}`, type: 'warning' });
      } else {
        await db.addRecords([newRecord]);
        setNotification({ msg: 'Record saved successfully.', type: 'success' });
        setFormData(prev => ({ 
            ...prev, 
            fsn: '', 
            value: 0,
            // Reset dates to defaults
            startDate: new Date().toISOString().split('T')[0],
            endDate: new Date(new Date().setMonth(new Date().getMonth() + 3)).toISOString().split('T')[0]
        }));
      }
    } catch (err) {
      setNotification({ msg: 'Failed to save record.', type: 'error' });
    } finally {
      setLoading(false);
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    Papa.parse(file, {
      header: true,
      skipEmptyLines: true,
      complete: async (results) => {
        setLoading(true);

        // 1. Validate Headers
        const headers = results.meta.fields || [];
        const kamHeader = headers.find(h => h.toUpperCase() === 'KAM');

        if (!kamHeader) {
            setNotification({ msg: "Upload Failed: 'KAM' column is missing in the CSV file.", type: 'error' });
            setLoading(false);
            e.target.value = ''; 
            return;
        }

        // 2. Identify and Add New Cities from Headers
        // Filter out static headers and 'Value'
        const staticHeaders = ['FSN', 'BRAND', 'TITLE', 'VERTICAL', 'KAM', 'STARTDATE', 'ENDDATE', 'VALUE'];

        let currentCities = await db.getCities();
        const potentialNewCities = headers.filter(h => !staticHeaders.includes(h.toUpperCase()));

        const newlyAddedCities: string[] = [];

        for (const h of potentialNewCities) {
            const cleanCode = h.toUpperCase().trim().replace(/[^A-Z0-9]/g, '');

            // Validation: Max 3 chars (standard airport/city codes), not 'PAN-INDIA' (handled by Value), and not existing
            if (cleanCode.length > 0 && cleanCode.length <= 3 && !currentCities.includes(cleanCode)) {
                await db.addCity(cleanCode);
                newlyAddedCities.push(cleanCode);
            }
        }

        if (newlyAddedCities.length > 0) {
            // Refresh list from DB to ensure we have the latest state
            currentCities = await db.getCities();
            setCities(currentCities); 
        }

        const newRecords: CommercialRecord[] = [];
        const requests: DuplicateRequest[] = [];
        const existingRecords = await db.getRecords();

        let skipped = 0;
        let missingKam = 0;

        results.data.forEach((row: any) => {
           if(!row.FSN) return;

           if(row.FSN.length !== 16) {
               skipped++;
               return;
           }

           const kamValue = row[kamHeader] || row['KAM']; 
           if (!kamValue || !kamValue.trim()) {
               missingKam++;
               return; 
           }

           // Identify columns that map to commercial values (Cities or 'Value')
           Object.keys(row).forEach(key => {
               const upperKey = key.toUpperCase();
               const cleanKey = upperKey.trim().replace(/[^A-Z0-9]/g, '');

               let targetCity = '';

               // Check if the column is 'Value' (PAN-INDIA) or matches a valid city code
               if (key === 'Value' || upperKey === 'VALUE') {
                   targetCity = 'PAN-INDIA';
               } else if (currentCities.includes(cleanKey)) {
                   targetCity = cleanKey;
               } else if (currentCities.includes(key)) { // Fallback for case-sensitive matches if stored differently
                   targetCity = key;
               }

               if (!targetCity) return; // Column is not a city or commercial value

               let val = parseFloat(row[key]);
               if (isNaN(val)) return;

               const isPercentage = bulkType === CommercialType.MARGIN_PERCENT || 
                                    bulkType === CommercialType.NLC_PERCENT || 
                                    bulkType === CommercialType.ON_INVOICE || 
                                    bulkType === CommercialType.OFF_INVOICE;

               if (isPercentage && val > 100) val = 100;
               if (isPercentage && val <= 1 && val > 0) val = val * 100;

               const rec: CommercialRecord = {
                 id: `rec_${Math.random().toString(36).substr(2,9)}_${Math.random()}`,
                 fsn: row.FSN,
                 brand: row.Brand || 'Unknown',
                 title: row.Title || 'Bulk Upload Item',
                 vertical: row.Vertical || 'Unknown',
                 kam: kamValue,
                 city: targetCity,
                 startDate: row.StartDate,
                 endDate: row.EndDate,
                 type: bulkType,
                 value: val,
                 lastUpdatedBy: user.name,
                 lastUpdatedAt: Date.now()
               };

               const isConflict = checkForConflict(existingRecords, rec);
               const isHighMargin = bulkType === CommercialType.MARGIN_PERCENT && val > 60;

               if (isConflict || isHighMargin) {
                 let reason = '';
                 if (isConflict) {
                     const isInvoice = bulkType === CommercialType.ON_INVOICE || bulkType === CommercialType.OFF_INVOICE;
                     reason = isInvoice ? 'Exact Duplicate' : 'Duplicate/Overlap';
                 }
                 if (isHighMargin) reason = reason ? reason + ' & High Margin' : 'High Margin';

                 const req: DuplicateRequest = {
                   id: `req_${Math.random().toString(36).substr(2,9)}_${Math.random()}`,
                   originalRecordId: null,
                   payload: rec,
                   requestedBy: user.name,
                   requestedAt: Date.now(),
                   status: 'PENDING',
                   reason: reason
                 };
                 requests.push(req);
               } else {
                 newRecords.push(rec);
               }
           });
        });

        if (newRecords.length > 0) {
          await db.addRecords(newRecords);
        }

        if (requests.length > 0) {
           await db.createDuplicateRequests(requests);
        }

        let msg = '';
        let type: 'success' | 'warning' | 'error' = 'success';

        if (newlyAddedCities.length > 0) msg += `New Cities Added: ${newlyAddedCities.join(', ')}. `;
        if (newRecords.length > 0) msg += `Uploaded ${newRecords.length} records. `;
        if (requests.length > 0) {
            msg += `${requests.length} sent for approval. `;
            type = 'warning';
        }
        if (skipped > 0) msg += `${skipped} skipped (Invalid FSN). `;
        if (missingKam > 0) msg += `${missingKam} skipped (Missing KAM). `;

        if (newRecords.length === 0 && requests.length === 0 && newlyAddedCities.length === 0) {
            if (missingKam > 0 || skipped > 0) {
                 type = 'error';
                 if (!msg) msg = "No valid records found (check FSN or KAM).";
            } else {
                 type = 'error';
                 msg = "No valid records or new cities found in file.";
            }
        }

        setNotification({ msg, type });
        setLoading(false);
        e.target.value = '';
      }
    });
  };

  const downloadTemplate = () => {
    const headers = ['FSN', 'Brand', 'Title', 'Vertical', 'KAM', 'StartDate', 'EndDate', ...cities];
    const isNLC = bulkType === CommercialType.NLC_VALUE;
    const exampleVal = isNLC ? '50000' : '10';
    const dummyRows = [
        ['MOBEXAMPLE123456', 'BrandX', 'Sample Product 1', 'Mobiles', 'John Doe', '2024-01-01', '2024-03-31', ...cities.map(() => exampleVal)],
    ];
    const csvContent = [headers.join(','), ...dummyRows.map(row => row.join(','))].join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv' });
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `template_${bulkType.replace(/\s/g, '')}.csv`;
    a.click();
    window.URL.revokeObjectURL(url);
  };

  return (
    <div className="space-y-6 animate-in slide-in-from-bottom-4 duration-500 max-w-7xl mx-auto">
      <div className="flex justify-between items-center">
        <div>
           <h2 className="text-2xl font-bold text-gray-800">Maker Workspace</h2>
           <p className="text-sm text-gray-500">Manage commercials and offers</p>
        </div>
        <div className="flex bg-white rounded shadow-sm border border-gray-200 p-1">
          <button
            onClick={() => setActiveTab('MANUAL')}
            className={`px-4 py-2 rounded text-sm font-medium transition-all ${activeTab === 'MANUAL' ? 'bg-fkBlue text-white shadow' : 'text-gray-500 hover:text-gray-900'}`}
          >
            Manual Entry
          </button>
          <button
            onClick={() => setActiveTab('BULK')}
            className={`px-4 py-2 rounded text-sm font-medium transition-all ${activeTab === 'BULK' ? 'bg-fkBlue text-white shadow' : 'text-gray-500 hover:text-gray-900'}`}
          >
            Bulk Upload
          </button>
        </div>
      </div>

      {notification.msg && (
        <div className={`p-4 rounded border flex items-center gap-3 shadow-sm ${
          notification.type === 'error' ? 'bg-red-50 border-red-200 text-red-700' :
          notification.type === 'warning' ? 'bg-orange-50 border-orange-200 text-orange-800' :
          'bg-green-50 border-green-200 text-green-700'
        }`}>
          {notification.type === 'error' ? <AlertTriangle className="h-5 w-5"/> : <FileText className="h-5 w-5"/>}
          <span className="font-medium">{notification.msg}</span>
          <button onClick={() => setNotification({msg:'', type:null})} className="ml-auto hover:bg-white/50 rounded p-1"><X className="h-4 w-4"/></button>
        </div>
      )}

      {/* Alerts */}
      <div className="space-y-2">
          {instantConflict && activeTab === 'MANUAL' && (
            <div className="p-3 bg-red-50 border-l-4 border-red-500 rounded shadow-sm flex items-center gap-3 animate-in fade-in slide-in-from-top-2">
                <ShieldAlert className="text-red-500 w-6 h-6" />
                <div>
                    <p className="font-bold text-gray-800 text-sm">Conflict Detected!</p>
                    <p className="text-xs text-gray-600">
                        {(formData.type === CommercialType.ON_INVOICE || formData.type === CommercialType.OFF_INVOICE) 
                         ? 'Exact duplicate date range exists. Saving triggers approval.' 
                         : 'Overlap with existing record. Saving triggers approval.'}
                    </p>
                </div>
            </div>
          )}
          {highMarginAlert && activeTab === 'MANUAL' && (
            <div className="p-3 bg-yellow-50 border-l-4 border-fkYellow rounded shadow-sm flex items-center gap-3 animate-in fade-in slide-in-from-top-2">
                <AlertTriangle className="text-fkYellow w-6 h-6" />
                <div>
                    <p className="font-bold text-gray-800 text-sm">High Margin Alert!</p>
                    <p className="text-xs text-gray-600">Margin &gt; 60% requires checker approval.</p>
                </div>
            </div>
          )}
      </div>

      {activeTab === 'MANUAL' ? (
        <form onSubmit={handleManualSubmit} className="fk-card p-6 grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          <div className="col-span-1">
            <label className="block text-xs font-semibold text-gray-500 uppercase mb-1">FSN (Product ID) <span className="text-red-500">*</span></label>
            <div className="relative">
                <input 
                  className="w-full bg-white border border-gray-300 rounded p-2.5 text-gray-900 focus:border-fkBlue focus:ring-1 focus:ring-fkBlue outline-none transition-colors" 
                  value={formData.fsn || ''}
                  onChange={e => setFormData({...formData, fsn: e.target.value})}
                  placeholder="16 Characters Required"
                  maxLength={16}
                />
                <div className={`text-[10px] text-right mt-1 font-mono ${formData.fsn?.length === 16 ? 'text-green-600' : 'text-gray-400'}`}>
                    {formData.fsn?.length || 0}/16
                </div>
            </div>
          </div>
          <div className="col-span-1">
            <label className="block text-xs font-semibold text-gray-500 uppercase mb-1">Brand <span className="text-red-500">*</span></label>
            <input 
              className="w-full bg-white border border-gray-300 rounded p-2.5 text-gray-900 focus:border-fkBlue focus:ring-1 focus:ring-fkBlue outline-none transition-colors" 
              value={formData.brand || ''}
