      {activeTab === 'APPROVALS' && (
        <div className="space-y-4">
           {requests.length > 0 && (
                <div className="sticky top-0 z-10 bg-white p-4 rounded-lg border border-gray-200 shadow-sm flex justify-between items-center animate-in slide-in-from-top-2">
