    const headers = ['FSN', 'Brand', 'Title', 'Vertical', 'KAM', 'StartDate', 'EndDate', ...extraCols, ...cities];
    const isNLC = bulkType === CommercialType.NLC_VALUE;
    const exampleVal = isNLC ? '50000' : '10';
