];

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [view, setView] = useState<'WORKSPACE' | 'EXPLORER' | 'MANUAL'>('WORKSPACE');
  const [showPin, setShowPin] = useState(false);
  const [isCheckerVerified, setIsCheckerVerified] = useState(false);
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);

  // Tour State
  const [isTourOpen, setIsTourOpen] = useState(false);
  const [currentStepIndex, setCurrentStepIndex] = useState(0);

  // Check persisted session
  useEffect(() => {
    const savedUser = localStorage.getItem('mm_session_user');
    if (savedUser) setUser(JSON.parse(savedUser));

    // Check PIN cache
    const pinCache = localStorage.getItem('mm_pin_verified');
    if (pinCache) {
       const { expiry } = JSON.parse(pinCache);
       if (new Date().getTime() < expiry) setIsCheckerVerified(true);
    }
  }, []);

  // Tour Logic: Automatically switch views/roles based on step
  useEffect(() => {
    if (isTourOpen) {
      const step = TOUR_STEPS[currentStepIndex];
      setView(step.view);

      // Temporary override for visual purposes during tour
      // We don't change the actual logged in user state deeply, just enough for rendering
      if (user) {
         if (step.role === 'CHECKER') setIsCheckerVerified(true);
      }
    }
  }, [currentStepIndex, isTourOpen]);

  const handleLogin = (u: User) => {
    setUser(u);
    localStorage.setItem('mm_session_user', JSON.stringify(u));
  };

  const handleLogout = () => {
    setUser(null);
    setIsCheckerVerified(false);
    setIsTourOpen(false);
    localStorage.removeItem('mm_session_user');
    localStorage.removeItem('mm_pin_verified');
  };

  const verifyPin = () => {
    setIsCheckerVerified(true);
    setShowPin(false);
    // 30 Days Expiry
    const expiry = new Date();
    expiry.setDate(expiry.getDate() + 30);
    localStorage.setItem('mm_pin_verified', JSON.stringify({ expiry: expiry.getTime() }));
  };

  const startTour = () => {
     setIsTourOpen(true);
     setCurrentStepIndex(0);
     setMobileMenuOpen(false);
     // Ensure we have a valid user context for rendering, default to Admin for tour capabilities if needed
     if (!user) {
         const demoUser: User = { id: 'demo', name: 'Demo User', role: Role.ADMIN, employeeId: 'demo' };
         setUser(demoUser);
         setIsCheckerVerified(true);
     }
  };

  if (!user) {
    return <Login onLogin={handleLogin} />;
  }

  // Guard Clause for Checker Access
  const renderWorkspace = () => {
    // During Tour, we force render based on step role requirement
    const effectiveRole = isTourOpen ? TOUR_STEPS[currentStepIndex].role : user.role;

    if (effectiveRole === Role.MAKER) return <MakerWorkspace user={user} />;

    // For Checker/Admin
    if (!isCheckerVerified && !isTourOpen) {
       return (
         <div className="h-full flex flex-col items-center justify-center text-center space-y-4">
            <div className="p-6 bg-white rounded-full shadow-lg">
                <Shield className="w-16 h-16 text-fkBlue" />
            </div>
            <h2 className="text-2xl font-bold text-gray-800">Restricted Access</h2>
            <p className="text-gray-500 max-w-md">Checker workspace contains sensitive auditing tools. Security verification is required.</p>
            <button 
              onClick={() => setShowPin(true)}
              className="bg-fkBlue text-white px-8 py-3 rounded shadow-md hover:bg-blue-600 transition-all font-semibold"
            >
              Verify Identity
            </button>
         </div>
       );
    }
    return <CheckerWorkspace user={user} />;
  };

  return (
    <div className="flex h-screen bg-[#f1f3f6] text-fkText overflow-hidden font-sans">
      {/* Sidebar - Desktop */}
      <aside className={`fixed inset-y-0 left-0 z-40 w-64 bg-white border-r border-gray-200 shadow-sm transform transition-transform duration-300 md:translate-x-0 ${mobileMenuOpen ? 'translate-x-0' : '-translate-x-full'} md:static md:flex flex-col print:hidden`}>
        <div className="h-20 flex items-center px-6 border-b border-gray-100">
          {/* Flipkart-ish Logo */}
          <div className="flex items-center gap-2">
            <div className="bg-fkYellow text-white p-1 rounded">
               <Zap className="w-5 h-5 fill-current" />
            </div>
            <div className="flex flex-col leading-none">
                <span className="text-lg font-bold text-fkBlue italic tracking-tighter">Minutes</span>
                <span className="text-xs text-gray-400 font-medium tracking-wide">Master</span>
            </div>
          </div>
        </div>

        <nav className="flex-1 p-4 space-y-2">
           <button 
             onClick={() => { setView('WORKSPACE'); setMobileMenuOpen(false); }}
             className={`w-full flex items-center space-x-3 px-4 py-3 rounded transition-all ${view === 'WORKSPACE' ? 'bg-fkBlue/10 text-fkBlue font-semibold' : 'text-gray-600 hover:bg-gray-50 hover:text-gray-900'}`}
           >
             <Briefcase className="w-5 h-5" />
             <span>Workspace</span>
           </button>

           <button 
             onClick={() => { setView('EXPLORER'); setMobileMenuOpen(false); }}
             className={`w-full flex items-center space-x-3 px-4 py-3 rounded transition-all ${view === 'EXPLORER' ? 'bg-fkBlue/10 text-fkBlue font-semibold' : 'text-gray-600 hover:bg-gray-50 hover:text-gray-900'}`}
           >
             <Database className="w-5 h-5" />
             <span>Data Explorer</span>
           </button>

           <button 
             onClick={() => { setView('MANUAL'); setMobileMenuOpen(false); }}
             className={`w-full flex items-center space-x-3 px-4 py-3 rounded transition-all ${view === 'MANUAL' ? 'bg-fkBlue/10 text-fkBlue font-semibold' : 'text-gray-600 hover:bg-gray-50 hover:text-gray-900'}`}
           >
             <Book className="w-5 h-5" />
             <span>User Manual</span>
           </button>

           <div className="pt-4 mt-4 border-t border-gray-100">
             <button 
                onClick={startTour}
                className="w-full flex items-center space-x-3 px-4 py-3 rounded transition-all bg-gradient-to-r from-purple-500 to-indigo-600 text-white shadow hover:shadow-lg hover:scale-[1.02]"
             >
                <PlayCircle className="w-5 h-5" />
                <span className="font-bold">Start Walkthrough</span>
             </button>
           </div>
        </nav>

        <div className="p-4 border-t border-gray-100 bg-gray-50">
          <div className="flex items-center gap-3 mb-4 px-2">
            <div className={`w-8 h-8 rounded-full flex items-center justify-center text-sm font-bold text-white shadow-sm ${user.role === 'MAKER' ? 'bg-purple-600' : 'bg-fkGreen'}`}>
              {user.name.charAt(0)}
            </div>
            <div className="overflow-hidden">
              <p className="text-sm font-semibold text-gray-800 truncate">{user.name}</p>
              <p className="text-xs text-gray-500 capitalize">{user.role}</p>
            </div>
          </div>
          <button 
            onClick={handleLogout}
            className="w-full flex items-center justify-center space-x-2 px-4 py-2 border border-gray-300 bg-white rounded text-sm text-gray-700 hover:bg-gray-50 transition-colors shadow-sm"
          >
            <LogOut className="w-4 h-4" />
            <span>Sign Out</span>
          </button>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 flex flex-col h-full relative overflow-hidden bg-[#f1f3f6] print:bg-white print:overflow-visible">
        {/* Mobile Header */}
        <header className="h-16 md:hidden flex items-center justify-between px-4 bg-fkBlue text-white shadow-md print:hidden">
          <span className="font-bold italic">MinutesMaster</span>
          <button onClick={() => setMobileMenuOpen(!mobileMenuOpen)} className="p-2">
            <Menu className="w-6 h-6" />
          </button>
        </header>

        <div className="flex-1 overflow-auto p-4 md:p-6 relative print:p-0 print:overflow-visible">
           {view === 'WORKSPACE' && renderWorkspace()}
           {view === 'EXPLORER' && <DataExplorer user={user} />}
           {view === 'MANUAL' && <UserManual />}
        </div>
      </main>

      {showPin && (
        <PinVerification 
          user={user} 
          onSuccess={verifyPin} 
          onCancel={() => setShowPin(false)} 
        />
      )}

      {/* Tour Overlay */}
      {isTourOpen && (
        <Tour 
           step={TOUR_STEPS[currentStepIndex]}
           currentStepIndex={currentStepIndex}
           totalSteps={TOUR_STEPS.length}
           onNext={() => {
             if (currentStepIndex < TOUR_STEPS.length - 1) {
               setCurrentStepIndex(currentStepIndex + 1);
             } else {
               setIsTourOpen(false);
             }
           }}
           onPrev={() => setCurrentStepIndex(Math.max(0, currentStepIndex - 1))}
           onClose={() => setIsTourOpen(false)}
        />
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { db } from '../services/db';
import { DuplicateRequest, User, CommercialType, CommercialRecord } from '../types';
import { Check, X, Search, BarChart3, Archive, TrendingUp, AlertCircle, FileDown, Calendar, Trash2, Database, Clock, ChevronDown, User as UserIcon, Layers, Upload, FileText, RefreshCw, Loader2, CheckSquare } from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer, ReferenceLine, LabelList } from 'recharts';
import Papa from 'papaparse';

interface CheckerProps {
  user: User;
}

export const CheckerWorkspace: React.FC<CheckerProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<'AUDIT' | 'APPROVALS' | 'CLOSURE'>('AUDIT');
  const [requests, setRequests] = useState<DuplicateRequest[]>([]);
  const [cities, setCities] = useState<string[]>([]);

  // Selection State for Approvals
  const [selectedRequestIds, setSelectedRequestIds] = useState<Set<string>>(new Set());

  // Audit State (Single)
  const [auditMode, setAuditMode] = useState<'SINGLE' | 'BULK'>('SINGLE');
  const [auditQuery, setAuditQuery] = useState({ fsn: '', city: 'BLR', targetMargin: 0, unit: 'PERCENT' });
  const [auditResult, setAuditResult] = useState<any>(null);

  // Audit State (Bulk)
  const [bulkAuditData, setBulkAuditData] = useState<any[]>([]);
  const [bulkAuditCity, setBulkAuditCity] = useState('BLR');
  const [bulkResults, setBulkResults] = useState<any[] | null>(null);
  const [bulkFile, setBulkFile] = useState<string | null>(null);

  const [loading, setLoading] = useState(false);

  // Progress State
  const [progress, setProgress] = useState(0);
  const [eta, setEta] = useState<string | null>(null);
  const [processingStatus, setProcessingStatus] = useState<string>('');

  // Autocomplete State
  const [allFsns, setAllFsns] = useState<string[]>([]);
  const [filteredFsns, setFilteredFsns] = useState<string[]>([]);
  const [showSuggestions, setShowSuggestions] = useState(false);

  // Closure/Export State
  const [selectedMonth, setSelectedMonth] = useState(new Date().toISOString().slice(0, 7)); // YYYY-MM
  const [exportLoading, setExportLoading] = useState(false);

  // Archive View State
  const [showArchive, setShowArchive] = useState(false);
  const [archiveData, setArchiveData] = useState<any[]>([]);

  // Safety Modal State
  const [showClearModal, setShowClearModal] = useState(false);
  const [clearConfirmationText, setClearConfirmationText] = useState('');

  useEffect(() => {
    loadRequests();
    loadCities();
    loadUniqueFsns();
    const interval = setInterval(loadRequests, 5000);
    return () => clearInterval(interval);
  }, []);

  // Sync selection with requests list (cleanup ghosts)
  useEffect(() => {
      const currentIds = new Set(requests.map(r => r.id));
      setSelectedRequestIds(prev => {
          const next = new Set();
          let changed = false;
          prev.forEach(id => {
              if (currentIds.has(id)) next.add(id);
              else changed = true;
          });
          return changed ? next : prev;
      });
  }, [requests]);

  const loadCities = async () => {
    const c = await db.getCities();
    setCities(c);
    if (!c.includes(auditQuery.city)) {
       setAuditQuery(prev => ({ ...prev, city: c.includes('BLR') ? 'BLR' : c[0] || '' }));
    }
  };

  const loadUniqueFsns = async () => {
    const records = await db.getRecords();
    const unique = Array.from(new Set(records.map(r => r.fsn)));
    setAllFsns(unique);
  };

  const loadRequests = async () => {
    const reqs = await db.getDuplicateRequests();
    setRequests(reqs.filter(r => r.status === 'PENDING'));
  };

  const loadArchive = async () => {
    const data = await db.getBinRecords();
    setArchiveData(data.sort((a: any, b: any) => b.deletedAt - a.deletedAt));
  };

  const toggleArchive = () => {
      if (!showArchive) loadArchive();
      setShowArchive(!showArchive);
  };

  const handleFsnChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = e.target.value;
    setAuditQuery({ ...auditQuery, fsn: val });

    if (val.length > 0) {
        const matches = allFsns.filter(f => f.toLowerCase().includes(val.toLowerCase()));
        setFilteredFsns(matches.slice(0, 5)); // Limit to 5 suggestions
        setShowSuggestions(true);
    } else {
        setShowSuggestions(false);
    }
  };

  const selectSuggestion = (fsn: string) => {
      setAuditQuery({ ...auditQuery, fsn });
      setShowSuggestions(false);
  };

  // SINGLE AUDIT Logic
  const handleAudit = async () => {
    if (!auditQuery.fsn) return;

    if (auditQuery.fsn.length !== 16) {
        alert("FSN must be exactly 16 characters.");
        return;
    }

    setLoading(true);
    setProcessingStatus('Analyzing FSN...');
    setProgress(50);
    setShowSuggestions(false); 

    const records = await db.getRecords();
    const today = new Date().toISOString().split('T')[0];

    // 1. Filter relevant records (Active & City Match/PAN)
    const activeRecords = records.filter(r => 
      r.fsn === auditQuery.fsn && 
      (r.city === auditQuery.city || r.city === 'PAN-INDIA') &&
      r.startDate <= today && r.endDate >= today
    );

    let baseVal = 0;
    let baseType = '-';
    let onInvVal = 0;
    let onInvSource = '-';
    let systemTotal = 0;

    const getRec = (type: CommercialType) => 
        activeRecords.find(r => r.type === type && r.city === auditQuery.city) ||
        activeRecords.find(r => r.type === type && r.city === 'PAN-INDIA');

    if (auditQuery.unit === 'PERCENT') {
        // Logic: Margin % > NLC %
        const marginRec = getRec(CommercialType.MARGIN_PERCENT);
        if (marginRec) {
            baseVal = marginRec.value;
            baseType = 'Margin %';
        } else {
            const nlcRec = getRec(CommercialType.NLC_PERCENT);
            if (nlcRec) {
                baseVal = nlcRec.value;
                baseType = 'NLC %';
            }
        }

        // On Invoice Logic
        const onRec = getRec(CommercialType.ON_INVOICE);
        if (onRec) {
            onInvVal = onRec.value;
            onInvSource = onRec.city === 'PAN-INDIA' ? 'PAN' : 'City';
        }

        systemTotal = baseVal + onInvVal;
    } else {
        // Logic: NLC Value (Amount)
        const nlcValRec = getRec(CommercialType.NLC_VALUE);
        if (nlcValRec) {
            baseVal = nlcValRec.value;
            baseType = 'NLC Value';
        }

        // On Invoice (For display only, not added to total)
        const onRec = getRec(CommercialType.ON_INVOICE);
        if (onRec) {
            onInvVal = onRec.value;
            onInvSource = onRec.city === 'PAN-INDIA' ? 'PAN' : 'City';
        }

        systemTotal = baseVal;
    }

    const variance = auditQuery.targetMargin - systemTotal;
    const variancePercent = auditQuery.targetMargin ? ((variance / auditQuery.targetMargin) * 100) : 0;

    setAuditResult({
      data: [
        { name: 'System', base: baseVal, onInv: auditQuery.unit === 'PERCENT' ? onInvVal : 0, total: systemTotal },
        { name: 'Target', target: auditQuery.targetMargin }
      ],
      systemTotal,
      targetTotal: auditQuery.targetMargin,
      variance,
      variancePercent: variancePercent.toFixed(2),
      status: Math.abs(variance) < 0.01 ? 'MATCH' : 'MISMATCH',
      details: activeRecords,
      baseType,
      onInvVal,
      onInvSource
    });
    setLoading(false);
    setProgress(100);
    setTimeout(() => { setProgress(0); }, 500);
  };

  // BULK AUDIT Handlers
  const handleBulkUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (!file) return;
      setBulkFile(file.name);

      setLoading(true);
      setProcessingStatus('Parsing CSV...');
      setProgress(0);
      setEta('Starting...');

      // Wrap in setTimeout to ensure UI updates before heavy parsing
      setTimeout(() => {
        Papa.parse(file, {
            header: true,
            skipEmptyLines: true,
            complete: (results) => {
                setBulkAuditData(results.data as any[]);
                setBulkResults(null);
                setLoading(false);
                setProgress(100);
                setTimeout(() => setProgress(0), 500);
            }
        });
      }, 100);
  };

  const downloadAuditTemplate = () => {
    const headers = ['FSN', 'Margin Value', 'Margin Rule', 'Margin Value Unit'];
    const dummyRow = ['MOBEXAMPLE123456', '20.5', 'MRP_GROSS_OF_TAXES', 'PERCENT'];
    const csvContent = [headers.join(','), dummyRow.join(',')].join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv' });
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `audit_template.csv`;
    a.click();
    window.URL.revokeObjectURL(url);
  };

  const runBulkAudit = async () => {
      if (bulkAuditData.length === 0) return;
      setLoading(true);
      setProcessingStatus('Building Search Index...');
      setProgress(0);
      setEta('Calculating...');

      const records = await db.getRecords();
      const today = new Date().toISOString().split('T')[0];

      // OPTIMIZATION: Build Index for O(1) lookup
      const fsnIndex = new Map<string, CommercialRecord[]>();
      records.forEach(r => {
          if(!fsnIndex.has(r.fsn)) fsnIndex.set(r.fsn, []);
          fsnIndex.get(r.fsn)!.push(r);
      });

      const BATCH_SIZE = 200;
      const totalItems = bulkAuditData.length;
      const startTime = Date.now();
      const resultsAccumulator: any[] = [];

      setProcessingStatus('Starting Bulk Audit...');

      const processBatch = async () => {
          for (let i = 0; i < totalItems; i++) {
               // Update Progress
               if (i % BATCH_SIZE === 0 && i > 0) {
                   const percent = Math.round((i / totalItems) * 100);
                   const elapsed = (Date.now() - startTime) / 1000;
                   const rate = i / elapsed;
                   const remainingSeconds = (totalItems - i) / rate;

                   setProgress(percent);
                   setEta(remainingSeconds < 60 ? `${Math.ceil(remainingSeconds)}s` : `${Math.ceil(remainingSeconds/60)}m`);
                   setProcessingStatus(`Auditing row ${i}/${totalItems}`);

                   await new Promise(resolve => setTimeout(resolve, 0));
               }

               const row = bulkAuditData[i] as any;
               // Fix: Ensure FSN is treated as a string
               const fsnRaw = row['FSN'];
               const fsn = fsnRaw ? String(fsnRaw) : '';

               // Fix: Ensure value is string before passing to parseFloat to avoid 'unknown' type error
               // Explicitly convert to string to handle 'unknown' types safely
               const marginValRaw = row['Margin Value'];
               const marginValStr = (marginValRaw !== undefined && marginValRaw !== null) ? String(marginValRaw) : '0';
               const targetVal = parseFloat(marginValStr);

               const unitRaw = row['Margin Value Unit'];
               const unit = (unitRaw ? String(unitRaw) : '').toUpperCase();

               if (!fsn) continue;

               // OPTIMIZATION: Use Map Index instead of array.filter
               const candidates = fsnIndex.get(fsn) || [];
               const activeRecords = candidates.filter(r => 
                   (r.city === bulkAuditCity || r.city === 'PAN-INDIA') &&
                   r.startDate <= today && r.endDate >= today
               );

               let baseVal = 0;
               let baseType = '-';
               let onInvVal = 0;
               let onInvSource = '-';

               const getRec = (type: CommercialType) => 
                     activeRecords.find(r => r.type === type && r.city === bulkAuditCity) ||
                     activeRecords.find(r => r.type === type && r.city === 'PAN-INDIA');

               if (unit.includes('PERCENT')) {
                  const marginRec = getRec(CommercialType.MARGIN_PERCENT);
                  if (marginRec) {
                      baseVal = marginRec.value;
                      baseType = 'Margin %';
                  } else {
                      const nlcRec = getRec(CommercialType.NLC_PERCENT);
                      if (nlcRec) {
                          baseVal = nlcRec.value;
                          baseType = 'NLC %';
                      }
                  }
               } else {
                  const nlcValRec = getRec(CommercialType.NLC_VALUE);
                  if (nlcValRec) {
                      baseVal = nlcValRec.value;
                      baseType = 'NLC Value';
                  }
               }

               const onRec = getRec(CommercialType.ON_INVOICE);
               if (onRec) {
                   onInvVal = onRec.value;
                   onInvSource = onRec.city === 'PAN-INDIA' ? 'PAN' : 'City';
               }

               let systemTotal = 0;
               let variance = 0;

               if (unit.includes('PERCENT')) {
                   systemTotal = baseVal + onInvVal;
                   variance = targetVal - systemTotal;
               } else {
                   systemTotal = baseVal;
                   variance = targetVal - systemTotal;
               }

               const status = Math.abs(variance) < 0.01 ? 'MATCH' : 'MISMATCH';
               const title = activeRecords[0]?.title || 'Unknown Title';

               resultsAccumulator.push({
                   fsn,
                   title,
                   targetVal,
                   unit,
                   baseVal,
                   baseType,
                   onInvVal,
                   onInvSource,
                   systemTotal,
                   variance,
                   status
               });
          }
      };

      await processBatch();

      setBulkResults(resultsAccumulator);
      setProgress(100);
      setLoading(false);
      setTimeout(() => {
          setProgress(0);
          setEta(null);
      }, 500);
  };

  const handleRequestAction = async (reqId: string, action: 'APPROVED' | 'REJECTED') => {
    await db.resolveDuplicateRequest(reqId, action, user.id);
    loadRequests();
    loadUniqueFsns();
  };

  // Selection Handlers
  const toggleSelectRequest = (id: string) => {
      setSelectedRequestIds(prev => {
          const next = new Set(prev);
          if (next.has(id)) next.delete(id);
          else next.add(id);
          return next;
      });
  };

  const toggleSelectAllRequests = () => {
      if (selectedRequestIds.size === requests.length) {
          setSelectedRequestIds(new Set());
      } else {
          setSelectedRequestIds(new Set(requests.map(r => r.id)));
      }
  };

  const handleBulkAction = async (action: 'APPROVED' | 'REJECTED') => {
      if (selectedRequestIds.size === 0) return;

      setLoading(true);
      setProcessingStatus(action === 'APPROVED' ? 'Approving requests...' : 'Rejecting requests...');
      setProgress(0);

      const ids = Array.from(selectedRequestIds);
      let count = 0;

      for (const id of ids) {
          await db.resolveDuplicateRequest(id, action, user.id);
          count++;
          if (count % 5 === 0) setProgress(Math.round((count / ids.length) * 100));
      }

      await loadRequests();
      await loadUniqueFsns();
      setSelectedRequestIds(new Set());
      setLoading(false);
      setProgress(0);
      setProcessingStatus('');
  };

  const handleExport = async (mode: 'MONTH' | 'FULL') => {
    setExportLoading(true);
    setProcessingStatus('Generating Export...');
    setLoading(true);
    setProgress(30);

    try {
        const records = await db.getRecords();
        let dataToExport = records;

        if (mode === 'MONTH') {
            const [year, month] = selectedMonth.split('-').map(Number);
            const startOfMonth = new Date(year, month - 1, 1).toISOString().split('T')[0];
            const endOfMonth = new Date(year, month, 0).toISOString().split('T')[0];
            dataToExport = records.filter(r => r.startDate <= endOfMonth && r.endDate >= startOfMonth);
        }

        setProgress(70);

        const csv = Papa.unparse(dataToExport.map(r => ({
            ID: r.id,
            FSN: r.fsn,
            Brand: r.brand,
            Title: r.title,
            Vertical: r.vertical,
            KAM: r.kam,
            City: r.city,
            Type: r.type,
            Value: r.value,
            StartDate: r.startDate,
            EndDate: r.endDate,
            LastUpdatedBy: r.lastUpdatedBy,
            LastUpdatedAt: new Date(r.lastUpdatedAt).toISOString()
        })));

        setProgress(100);

        const blob = new Blob([csv], { type: 'text/csv' });
        const url = window.URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `mm_export_${mode.toLowerCase()}_${Date.now()}.csv`;
        a.click();
        window.URL.revokeObjectURL(url);
    } catch (e) {
        alert('Export failed');
    } finally {
        setExportLoading(false);
        setLoading(false);
        setProgress(0);
    }
  };

  const initiateClearDB = () => {
      setClearConfirmationText('');
      setShowClearModal(true);
  };

  const confirmClearDB = async () => {
    setShowClearModal(false);
    setLoading(true);
    setProcessingStatus('Archiving active records...');
    setProgress(10);

    try {
        // Simulate progress for heavy DB op
        const interval = setInterval(() => {
            setProgress(prev => Math.min(prev + 10, 90));
        }, 200);

        await db.clearAllRecords(user.name);

        clearInterval(interval);
        setProgress(100);

        alert("Database reset. Records archived.");
        setAuditResult(null);
        setRequests([]);
        loadArchive();
        setAllFsns([]);
        setBulkResults(null);
    } catch (e) {
        alert("Failed.");
