import { CommercialRecord, DuplicateRequest, User, Role, CommercialType, CITIES as DEFAULT_CITIES } from '../types';

const DB_NAME = 'MinutesMasterDB';
const DB_VERSION = 1;

// Store Names
const STORE_RECORDS = 'records';
const STORE_REQUESTS = 'requests';
const STORE_BIN = 'bin';
const STORE_USERS = 'users';
const STORE_CONFIG = 'config';

const STORAGE_KEYS_LEGACY = {
  USERS: 'mm_users',
  RECORDS: 'mm_records',
  REQUESTS: 'mm_requests',
  BIN: 'mm_bin',
  CITIES: 'mm_cities'
};

// Seed Data
const SEED_USERS: User[] = [
  { id: '1', employeeId: 'maker1', name: 'Maker', role: Role.MAKER },
  { id: '2', employeeId: 'checker1', name: 'Checker', role: Role.CHECKER, pin: '1234' },
  { id: '3', employeeId: 'admin1', name: 'Admin', role: Role.ADMIN, pin: '9999' },
];

type RecordListener = (records: CommercialRecord[]) => void;
type CityListener = (cities: string[]) => void;

class DBService {
  private dbPromise: Promise<IDBDatabase> | null = null;
  private listeners: RecordListener[] = [];
  private cityListeners: CityListener[] = [];

  constructor() {
    this.init();
  }

  // --- IndexedDB Core Wrappers ---

  private async getDB(): Promise<IDBDatabase> {
    if (this.dbPromise) return this.dbPromise;

    this.dbPromise = new Promise((resolve, reject) => {
      const request = indexedDB.open(DB_NAME, DB_VERSION);

      request.onupgradeneeded = (event) => {
        const db = (event.target as IDBOpenDBRequest).result;

        if (!db.objectStoreNames.contains(STORE_RECORDS)) {
          db.createObjectStore(STORE_RECORDS, { keyPath: 'id' });
        }
        if (!db.objectStoreNames.contains(STORE_REQUESTS)) {
          db.createObjectStore(STORE_REQUESTS, { keyPath: 'id' });
        }
        if (!db.objectStoreNames.contains(STORE_BIN)) {
          // Bin needs to allow multiple deleted versions, so we use autoIncrement
          db.createObjectStore(STORE_BIN, { keyPath: 'binId', autoIncrement: true });
        }
        if (!db.objectStoreNames.contains(STORE_USERS)) {
          db.createObjectStore(STORE_USERS, { keyPath: 'id' });
        }
        if (!db.objectStoreNames.contains(STORE_CONFIG)) {
          db.createObjectStore(STORE_CONFIG, { keyPath: 'key' });
        }
      };

      request.onsuccess = (event) => {
        resolve((event.target as IDBOpenDBRequest).result);
      };

      request.onerror = (event) => {
        console.error("IDB Open Error:", (event.target as IDBOpenDBRequest).error);
        reject((event.target as IDBOpenDBRequest).error);
      };
    });

    return this.dbPromise;
  }

  private async transaction<T>(
    storeNames: string | string[], 
    mode: IDBTransactionMode, 
    callback: (store: IDBObjectStore) => IDBRequest<T> | void
  ): Promise<T> {
    const db = await this.getDB();
    return new Promise((resolve, reject) => {
      const tx = db.transaction(storeNames, mode);
      const store = tx.objectStore(Array.isArray(storeNames) ? storeNames[0] : storeNames);

      let req: IDBRequest | void;
      try {
        req = callback(store);
      } catch (e) {
        reject(e);
        return;
      }

      tx.oncomplete = () => {
        resolve(req ? req.result : undefined);
      };
      tx.onerror = () => reject(tx.error);
    });
  }

  private async getAll<T>(storeName: string): Promise<T[]> {
    return this.transaction(storeName, 'readonly', (store) => store.getAll());
  }

  private async get<T>(storeName: string, key: string): Promise<T | undefined> {
    return this.transaction(storeName, 'readonly', (store) => store.get(key));
  }

  private async put(storeName: string, value: any): Promise<void> {
    await this.transaction(storeName, 'readwrite', (store) => store.put(value));
  }

  private async bulkPut(storeName: string, values: any[]): Promise<void> {
    const db = await this.getDB();
    return new Promise((resolve, reject) => {
      const tx = db.transaction(storeName, 'readwrite');
      const store = tx.objectStore(storeName);

      values.forEach(v => store.put(v));

      tx.oncomplete = () => resolve();
      tx.onerror = () => reject(tx.error);
    });
  }

  private async delete(storeName: string, key: string | number): Promise<void> {
    await this.transaction(storeName, 'readwrite', (store) => store.delete(key));
  }

  private async bulkDelete(storeName: string, keys: string[]): Promise<void> {
      const db = await this.getDB();
      return new Promise((resolve, reject) => {
        const tx = db.transaction(storeName, 'readwrite');
        const store = tx.objectStore(storeName);
        keys.forEach(k => store.delete(k));
        tx.oncomplete = () => resolve();
        tx.onerror = () => reject(tx.error);
      });
  }

  private async clear(storeName: string): Promise<void> {
    await this.transaction(storeName, 'readwrite', (store) => store.clear());
  }

  // --- Initialization & Migration ---

  async init() {
    try {
        const db = await this.getDB();

        // 1. Check if we need to migrate from LocalStorage
        const legacyRecords = localStorage.getItem(STORAGE_KEYS_LEGACY.RECORDS);
        if (legacyRecords) {
            await this.migrateFromLocalStorage();
        } else {
            // 2. Check if we need to seed initial data (Users/Cities)
            const users = await this.getAll<User>(STORE_USERS);
            if (users.length === 0) {
                await this.bulkPut(STORE_USERS, SEED_USERS);
            }

            const cityConfig = await this.get<{key: string, value: string[]}>(STORE_CONFIG, 'cities');
            if (!cityConfig) {
                await this.put(STORE_CONFIG, { key: 'cities', value: DEFAULT_CITIES });
            }
        }
    } catch (e) {
        console.error("DB Init Failed", e);
    }
  }

  private async migrateFromLocalStorage() {
      console.log("Migrating from LocalStorage to IndexedDB...");
      try {
          // Records
          const records = JSON.parse(localStorage.getItem(STORAGE_KEYS_LEGACY.RECORDS) || '[]');
          if(records.length > 0) await this.bulkPut(STORE_RECORDS, records);

          // Users
          let users = JSON.parse(localStorage.getItem(STORAGE_KEYS_LEGACY.USERS) || '[]');
          if (users.length === 0) users = SEED_USERS;
          await this.bulkPut(STORE_USERS, users);

          // Requests
          const requests = JSON.parse(localStorage.getItem(STORAGE_KEYS_LEGACY.REQUESTS) || '[]');
          if(requests.length > 0) await this.bulkPut(STORE_REQUESTS, requests);

          // Bin
          const bin = JSON.parse(localStorage.getItem(STORAGE_KEYS_LEGACY.BIN) || '[]');
          // Bin items in legacy didn't have a binId, autoIncrement will handle it
          if(bin.length > 0) await this.bulkPut(STORE_BIN, bin);

          // Cities
          const cities = JSON.parse(localStorage.getItem(STORAGE_KEYS_LEGACY.CITIES) || JSON.stringify(DEFAULT_CITIES));
          await this.put(STORE_CONFIG, { key: 'cities', value: cities });

          // Cleanup LocalStorage
          localStorage.removeItem(STORAGE_KEYS_LEGACY.RECORDS);
          localStorage.removeItem(STORAGE_KEYS_LEGACY.REQUESTS);
          localStorage.removeItem(STORAGE_KEYS_LEGACY.BIN);
          // We keep USERS and CITIES keys in LS as backups or remove them? 
          // Let's remove to ensure single source of truth, but AUTH component might be reading LS in this demo.
          // Wait, the Auth component in this app calls db.login(), which we will update.
          localStorage.removeItem(STORAGE_KEYS_LEGACY.USERS); 
          localStorage.removeItem(STORAGE_KEYS_LEGACY.CITIES);

          console.log("Migration Complete.");
      } catch (e) {
          console.error("Migration Failed", e);
      }
  }

  // --- Public API ---

  // Subscriptions - Records
  subscribeToRecords(callback: RecordListener): () => void {
    this.listeners.push(callback);
    this.getRecords().then(records => callback(records));
    return () => {
      this.listeners = this.listeners.filter(l => l !== callback);
    };
  }

  private async notifyListeners() {
    const records = await this.getRecords();
    this.listeners.forEach(l => l(records));
  }

  // Subscriptions - Cities
  subscribeToCities(callback: CityListener): () => void {
    this.cityListeners.push(callback);
    this.getCities().then(c => callback(c));
    return () => {
      this.cityListeners = this.cityListeners.filter(l => l !== callback);
    };
  }

  private async notifyCityListeners() {
      const cities = await this.getCities();
      this.cityListeners.forEach(l => l(cities));
  }

  // Auth
  async login(employeeId: string): Promise<User | null> {
    const users = await this.getAll<User>(STORE_USERS);
    return users.find(u => u.employeeId === employeeId) || null;
  }

  async verifyPin(userId: string, pin: string): Promise<boolean> {
    const user = await this.get<User>(STORE_USERS, userId);
    return user ? user.pin === pin : false;
  }

  // Cities
  async getCities(): Promise<string[]> {
    const config = await this.get<{key: string, value: string[]}>(STORE_CONFIG, 'cities');
    return config ? config.value : DEFAULT_CITIES;
  }

  async addCity(city: string): Promise<void> {
    const cities = await this.getCities();
    if (!cities.includes(city)) {
      cities.push(city);
      await this.put(STORE_CONFIG, { key: 'cities', value: cities });
      this.notifyCityListeners();
    }
  }

  async deleteCity(city: string): Promise<void> {
    const cities = await this.getCities();
    const updated = cities.filter(c => c !== city);
    await this.put(STORE_CONFIG, { key: 'cities', value: updated });
    this.notifyCityListeners();
  }

  // Records
  async getRecords(): Promise<CommercialRecord[]> {
    return this.getAll<CommercialRecord>(STORE_RECORDS);
  }

  async addRecords(records: CommercialRecord[]): Promise<void> {
    await this.bulkPut(STORE_RECORDS, records);
    await this.notifyListeners();
  }

  async updateRecord(updatedRecord: CommercialRecord): Promise<void> {
    await this.put(STORE_RECORDS, updatedRecord);
    await this.notifyListeners();
  }

  async updateRecords(updatedRecords: CommercialRecord[]): Promise<void> {
    await this.bulkPut(STORE_RECORDS, updatedRecords);
    await this.notifyListeners();
  }

  async deleteRecord(recordId: string, movedToBinBy: string): Promise<void> {
      const record = await this.get<CommercialRecord>(STORE_RECORDS, recordId);
      if (record) {
          await this.put(STORE_BIN, { ...record, deletedBy: movedToBinBy, deletedAt: Date.now() });
          await this.delete(STORE_RECORDS, recordId);
          await this.notifyListeners();
      }
  }

  async deleteRecords(recordIds: string[], movedToBinBy: string): Promise<void> {
      // PHASE 1: READ - Fetch all records to be deleted
      // We do this separately to avoid keeping a read-write transaction open during potential read delays
      const recordsToDelete: CommercialRecord[] = [];
      const db = await this.getDB();

      const readTx = db.transaction(STORE_RECORDS, 'readonly');
      const readStore = readTx.objectStore(STORE_RECORDS);

      const readPromises = recordIds.map(id => new Promise<CommercialRecord | undefined>((resolve) => {
          const req = readStore.get(id);
          req.onsuccess = () => resolve(req.result);
          req.onerror = () => resolve(undefined);
      }));

      const results = await Promise.all(readPromises);
      results.forEach(r => { if(r) recordsToDelete.push(r); });

      if (recordsToDelete.length === 0) return;

      // PHASE 2: WRITE - Move to Bin and Delete
      return new Promise((resolve, reject) => {
          const writeTx = db.transaction([STORE_RECORDS, STORE_BIN], 'readwrite');
          const recordStore = writeTx.objectStore(STORE_RECORDS);
          const binStore = writeTx.objectStore(STORE_BIN);
          const timestamp = Date.now();

          recordsToDelete.forEach(rec => {
              // 1. Put to Bin
              binStore.put({ ...rec, deletedBy: movedToBinBy, deletedAt: timestamp });
              // 2. Delete from Records
              recordStore.delete(rec.id);
          });

          writeTx.oncomplete = () => {
              this.notifyListeners();
              resolve();
          };

          writeTx.onerror = (e) => {
              console.error("Delete Transaction Failed", writeTx.error);
              reject(writeTx.error);
          };
      });
  }

  async getBinRecords(): Promise<any[]> {
    return this.getAll(STORE_BIN);
  }

  async clearAllRecords(clearedBy: string): Promise<void> {
    // 1. Fetch all records to move to bin (Read)
    const records = await this.getAll<CommercialRecord>(STORE_RECORDS);

    // 2. Perform writes in a single transaction (Write)
    const db = await this.getDB();

    return new Promise((resolve, reject) => {
        const tx = db.transaction([STORE_RECORDS, STORE_BIN, STORE_REQUESTS], 'readwrite');
        const recordStore = tx.objectStore(STORE_RECORDS);
        const binStore = tx.objectStore(STORE_BIN);
        const reqStore = tx.objectStore(STORE_REQUESTS);
        const timestamp = Date.now();

        // Move to Bin
        records.forEach(r => {
             binStore.put({ ...r, deletedBy: clearedBy, deletedAt: timestamp, note: 'BATCH_CLEAR_MONTH_END' });
        });

        // Clear Stores
        recordStore.clear();
        reqStore.clear();

        tx.oncomplete = () => {
            this.notifyListeners();
            resolve();
        };

        tx.onerror = (e) => {
            console.error("Clear Transaction Failed", tx.error);
            reject(tx.error);
        };
    });
  }

  // Requests
  async getDuplicateRequests(): Promise<DuplicateRequest[]> {
    return this.getAll<DuplicateRequest>(STORE_REQUESTS);
  }

  async createDuplicateRequest(request: DuplicateRequest): Promise<void> {
    await this.put(STORE_REQUESTS, request);
  }

  async createDuplicateRequests(requests: DuplicateRequest[]): Promise<void> {
    await this.bulkPut(STORE_REQUESTS, requests);
  }

  async resolveDuplicateRequest(requestId: string, status: 'APPROVED' | 'REJECTED', resolverId: string): Promise<void> {
    const request = await this.get<DuplicateRequest>(STORE_REQUESTS, requestId);
    if (!request) return;

    request.status = status;
    await this.put(STORE_REQUESTS, request); // Update status

    if (status === 'APPROVED') {
        const newRec = request.payload;
        const allRecords = await this.getRecords();
        const isInvoice = newRec.type === CommercialType.ON_INVOICE || newRec.type === CommercialType.OFF_INVOICE;

        // Find Conflicts
        let idsToDelete: string[] = [];

        if (isInvoice) {
            idsToDelete = allRecords.filter(r => 
                r.fsn === newRec.fsn &&
                r.city === newRec.city &&
                r.type === newRec.type &&
                r.startDate === newRec.startDate &&
                r.endDate === newRec.endDate
            ).map(r => r.id);
        } else {
             idsToDelete = allRecords.filter(r => 
                r.fsn === newRec.fsn &&
                r.city === newRec.city &&
                r.type === newRec.type &&
                (newRec.startDate <= r.endDate && newRec.endDate >= r.startDate)
            ).map(r => r.id);
        }

        if (idsToDelete.length > 0) {
            await this.deleteRecords(idsToDelete, resolverId);
        }
        await this.addRecords([newRec]);
    }
  }
}

export const db = new DBService();

import React, { useState, useEffect, useMemo } from 'react';
import { db } from '../services/db';
import { CommercialRecord, User, Role, COMMERCIAL_TYPES, CommercialType } from '../types';
import { Download, Filter, RefreshCw, Trash2, Edit2, Save, X, Clock, ChevronLeft, ChevronRight, Loader2, AlertTriangle, CheckSquare, Square } from 'lucide-react';

interface DataExplorerProps {
  user: User;
}

interface PivotRow {
  key: string;
  fsn: string;
  brand: string;
  title: string;
  vertical: string;
  kam: string;
  type: CommercialType;
  startDate: string;
  endDate: string;
  cityRecords: { [key: string]: CommercialRecord | undefined };
  values: { [key: string]: number | undefined };
  isExpiringSoon: boolean;
}

export const DataExplorer: React.FC<DataExplorerProps> = ({ user }) => {
  const [records, setRecords] = useState<CommercialRecord[]>([]);
  const [cities, setCities] = useState<string[]>([]);
  const [loading, setLoading] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');

  // Pagination State
  const [currentPage, setCurrentPage] = useState(1);
  const itemsPerPage = 50;

  // Edit State
  const [editingRowKey, setEditingRowKey] = useState<string | null>(null);
  const [editForm, setEditForm] = useState<Partial<PivotRow> | null>(null);

  // Selection State
  const [selectedRowKeys, setSelectedRowKeys] = useState<Set<string>>(new Set());

  // Progress State for Actions (Delete/Save)
  const [processingAction, setProcessingAction] = useState(false);
  const [progress, setProgress] = useState(0);
  const [processingStatus, setProcessingStatus] = useState('');

  // Permission Check
  const canEdit = user.role !== Role.MAKER;

  useEffect(() => {
    setLoading(true);

    // Subscribe to Cities (Real-time updates)
    const unsubCities = db.subscribeToCities((data) => {
      setCities(data);
    });

    // Subscribe to Records (Real-time updates, acts like onSnapshot)
    const unsubRecords = db.subscribeToRecords((data) => {
      setRecords(data);
      setLoading(false);
    });

    return () => {
      unsubCities();
      unsubRecords();
    };
  }, []);

  const pivotData: PivotRow[] = useMemo(() => {
    const map = new Map<string, PivotRow>();
    const today = new Date();
    const sevenDaysLater = new Date();
    sevenDaysLater.setDate(today.getDate() + 7);

    records.forEach(r => {
      const key = `${r.fsn}_${r.type}_${r.startDate}_${r.endDate}`;
      if (!map.has(key)) {
        const endDate = new Date(r.endDate);
        const isExpiringSoon = endDate >= today && endDate <= sevenDaysLater;

        map.set(key, {
          key,
          fsn: r.fsn,
          brand: r.brand,
          title: r.title,
          vertical: r.vertical || '',
          kam: r.kam || '',
          type: r.type,
          startDate: r.startDate,
          endDate: r.endDate,
          cityRecords: {},
          values: {},
          isExpiringSoon
        });
      }
      const entry = map.get(key)!;
      entry.cityRecords[r.city] = r;
      entry.values[r.city] = r.value;

      // Update inherited fields if needed
      if(r.vertical && !entry.vertical) entry.vertical = r.vertical;
      if(r.kam && !entry.kam) entry.kam = r.kam;
    });
    let result = Array.from(map.values());
    if (searchTerm) {
      const lower = searchTerm.toLowerCase();
      result = result.filter(item => 
        item.fsn.toLowerCase().includes(lower) || 
        item.brand.toLowerCase().includes(lower) ||
        item.title.toLowerCase().includes(lower)
      );
    }
    return result;
  }, [records, searchTerm]);

  // Pagination Logic
  const totalPages = Math.ceil(pivotData.length / itemsPerPage);
  const paginatedData = useMemo(() => {
      const start = (currentPage - 1) * itemsPerPage;
      return pivotData.slice(start, start + itemsPerPage);
  }, [pivotData, currentPage]);

  useEffect(() => {
      setCurrentPage(1);
      // Optional: Clear selection on search? No, keep it.
  }, [searchTerm]);

  const exportCSV = () => {
    const headers = ['FSN', 'Brand', 'Title', 'Vertical', 'KAM', 'Type', 'Start', 'End', ...cities].join(',');
    const rows = pivotData.map(row => {
      const cityVals = cities.map(c => {
          const val = row.values[c];
          const pan = row.values['PAN-INDIA'];
          // Export effective value
          return val !== undefined ? val : (pan !== undefined ? pan : '');
      }).join(',');
      return `${row.fsn},${row.brand},${row.title},${row.vertical},${row.kam},${row.type},${row.startDate},${row.endDate},${cityVals}`;
    }).join('\n');

    const blob = new Blob([headers + '\n' + rows], { type: 'text/csv' });
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `mm_export_${Date.now()}.csv`;
    a.click();
    window.URL.revokeObjectURL(url);
  };

  const handleEditClick = (row: PivotRow) => {
    setEditingRowKey(row.key);
    setEditForm({ ...row, values: { ...row.values } });
  };

  const handleCancelEdit = () => {
    setEditingRowKey(null);
    setEditForm(null);
  };

  // Selection Handlers
  const handleSelectAll = (e: React.ChangeEvent<HTMLInputElement>) => {
      if (e.target.checked) {
          // Select all visible in current filter (all filtered rows, not just page)
          const allKeys = new Set(pivotData.map(r => r.key));
          setSelectedRowKeys(allKeys);
      } else {
          setSelectedRowKeys(new Set());
      }
  };

  const handleSelectRow = (key: string) => {
      const newSet = new Set(selectedRowKeys);
      if (newSet.has(key)) newSet.delete(key);
      else newSet.add(key);
      setSelectedRowKeys(newSet);
  };

  const handleBulkDelete = async () => {
    if (!canEdit || selectedRowKeys.size === 0) return;

    if (!window.confirm(`Are you sure you want to permanently delete ${selectedRowKeys.size} selected items?`)) return;

    setProcessingAction(true);
    setProcessingStatus('Analyzing selection...');
    setProgress(10);

    try {
      await new Promise(resolve => setTimeout(resolve, 50));

      const selectedSet = selectedRowKeys;
      // Gather all related record IDs from the selected pivot keys
      const idsToDelete = records.filter(r => {
           const key = `${r.fsn}_${r.type}_${r.startDate}_${r.endDate}`;
           return selectedSet.has(key);
      }).map(r => r.id);

      if (idsToDelete.length === 0) {
          setProcessingAction(false);
          return;
      }

      setProcessingStatus(`Archiving ${idsToDelete.length} records...`);
      setProgress(30);

      // Simulate progress for visual feedback
      const interval = setInterval(() => {
          setProgress(prev => Math.min(prev + 10, 90));
      }, 150);

      await db.deleteRecords(idsToDelete, user.name);

      clearInterval(interval);
      setProgress(100);
      setProcessingStatus('Deletion Complete');

      setSelectedRowKeys(new Set()); // Clear selection
      await new Promise(resolve => setTimeout(resolve, 500));
    } catch (e) {
      alert('Error deleting records');
    } finally {
      setProcessingAction(false);
      setProgress(0);
      setProcessingStatus('');
    }
  };

  const handleSaveEdit = async (originalRow: PivotRow) => {
    if (!editForm || !canEdit) return;

    if ((editForm.fsn || originalRow.fsn).length !== 16) {
        alert("FSN must be exactly 16 characters.");
        return;
    }

    setProcessingAction(true);
    setProcessingStatus('Validating changes...');
    setProgress(20);

    try {
      const recordsToUpdate = records.filter(r => 
          r.fsn === originalRow.fsn && r.type === originalRow.type && r.startDate === originalRow.startDate && r.endDate === originalRow.endDate
      );

      const updatePromises: Promise<void>[] = [];
      const recordsForBulkUpdate: CommercialRecord[] = [];

      setProcessingStatus('Updating active records...');
      setProgress(40);

      recordsToUpdate.forEach(r => {
        const newCityValue = editForm.values?.[r.city];
        const updatedRecord: CommercialRecord = {
          ...r,
          fsn: editForm.fsn || r.fsn,
          brand: editForm.brand || r.brand,
          title: editForm.title || r.title,
          vertical: editForm.vertical || r.vertical,
          kam: editForm.kam || r.kam,
          type: editForm.type || r.type,
          startDate: editForm.startDate || r.startDate,
          endDate: editForm.endDate || r.endDate,
          value: newCityValue !== undefined ? Number(newCityValue) : r.value,
          lastUpdatedBy: user.name,
          lastUpdatedAt: Date.now()
        };
        recordsForBulkUpdate.push(updatedRecord);
      });

      if (recordsForBulkUpdate.length > 0) updatePromises.push(db.updateRecords(recordsForBulkUpdate));

      setProgress(60);
      setProcessingStatus('Checking for new city overrides...');

      for (const city of cities) {
        const hasExisting = recordsToUpdate.some(r => r.city === city);
        const newVal = editForm.values?.[city];
        // Note: We do NOT inherit PAN-INDIA during save. Saving creates an explicit override.
        if (!hasExisting && newVal !== undefined && Number(newVal) !== 0) {
           updatePromises.push(db.addRecords([{
             id: `rec_${Date.now()}_${Math.random().toString(36).substr(2,5)}`,
             fsn: editForm.fsn!,
             brand: editForm.brand!,
             title: editForm.title!,
             vertical: editForm.vertical || '',
             kam: editForm.kam || '',
             type: editForm.type!,
             city: city,
             startDate: editForm.startDate!,
             endDate: editForm.endDate!,
             value: Number(newVal),
             lastUpdatedBy: user.name,
             lastUpdatedAt: Date.now()
           }]));
        }
      }

      setProgress(80);
      await Promise.all(updatePromises);

      setProgress(100);
      setProcessingStatus('Saved Successfully');
      await new Promise(resolve => setTimeout(resolve, 500));

      setEditingRowKey(null);
      setEditForm(null);
    } catch (e) {
      alert('Failed to save changes');
    } finally {
      setProcessingAction(false);
      setProgress(0);
      setProcessingStatus('');
    }
  };

  const refreshCities = async () => {
    // Legacy manual refresh, primarily triggers a re-fetch via db.getCities()
    // but the subscription handles updates automatically now.
    // Keeping for manual user trigger confidence.
    setLoading(true);
    const c = await db.getCities();
    setCities(c);
    setLoading(false);
  };

  const isAllSelected = pivotData.length > 0 && selectedRowKeys.size === pivotData.length;
  const isIndeterminate = selectedRowKeys.size > 0 && selectedRowKeys.size < pivotData.length;

  return (
    <div className="space-y-4 h-full flex flex-col animate-in fade-in duration-500 relative">

      {/* Action Progress Overlay */}
      {processingAction && (
          <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center backdrop-blur-sm">
              <div className="bg-white p-8 rounded-lg shadow-2xl max-w-md w-full animate-in zoom-in duration-200">
                  <div className="flex items-center justify-between mb-4">
                      <h3 className="font-bold text-gray-800 text-lg">System Update</h3>
                      <Loader2 className="w-5 h-5 text-fkBlue animate-spin" />
                  </div>

                  <div className="w-full bg-gray-200 rounded-full h-4 mb-2 overflow-hidden">
                      <div 
                        className="bg-fkBlue h-4 rounded-full transition-all duration-300 ease-out flex items-center justify-end pr-2"
                        style={{ width: `${progress}%` }}
                      >
                          {progress > 10 && <span className="text-[9px] text-white font-bold">{progress}%</span>}
                      </div>
                  </div>

                  <div className="flex justify-between text-xs text-gray-500 font-medium">
                      <span>{processingStatus || 'Processing...'}</span>
                      <span>{progress}%</span>
                  </div>
              </div>
          </div>
      )}

      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
           <h2 className="text-2xl font-bold text-gray-800">Database Explorer</h2>
           <p className="text-sm text-gray-500">Search and edit active commercial records</p>
        </div>
        <div className="flex gap-2 items-center">
           {selectedRowKeys.size > 0 && canEdit && (
               <button 
                 onClick={handleBulkDelete}
                 className="flex items-center gap-2 px-4 py-2 bg-red-600 hover:bg-red-700 text-white rounded shadow-sm text-sm font-bold transition-all animate-in zoom-in"
               >
                 <Trash2 className="h-4 w-4" /> Delete ({selectedRowKeys.size})
               </button>
           )}

           <div className="relative">
             <Filter className="absolute left-3 top-2.5 h-4 w-4 text-gray-400"/>
             <input 
               className="bg-white border border-gray-300 rounded shadow-sm py-2 pl-9 pr-4 text-sm text-gray-800 focus:ring-1 focus:ring-fkBlue focus:border-fkBlue outline-none w-64 transition-shadow"
               placeholder="Filter by FSN, Brand..."
               value={searchTerm}
               onChange={e => setSearchTerm(e.target.value)}
             />
           </div>
           <button onClick={refreshCities} className="p-2 bg-white border border-gray-300 rounded hover:bg-gray-50 text-gray-600 shadow-sm">
             <RefreshCw className={`h-5 w-5 ${loading ? 'animate-spin' : ''}`} />
           </button>
           <button onClick={exportCSV} className="flex items-center gap-2 px-4 py-2 bg-fkGreen hover:bg-green-700 text-white rounded shadow-sm text-sm font-bold transition-colors">
             <Download className="h-4 w-4" /> Export CSV
           </button>
        </div>
      </div>

      <div className="flex-1 bg-white rounded-lg shadow-sm border border-gray-200 overflow-hidden flex flex-col relative">
        <div className="overflow-auto scrollbar-hide flex-1">
          <table className="w-full text-left border-collapse min-w-[1400px]">
            <thead className="bg-gray-50 sticky top-0 z-10 text-xs uppercase text-gray-500 font-semibold shadow-sm">
              <tr>
                {canEdit && (
                    <th className="p-4 border-b border-gray-200 bg-gray-50 w-10 text-center">
                        <input 
                            type="checkbox"
                            checked={isAllSelected}
                            ref={input => { if(input) input.indeterminate = isIndeterminate; }}
                            onChange={handleSelectAll}
                            className="w-4 h-4 rounded border-gray-300 text-fkBlue focus:ring-fkBlue cursor-pointer"
                        />
                    </th>
                )}
                <th className="p-4 border-b border-gray-200 min-w-[120px] bg-gray-50">FSN</th>
                <th className="p-4 border-b border-gray-200 bg-gray-50">Brand</th>
                <th className="p-4 border-b border-gray-200 bg-gray-50">Title</th>
                <th className="p-4 border-b border-gray-200 bg-gray-50">Vertical</th>
                <th className="p-4 border-b border-gray-200 bg-gray-50">KAM</th>
                <th className="p-4 border-b border-gray-200 bg-gray-50 min-w-[120px]">Type</th>
                <th className="p-4 border-b border-gray-200 text-center min-w-[200px] bg-gray-50">Dates</th>
                {cities.map(c => (
                  <th key={c} className="p-4 border-b border-gray-200 text-center min-w-[80px] bg-gray-50">{c}</th>
                ))}
                {canEdit && <th className="p-4 border-b border-gray-200 text-center sticky right-0 bg-gray-50 z-20 w-24">Actions</th>}
              </tr>
            </thead>
            <tbody className="text-sm divide-y divide-gray-100">
              {paginatedData.map((row) => {
                const isEditing = editingRowKey === row.key;
                const isSelected = selectedRowKeys.has(row.key);

                return (
                  <tr key={row.key} className={`transition-colors group ${isEditing ? 'bg-blue-50' : isSelected ? 'bg-blue-50/50' : 'hover:bg-gray-50'}`}>
                    {canEdit && (
                        <td className="p-4 text-center">
                            <input 
                                type="checkbox"
                                checked={isSelected}
                                onChange={() => handleSelectRow(row.key)}
                                className="w-4 h-4 rounded border-gray-300 text-fkBlue focus:ring-fkBlue cursor-pointer"
                            />
                        </td>
                    )}
                    <td className="p-4 font-mono text-fkBlue font-semibold">
                        {isEditing ? (
                            <input className="w-full bg-white border border-gray-300 rounded px-2 py-1 text-gray-800 text-xs font-mono"
                              value={editForm?.fsn || ''} onChange={e => setEditForm(prev => ({ ...prev!, fsn: e.target.value }))} 
                              maxLength={16}
                              />
                        ) : (
                          <div className="flex items-center gap-2">
                             {row.fsn}
                             {row.isExpiringSoon && (
                               <span title="Expiring within 7 days">
                                 <Clock className="w-3 h-3 text-fkYellow animate-pulse" />
                               </span>
                             )}
                          </div>
                        )}
                    </td>
                    <td className="p-4 text-gray-700 max-w-[150px] truncate">
                        {isEditing ? (
                            <input className="w-full bg-white border border-gray-300 rounded px-2 py-1 text-gray-800 text-xs"
                              value={editForm?.brand || ''} onChange={e => setEditForm(prev => ({ ...prev!, brand: e.target.value }))} />
                        ) : row.brand}
                    </td>
                    <td className="p-4 text-gray-700 max-w-[200px] truncate" title={row.title}>
                        {isEditing ? (
                            <input className="w-full bg-white border border-gray-300 rounded px-2 py-1 text-gray-800 text-xs"
                              value={editForm?.title || ''} onChange={e => setEditForm(prev => ({ ...prev!, title: e.target.value }))} />
                        ) : row.title}
                    </td>
                    <td className="p-4 text-gray-700 max-w-[150px] truncate">
                        {isEditing ? (
                            <input className="w-full bg-white border border-gray-300 rounded px-2 py-1 text-gray-800 text-xs"
                              value={editForm?.vertical || ''} onChange={e => setEditForm(prev => ({ ...prev!, vertical: e.target.value }))} />
                        ) : row.vertical}
                    </td>
                    <td className="p-4 text-gray-700 max-w-[150px] truncate">
                        {isEditing ? (
                            <input className="w-full bg-white border border-gray-300 rounded px-2 py-1 text-gray-800 text-xs"
                              value={editForm?.kam || ''} onChange={e => setEditForm(prev => ({ ...prev!, kam: e.target.value }))} />
                        ) : row.kam}
                    </td>
                    <td className="p-4">
                      {isEditing ? (
                          <select className="w-full bg-white border border-gray-300 rounded px-2 py-1 text-gray-800 text-xs"
                             value={editForm?.type} onChange={e => setEditForm(prev => ({ ...prev!, type: e.target.value as CommercialType }))}>
                            {COMMERCIAL_TYPES.map(t => <option key={t} value={t}>{t}</option>)}
                          </select>
                      ) : (
                          <span className={`px-2 py-1 rounded text-[10px] border whitespace-nowrap font-medium ${
                            row.type.includes('Margin') ? 'border-purple-200 text-purple-700 bg-purple-50' : 
                            'border-blue-200 text-blue-700 bg-blue-50'
                          }`}>
                            {row.type}
                          </span>
                      )}
                    </td>
                    <td className="p-4 text-gray-500 text-xs text-center">
                      {isEditing ? (
                        <div className="flex flex-col gap-2">
                           <input type="date" className="bg-white border border-gray-300 rounded px-2 py-1 text-gray-800 text-xs w-full"
                             value={editForm?.startDate || row.startDate} onChange={e => setEditForm(prev => ({ ...prev!, startDate: e.target.value }))} />
                           <input type="date" className="bg-white border border-gray-300 rounded px-2 py-1 text-gray-800 text-xs w-full"
                             value={editForm?.endDate || row.endDate} onChange={e => setEditForm(prev => ({ ...prev!, endDate: e.target.value }))} />
                        </div>
                      ) : (
                        <div className="flex flex-col items-center">
                           <span className="font-mono">{row.startDate}</span>
                           <span className="text-[10px] text-gray-400">to</span>
                           <span className={`font-mono ${row.isExpiringSoon ? 'text-fkYellow font-bold' : ''}`}>{row.endDate}</span>
                        </div>
                      )}
                    </td>
                    {cities.map(c => {
                      const specificVal = row.values[c];
                      const panVal = row.values['PAN-INDIA'];
                      const effectiveVal = specificVal !== undefined ? specificVal : (c !== 'PAN-INDIA' ? panVal : undefined);
                      const isInherited = specificVal === undefined && effectiveVal !== undefined;

                      return (
                        <td key={c} className={`p-2 text-center border-l border-gray-100 ${isEditing ? 'p-1' : ''}`}>
                           {isEditing ? (
                             <input type="number" className="w-16 bg-white border border-gray-300 rounded px-1 py-1 text-center text-gray-800 text-sm focus:border-fkBlue outline-none"
                               value={editForm?.values?.[c] ?? ''} placeholder={isInherited ? String(effectiveVal) : '-'}
                               onChange={e => {
                                 const val = e.target.value;
                                 setEditForm(prev => ({ ...prev!, values: { ...prev!.values, [c]: val === '' ? undefined : parseFloat(val) } }));
                               }} />
                           ) : (
                               effectiveVal !== undefined ? (
                                   <span className={isInherited ? "text-gray-400 italic" : "text-gray-800 font-bold"}>
                                     {effectiveVal}
                                     {isInherited && <span className="ml-1 text-[8px] border border-gray-200 rounded px-0.5 text-gray-400 not-italic">PAN</span>}
                                   </span>
                               ) : <span className="text-gray-300">-</span>
                           )}
                        </td>
                      );
                    })}
                    {canEdit && (
                      <td className="p-4 border-l border-gray-200 sticky right-0 bg-white group-hover:bg-blue-50/50 transition-colors z-10 shadow-[-5px_0_10px_-5px_rgba(0,0,0,0.1)]">
                        <div className="flex items-center justify-center gap-2">
                          {isEditing ? (
                            <>
                              <button onClick={() => handleSaveEdit(row)} className="p-1.5 bg-green-600 hover:bg-green-700 rounded text-white shadow-sm" title="Save">
                                <Save className="w-4 h-4" />
                              </button>
                              <button onClick={handleCancelEdit} className="p-1.5 bg-gray-500 hover:bg-gray-600 rounded text-white" title="Cancel">
                                <X className="w-4 h-4" />
                              </button>
                            </>
                          ) : (
                            <>
                              <button onClick={() => handleEditClick(row)} className="p-1.5 hover:bg-blue-100 text-gray-400 hover:text-fkBlue rounded transition-colors" title="Edit Row">
                                <Edit2 className="w-4 h-4" />
                              </button>
                            </>
                          )}
                        </div>
                      </td>
                    )}
                  </tr>
                );
              })}
              {pivotData.length === 0 && !loading && (
                 <tr><td colSpan={cities.length + 7} className="p-8 text-center text-gray-500">No records found.</td></tr>
              )}
            </tbody>
          </table>
        </div>

        {/* Pagination Bar */}
        <div className="bg-gray-50 p-3 flex justify-between items-center border-t border-gray-200 text-xs">
          <div className="text-gray-500">
             Showing {Math.min(itemsPerPage, pivotData.length)} of {pivotData.length} records.
             {selectedRowKeys.size > 0 && <span className="ml-2 font-bold text-fkBlue">{selectedRowKeys.size} selected.</span>}
          </div>
          <div className="flex items-center gap-2">
             <button 
                onClick={() => setCurrentPage(p => Math.max(1, p - 1))}
                disabled={currentPage === 1}
                className="p-1.5 rounded hover:bg-gray-200 disabled:opacity-50 disabled:hover:bg-transparent"
             >
                <ChevronLeft className="w-4 h-4" />
             </button>
             <span className="font-bold text-gray-700">Page {currentPage} of {Math.max(1, totalPages)}</span>
             <button 
                onClick={() => setCurrentPage(p => Math.min(totalPages, p + 1))}
                disabled={currentPage === totalPages || totalPages === 0}
                className="p-1.5 rounded hover:bg-gray-200 disabled:opacity-50 disabled:hover:bg-transparent"
             >
                <ChevronRight className="w-4 h-4" />
             </button>
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { db } from '../services/db';
import { DuplicateRequest, User, CommercialType, CommercialRecord } from '../types';
import { Check, X, Search, BarChart3, Archive, TrendingUp, AlertCircle, FileDown, Calendar, Trash2, Database, Clock, ChevronDown, User as UserIcon, Layers, Upload, FileText, RefreshCw, Loader2, CheckSquare } from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer, ReferenceLine, LabelList } from 'recharts';
import Papa from 'papaparse';

interface CheckerProps {
  user: User;
}

export const CheckerWorkspace: React.FC<CheckerProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<'AUDIT' | 'APPROVALS' | 'CLOSURE'>('AUDIT');
  const [requests, setRequests] = useState<DuplicateRequest[]>([]);
  const [cities, setCities] = useState<string[]>([]);

  // Selection State for Approvals
  const [selectedRequestIds, setSelectedRequestIds] = useState<Set<string>>(new Set());
  const [approvalSearchTerm, setApprovalSearchTerm] = useState('');

  // Audit State (Single)
  const [auditMode, setAuditMode] = useState<'SINGLE' | 'BULK'>('SINGLE');
  const [auditQuery, setAuditQuery] = useState({ fsn: '', city: 'BLR', targetMargin: 0, unit: 'PERCENT' });
  const [auditResult, setAuditResult] = useState<any>(null);

  // Audit State (Bulk)
  const [bulkAuditData, setBulkAuditData] = useState<any[]>([]);
  const [bulkAuditCity, setBulkAuditCity] = useState('BLR');
  const [bulkResults, setBulkResults] = useState<any[] | null>(null);
  const [bulkFile, setBulkFile] = useState<string | null>(null);

  const [loading, setLoading] = useState(false);

  // Progress State
  const [progress, setProgress] = useState(0);
  const [eta, setEta] = useState<string | null>(null);
  const [processingStatus, setProcessingStatus] = useState<string>('');

  // Autocomplete State
  const [allFsns, setAllFsns] = useState<string[]>([]);
  const [filteredFsns, setFilteredFsns] = useState<string[]>([]);
  const [showSuggestions, setShowSuggestions] = useState(false);

  // Closure/Export State
  const [selectedMonth, setSelectedMonth] = useState(new Date().toISOString().slice(0, 7)); // YYYY-MM
  const [exportLoading, setExportLoading] = useState(false);

  // Archive View State
  const [showArchive, setShowArchive] = useState(false);
  const [archiveData, setArchiveData] = useState<any[]>([]);

  // Safety Modal State
  const [showClearModal, setShowClearModal] = useState(false);
  const [clearConfirmationText, setClearConfirmationText] = useState('');

  useEffect(() => {
    loadRequests();
    loadCities();
    loadUniqueFsns();
    const interval = setInterval(loadRequests, 5000);
    return () => clearInterval(interval);
  }, []);

  // Sync selection with requests list (cleanup ghosts)
  useEffect(() => {
      const currentIds = new Set(requests.map(r => r.id));
      setSelectedRequestIds(prev => {
          const next = new Set();
          let changed = false;
          prev.forEach(id => {
              if (currentIds.has(id)) next.add(id);
              else changed = true;
          });
          return changed ? next : prev;
      });
  }, [requests]);

  const filteredRequests = useMemo(() => {
    if (!approvalSearchTerm.trim()) return requests;
    const lowerTerm = approvalSearchTerm.toLowerCase();
    return requests.filter(req => 
      req.payload.fsn.toLowerCase().includes(lowerTerm) ||
      req.payload.title.toLowerCase().includes(lowerTerm) ||
      req.requestedBy.toLowerCase().includes(lowerTerm) ||
      (req.payload.kam && req.payload.kam.toLowerCase().includes(lowerTerm))
    );
  }, [requests, approvalSearchTerm]);

  const loadCities = async () => {
    const c = await db.getCities();
    setCities(c);
    if (!c.includes(auditQuery.city)) {
       setAuditQuery(prev => ({ ...prev, city: c.includes('BLR') ? 'BLR' : c[0] || '' }));
    }
  };

  const loadUniqueFsns = async () => {
    const records = await db.getRecords();
    const unique = Array.from(new Set(records.map(r => r.fsn)));
    setAllFsns(unique);
  };

  const loadRequests = async () => {
    const reqs = await db.getDuplicateRequests();
    setRequests(reqs.filter(r => r.status === 'PENDING'));
  };

  const loadArchive = async () => {
    const data = await db.getBinRecords();
    setArchiveData(data.sort((a: any, b: any) => b.deletedAt - a.deletedAt));
  };

  const toggleArchive = () => {
      if (!showArchive) loadArchive();
      setShowArchive(!showArchive);
  };

  const handleFsnChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = e.target.value;
    setAuditQuery({ ...auditQuery, fsn: val });

    if (val.length > 0) {
        const matches = allFsns.filter(f => f.toLowerCase().includes(val.toLowerCase()));
        setFilteredFsns(matches.slice(0, 5)); // Limit to 5 suggestions
        setShowSuggestions(true);
    } else {
        setShowSuggestions(false);
    }
  };

  const selectSuggestion = (fsn: string) => {
      setAuditQuery({ ...auditQuery, fsn });
      setShowSuggestions(false);
  };

  // SINGLE AUDIT Logic
  const handleAudit = async () => {
    if (!auditQuery.fsn) return;

    if (auditQuery.fsn.length !== 16) {
        alert("FSN must be exactly 16 characters.");
        return;
    }

    setLoading(true);
    setProcessingStatus('Analyzing FSN...');
    setProgress(50);
    setShowSuggestions(false); 

    const records = await db.getRecords();
    const today = new Date().toISOString().split('T')[0];

    // 1. Filter relevant records (Active & City Match/PAN)
    const activeRecords = records.filter(r => 
      r.fsn === auditQuery.fsn && 
      (r.city === auditQuery.city || r.city === 'PAN-INDIA') &&
      r.startDate <= today && r.endDate >= today
    );

    let baseVal = 0;
    let baseType = '-';
    let onInvVal = 0;
    let onInvSource = '-';
    let systemTotal = 0;

    const getRec = (type: CommercialType) => 
        activeRecords.find(r => r.type === type && r.city === auditQuery.city) ||
        activeRecords.find(r => r.type === type && r.city === 'PAN-INDIA');

    if (auditQuery.unit === 'PERCENT') {
        // Logic: Margin % > NLC %
        const marginRec = getRec(CommercialType.MARGIN_PERCENT);
        if (marginRec) {
            baseVal = marginRec.value;
            baseType = 'Margin %';
        } else {
            const nlcRec = getRec(CommercialType.NLC_PERCENT);
            if (nlcRec) {
                baseVal = nlcRec.value;
                baseType = 'NLC %';
            }
        }

        // On Invoice Logic
        const onRec = getRec(CommercialType.ON_INVOICE);
        if (onRec) {
            onInvVal = onRec.value;
            onInvSource = onRec.city === 'PAN-INDIA' ? 'PAN' : 'City';
        }

        systemTotal = baseVal + onInvVal;
    } else {
        // Logic: NLC Value (Amount)
        const nlcValRec = getRec(CommercialType.NLC_VALUE);
        if (nlcValRec) {
            baseVal = nlcValRec.value;
            baseType = 'NLC Value';
        }

        // On Invoice (For display only, not added to total)
        const onRec = getRec(CommercialType.ON_INVOICE);
        if (onRec) {
            onInvVal = onRec.value;
            onInvSource = onRec.city === 'PAN-INDIA' ? 'PAN' : 'City';
        }

        systemTotal = baseVal;
    }

    const variance = auditQuery.targetMargin - systemTotal;
    const variancePercent = auditQuery.targetMargin ? ((variance / auditQuery.targetMargin) * 100) : 0;

    setAuditResult({
      data: [
        { name: 'System', base: baseVal, onInv: auditQuery.unit === 'PERCENT' ? onInvVal : 0, total: systemTotal },
        { name: 'Target', target: auditQuery.targetMargin }
      ],
      systemTotal,
      targetTotal: auditQuery.targetMargin,
      variance,
      variancePercent: variancePercent.toFixed(2),
      status: Math.abs(variance) < 0.01 ? 'MATCH' : 'MISMATCH',
      details: activeRecords,
      baseType,
      onInvVal,
      onInvSource
    });
    setLoading(false);
    setProgress(100);
    setTimeout(() => { setProgress(0); }, 500);
  };

  // BULK AUDIT Handlers
  const handleBulkUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (!file) return;
      setBulkFile(file.name);

      setLoading(true);
      setProcessingStatus('Parsing CSV...');
      setProgress(0);
      setEta('Starting...');

      // Wrap in setTimeout to ensure UI updates before heavy parsing
      setTimeout(() => {
        Papa.parse(file, {
            header: true,
            skipEmptyLines: true,
            complete: (results) => {
                setBulkAuditData(results.data as any[]);
                setBulkResults(null);
                setLoading(false);
                setProgress(100);
                setTimeout(() => setProgress(0), 500);
            }
        });
      }, 100);
  };

  const downloadAuditTemplate = () => {
    const headers = ['FSN', 'Margin Value', 'Margin Rule', 'Margin Value Unit'];
    const dummyRow = ['MOBEXAMPLE123456', '20.5', 'MRP_GROSS_OF_TAXES', 'PERCENT'];
    const csvContent = [headers.join(','), dummyRow.join(',')].join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv' });
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `audit_template.csv`;
    a.click();
    window.URL.revokeObjectURL(url);
  };

  const runBulkAudit = async () => {
      if (bulkAuditData.length === 0) return;
      setLoading(true);
      setProcessingStatus('Building Search Index...');
      setProgress(0);
      setEta('Calculating...');

      const records = await db.getRecords();
      const today = new Date().toISOString().split('T')[0];

      // OPTIMIZATION: Build Index for O(1) lookup
      const fsnIndex = new Map<string, CommercialRecord[]>();
      records.forEach(r => {
          if(!fsnIndex.has(r.fsn)) fsnIndex.set(r.fsn, []);
          fsnIndex.get(r.fsn)!.push(r);
      });

      const BATCH_SIZE = 200;
      const totalItems = bulkAuditData.length;
      const startTime = Date.now();
      const resultsAccumulator: any[] = [];

      setProcessingStatus('Starting Bulk Audit...');

      const processBatch = async () => {
          for (let i = 0; i < totalItems; i++) {
               // Update Progress
               if (i % BATCH_SIZE === 0 && i > 0) {
                   const percent = Math.round((i / totalItems) * 100);
                   const elapsed = (Date.now() - startTime) / 1000;
                   const rate = i / elapsed;
                   const remainingSeconds = (totalItems - i) / rate;

                   setProgress(percent);
                   setEta(remainingSeconds < 60 ? `${Math.ceil(remainingSeconds)}s` : `${Math.ceil(remainingSeconds/60)}m`);
                   setProcessingStatus(`Auditing row ${i}/${totalItems}`);

                   await new Promise(resolve => setTimeout(resolve, 0));
               }

               const row = bulkAuditData[i] as any;
               // Fix: Ensure FSN is treated as a string
               const fsnRaw = row['FSN'];
               const fsn = fsnRaw ? `${fsnRaw}` : '';

               // Fix: Ensure value is string before passing to parseFloat to avoid 'unknown' type error
               // Explicitly convert to string to handle 'unknown' types safely
               const marginValRaw = row['Margin Value'];
               const marginValStr = (marginValRaw !== undefined && marginValRaw !== null) ? `${marginValRaw}` : '0';
               const targetVal = parseFloat(marginValStr);

               const unitRaw = row['Margin Value Unit'];
               const unit = (unitRaw ? `${unitRaw}` : '').toUpperCase();

               if (!fsn) continue;

               // OPTIMIZATION: Use Map Index instead of array.filter
               const candidates = fsnIndex.get(fsn) || [];
               const activeRecords = candidates.filter(r => 
                   (r.city === bulkAuditCity || r.city === 'PAN-INDIA') &&
                   r.startDate <= today && r.endDate >= today
               );

               let baseVal = 0;
               let baseType = '-';
               let onInvVal = 0;
               let onInvSource = '-';

               const getRec = (type: CommercialType) => 
                     activeRecords.find(r => r.type === type && r.city === bulkAuditCity) ||
                     activeRecords.find(r => r.type === type && r.city === 'PAN-INDIA');

               if (unit.includes('PERCENT')) {
                  const marginRec = getRec(CommercialType.MARGIN_PERCENT);
                  if (marginRec) {
                      baseVal = marginRec.value;
                      baseType = 'Margin %';
                  } else {
                      const nlcRec = getRec(CommercialType.NLC_PERCENT);
                      if (nlcRec) {
                          baseVal = nlcRec.value;
                          baseType = 'NLC %';
                      }
                  }
               } else {
                  const nlcValRec = getRec(CommercialType.NLC_VALUE);
                  if (nlcValRec) {
                      baseVal = nlcValRec.value;
                      baseType = 'NLC Value';
                  }
               }

               const onRec = getRec(CommercialType.ON_INVOICE);
               if (onRec) {
                   onInvVal = onRec.value;
                   onInvSource = onRec.city === 'PAN-INDIA' ? 'PAN' : 'City';
               }

               let systemTotal = 0;
               let variance = 0;

               if (unit.includes('PERCENT')) {
                   systemTotal = baseVal + onInvVal;
                   variance = targetVal - systemTotal;
               } else {
                   systemTotal = baseVal;
                   variance = targetVal - systemTotal;
               }

               const status = Math.abs(variance) < 0.01 ? 'MATCH' : 'MISMATCH';
               const title = activeRecords[0]?.title || 'Unknown Title';

               resultsAccumulator.push({
                   fsn,
                   title,
                   targetVal,
                   unit,
                   baseVal,
                   baseType,
                   onInvVal,
                   onInvSource,
                   systemTotal,
                   variance,
                   status
               });
          }
      };

      await processBatch();

      setBulkResults(resultsAccumulator);
      setProgress(100);
      setLoading(false);
      setTimeout(() => {
          setProgress(0);
          setEta(null);
      }, 500);
  };

  const handleRequestAction = async (reqId: string, action: 'APPROVED' | 'REJECTED') => {
    await db.resolveDuplicateRequest(reqId, action, user.id);
    loadRequests();
    loadUniqueFsns();
  };

  // Selection Handlers
  const toggleSelectRequest = (id: string) => {
      setSelectedRequestIds(prev => {
          const next = new Set(prev);
          if (next.has(id)) next.delete(id);
          else next.add(id);
          return next;
      });
  };

  const toggleSelectAllRequests = () => {
      const allSelected = filteredRequests.length > 0 && filteredRequests.every(r => selectedRequestIds.has(r.id));

      setSelectedRequestIds(prev => {
          const next = new Set(prev);
          if (allSelected) {
              filteredRequests.forEach(r => next.delete(r.id));
          } else {
              filteredRequests.forEach(r => next.add(r.id));
          }
          return next;
      });
  };

  const handleBulkAction = async (action: 'APPROVED' | 'REJECTED') => {
      if (selectedRequestIds.size === 0) return;

      setLoading(true);
      setProcessingStatus(action === 'APPROVED' ? 'Approving requests...' : 'Rejecting requests...');
      setProgress(0);

      const ids = Array.from(selectedRequestIds);
      let count = 0;

      for (const id of ids) {
          await db.resolveDuplicateRequest(id, action, user.id);
          count++;
          if (count % 5 === 0) setProgress(Math.round((count / ids.length) * 100));
      }

      await loadRequests();
      await loadUniqueFsns();
      setSelectedRequestIds(new Set());
      setLoading(false);
      setProgress(0);
      setProcessingStatus('');
  };

  const handleExport = async (mode: 'MONTH' | 'FULL') => {
    setExportLoading(true);
    setProcessingStatus('Generating Export...');
    setLoading(true);
    setProgress(30);

    try {
        const records = await db.getRecords();
        let dataToExport = records;

        if (mode === 'MONTH') {
            const [year, month] = selectedMonth.split('-').map(Number);
            const startOfMonth = new Date(year, month - 1, 1).toISOString().split('T')[0];
            const endOfMonth = new Date(year, month, 0).toISOString().split('T')[0];
            dataToExport = records.filter(r => r.startDate <= endOfMonth && r.endDate >= startOfMonth);
        }

        setProgress(70);

        const csv = Papa.unparse(dataToExport.map(r => ({
            ID: r.id,
            FSN: r.fsn,
            Brand: r.brand,
            Title: r.title,
            Vertical: r.vertical,
            KAM: r.kam,
            City: r.city,
            Type: r.type,
            Value: r.value,
            StartDate: r.startDate,
            EndDate: r.endDate,
            LastUpdatedBy: r.lastUpdatedBy,
            LastUpdatedAt: new Date(r.lastUpdatedAt).toISOString()
        })));

        setProgress(100);

        const blob = new Blob([csv], { type: 'text/csv' });
        const url = window.URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `mm_export_${mode.toLowerCase()}_${Date.now()}.csv`;
        a.click();
        window.URL.revokeObjectURL(url);
    } catch (e) {
        alert('Export failed');
    } finally {
        setExportLoading(false);
        setLoading(false);
        setProgress(0);
    }
  };

  const initiateClearDB = () => {
      setClearConfirmationText('');
      setShowClearModal(true);
  };

  const confirmClearDB = async () => {
    setShowClearModal(false);
    setLoading(true);
    setProcessingStatus('Archiving active records...');
    setProgress(10);

    try {
        // Simulate progress for heavy DB op
        const interval = setInterval(() => {
            setProgress(prev => Math.min(prev + 10, 90));
        }, 200);

        await db.clearAllRecords(user.name);

        clearInterval(interval);
        setProgress(100);

        alert("Database reset. Records archived.");
        setAuditResult(null);
        setRequests([]);
        loadArchive();
        setAllFsns([]);
        setBulkResults(null);
    } catch (e) {
        alert("Failed.");
    } finally {
        setLoading(false);
        setProgress(0);
        setClearConfirmationText('');
    }
  };

  const CustomTooltip = ({ active, payload, label }: any) => {
    if (active && payload && payload.length) {
      return (
        <div className="bg-white border border-gray-200 p-3 rounded shadow-lg text-xs">
