                    <button 
                      onClick={() => { setView('MANUAL'); setMobileMenuOpen(false); }}
                      className={`w-full text-left py-2 px-4 text-sm font-medium hover:bg-blue-50 hover:text-fkBlue transition-colors ${view === 'MANUAL' ? 'text-fkBlue bg-blue-50 font-bold' : 'text-gray-600'}`}
                    >
                      User Manual
                    </button>
                 </div>
              </div>

              <div className="border-t border-gray-100 p-4 mt-auto md:hidden">
                 <button onClick={handleLogout} className="text-sm font-medium text-red-600 w-full text-left flex items-center gap-2">
