                            checked={filteredRequests.length > 0 && filteredRequests.every(r => selectedRequestIds.has(r.id))}
                            onChange={toggleSelectAllRequests}
                            className="w-5 h-5 rounded border-gray-300 text-fkBlue focus:ring-fkBlue cursor-pointer"
                        />
                        <span className="font-semibold text-gray-700">
                            {selectedRequestIds.size === 0 ? 'Select All' : `${selectedRequestIds.size} Selected`}
                        </span>
                    </div>
                    {selectedRequestIds.size > 0 && (
                        <div className="flex gap-2">
                            <button 
                                onClick={() => handleBulkAction('REJECTED')}
                                className="px-4 py-2 bg-white border border-red-200 text-red-600 hover:bg-red-50 rounded text-sm font-bold transition-colors"
                            >
                                Reject ({selectedRequestIds.size})
                            </button>
                            <button 
                                onClick={() => handleBulkAction('APPROVED')}
                                className="px-4 py-2 bg-fkGreen hover:bg-green-700 text-white rounded text-sm font-bold shadow-sm transition-colors"
                            >
                                Approve ({selectedRequestIds.size})
                            </button>
                        </div>
                    )}
                </div>
           )}

          {requests.length === 0 ? (
            <div className="text-center py-20 bg-white rounded-lg border border-gray-200">
              <Check className="w-12 h-12 mx-auto mb-3 text-green-500 opacity-50" />
              <p className="text-gray-500 font-medium">No pending approvals.</p>
            </div>
          ) : filteredRequests.length === 0 ? (
             <div className="text-center py-20 bg-white rounded-lg border border-gray-200">
                <Search className="w-12 h-12 mx-auto mb-3 text-gray-300" />
                <p className="text-gray-500 font-medium">No requests match "{approvalSearchTerm}".</p>
             </div>
          ) : (
            filteredRequests.map(req => (
              <div key={req.id} className={`fk-card p-5 flex flex-col md:flex-row gap-4 border-l-4 border-l-fkYellow transition-colors ${selectedRequestIds.has(req.id) ? 'bg-blue-50/30' : ''}`}>
                <div className="flex items-start gap-4 flex-1">
                     <input 
                        type="checkbox"
                        checked={selectedRequestIds.has(req.id)}
                        onChange={() => toggleSelectRequest(req.id)}
                        className="mt-1.5 w-5 h-5 rounded border-gray-300 text-fkBlue focus:ring-fkBlue cursor-pointer flex-shrink-0"
                     />
                     <div className="flex-1">
                        <div className="flex items-center gap-2 mb-2">
                            <span className="bg-yellow-100 text-yellow-800 text-xs px-2 py-0.5 rounded font-bold">ACTION REQUIRED</span>
                            <h4 className="font-bold text-gray-800 text-lg">{req.payload.title} <span className="text-gray-400 font-normal">({req.payload.fsn})</span></h4>
                        </div>
                        <div className="text-sm text-gray-500 grid grid-cols-2 md:grid-cols-4 gap-x-8 gap-y-1 mb-2">
                            <span>City: <b className="text-gray-800">{req.payload.city}</b></span>
                            <span>Type: <b className="text-gray-800">{req.payload.type}</b></span>
                            <span>New Value: <b className="text-fkBlue">{req.payload.value}</b></span>
                            <span>By: {req.requestedBy}</span>
                        </div>
                        <div className="text-xs flex gap-4 text-gray-400">
                            <span className="flex items-center gap-1"><Layers className="w-3 h-3"/> {req.payload.vertical || 'N/A'}</span>
                            <span className="flex items-center gap-1"><UserIcon className="w-3 h-3"/> {req.payload.kam || 'N/A'}</span>
                        </div>
                        {req.reason && (
                            <div className="mt-2 bg-red-50 text-red-600 text-xs px-2 py-1 rounded inline-block font-semibold">
                                Reason: {req.reason}
                            </div>
                        )}
                     </div>
                </div>

                <div className="flex gap-2 w-full md:w-auto self-start md:self-center pl-9 md:pl-0">
                  <button 
                    onClick={() => handleRequestAction(req.id, 'REJECTED')}
                    className="flex-1 md:flex-none px-4 py-2 rounded bg-gray-100 hover:bg-gray-200 text-gray-700 text-sm font-medium transition-colors"
                  >
                    Reject
                  </button>
                  <button 
                    onClick={() => handleRequestAction(req.id, 'APPROVED')}
                    className="flex-1 md:flex-none px-4 py-2 rounded bg-fkGreen hover:bg-green-700 text-white font-bold text-sm shadow transition-colors"
                  >
                    Approve
                  </button>
                </div>
              </div>
            ))
          )}
        </div>
      )}

      {activeTab === 'CLOSURE' && (
        <div className="space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                {/* Export Section */}
                <div className="fk-card p-6 space-y-4">
                    <div className="flex items-center gap-3 mb-2">
                        <div className="bg-blue-50 p-3 rounded-lg">
                            <FileDown className="w-6 h-6 text-fkBlue" />
                        </div>
                        <div>
                            <h3 className="text-lg font-bold text-gray-800">Export Data</h3>
                            <p className="text-sm text-gray-500">Download data for records and auditing.</p>
                        </div>
                    </div>

                    <div className="pt-4 space-y-4 border-t border-gray-100">
                        <div>
                            <label className="block text-xs font-bold text-gray-500 mb-2 flex items-center gap-2 uppercase">
                                <Calendar className="w-3 h-3" /> Select Month
                            </label>
                            <input 
                                type="month"
                                className="w-full bg-white border border-gray-300 rounded p-2 text-gray-800"
                                value={selectedMonth}
                                onChange={(e) => setSelectedMonth(e.target.value)}
                            />
                        </div>
                        <div className="flex flex-col gap-3">
                            <button 
                                onClick={() => handleExport('MONTH')}
                                disabled={exportLoading}
                                className="w-full py-2 bg-fkBlue hover:bg-blue-600 rounded text-white text-sm font-bold shadow-sm transition-colors"
                            >
                                Export {selectedMonth} Data
                            </button>
                            <button 
                                onClick={() => handleExport('FULL')}
                                disabled={exportLoading}
                                className="w-full py-2 border border-gray-300 hover:bg-gray-50 rounded text-gray-600 text-sm font-medium transition-colors"
                            >
                                Export Full Database
                            </button>
                        </div>
                    </div>
                </div>

                {/* Clear Section */}
                <div className="fk-card p-6 space-y-4 border-red-100 bg-red-50/30">
                    <div className="flex items-center gap-3 mb-2">
                        <div className="bg-red-100 p-3 rounded-lg">
                            <Database className="w-6 h-6 text-red-600" />
                        </div>
                        <div>
                            <h3 className="text-lg font-bold text-red-600">System Reset</h3>
                            <p className="text-sm text-gray-500">Clear database for new operational cycle.</p>
                        </div>
                    </div>

                    <div className="pt-4 space-y-4 border-t border-red-100">
                        <div className="bg-red-50 border border-red-100 p-4 rounded text-sm text-red-700">
                            <p className="flex items-start gap-2">
                                <AlertCircle className="w-5 h-5 flex-shrink-0" />
                                <span>
                                    <strong>Warning:</strong> This deletes ALL active records. Export data first.
                                </span>
                            </p>
                        </div>

                        <button 
                            onClick={initiateClearDB}
                            disabled={loading}
                            className="w-full py-3 bg-red-600 hover:bg-red-700 rounded text-white font-bold shadow-md flex items-center justify-center gap-2 transition-all"
                        >
                            <Trash2 className="w-4 h-4" /> Clear Database
                        </button>
                    </div>
                </div>
            </div>

            {/* Archive Viewer */}
            <div className="fk-card p-6 space-y-4">
                 <div className="flex items-center justify-between">
                     <h3 className="text-lg font-bold text-gray-800 flex items-center gap-2">
                        <Archive className="w-5 h-5 text-gray-500" /> Archived Records (Bin)
                     </h3>
                     <button onClick={toggleArchive} className="flex items-center gap-2 text-sm text-fkBlue hover:underline transition-colors font-medium">
                        {showArchive ? 'Hide Archive' : 'View Deleted Records'}
                        <Clock className="w-3 h-3" />
                     </button>
                 </div>

                 {showArchive && (
                     <div className="overflow-auto max-h-80 border border-gray-200 rounded-lg animate-in fade-in">
                        <table className="w-full text-left text-xs text-gray-600">
                            <thead className="bg-gray-50 sticky top-0 font-bold text-gray-700 border-b border-gray-200">
                                <tr>
                                    <th className="p-3">Deleted At</th>
                                    <th className="p-3">Deleted By</th>
                                    <th className="p-3">FSN</th>
                                    <th className="p-3">City</th>
                                    <th className="p-3">Reason</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-gray-100 bg-white">
                                {archiveData.map((r, i) => (
                                    <tr key={i} className="hover:bg-gray-50">
                                        <td className="p-3 font-mono text-gray-500">{new Date(r.deletedAt).toLocaleString()}</td>
                                        <td className="p-3">{r.deletedBy}</td>
                                        <td className="p-3 font-medium">{r.fsn}</td>
                                        <td className="p-3">{r.city}</td>
                                        <td className="p-3 text-fkYellow font-medium">{r.note || 'Manual Delete/Override'}</td>
                                    </tr>
                                ))}
                                {archiveData.length === 0 && <tr><td colSpan={5} className="p-6 text-center italic text-gray-400">Bin is empty</td></tr>}
                            </tbody>
                        </table>
                     </div>
                 )}
            </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { User, Role } from './types';
import { db } from './services/db';
import { Login, PinVerification } from './components/Auth';
import { MakerWorkspace } from './components/MakerWorkspace';
import { CheckerWorkspace } from './components/CheckerWorkspace';
import { DataExplorer } from './components/DataExplorer';
import { UserManual } from './components/UserManual';
import { Tour, TourStep } from './components/Tour';
import { Shield, Briefcase, Menu, Zap, Book, PlayCircle, Search as SearchIcon, User as UserIcon, ChevronDown, Home, Database, FileText, LogOut } from 'lucide-react';

const TOUR_STEPS: TourStep[] = [
  {
    title: "Welcome to Minutes Master",
    content: "This application streamlines commercial operations by separating duties between Makers (Entry) and Checkers (Audit). Let's take a quick tour of the key features.",
    view: 'WORKSPACE',
    role: 'MAKER'
  },
  {
    title: "Maker: Manual Entry",
    content: "Category Managers use this form to create individual records. The system automatically detects conflicts (overlaps) and high margin values (>60%) to trigger approval workflows.",
    targetId: 'tour-maker-manual',
    view: 'WORKSPACE',
    role: 'MAKER'
  },
  {
    title: "Maker: Bulk Upload",
    content: "For high volume updates, Makers can upload CSV files. The system validates headers, detects new cities automatically, and processes records in optimized batches.",
    targetId: 'tour-maker-bulk',
    view: 'WORKSPACE',
    role: 'MAKER',
    tab: 'BULK' 
  },
  {
    title: "Checker: Audit Tool",
    content: "Finance teams use this workspace. The Audit Tool allows comparison of System Data vs Target Margins (Value or %), instantly highlighting variances.",
    targetId: 'tour-checker-audit',
    view: 'WORKSPACE',
    role: 'CHECKER'
  },
  {
    title: "Checker: Approvals",
    content: "Any data entry that flagged a conflict or high margin appears here. Checkers can bulk approve or reject changes. Approved conflicts automatically archive the old record.",
    targetId: 'tour-checker-approvals',
    view: 'WORKSPACE',
    role: 'CHECKER'
  },
  {
    title: "Data Explorer",
    content: "A unified view of the active database. Checkers can edit or delete records directly in this grid view for quick corrections.",
    view: 'EXPLORER',
    role: 'CHECKER'
  }
];

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [view, setView] = useState<'WORKSPACE' | 'EXPLORER' | 'MANUAL'>('WORKSPACE');
  const [showPin, setShowPin] = useState(false);
  const [isCheckerVerified, setIsCheckerVerified] = useState(false);
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);

  // Tour State
  const [isTourOpen, setIsTourOpen] = useState(false);
  const [currentStepIndex, setCurrentStepIndex] = useState(0);

  // Check persisted session
  useEffect(() => {
    const savedUser = localStorage.getItem('mm_session_user');
    if (savedUser) setUser(JSON.parse(savedUser));

    // Check PIN cache
    const pinCache = localStorage.getItem('mm_pin_verified');
    if (pinCache) {
       const { expiry } = JSON.parse(pinCache);
       if (new Date().getTime() < expiry) setIsCheckerVerified(true);
    }
  }, []);

  // Tour Logic: Automatically switch views/roles based on step
  useEffect(() => {
    if (isTourOpen) {
      const step = TOUR_STEPS[currentStepIndex];
      setView(step.view);

      if (user) {
         if (step.role === 'CHECKER') setIsCheckerVerified(true);
      }
    }
  }, [currentStepIndex, isTourOpen]);

  const handleLogin = (u: User) => {
    setUser(u);
    localStorage.setItem('mm_session_user', JSON.stringify(u));
  };

  const handleLogout = () => {
    setUser(null);
    setIsCheckerVerified(false);
    localStorage.removeItem('mm_session_user');
    localStorage.removeItem('mm_pin_verified');
    setView('WORKSPACE');
  };

  const verifyPin = () => {
    setIsCheckerVerified(true);
    setShowPin(false);
    // 30 Days Expiry
    const expiry = new Date();
    expiry.setDate(expiry.getDate() + 30);
    localStorage.setItem('mm_pin_verified', JSON.stringify({ expiry: expiry.getTime() }));
  };

  const startTour = () => {
     setIsTourOpen(true);
     setCurrentStepIndex(0);
     setMobileMenuOpen(false);
     if (!user) {
         const demoUser: User = { id: 'demo', name: 'Demo User', role: Role.MAKER, employeeId: 'demo' };
         setUser(demoUser);
         setIsCheckerVerified(true);
     }
  };

  const handleSwitchRole = async (targetRole: Role) => {
    if (targetRole === user?.role) return;

    let empId = 'maker1';
    if (targetRole === Role.CHECKER) empId = 'checker1';

    const newUser = await db.login(empId);
    if (newUser) {
      handleLogin(newUser);
      setView('WORKSPACE');
      // If switching to a restricted role, reset verification to simulate real login flow
      if (targetRole === Role.CHECKER) {
        setIsCheckerVerified(false); 
      }
    }
  };

  if (!user) {
    return <Login onLogin={handleLogin} />;
  }

  // Guard Clause for Checker Access
  const renderWorkspace = () => {
    const effectiveRole = isTourOpen ? TOUR_STEPS[currentStepIndex].role : user.role;

    if (effectiveRole === Role.MAKER) return <MakerWorkspace user={user} />;

    // For Checker
    if (!isCheckerVerified && !isTourOpen) {
       return (
         <div className="h-full flex flex-col items-center justify-center text-center space-y-6 bg-white rounded shadow p-8 max-w-xl mx-auto mt-10">
            <div className="p-4 bg-blue-50 rounded-full">
                <Shield className="w-12 h-12 text-fkBlue" />
            </div>
            <div>
              <h2 className="text-xl font-medium text-gray-800">Restricted Access</h2>
              <p className="text-gray-500 mt-2 text-sm">Checker workspace contains sensitive auditing tools. Security verification is required.</p>
            </div>
            <button 
              onClick={() => setShowPin(true)}
              className="bg-fkYellow text-white px-10 py-3 rounded-sm shadow hover:shadow-lg transition-all font-medium uppercase text-sm tracking-wide"
            >
              Verify Identity
            </button>
         </div>
       );
    }
    return <CheckerWorkspace user={user} />;
  };

  return (
    <div className="flex flex-col h-screen bg-[#f1f3f6] text-fkText overflow-hidden font-sans">

      {/* Flipkart-style Navbar */}
      <header className="bg-fkBlue text-white h-16 flex items-center shadow-md z-50 print:hidden shrink-0">
        <div className="container mx-auto max-w-[1400px] px-4 md:px-6 flex justify-between items-center h-full">

          <div className="flex items-center gap-4">
            <button onClick={() => setMobileMenuOpen(!mobileMenuOpen)} className="md:hidden p-1">
              <Menu className="w-6 h-6" />
            </button>

            {/* Logo */}
            <div 
              className="flex flex-col items-end cursor-pointer group select-none"
              onClick={() => setView('WORKSPACE')}
            >
              <div className="flex items-center gap-1">
                 <span className="font-bold text-lg md:text-xl italic tracking-tight">Flipkart</span>
                 <div className="bg-fkYellow text-white p-0.5 rounded-sm">
                    <Zap className="w-3 h-3 md:w-4 md:h-4 fill-current text-white" />
                 </div>
              </div>
              <span className="text-[10px] md:text-xs font-medium text-gray-200 hover:text-white flex items-center gap-0.5 -mt-1 tracking-wide">
                Minutes<span className="text-fkYellow font-bold">Master</span>
              </span>
            </div>
          </div>

          {/* Search Bar (Mock) */}
          <div className="hidden md:flex flex-1 max-w-xl mx-8 relative">
             <input 
               type="text" 
               placeholder="Search for Products, FSNs or Brands" 
               className="w-full py-2 px-4 rounded-sm text-gray-800 text-sm focus:outline-none shadow-sm"
             />
             <SearchIcon className="absolute right-3 top-2.5 w-4 h-4 text-fkBlue" />
          </div>

          {/* Nav Items */}
          <div className="flex items-center gap-6 md:gap-8 text-sm font-medium">

             {/* Role Switcher Dropdown */}
             <div className="relative group hidden md:block">
                 <button className="flex items-center gap-1 cursor-pointer bg-white text-fkBlue px-5 py-1 rounded-sm border border-[#dbdbdb] hover:bg-blue-50 transition-colors">
                    <span>{user.role}</span>
                    <ChevronDown className="w-3 h-3 group-hover:rotate-180 transition-transform" />
                 </button>

                 <div className="absolute top-full right-0 mt-1 bg-white text-gray-800 w-32 rounded-sm shadow-lg border border-gray-100 hidden group-hover:block z-50 animate-in fade-in slide-in-from-top-1 duration-200">
                     {Object.values(Role).map((roleValue) => (
                         <button 
                            key={roleValue}
                            onClick={() => handleSwitchRole(roleValue)}
                            className={`w-full text-left px-4 py-2 hover:bg-gray-50 text-xs ${user.role === roleValue ? 'font-bold text-fkBlue bg-blue-50' : 'text-gray-600'}`}
                         >
                            {roleValue}
                         </button>
                     ))}
                 </div>
             </div>

             {/* Standalone Tour Button (Moved from Dropdown) */}
             <button 
                onClick={startTour} 
                className="flex items-center gap-2 hover:text-fkYellow transition-colors group" 
                title="Start Tour"
             >
                <PlayCircle className="w-4 h-4 group-hover:fill-fkYellow" />
                <span className="hidden lg:inline group-hover:underline">Tour Guide</span>
             </button>

             {/* User Name (Static, No Dropdown) */}
             <div className="flex items-center gap-2 cursor-default select-none">
                <div className="w-7 h-7 bg-white/20 rounded-full flex items-center justify-center text-xs font-bold shadow-sm">
                    {user.name.charAt(0)}
                </div>
                <span className="hidden md:inline">{user.name}</span>
             </div>

             <button 
                onClick={handleLogout}
                className="flex items-center gap-1 cursor-pointer hover:text-gray-100 transition-colors group"
                title="Logout"
             >
                <LogOut className="w-4 h-4 group-hover:text-red-300" />
                <span className="hidden md:inline group-hover:text-red-100">Logout</span>
             </button>
          </div>
        </div>
      </header>

      {/* Content Area */}
      <div className="flex flex-1 overflow-hidden container mx-auto max-w-[1400px]">

        {/* Sidebar (Desktop) - Like My Account Sidebar */}
        <aside className={`fixed md:relative z-40 w-64 bg-white md:bg-transparent h-full transform transition-transform duration-300 ${mobileMenuOpen ? 'translate-x-0' : '-translate-x-full'} md:translate-x-0 md:block shrink-0 md:py-4 print:hidden`}>
           <div className="bg-white md:shadow-card md:rounded-sm h-full md:h-auto overflow-hidden">

              <div className="p-4 border-b border-gray-100 flex items-center gap-3">
                 <div className="w-12 h-12 rounded-full bg-gray-100 flex items-center justify-center">
                    <UserIcon className="w-6 h-6 text-fkBlue" />
                 </div>
                 <div>
                    <div className="text-xs text-gray-500">Hello,</div>
                    <div className="font-bold text-gray-800">{user.name}</div>
                 </div>
              </div>

              <div className="py-2">

                 {/* Home Button */}
                 <div className="px-4 mb-2">
                    <button 
                      onClick={() => { setView('WORKSPACE'); setMobileMenuOpen(false); }}
                      className={`w-full text-left py-2 px-4 text-sm font-medium hover:bg-blue-50 hover:text-fkBlue transition-colors rounded-sm flex items-center gap-3 ${view === 'WORKSPACE' ? 'text-fkBlue bg-blue-50 font-bold' : 'text-gray-600'}`}
                    >
                      <Home className="w-4 h-4" />
                      Home
                    </button>
                 </div>

                 <div className="px-4 py-3 border-t border-gray-50">
                    <div className="text-xs font-medium text-gray-400 uppercase tracking-wide mb-2 flex items-center gap-2">
                       <Briefcase className="w-3 h-3 text-fkBlue" /> Operations
                    </div>
                    {/* Data Explorer */}
                    <button 
                      onClick={() => { setView('EXPLORER'); setMobileMenuOpen(false); }}
                      className={`w-full text-left py-2 px-4 text-sm font-medium hover:bg-blue-50 hover:text-fkBlue transition-colors rounded-sm flex items-center gap-3 ${view === 'EXPLORER' ? 'text-fkBlue bg-blue-50 font-bold' : 'text-gray-600'}`}
                    >
                      <Database className="w-4 h-4" />
                      Data Explorer
                    </button>
                 </div>

                 <div className="px-4 py-3">
                    <div className="text-xs font-medium text-gray-400 uppercase tracking-wide mb-2 flex items-center gap-2">
                       <Book className="w-3 h-3 text-fkBlue" /> Resources
                    </div>
                    <button 
                      onClick={() => { setView('MANUAL'); setMobileMenuOpen(false); }}
                      className={`w-full text-left py-2 px-4 text-sm font-medium hover:bg-blue-50 hover:text-fkBlue transition-colors rounded-sm flex items-center gap-3 ${view === 'MANUAL' ? 'text-fkBlue bg-blue-50 font-bold' : 'text-gray-600'}`}
                    >
                      <FileText className="w-4 h-4" />
                      User Manual
                    </button>
                 </div>
              </div>
           </div>
        </aside>

        {/* Overlay for mobile sidebar */}
        {mobileMenuOpen && (
           <div className="fixed inset-0 bg-black/50 z-30 md:hidden" onClick={() => setMobileMenuOpen(false)} />
        )}

        {/* Main Content View */}
        <main className="flex-1 overflow-auto p-4 md:py-4 md:px-6 relative print:p-0 print:overflow-visible no-scrollbar">
           {view === 'WORKSPACE' && renderWorkspace()}
           {view === 'EXPLORER' && <DataExplorer user={user} />}
           {view === 'MANUAL' && <UserManual />}
        </main>

      </div>

      {showPin && (
        <PinVerification 
          user={user} 
          onSuccess={verifyPin} 
          onCancel={() => setShowPin(false)} 
        />
      )}

      {/* Tour Overlay */}
      {isTourOpen && (
        <Tour 
           step={TOUR_STEPS[currentStepIndex]}
           currentStepIndex={currentStepIndex}
           totalSteps={TOUR_STEPS.length}
           onNext={() => {
             if (currentStepIndex < TOUR_STEPS.length - 1) {
               setCurrentStepIndex(currentStepIndex + 1);
             } else {
               setIsTourOpen(false);
             }
           }}
           onPrev={() => setCurrentStepIndex(Math.max(0, currentStepIndex - 1))}
           onClose={() => setIsTourOpen(false)}
        />
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { db } from '../services/db';
import { DuplicateRequest, User, CommercialType, CommercialRecord } from '../types';
import { Check, X, Search, BarChart3, Archive, TrendingUp, AlertCircle, FileDown, Calendar, Trash2, Database, Clock, ChevronDown, User as UserIcon, Layers, Upload, FileText, RefreshCw, Loader2, CheckSquare } from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer, ReferenceLine, LabelList } from 'recharts';
import Papa from 'papaparse';

interface CheckerProps {
  user: User;
}

export const CheckerWorkspace: React.FC<CheckerProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<'AUDIT' | 'APPROVALS' | 'CLOSURE'>('AUDIT');
  const [requests, setRequests] = useState<DuplicateRequest[]>([]);
  const [cities, setCities] = useState<string[]>([]);

  // Selection State for Approvals
  const [selectedRequestIds, setSelectedRequestIds] = useState<Set<string>>(new Set());
  const [approvalSearchTerm, setApprovalSearchTerm] = useState('');

  // Audit State (Single)
  const [auditMode, setAuditMode] = useState<'SINGLE' | 'BULK'>('SINGLE');
  const [auditQuery, setAuditQuery] = useState({ fsn: '', city: 'BLR', targetMargin: 0, unit: 'PERCENT' });
  const [auditResult, setAuditResult] = useState<any>(null);

  // Audit State (Bulk)
  const [bulkAuditData, setBulkAuditData] = useState<any[]>([]);
  const [bulkAuditCity, setBulkAuditCity] = useState('BLR');
  const [bulkResults, setBulkResults] = useState<any[] | null>(null);
  const [bulkFile, setBulkFile] = useState<string | null>(null);

  const [loading, setLoading] = useState(false);

  // Progress State
  const [progress, setProgress] = useState(0);
  const [eta, setEta] = useState<string | null>(null);
  const [processingStatus, setProcessingStatus] = useState<string>('');

  // Autocomplete State
  const [allFsns, setAllFsns] = useState<string[]>([]);
  const [filteredFsns, setFilteredFsns] = useState<string[]>([]);
  const [showSuggestions, setShowSuggestions] = useState(false);

  // Closure/Export State
  const [selectedMonth, setSelectedMonth] = useState(new Date().toISOString().slice(0, 7)); // YYYY-MM
  const [exportLoading, setExportLoading] = useState(false);

  // Archive View State
  const [showArchive, setShowArchive] = useState(false);
  const [archiveData, setArchiveData] = useState<any[]>([]);

  // Safety Modal State
  const [showClearModal, setShowClearModal] = useState(false);
  const [clearConfirmationText, setClearConfirmationText] = useState('');

  useEffect(() => {
    loadRequests();
    loadCities();
    loadUniqueFsns();
    const interval = setInterval(loadRequests, 5000);
    return () => clearInterval(interval);
  }, []);

  // Sync selection with requests list (cleanup ghosts)
  useEffect(() => {
      const currentIds = new Set(requests.map(r => r.id));
      setSelectedRequestIds(prev => {
          const next = new Set();
          let changed = false;
          prev.forEach(id => {
              if (currentIds.has(id)) next.add(id);
              else changed = true;
          });
          return changed ? next : prev;
      });
  }, [requests]);

  const filteredRequests = useMemo(() => {
    if (!approvalSearchTerm.trim()) return requests;
    const lowerTerm = approvalSearchTerm.toLowerCase();
    return requests.filter(req => 
      req.payload.fsn.toLowerCase().includes(lowerTerm) ||
      req.payload.title.toLowerCase().includes(lowerTerm) ||
      req.requestedBy.toLowerCase().includes(lowerTerm) ||
      (req.payload.kam && req.payload.kam.toLowerCase().includes(lowerTerm))
    );
  }, [requests, approvalSearchTerm]);

  const loadCities = async () => {
    const c = await db.getCities();
    setCities(c);
    if (!c.includes(auditQuery.city)) {
       setAuditQuery(prev => ({ ...prev, city: c.includes('BLR') ? 'BLR' : c[0] || '' }));
    }
  };

  const loadUniqueFsns = async () => {
    const records = await db.getRecords();
    const unique = Array.from(new Set(records.map(r => r.fsn)));
    setAllFsns(unique);
  };

  const loadRequests = async () => {
    const reqs = await db.getDuplicateRequests();
    setRequests(reqs.filter(r => r.status === 'PENDING'));
  };

  const loadArchive = async () => {
    const data = await db.getBinRecords();
    setArchiveData(data.sort((a: any, b: any) => b.deletedAt - a.deletedAt));
  };

  const toggleArchive = () => {
      if (!showArchive) loadArchive();
      setShowArchive(!showArchive);
  };

  const handleFsnChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = e.target.value;
    setAuditQuery({ ...auditQuery, fsn: val });

    if (val.length > 0) {
        const matches = allFsns.filter(f => f.toLowerCase().includes(val.toLowerCase()));
        setFilteredFsns(matches.slice(0, 5)); // Limit to 5 suggestions
        setShowSuggestions(true);
    } else {
        setShowSuggestions(false);
    }
  };

  const selectSuggestion = (fsn: string) => {
      setAuditQuery({ ...auditQuery, fsn });
      setShowSuggestions(false);
  };

  // SINGLE AUDIT Logic
  const handleAudit = async () => {
    if (!auditQuery.fsn) return;

    if (auditQuery.fsn.length !== 16) {
        alert("FSN must be exactly 16 characters.");
        return;
    }

    setLoading(true);
    setProcessingStatus('Analyzing FSN...');
    setProgress(50);
    setShowSuggestions(false); 

    const records = await db.getRecords();
    const today = new Date().toISOString().split('T')[0];

    // 1. Filter relevant records (Active & City Match/PAN)
    const activeRecords = records.filter(r => 
      r.fsn === auditQuery.fsn && 
      (r.city === auditQuery.city || r.city === 'PAN-INDIA') &&
      r.startDate <= today && r.endDate >= today
    );

    let baseVal = 0;
    let baseType = '-';
    let onInvVal = 0;
    let onInvSource = '-';
    let systemTotal = 0;

    const getRec = (type: CommercialType) => 
        activeRecords.find(r => r.type === type && r.city === auditQuery.city) ||
        activeRecords.find(r => r.type === type && r.city === 'PAN-INDIA');

    if (auditQuery.unit === 'PERCENT') {
        // Logic: Margin % > NLC %
        const marginRec = getRec(CommercialType.MARGIN_PERCENT);
        if (marginRec) {
            baseVal = marginRec.value;
            baseType = 'Margin %';
        } else {
            const nlcRec = getRec(CommercialType.NLC_PERCENT);
            if (nlcRec) {
                baseVal = nlcRec.value;
                baseType = 'NLC %';
            }
        }

        // On Invoice Logic
        const onRec = getRec(CommercialType.ON_INVOICE);
        if (onRec) {
            onInvVal = onRec.value;
            onInvSource = onRec.city === 'PAN-INDIA' ? 'PAN' : 'City';
        }

        systemTotal = baseVal + onInvVal;
    } else {
        // Logic: NLC Value (Amount)
        const nlcValRec = getRec(CommercialType.NLC_VALUE);
        if (nlcValRec) {
            baseVal = nlcValRec.value;
            baseType = 'NLC Value';
        }

        // On Invoice (For display only, not added to total)
        const onRec = getRec(CommercialType.ON_INVOICE);
        if (onRec) {
            onInvVal = onRec.value;
            onInvSource = onRec.city === 'PAN-INDIA' ? 'PAN' : 'City';
        }

        systemTotal = baseVal;
    }

    const variance = auditQuery.targetMargin - systemTotal;
    const variancePercent = auditQuery.targetMargin ? ((variance / auditQuery.targetMargin) * 100) : 0;

    setAuditResult({
      data: [
        { name: 'System', base: baseVal, onInv: auditQuery.unit === 'PERCENT' ? onInvVal : 0, total: systemTotal },
        { name: 'Target', target: auditQuery.targetMargin }
      ],
      systemTotal,
      targetTotal: auditQuery.targetMargin,
      variance,
      variancePercent: variancePercent.toFixed(2),
      status: Math.abs(variance) < 0.01 ? 'MATCH' : 'MISMATCH',
      details: activeRecords,
      baseType,
      onInvVal,
      onInvSource
    });
    setLoading(false);
    setProgress(100);
    setTimeout(() => { setProgress(0); }, 500);
  };

  // BULK AUDIT Handlers
  const handleBulkUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (!file) return;
      setBulkFile(file.name);

      setLoading(true);
      setProcessingStatus('Parsing CSV...');
      setProgress(0);
      setEta('Starting...');

      // Wrap in setTimeout to ensure UI updates before heavy parsing
      setTimeout(() => {
        Papa.parse(file, {
            header: true,
            skipEmptyLines: true,
            complete: (results) => {
                setBulkAuditData(results.data as any[]);
                setBulkResults(null);
                setLoading(false);
                setProgress(100);
                setTimeout(() => setProgress(0), 500);
            }
        });
      }, 100);
  };

  const downloadAuditTemplate = () => {
    const headers = ['FSN', 'Margin Value', 'Margin Rule', 'Margin Value Unit'];
    const dummyRow = ['MOBEXAMPLE123456', '20.5', 'MRP_GROSS_OF_TAXES', 'PERCENT'];
    const csvContent = [headers.join(','), dummyRow.join(',')].join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv' });
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `audit_template.csv`;
    a.click();
    window.URL.revokeObjectURL(url);
  };

  const runBulkAudit = async () => {
      if (bulkAuditData.length === 0) return;
      setLoading(true);
      setProcessingStatus('Building Search Index...');
      setProgress(0);
      setEta('Calculating...');

      const records = await db.getRecords();
      const today = new Date().toISOString().split('T')[0];

      // OPTIMIZATION: Build Index for O(1) lookup
      const fsnIndex = new Map<string, CommercialRecord[]>();
      records.forEach(r => {
          if(!fsnIndex.has(r.fsn)) fsnIndex.set(r.fsn, []);
          fsnIndex.get(r.fsn)!.push(r);
      });

      const BATCH_SIZE = 200;
      const totalItems = bulkAuditData.length;
      const startTime = Date.now();
      const resultsAccumulator: any[] = [];

      setProcessingStatus('Starting Bulk Audit...');

      const processBatch = async () => {
          for (let i = 0; i < totalItems; i++) {
               // Update Progress
               if (i % BATCH_SIZE === 0 && i > 0) {
                   const percent = Math.round((i / totalItems) * 100);
                   const elapsed = (Date.now() - startTime) / 1000;
                   const rate = i / elapsed;
                   const remainingSeconds = (totalItems - i) / rate;

                   setProgress(percent);
                   setEta(remainingSeconds < 60 ? `${Math.ceil(remainingSeconds)}s` : `${Math.ceil(remainingSeconds/60)}m`);
                   setProcessingStatus(`Auditing row ${i}/${totalItems}`);

                   await new Promise(resolve => setTimeout(resolve, 0));
               }

               const row = bulkAuditData[i] as any;
               if (!row) continue;

               // Fix: Ensure FSN is treated as a string
               const fsnRaw = row['FSN'];
               const fsn = fsnRaw ? String(fsnRaw) : '';

               // Fix: Ensure value is string before passing to parseFloat to avoid 'unknown' type error
               // Explicitly convert to string to handle 'unknown' types safely
               const marginValRaw = row['Margin Value'];
               let marginValStr = '0';
               if (marginValRaw !== undefined && marginValRaw !== null) {
                   marginValStr = String(marginValRaw);
               }
               const targetVal = parseFloat(marginValStr);

               const unitRaw = row['Margin Value Unit'];
               const unit = (unitRaw ? String(unitRaw) : '').toUpperCase();

               if (!fsn) continue;

               // OPTIMIZATION: Use Map Index instead of array.filter
               const candidates = fsnIndex.get(fsn) || [];
               const activeRecords = candidates.filter(r => 
                   (r.city === bulkAuditCity || r.city === 'PAN-INDIA') &&
                   r.startDate <= today && r.endDate >= today
               );

               let baseVal = 0;
               let baseType = '-';
               let onInvVal = 0;
               let onInvSource = '-';

               const getRec = (type: CommercialType) => 
                     activeRecords.find(r => r.type === type && r.city === bulkAuditCity) ||
                     activeRecords.find(r => r.type === type && r.city === 'PAN-INDIA');

               if (unit.includes('PERCENT')) {
                  const marginRec = getRec(CommercialType.MARGIN_PERCENT);
                  if (marginRec) {
                      baseVal = marginRec.value;
                      baseType = 'Margin %';
                  } else {
                      const nlcRec = getRec(CommercialType.NLC_PERCENT);
                      if (nlcRec) {
                          baseVal = nlcRec.value;
                          baseType = 'NLC %';
                      }
                  }
               } else {
                  const nlcValRec = getRec(CommercialType.NLC_VALUE);
                  if (nlcValRec) {
                      baseVal = nlcValRec.value;
                      baseType = 'NLC Value';
                  }
               }

               const onRec = getRec(CommercialType.ON_INVOICE);
               if (onRec) {
                   onInvVal = onRec.value;
                   onInvSource = onRec.city === 'PAN-INDIA' ? 'PAN' : 'City';
               }

               let systemTotal = 0;
               let variance = 0;

               if (unit.includes('PERCENT')) {
                   systemTotal = baseVal + onInvVal;
                   variance = targetVal - systemTotal;
               } else {
                   systemTotal = baseVal;
                   variance = targetVal - systemTotal;
               }

               const status = Math.abs(variance) < 0.01 ? 'MATCH' : 'MISMATCH';
               const title = activeRecords[0]?.title || 'Unknown Title';

               resultsAccumulator.push({
                   fsn,
                   title,
                   targetVal,
                   unit,
                   baseVal,
                   baseType,
                   onInvVal,
                   onInvSource,
                   systemTotal,
                   variance,
                   status
               });
          }
      };

      await processBatch();

      setBulkResults(resultsAccumulator);
      setProgress(100);
      setLoading(false);
      setTimeout(() => {
          setProgress(0);
          setEta(null);
      }, 500);
  };

  const handleRequestAction = async (reqId: string, action: 'APPROVED' | 'REJECTED') => {
    await db.resolveDuplicateRequest(reqId, action, user.id);
    loadRequests();
    loadUniqueFsns();
  };

  // Selection Handlers
  const toggleSelectRequest = (id: string) => {
      setSelectedRequestIds(prev => {
          const next = new Set(prev);
          if (next.has(id)) next.delete(id);
          else next.add(id);
          return next;
      });
  };

  const toggleSelectAllRequests = () => {
      const allSelected = filteredRequests.length > 0 && filteredRequests.every(r => selectedRequestIds.has(r.id));

      setSelectedRequestIds(prev => {
          const next = new Set(prev);
          if (allSelected) {
              filteredRequests.forEach(r => next.delete(r.id));
          } else {
              filteredRequests.forEach(r => next.add(r.id));
          }
          return next;
      });
  };

  const handleBulkAction = async (action: 'APPROVED' | 'REJECTED') => {
      if (selectedRequestIds.size === 0) return;

      setLoading(true);
      setProcessingStatus(action === 'APPROVED' ? 'Approving requests...' : 'Rejecting requests...');
      setProgress(0);

      const ids = Array.from(selectedRequestIds);
      let count = 0;

      for (const id of ids) {
          await db.resolveDuplicateRequest(id, action, user.id);
          count++;
          if (count % 5 === 0) setProgress(Math.round((count / ids.length) * 100));
      }

      await loadRequests();
      await loadUniqueFsns();
      setSelectedRequestIds(new Set());
      setLoading(false);
      setProgress(0);
      setProcessingStatus('');
  };

  const handleExport = async (mode: 'MONTH' | 'FULL') => {
    setExportLoading(true);
    setProcessingStatus('Generating Export...');
    setLoading(true);
    setProgress(30);

    try {
        const records = await db.getRecords();
        let dataToExport = records;

        if (mode === 'MONTH') {
            const [year, month] = selectedMonth.split('-').map(Number);
            const startOfMonth = new Date(year, month - 1, 1).toISOString().split('T')[0];
            const endOfMonth = new Date(year, month, 0).toISOString().split('T')[0];
            dataToExport = records.filter(r => r.startDate <= endOfMonth && r.endDate >= startOfMonth);
        }

        setProgress(70);

        const csv = Papa.unparse(dataToExport.map(r => ({
            ID: r.id,
            FSN: r.fsn,
            Brand: r.brand,
            Title: r.title,
            Vertical: r.vertical,
            KAM: r.kam,
            City: r.city,
            Type: r.type,
            Value: r.value,
            StartDate: r.startDate,
            EndDate: r.endDate,
            LastUpdatedBy: r.lastUpdatedBy,
            LastUpdatedAt: new Date(r.lastUpdatedAt).toISOString()
        })));

        setProgress(100);

        const blob = new Blob([csv], { type: 'text/csv' });
        const url = window.URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `mm_export_${mode.toLowerCase()}_${Date.now()}.csv`;
        a.click();
        window.URL.revokeObjectURL(url);
    } catch (e) {
        alert('Export failed');
    } finally {
        setExportLoading(false);
        setLoading(false);
        setProgress(0);
    }
  };

  const initiateClearDB = () => {
      setClearConfirmationText('');
      setShowClearModal(true);
  };

  const confirmClearDB = async () => {
    setShowClearModal(false);
    setLoading(true);
    setProcessingStatus('Archiving active records...');
    setProgress(10);

    try {
        // Simulate progress for heavy DB op
        const interval = setInterval(() => {
            setProgress(prev => Math.min(prev + 10, 90));
        }, 200);

        await db.clearAllRecords(user.name);

        clearInterval(interval);
        setProgress(100);

        alert("Database reset. Records archived.");
        setAuditResult(null);
        setRequests([]);
        loadArchive();
        setAllFsns([]);
        setBulkResults(null);
    } catch (e) {
        alert("Failed.");
    } finally {
        setLoading(false);
        setProgress(0);
        setClearConfirmationText('');
    }
  };

  const CustomTooltip = ({ active, payload, label }: any) => {
    if (active && payload && payload.length) {
      return (
        <div className="bg-white border border-gray-200 p-3 rounded shadow-lg text-xs">
          <p className="font-bold text-gray-800 mb-2">{label}</p>
          {payload.map((entry: any, index: number) => (
            <div key={index} className="flex items-center gap-2 mb-1">
               <div className="w-2 h-2 rounded-full" style={{ backgroundColor: entry.color }} />
               <span className="text-gray-500">{entry.name}:</span>
               <span className="text-gray-900 font-mono font-bold">{Number(entry.value).toFixed(2)}</span>
            </div>
          ))}
          {label === 'System' && (
             <div className="mt-2 pt-2 border-t border-gray-100 flex justify-between gap-4">
                <span className="text-gray-600 font-bold">Total:</span>
                <span className="text-gray-900 font-mono font-bold">{payload.reduce((acc: number, cur: any) => acc + (cur.value || 0), 0).toFixed(2)}</span>
             </div>
          )}
          {label === 'System' && auditResult && (
              <div className="mt-1 pt-1 border-t border-gray-50 text-[10px] text-gray-500 space-y-0.5">
                   <div className="flex justify-between"><span>Base ({auditResult.baseType}):</span> <span>{auditResult.data[0].base}</span></div>
                   {auditQuery.unit === 'PERCENT' && (
                       <div className="flex justify-between"><span>On Inv %:</span> <span>{auditResult.onInvVal}</span></div>
                   )}
                   {auditResult.onInvSource === 'PAN' && <div className="text-gray-400 italic text-[9px]">* On Inv from PAN-INDIA</div>}
              </div>
          )}
        </div>
      );
    }
    return null;
  };

  return (
    <div className="space-y-6 max-w-7xl mx-auto animate-in fade-in duration-500 relative">

      {/* Progress Overlay */}
      {loading && (
          <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center backdrop-blur-sm">
              <div className="bg-white p-8 rounded-lg shadow-2xl max-w-md w-full animate-in zoom-in duration-200">
                  <div className="flex items-center justify-between mb-4">
                      <h3 className="font-bold text-gray-800 text-lg">Processing Task</h3>
                      {eta && (
                          <span className="text-xs font-mono bg-blue-50 text-fkBlue px-2 py-1 rounded flex items-center gap-1">
                             <Clock className="w-3 h-3"/> {eta} remaining
                          </span>
                      )}
                  </div>

                  <div className="w-full bg-gray-200 rounded-full h-4 mb-2 overflow-hidden">
                      <div 
                        className="bg-fkBlue h-4 rounded-full transition-all duration-300 ease-out flex items-center justify-end pr-2"
                        style={{ width: `${progress}%` }}
                      >
                          {progress > 10 && <span className="text-[9px] text-white font-bold">{progress}%</span>}
                      </div>
                  </div>

                  <div className="flex justify-between text-xs text-gray-500">
                      <span className="flex items-center gap-2">
                          <Loader2 className="w-3 h-3 animate-spin"/> {processingStatus || 'Please wait...'}
                      </span>
                      <span>{progress}%</span>
                  </div>
              </div>
          </div>
      )}

      {/* Safety Modal for DB Clear */}
      {showClearModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm p-4">
            <div className="bg-white rounded-lg shadow-2xl max-w-md w-full p-6 border border-red-100 animate-in zoom-in duration-200">
                <div className="flex items-center gap-3 mb-4 text-red-600">
                    <div className="bg-red-100 p-2 rounded-full">
                        <AlertCircle className="w-6 h-6" />
                    </div>
                    <h3 className="text-xl font-bold">System Reset Confirmation</h3>
                </div>

                <p className="text-gray-600 mb-4 text-sm leading-relaxed">
                    This action will <strong>archive all active records</strong> to the Bin and reset the workspace for the new month. This cannot be undone easily.
                </p>

                <label className="block text-xs font-bold text-gray-500 uppercase mb-2">
                    Type "DELETE" to confirm
                </label>
                <input 
                    type="text" 
                    value={clearConfirmationText}
                    onChange={(e) => setClearConfirmationText(e.target.value)}
                    className="w-full border border-gray-300 rounded p-3 text-gray-900 focus:border-red-500 focus:ring-1 focus:ring-red-500 outline-none font-mono mb-6"
                    placeholder="DELETE"
                    autoFocus
                />

                <div className="flex justify-end gap-3">
                    <button 
                        onClick={() => setShowClearModal(false)}
                        className="px-4 py-2 text-gray-600 hover:bg-gray-100 rounded font-medium transition-colors"
                    >
                        Cancel
                    </button>
                    <button 
                        onClick={confirmClearDB}
                        disabled={clearConfirmationText !== 'DELETE'}
                        className="px-4 py-2 bg-red-600 hover:bg-red-700 text-white rounded font-bold shadow-sm disabled:opacity-50 disabled:cursor-not-allowed transition-all flex items-center gap-2"
                    >
                        <Trash2 className="w-4 h-4" /> Confirm Reset
                    </button>
                </div>
            </div>
        </div>
      )}

      <div className="flex justify-between items-center border-b border-gray-200 pb-4">
        <div>
            <h2 className="text-2xl font-bold text-gray-800 flex items-center gap-2">
               Checker Workspace
            </h2>
            <p className="text-sm text-gray-500">Audit commercial logic and approvals</p>
        </div>
        <div className="flex gap-1 bg-white p-1 rounded border border-gray-200">
          <button onClick={() => setActiveTab('AUDIT')} className={`px-4 py-2 rounded text-sm font-semibold transition-all ${activeTab === 'AUDIT' ? 'bg-fkBlue text-white shadow-sm' : 'text-gray-500 hover:text-gray-800'}`}>Audit Tool</button>
          <button onClick={() => setActiveTab('APPROVALS')} className={`px-4 py-2 rounded text-sm font-semibold transition-all flex items-center gap-2 ${activeTab === 'APPROVALS' ? 'bg-fkBlue text-white shadow-sm' : 'text-gray-500 hover:text-gray-800'}`}>
            Approvals
            {requests.length > 0 && <span className="bg-red-500 text-white text-[10px] px-1.5 py-0.5 rounded-full">{requests.length}</span>}
          </button>
          <button onClick={() => setActiveTab('CLOSURE')} className={`px-4 py-2 rounded text-sm font-semibold transition-all ${activeTab === 'CLOSURE' ? 'bg-fkYellow text-white shadow-sm' : 'text-gray-500 hover:text-gray-800'}`}>
            Month End
          </button>
        </div>
      </div>

