export const MakerWorkspace: React.FC<MakerProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<'MANUAL' | 'BULK'>('MANUAL');
  const [cities, setCities] = useState<string[]>([]);

  // Manual Entry State
  const [formData, setFormData] = useState<Partial<CommercialRecord>>({
    fsn: '',
    brand: '',
    title: '',
    vertical: '',
    kam: '',
    city: 'PAN-INDIA',
    type: CommercialType.MARGIN_PERCENT,
    value: 0,
    startDate: '',
    endDate: ''
  });
  const [loading, setLoading] = useState(false);
  const [statusMsg, setStatusMsg] = useState<{type: 'success' | 'error', text: string} | null>(null);

  // Bulk State
  const [bulkFile, setBulkFile] = useState<File | null>(null);
  const [bulkType, setBulkType] = useState<CommercialType>(CommercialType.MARGIN_PERCENT);
  const [bulkLoading, setBulkLoading] = useState(false);
  const [bulkProgress, setBulkProgress] = useState(0);
  const [bulkResult, setBulkResult] = useState<{success: number, failed: number, requests: number} | null>(null);

  useEffect(() => {
    db.getCities().then(setCities);
  }, []);

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: name === 'value' ? parseFloat(value) : value
    }));
  };

  const handleManualSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.fsn || formData.fsn.length !== 16) {
      setStatusMsg({ type: 'error', text: 'FSN must be 16 characters' });
      return;
    }
    if (!formData.startDate || !formData.endDate) {
      setStatusMsg({ type: 'error', text: 'Date range is required' });
      return;
    }

    setLoading(true);
    setStatusMsg(null);

    try {
      const record: CommercialRecord = {
        id: `rec_${Date.now()}`,
        ...formData as CommercialRecord,
        lastUpdatedBy: user.name,
        lastUpdatedAt: Date.now()
      };

      // Check for conflicts or approvals
      const needsApproval = await checkNeedsApproval(record);

      if (needsApproval.required) {
        const req: DuplicateRequest = {
            id: `req_${Date.now()}`,
            originalRecordId: null, // New record
            payload: record,
            requestedBy: user.name,
            requestedAt: Date.now(),
            status: 'PENDING',
            reason: needsApproval.reason
        };
        await db.createDuplicateRequest(req);
        setStatusMsg({ type: 'success', text: 'High value or conflict detected. Sent for approval.' });
      } else {
        await db.addRecords([record]);
        setStatusMsg({ type: 'success', text: 'Record added successfully.' });
      }

      // Reset sensitive fields
      setFormData(prev => ({ ...prev, value: 0 }));
    } catch (err) {
      setStatusMsg({ type: 'error', text: 'Failed to save record.' });
    } finally {
      setLoading(false);
    }
  };

  const checkNeedsApproval = async (rec: CommercialRecord): Promise<{required: boolean, reason?: string}> => {
     // 1. High Margin Check
     if ((rec.type === CommercialType.MARGIN_PERCENT || rec.type === CommercialType.ON_INVOICE || rec.type === CommercialType.OFF_INVOICE) && rec.value > 60) {
         return { required: true, reason: 'High Margin Value (>60%)' };
     }

     // 2. Conflict Check (Overlap)
     const allRecords = await db.getRecords();
     const conflict = allRecords.find(r => 
        r.fsn === rec.fsn &&
        r.type === rec.type &&
        r.city === rec.city &&
        (
            (rec.startDate <= r.endDate && rec.startDate >= r.startDate) ||
            (rec.endDate <= r.endDate && rec.endDate >= r.startDate) ||
            (rec.startDate <= r.startDate && rec.endDate >= r.endDate)
        )
     );

     if (conflict) {
         return { required: true, reason: 'Date Overlap Conflict' };
     }

     return { required: false };
  };

  // Bulk Upload Logic
  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      if (e.target.files?.[0]) {
          setBulkFile(e.target.files[0]);
          setBulkResult(null);
      }
  };

  const downloadTemplate = () => {
    // Dynamically Add 'Unit' column to template if it's NLC type to guide user
    const extraCols = [];
    if (bulkType === CommercialType.NLC_VALUE || bulkType === CommercialType.NLC_PERCENT) {
        extraCols.push('Unit');
    }

    // Dates are not required for Margin % as per business logic (defaults used) in some apps, 
    // but here we enforce dates for all records as per types.
    const baseHeaders = ['FSN', 'Brand', 'Title', 'Vertical', 'KAM', 'StartDate', 'EndDate'];

    const headers = [...baseHeaders, ...extraCols, ...cities];
    const isNLC = bulkType === CommercialType.NLC_VALUE;
    const exampleVal = isNLC ? '50000' : '10';
    const exampleUnit = isNLC ? 'Value' : 'Percent';

    const baseRow = ['MOBEXAMPLE123456', 'BrandX', 'Sample Product 1', 'Mobiles', 'John Doe', '2024-01-01', '2024-03-31'];

    const dummyRows = [
        [...baseRow, ...(extraCols.length ? [exampleUnit] : []), ...cities.map(() => exampleVal)],
    ];
    const csvContent = [headers.join(','), ...dummyRows.map(row => row.join(','))].join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv' });
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `template_${bulkType.replace(/\s/g, '')}.csv`;
    a.click();
    window.URL.revokeObjectURL(url);
  };

  const processBulkUpload = async () => {
      if (!bulkFile) return;
      setBulkLoading(true);
      setBulkProgress(0);

      Papa.parse(bulkFile, {
          header: true,
          skipEmptyLines: true,
          complete: async (results) => {
              const rows = results.data as any[];
              let successCount = 0;
              let failCount = 0;
              let requestCount = 0;

              const recordsToAdd: CommercialRecord[] = [];
              const requestsToAdd: DuplicateRequest[] = [];

              const total = rows.length;

              for (let i = 0; i < total; i++) {
                  const row = rows[i];
                  // Basic Validation
                  if (!row.FSN || row.FSN.length !== 16 || !row.StartDate || !row.EndDate) {
                      failCount++;
                      continue;
                  }

                  // Process each city column
                  for (const city of cities) {
                      const valStr = row[city];
                      if (!valStr) continue;

                      const val = parseFloat(valStr);
                      if (isNaN(val)) continue;

                      const rec: CommercialRecord = {
                          id: `rec_bulk_${Date.now()}_${i}_${city}`,
                          fsn: row.FSN,
                          brand: row.Brand || 'Unknown',
                          title: row.Title || 'Bulk Upload',
                          vertical: row.Vertical || '',
                          kam: row.KAM || user.name,
                          city: city,
                          type: bulkType,
                          value: val,
                          startDate: row.StartDate,
                          endDate: row.EndDate,
                          lastUpdatedBy: user.name,
                          lastUpdatedAt: Date.now()
                      };

                      const approval = await checkNeedsApproval(rec);
                      if (approval.required) {
                          requestsToAdd.push({
                            id: `req_${Date.now()}_${i}_${city}`,
                            originalRecordId: null,
                            payload: rec,
                            requestedBy: user.name,
                            requestedAt: Date.now(),
                            status: 'PENDING',
                            reason: approval.reason
                          });
                          requestCount++;
                      } else {
                          recordsToAdd.push(rec);
                          successCount++;
                      }
                  }

                  if (i % 20 === 0) setBulkProgress(Math.round((i / total) * 100));
              }

              if (recordsToAdd.length > 0) await db.addRecords(recordsToAdd);
              if (requestsToAdd.length > 0) await db.createDuplicateRequests(requestsToAdd);

              setBulkResult({ success: successCount, failed: failCount, requests: requestCount });
              setBulkLoading(false);
              setBulkProgress(100);
          }
      });
  };

  return (
    <div className="max-w-5xl mx-auto space-y-6 animate-in fade-in">
       <div className="flex justify-between items-center pb-4 border-b border-gray-200">
          <div>
            <h2 className="text-2xl font-bold text-gray-800">Maker Workspace</h2>
            <p className="text-sm text-gray-500">Create and manage commercial records</p>
          </div>
          <div className="flex bg-white p-1 rounded border border-gray-200">
             <button 
                onClick={() => setActiveTab('MANUAL')}
                className={`px-4 py-2 text-sm font-bold rounded transition-colors ${activeTab === 'MANUAL' ? 'bg-fkYellow text-white shadow-sm' : 'text-gray-500 hover:bg-gray-50'}`}
             >
                Manual Entry
             </button>
             <button 
                onClick={() => setActiveTab('BULK')}
                className={`px-4 py-2 text-sm font-bold rounded transition-colors ${activeTab === 'BULK' ? 'bg-fkYellow text-white shadow-sm' : 'text-gray-500 hover:bg-gray-50'}`}
             >
                Bulk Upload
             </button>
          </div>
       </div>

       {activeTab === 'MANUAL' && (
         <div id="tour-maker-manual" className="bg-white rounded-lg shadow-sm border border-gray-200 p-6">
             <form onSubmit={handleManualSubmit} className="space-y-6">
                 <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                     {/* Product Details */}
                     <div className="space-y-4">
                        <h3 className="text-sm font-bold text-gray-400 uppercase tracking-wider mb-2">Product Info</h3>
                        <div>
                            <label className="block text-xs font-bold text-gray-700 mb-1">FSN (16 Chars)</label>
                            <input name="fsn" value={formData.fsn} onChange={handleInputChange} maxLength={16}
                                className="w-full border border-gray-300 rounded p-2 text-sm focus:border-fkBlue outline-none font-mono uppercase" placeholder="e.g. MOB1234567890123" required />
                        </div>
                        <div className="grid grid-cols-2 gap-4">
                            <div>
                                <label className="block text-xs font-bold text-gray-700 mb-1">Brand</label>
                                <input name="brand" value={formData.brand} onChange={handleInputChange}
                                    className="w-full border border-gray-300 rounded p-2 text-sm focus:border-fkBlue outline-none" required />
                            </div>
                            <div>
                                <label className="block text-xs font-bold text-gray-700 mb-1">Title</label>
                                <input name="title" value={formData.title} onChange={handleInputChange}
                                    className="w-full border border-gray-300 rounded p-2 text-sm focus:border-fkBlue outline-none" required />
                            </div>
                        </div>
                        <div className="grid grid-cols-2 gap-4">
                            <div>
                                <label className="block text-xs font-bold text-gray-700 mb-1">Vertical</label>
                                <input name="vertical" value={formData.vertical} onChange={handleInputChange}
                                    className="w-full border border-gray-300 rounded p-2 text-sm focus:border-fkBlue outline-none" />
                            </div>
                            <div>
                                <label className="block text-xs font-bold text-gray-700 mb-1">KAM</label>
                                <input name="kam" value={formData.kam} onChange={handleInputChange}
                                    className="w-full border border-gray-300 rounded p-2 text-sm focus:border-fkBlue outline-none" />
                            </div>
                        </div>
                     </div>

                     {/* Commercial Details */}
                     <div className="space-y-4">
                        <h3 className="text-sm font-bold text-gray-400 uppercase tracking-wider mb-2">Commercials</h3>
                        <div className="grid grid-cols-2 gap-4">
                            <div>
                                <label className="block text-xs font-bold text-gray-700 mb-1">City</label>
                                <select name="city" value={formData.city} onChange={handleInputChange}
                                    className="w-full border border-gray-300 rounded p-2 text-sm focus:border-fkBlue outline-none">
                                    {cities.map(c => <option key={c} value={c}>{c}</option>)}
                                </select>
                            </div>
                            <div>
                                <label className="block text-xs font-bold text-gray-700 mb-1">Type</label>
                                <select name="type" value={formData.type} onChange={handleInputChange}
                                    className="w-full border border-gray-300 rounded p-2 text-sm focus:border-fkBlue outline-none">
                                    {COMMERCIAL_TYPES.map(t => <option key={t} value={t}>{t}</option>)}
                                </select>
                            </div>
                        </div>
                        <div>
                            <label className="block text-xs font-bold text-gray-700 mb-1">Value</label>
                            <input type="number" name="value" value={formData.value} onChange={handleInputChange} step="0.01"
                                className="w-full border border-gray-300 rounded p-2 text-sm focus:border-fkBlue outline-none font-bold text-gray-800" required />
                        </div>
                        <div className="grid grid-cols-2 gap-4">
                            <div>
                                <label className="block text-xs font-bold text-gray-700 mb-1">Start Date</label>
                                <input type="date" name="startDate" value={formData.startDate} onChange={handleInputChange}
                                    className="w-full border border-gray-300 rounded p-2 text-sm focus:border-fkBlue outline-none" required />
                            </div>
                            <div>
                                <label className="block text-xs font-bold text-gray-700 mb-1">End Date</label>
                                <input type="date" name="endDate" value={formData.endDate} onChange={handleInputChange}
                                    className="w-full border border-gray-300 rounded p-2 text-sm focus:border-fkBlue outline-none" required />
                            </div>
                        </div>
                     </div>
                 </div>

                 <div className="pt-4 border-t border-gray-100 flex justify-between items-center">
                    <div className="text-sm">
                       {statusMsg && (
                           <div className={`flex items-center gap-2 ${statusMsg.type === 'success' ? 'text-green-600' : 'text-red-600'}`}>
                               {statusMsg.type === 'success' ? <Check className="w-4 h-4"/> : <AlertTriangle className="w-4 h-4"/>}
                               {statusMsg.text}
                           </div>
                       )}
                    </div>
                    <button type="submit" disabled={loading} className="px-6 py-2 bg-fkBlue hover:bg-blue-600 text-white font-bold rounded shadow transition-colors flex items-center gap-2">
                        {loading ? <Loader2 className="animate-spin w-4 h-4"/> : <Save className="w-4 h-4"/>}
                        Save Record
                    </button>
                 </div>
             </form>
         </div>
       )}

       {activeTab === 'BULK' && (
           <div id="tour-maker-bulk" className="bg-white rounded-lg shadow-sm border border-gray-200 p-8 text-center space-y-6">
                <div className="max-w-md mx-auto space-y-4">
                    <div className="bg-blue-50 p-4 rounded-full w-16 h-16 flex items-center justify-center mx-auto">
                        <Upload className="w-8 h-8 text-fkBlue" />
                    </div>
                    <h3 className="text-xl font-bold text-gray-800">Bulk Upload Records</h3>
                    <p className="text-sm text-gray-500">Upload CSV file to update commercials in bulk. Overlaps will trigger approval requests.</p>
                </div>

                <div className="max-w-md mx-auto">
                    <label className="block text-left text-xs font-bold text-gray-700 mb-1">Select Commercial Type for File</label>
                    <select 
                        value={bulkType} 
                        onChange={(e) => setBulkType(e.target.value as CommercialType)}
                        className="w-full border border-gray-300 rounded p-2 text-sm mb-4"
                    >
                        {COMMERCIAL_TYPES.map(t => <option key={t} value={t}>{t}</option>)}
                    </select>

                    <div className="border-2 border-dashed border-gray-300 rounded-lg p-8 hover:bg-gray-50 transition-colors relative cursor-pointer">
                        <input type="file" accept=".csv" onChange={handleFileChange} className="absolute inset-0 w-full h-full opacity-0 cursor-pointer" />
                        <p className="text-sm font-medium text-gray-600">{bulkFile ? bulkFile.name : 'Click to select CSV file'}</p>
                    </div>

                    <button onClick={downloadTemplate} className="text-fkBlue text-sm font-medium mt-4 hover:underline flex items-center justify-center gap-2">
                        <Download className="w-4 h-4"/> Download Template
                    </button>
                </div>

                {bulkFile && (
                    <div className="max-w-md mx-auto pt-4 border-t border-gray-100">
                        {bulkLoading ? (
                            <div className="space-y-2">
                                <div className="w-full bg-gray-200 rounded-full h-2">
                                    <div className="bg-fkBlue h-2 rounded-full transition-all" style={{ width: `${bulkProgress}%` }}></div>
                                </div>
                                <p className="text-xs text-gray-500">Processing... {bulkProgress}%</p>
                            </div>
                        ) : (
                            <button 
                                onClick={processBulkUpload}
                                className="w-full bg-fkBlue hover:bg-blue-600 text-white font-bold py-3 rounded shadow transition-colors"
                            >
                                Process File
                            </button>
                        )}
                    </div>
                )}

                {bulkResult && (
                    <div className="max-w-md mx-auto bg-gray-50 p-4 rounded border border-gray-200 text-sm">
                        <h4 className="font-bold mb-2">Upload Results</h4>
                        <div className="grid grid-cols-3 gap-2 text-center">
                            <div className="text-green-600">
                                <div className="text-lg font-bold">{bulkResult.success}</div>
                                <div className="text-xs">Added</div>
                            </div>
                            <div className="text-fkYellow">
                                <div className="text-lg font-bold">{bulkResult.requests}</div>
                                <div className="text-xs">Pending</div>
                            </div>
                            <div className="text-red-600">
                                <div className="text-lg font-bold">{bulkResult.failed}</div>
                                <div className="text-xs">Failed</div>
                            </div>
                        </div>
                    </div>
                )}
           </div>
       )}
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { db } from '../services/db';
import { DuplicateRequest, User, CommercialType, CommercialRecord } from '../types';
import { Check, X, Search, BarChart3, Archive, TrendingUp, AlertCircle, FileDown, Calendar, Trash2, Database, Clock, ChevronDown, User as UserIcon, Layers, Upload, FileText, RefreshCw, Loader2, CheckSquare } from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer, ReferenceLine, LabelList } from 'recharts';
import Papa from 'papaparse';

interface CheckerProps {
  user: User;
}

export const CheckerWorkspace: React.FC<CheckerProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<'AUDIT' | 'APPROVALS' | 'CLOSURE'>('AUDIT');
  const [requests, setRequests] = useState<DuplicateRequest[]>([]);
  const [cities, setCities] = useState<string[]>([]);

  // Selection State for Approvals
  const [selectedRequestIds, setSelectedRequestIds] = useState<Set<string>>(new Set());
  const [approvalSearchTerm, setApprovalSearchTerm] = useState('');

  // Audit State (Single)
  const [auditMode, setAuditMode] = useState<'SINGLE' | 'BULK'>('SINGLE');
  const [auditQuery, setAuditQuery] = useState({ fsn: '', city: 'BLR', targetMargin: 0, unit: 'PERCENT' });
  const [auditResult, setAuditResult] = useState<any>(null);

  // Audit State (Bulk)
  const [bulkAuditData, setBulkAuditData] = useState<any[]>([]);
  const [bulkAuditCity, setBulkAuditCity] = useState('BLR');
  const [bulkResults, setBulkResults] = useState<any[] | null>(null);
  const [bulkFile, setBulkFile] = useState<string | null>(null);

  const [loading, setLoading] = useState(false);

  // Progress State
  const [progress, setProgress] = useState(0);
  const [eta, setEta] = useState<string | null>(null);
  const [processingStatus, setProcessingStatus] = useState<string>('');

  // Autocomplete State
  const [allFsns, setAllFsns] = useState<string[]>([]);
  const [filteredFsns, setFilteredFsns] = useState<string[]>([]);
  const [showSuggestions, setShowSuggestions] = useState(false);

  // Closure/Export State
  const [selectedMonth, setSelectedMonth] = useState(new Date().toISOString().slice(0, 7)); // YYYY-MM
  const [exportLoading, setExportLoading] = useState(false);

  // Archive View State
  const [showArchive, setShowArchive] = useState(false);
  const [archiveData, setArchiveData] = useState<any[]>([]);

  // Safety Modal State
  const [showClearModal, setShowClearModal] = useState(false);
  const [clearConfirmationText, setClearConfirmationText] = useState('');

  useEffect(() => {
    loadRequests();
    loadCities();
    loadUniqueFsns();
    const interval = setInterval(loadRequests, 5000);
    return () => clearInterval(interval);
  }, []);

  // Sync selection with requests list (cleanup ghosts)
  useEffect(() => {
      const currentIds = new Set(requests.map(r => r.id));
      setSelectedRequestIds(prev => {
          const next = new Set();
          let changed = false;
          prev.forEach(id => {
              if (currentIds.has(id)) next.add(id);
              else changed = true;
          });
          return changed ? next : prev;
      });
  }, [requests]);

  const filteredRequests = useMemo(() => {
    if (!approvalSearchTerm.trim()) return requests;
    const lowerTerm = approvalSearchTerm.toLowerCase();
    return requests.filter(req => 
      req.payload.fsn.toLowerCase().includes(lowerTerm) ||
      req.payload.title.toLowerCase().includes(lowerTerm) ||
      req.requestedBy.toLowerCase().includes(lowerTerm) ||
      (req.payload.kam && req.payload.kam.toLowerCase().includes(lowerTerm))
    );
  }, [requests, approvalSearchTerm]);

  const loadCities = async () => {
    const c = await db.getCities();
    setCities(c);
    if (!c.includes(auditQuery.city)) {
       setAuditQuery(prev => ({ ...prev, city: c.includes('BLR') ? 'BLR' : c[0] || '' }));
    }
  };

  const loadUniqueFsns = async () => {
    const records = await db.getRecords();
    const unique = Array.from(new Set(records.map(r => r.fsn)));
    setAllFsns(unique);
  };

  const loadRequests = async () => {
    const reqs = await db.getDuplicateRequests();
    setRequests(reqs.filter(r => r.status === 'PENDING'));
  };

  const loadArchive = async () => {
    const data = await db.getBinRecords();
    setArchiveData(data.sort((a: any, b: any) => b.deletedAt - a.deletedAt));
  };

  const toggleArchive = () => {
      if (!showArchive) loadArchive();
      setShowArchive(!showArchive);
  };

  const handleFsnChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = e.target.value;
    setAuditQuery({ ...auditQuery, fsn: val });

    if (val.length > 0) {
        const matches = allFsns.filter(f => f.toLowerCase().includes(val.toLowerCase()));
        setFilteredFsns(matches.slice(0, 5)); // Limit to 5 suggestions
        setShowSuggestions(true);
    } else {
        setShowSuggestions(false);
    }
  };

  const selectSuggestion = (fsn: string) => {
      setAuditQuery({ ...auditQuery, fsn });
      setShowSuggestions(false);
  };

  // SINGLE AUDIT Logic
  const handleAudit = async () => {
    if (!auditQuery.fsn) return;

    if (auditQuery.fsn.length !== 16) {
        alert("FSN must be exactly 16 characters.");
        return;
    }

    setLoading(true);
    setProcessingStatus('Analyzing FSN...');
    setProgress(50);
    setShowSuggestions(false); 

    const records = await db.getRecords();
    const today = new Date().toISOString().split('T')[0];

    // 1. Filter relevant records (Active & City Match/PAN)
    const activeRecords = records.filter(r => 
      r.fsn === auditQuery.fsn && 
      (r.city === auditQuery.city || r.city === 'PAN-INDIA') &&
      r.startDate <= today && r.endDate >= today
    );

    let baseVal = 0;
    let baseType = '-';
    let onInvVal = 0;
    let onInvSource = '-';
    let systemTotal = 0;

    const getRec = (type: CommercialType) => 
        activeRecords.find(r => r.type === type && r.city === auditQuery.city) ||
        activeRecords.find(r => r.type === type && r.city === 'PAN-INDIA');

    if (auditQuery.unit === 'PERCENT') {
        // Logic: Margin % > NLC %
        const marginRec = getRec(CommercialType.MARGIN_PERCENT);
        if (marginRec) {
            baseVal = marginRec.value;
            baseType = 'Margin %';
        } else {
            const nlcRec = getRec(CommercialType.NLC_PERCENT);
            if (nlcRec) {
                baseVal = nlcRec.value;
                baseType = 'NLC %';
            }
        }

        // On Invoice Logic
        const onRec = getRec(CommercialType.ON_INVOICE);
        if (onRec) {
            onInvVal = onRec.value;
            onInvSource = onRec.city === 'PAN-INDIA' ? 'PAN' : 'City';
        }

        systemTotal = baseVal + onInvVal;
    } else {
        // Logic: NLC Value (Amount)
        const nlcValRec = getRec(CommercialType.NLC_VALUE);
        if (nlcValRec) {
            baseVal = nlcValRec.value;
            baseType = 'NLC Value';
        }

        // On Invoice (For display only, not added to total)
        const onRec = getRec(CommercialType.ON_INVOICE);
        if (onRec) {
            onInvVal = onRec.value;
            onInvSource = onRec.city === 'PAN-INDIA' ? 'PAN' : 'City';
        }

        systemTotal = baseVal;
    }

    const variance = auditQuery.targetMargin - systemTotal;
    const variancePercent = auditQuery.targetMargin ? ((variance / auditQuery.targetMargin) * 100) : 0;

    setAuditResult({
      data: [
        { name: 'System', base: baseVal, onInv: auditQuery.unit === 'PERCENT' ? onInvVal : 0, total: systemTotal },
        { name: 'Target', target: auditQuery.targetMargin }
      ],
      systemTotal,
      targetTotal: auditQuery.targetMargin,
      variance,
      variancePercent: variancePercent.toFixed(2),
      status: Math.abs(variance) < 0.01 ? 'MATCH' : 'MISMATCH',
      details: activeRecords,
      baseType,
      onInvVal,
      onInvSource
    });
    setLoading(false);
    setProgress(100);
    setTimeout(() => { setProgress(0); }, 500);
  };

  // BULK AUDIT Handlers
