<?xml version="1.0" encoding="UTF-8"?>
<changes>
  <change>
    <file>MakerWorkspace.tsx</file>
    <content><![CDATA[// Other imports and code above...

  const downloadTemplate = (bulkType: BulkType) => {
    const headers = [
      'CommercialType',
      'Vendor',
      'Product',
      'Margin%',
      'OrOffInvoice',
      'TransactionType',
      'Price',
      'Cost',
    ];

    const dummyData = [
      'MARGIN_PERCENT', // Or whatever default or example value you prefer
      'VendorA',
      'ProductX',
      '10',
      '',
      'Sale',
      '100',
      '90',
    ];

    if (bulkType === 'MARGIN_PERCENT') {
      headers.splice(3, 1, 'Margin %');
    }

    if (bulkType !== 'MARGIN_PERCENT') {
        headers.push('StartDate', 'EndDate');
        dummyData.push('2024-01-01', '2024-03-31');
    }

    const csvData = [headers.join(',')];
    csvData.push(dummyData.join(','));

    const csvString = csvData.join('\n');
    const blob = new Blob([csvString], { type: 'text/csv' });
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `template_${bulkType.replace(/\s/g, '')}.csv`;
    a.click();
    window.URL.revokeObjectURL(url);
